function Get-StrictSkillDispatchProperty {
    param(
        $Object,
        [string[]]$Names
    )

    foreach ($name in @($Names)) {
        if (Test-OperationObjectProperty $Object $name) {
            return Get-OperationObjectProperty $Object $name
        }
    }
    return $null
}

function Get-StrictSkillDispatchNames {
    param($Value)

    $seen = New-Object System.Collections.Generic.HashSet[string]([System.StringComparer]::OrdinalIgnoreCase)
    $names = New-Object System.Collections.Generic.List[string]
    foreach ($item in @($Value)) {
        $name = ([string]$item).Trim()
        if (-not [string]::IsNullOrWhiteSpace($name) -and $seen.Add($name)) {
            $names.Add($name) | Out-Null
        }
    }
    return [string[]]@($names.ToArray())
}

function Test-StrictSkillDispatchNameSetEqual {
    param(
        [string[]]$Left,
        [string[]]$Right
    )

    $leftNames = Get-StrictSkillDispatchNames $Left
    $rightNames = Get-StrictSkillDispatchNames $Right
    if ($leftNames.Count -ne $rightNames.Count) { return $false }
    $rightSet = New-Object System.Collections.Generic.HashSet[string]([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($name in $rightNames) { $rightSet.Add($name) | Out-Null }
    foreach ($name in $leftNames) { if (-not $rightSet.Contains($name)) { return $false } }
    return $true
}

function Test-StrictSkillDispatchOptIn {
    param($Request)

    $explicit = Get-StrictSkillDispatchProperty $Request @('strict_dispatch', 'strict')
    if ($explicit -is [bool]) { return [bool]$explicit }
    if ($explicit -is [string]) { return [string]::Equals($explicit.Trim(), 'true', [StringComparison]::OrdinalIgnoreCase) }
    $mode = ([string](Get-StrictSkillDispatchProperty $Request @('dispatch_mode', 'mode', 'fallback'))).Trim().ToLowerInvariant()
    return $mode -in @('strict', 'strict_fallback')
}

function New-StrictSkillDispatchTrace {
    param(
        [Parameter(Mandatory = $true)][string]$TraceId,
        [Parameter(Mandatory = $true)]$Request,
        [string[]]$CandidateNames = @(),
        [string[]]$SelectedNames = @(),
        [string[]]$InjectedNames = @(),
        [string]$AbstainedReason = '',
        [Parameter(Mandatory = $true)][string]$CapturedAt
    )

    $events = New-Object System.Collections.Generic.List[object]
    $correlationId = [string](Get-StrictSkillDispatchProperty $Request @('correlation_id', 'request_id', 'thread_id'))
    $index = 0
    foreach ($name in @($CandidateNames)) {
        $events.Add([pscustomobject][ordered]@{
                event_id = ('{0}|listed|{1}|{2}' -f $TraceId, $name, $index)
                kind = 'listed'
                skill_name = $name
                occurred_at = $CapturedAt
                correlation_id = $correlationId
            }) | Out-Null
        $index++
    }
    foreach ($name in @($SelectedNames)) {
        $events.Add([pscustomobject][ordered]@{
                event_id = ('{0}|selected|{1}|{2}' -f $TraceId, $name, $index)
                kind = 'selected'
                skill_name = $name
                occurred_at = $CapturedAt
                correlation_id = $correlationId
            }) | Out-Null
        $index++
    }
    foreach ($name in @($InjectedNames)) {
        $events.Add([pscustomobject][ordered]@{
                event_id = ('{0}|injected|{1}|{2}' -f $TraceId, $name, $index)
                kind = 'injected'
                skill_name = $name
                occurred_at = $CapturedAt
                correlation_id = $correlationId
            }) | Out-Null
        $index++
    }
    if (-not [string]::IsNullOrWhiteSpace($AbstainedReason)) {
        $abstainedNames = if (@($SelectedNames).Count -gt 0) { @($SelectedNames) } elseif (@($CandidateNames).Count -gt 0) { @($CandidateNames) } else { @('strict-dispatch') }
        foreach ($name in $abstainedNames) {
            $events.Add([pscustomobject][ordered]@{
                    event_id = ('{0}|abstained|{1}|{2}' -f $TraceId, $name, $index)
                    kind = 'abstained'
                    skill_name = $name
                    occurred_at = $CapturedAt
                    correlation_id = $correlationId
                    reason = $AbstainedReason
                }) | Out-Null
            $index++
        }
    }
    return New-NativeInvocationTrace -TraceId $TraceId -Surface 'app_server' -Source 'app_server' -Freshness 'fresh' -CapturedAt $CapturedAt -Events $events.ToArray()
}

function New-StrictSkillDispatchResult {
    param(
        [Parameter(Mandatory = $true)][string]$Status,
        [Parameter(Mandatory = $true)][bool]$FallbackEntered,
        [bool]$PlatformNa = $false,
        [object[]]$Candidates = @(),
        [string[]]$SelectedNames = @(),
        $Injection = $null,
        [Parameter(Mandatory = $true)]$Trace,
        [object[]]$Findings = @(),
        [string]$ReceiptId = ''
    )

    return [pscustomobject][ordered]@{
        schema_version = 1
        status = $Status
        fallback_entered = $FallbackEntered
        platform_na = $PlatformNa
        candidates = [object[]]@($Candidates)
        candidate_count = @($Candidates).Count
        selected_names = [string[]]@($SelectedNames)
        injection = $Injection
        host_adjudication_receipt_id = if ([string]::IsNullOrWhiteSpace($ReceiptId)) { $null } else { $ReceiptId }
        trace = $Trace
        findings = [object[]]@($Findings)
        provider_calls = 0
        native_mutations = 0
        writes = 0
    }
}

function Get-StrictSkillDispatchEligibleEntries {
    param(
        [object[]]$Candidates,
        [object[]]$EligibilityResults
    )

    $eligible = New-Object System.Collections.Generic.List[object]
    foreach ($candidate in @($Candidates)) {
        if ($null -eq $candidate) { continue }
        $name = ([string](Get-StrictSkillDispatchProperty $candidate @('name', 'skill_name'))).Trim()
        if ([string]::IsNullOrWhiteSpace($name)) { continue }
        if ((Get-StrictSkillDispatchProperty $candidate @('kind')) -and [string](Get-StrictSkillDispatchProperty $candidate @('kind')) -ne 'skill') { continue }
        if (Test-OperationObjectProperty $candidate 'enabled' -and -not [bool](Get-StrictSkillDispatchProperty $candidate @('enabled'))) { continue }
        $decision = @($EligibilityResults | Where-Object { [string]$_.skill_name -ieq $name } | Select-Object -First 1)
        if ($decision.Count -eq 0) { continue }
        $policyResult = $decision[0]
        $contract = Test-SkillEligibilityResultContract $policyResult
        if (-not [bool]$contract.pass) { continue }
        if ([string]$policyResult.decision -ne 'allow' -or [bool]$policyResult.eligible -ne $true) { continue }
        if ([string]$policyResult.decision_owner -ne 'deterministic_policy') { continue }
        if ([bool]$policyResult.semantic_selection_performed -ne $false -or [bool]$policyResult.profile_filter_applied -ne $false) { continue }
        $eligible.Add($candidate) | Out-Null
    }
    return [object[]]@($eligible.ToArray())
}

function Test-StrictSkillDispatchHostAdjudicationReceipt {
    param(
        $Receipt,
        [string]$RequestId,
        [string[]]$CandidateNames
    )

    $findings = New-Object System.Collections.Generic.List[object]
    if ($null -eq $Receipt) {
        $findings.Add((New-OperationFinding 'adjudication_receipt_required' 'error' '$.host_adjudication_receipt' 'Host adjudication receipt is required before skill injection.')) | Out-Null
        return [pscustomobject][ordered]@{ pass = $false; selected_names = @(); receipt_id = ''; findings = $findings.ToArray() }
    }
    if ((Get-StrictSkillDispatchProperty $Receipt @('schema_version')) -ne 1) { $findings.Add((New-OperationFinding 'adjudication_schema_invalid' 'error' '$.schema_version' 'Only host adjudication receipt schema version 1 is supported.')) | Out-Null }
    if ([string](Get-StrictSkillDispatchProperty $Receipt @('status')) -ne 'accepted') { $findings.Add((New-OperationFinding 'adjudication_status_invalid' 'error' '$.status' 'Host adjudication must be explicitly accepted.')) | Out-Null }
    if ([string](Get-StrictSkillDispatchProperty $Receipt @('decision_owner')) -ne 'host_ai') { $findings.Add((New-OperationFinding 'adjudication_owner_invalid' 'error' '$.decision_owner' 'Host AI must own semantic adjudication.')) | Out-Null }
    if ([string](Get-StrictSkillDispatchProperty $Receipt @('freshness')) -ne 'fresh') { $findings.Add((New-OperationFinding 'adjudication_stale' 'error' '$.freshness' 'Stale or unknown adjudication cannot authorize injection.')) | Out-Null }
    if (-not (Test-OperationRfc3339 (Get-StrictSkillDispatchProperty $Receipt @('captured_at')))) { $findings.Add((New-OperationFinding 'adjudication_timestamp_invalid' 'error' '$.captured_at' 'Host adjudication captured_at must be RFC3339.')) | Out-Null }
    $receiptRequestId = [string](Get-StrictSkillDispatchProperty $Receipt @('request_id'))
    if (-not [string]::IsNullOrWhiteSpace($RequestId) -and -not [string]::Equals($receiptRequestId, $RequestId, [StringComparison]::Ordinal)) { $findings.Add((New-OperationFinding 'adjudication_request_mismatch' 'error' '$.request_id' 'Host adjudication receipt does not belong to this request.')) | Out-Null }
    $receiptCandidates = Get-StrictSkillDispatchNames (Get-StrictSkillDispatchProperty $Receipt @('candidate_names', 'candidates'))
    $selectedNames = Get-StrictSkillDispatchNames (Get-StrictSkillDispatchProperty $Receipt @('selected_names', 'selected'))
    if (-not (Test-OperationArray (Get-StrictSkillDispatchProperty $Receipt @('candidate_names', 'candidates')))) { $findings.Add((New-OperationFinding 'adjudication_candidates_invalid' 'error' '$.candidate_names' 'Host adjudication candidate_names must be an array.')) | Out-Null }
    if (-not (Test-OperationArray (Get-StrictSkillDispatchProperty $Receipt @('selected_names', 'selected')))) { $findings.Add((New-OperationFinding 'adjudication_selection_invalid' 'error' '$.selected_names' 'Host adjudication selected_names must be an array.')) | Out-Null }
    if (-not (Test-StrictSkillDispatchNameSetEqual $receiptCandidates $CandidateNames)) { $findings.Add((New-OperationFinding 'adjudication_candidate_mismatch' 'error' '$.candidate_names' 'Host adjudication must cover exactly the bounded eligible candidate set.')) | Out-Null }
    $candidateSet = New-Object System.Collections.Generic.HashSet[string]([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($name in @($CandidateNames)) { $candidateSet.Add($name) | Out-Null }
    foreach ($name in @($selectedNames)) { if (-not $candidateSet.Contains($name)) { $findings.Add((New-OperationFinding 'adjudication_selection_outside_candidates' 'error' '$.selected_names' 'Host adjudication selected a non-eligible candidate.')) | Out-Null } }
    foreach ($field in @('provider_calls', 'native_mutations', 'writes')) {
        if ([long](Get-StrictSkillDispatchProperty $Receipt @($field)) -ne 0) { $findings.Add((New-OperationFinding 'adjudication_side_effect_forbidden' 'error' ('$.{0}' -f $field) 'Host adjudication receipt must be zero-side-effect.')) | Out-Null }
    }
    return [pscustomobject][ordered]@{
        pass = @($findings | Where-Object severity -eq 'error').Count -eq 0
        selected_names = [string[]]@($selectedNames)
        receipt_id = [string](Get-StrictSkillDispatchProperty $Receipt @('receipt_id'))
        findings = [object[]]@($findings.ToArray())
    }
}

function Invoke-StrictSkillDispatch {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]$Request,
        [object[]]$Candidates = @(),
        [object[]]$EligibilityResults = @(),
        $HostAdjudicationReceipt = $null,
        [Parameter(Mandatory = $true)]$Adapter,
        [ValidateRange(1, 32)][int]$MaxCandidates = 3,
        [Parameter(Mandatory = $true)][string]$CapturedAt,
        [string]$TraceId = ''
    )

    $requestId = [string](Get-StrictSkillDispatchProperty $Request @('request_id', 'turn_id', 'thread_id'))
    if ([string]::IsNullOrWhiteSpace($TraceId)) { $TraceId = if ([string]::IsNullOrWhiteSpace($requestId)) { 'strict-dispatch' } else { $requestId + '|strict-dispatch' } }
    $rawCandidates = [object[]]@($Candidates | Where-Object { $null -ne $_ })

    if (-not (Test-StrictSkillDispatchOptIn $Request)) {
        $trace = New-StrictSkillDispatchTrace -TraceId $TraceId -Request $Request -AbstainedReason 'strict_opt_in_required' -CapturedAt $CapturedAt
        return New-StrictSkillDispatchResult -Status 'not_requested' -FallbackEntered $false -Trace $trace
    }

    if ($rawCandidates.Count -gt $MaxCandidates) {
        $trace = New-StrictSkillDispatchTrace -TraceId $TraceId -Request $Request -AbstainedReason 'candidate_set_too_large' -CapturedAt $CapturedAt
        $finding = New-OperationFinding 'candidate_set_too_large' 'error' '$.candidates' ('Strict dispatch candidate set exceeds the bound of {0}.' -f $MaxCandidates)
        return New-StrictSkillDispatchResult -Status 'candidate_set_too_large' -FallbackEntered $true -Trace $trace -Findings @($finding)
    }

    $eligible = Get-StrictSkillDispatchEligibleEntries -Candidates $rawCandidates -EligibilityResults $EligibilityResults
    $eligibleNames = [string[]]@($eligible | ForEach-Object { [string]$_.name })
    if ($eligible.Count -eq 0) {
        $trace = New-StrictSkillDispatchTrace -TraceId $TraceId -Request $Request -AbstainedReason 'no_eligible_candidates' -CapturedAt $CapturedAt
        $finding = New-OperationFinding 'no_eligible_candidates' 'error' '$.candidates' 'No candidate passed the shared deterministic eligibility policy.'
        return New-StrictSkillDispatchResult -Status 'no_eligible_candidates' -FallbackEntered $true -Trace $trace -Findings @($finding)
    }

    $adapterContract = Test-AppServerSkillDispatchAdapterContract $Adapter
    if (-not [bool]$adapterContract.pass -or -not [bool]$Adapter.supports_skill_injection) {
        $trace = New-StrictSkillDispatchTrace -TraceId $TraceId -Request $Request -CandidateNames $eligibleNames -AbstainedReason 'app_server_skill_injection_unsupported' -CapturedAt $CapturedAt
        $finding = New-OperationFinding 'app_server_skill_injection_unsupported' 'warning' '$.adapter' 'App Server skill item injection is unavailable; native-only remains primary.'
        return New-StrictSkillDispatchResult -Status 'platform_na' -FallbackEntered $true -PlatformNa $true -Candidates $eligible -Trace $trace -Findings @($finding)
    }

    $adjudication = Test-StrictSkillDispatchHostAdjudicationReceipt -Receipt $HostAdjudicationReceipt -RequestId $requestId -CandidateNames $eligibleNames
    if (-not [bool]$adjudication.pass) {
        $status = if ($null -eq $HostAdjudicationReceipt) { 'adjudication_required' } else { 'adjudication_invalid' }
        $trace = New-StrictSkillDispatchTrace -TraceId $TraceId -Request $Request -CandidateNames $eligibleNames -AbstainedReason $status -CapturedAt $CapturedAt
        return New-StrictSkillDispatchResult -Status $status -FallbackEntered $true -Candidates $eligible -Trace $trace -Findings @($adjudication.findings)
    }

    $selectedNames = [string[]]@($adjudication.selected_names)
    if ($selectedNames.Count -eq 0) {
        $trace = New-StrictSkillDispatchTrace -TraceId $TraceId -Request $Request -CandidateNames $eligibleNames -AbstainedReason 'host_adjudication_abstained' -CapturedAt $CapturedAt
        $finding = New-OperationFinding 'host_adjudication_abstained' 'warning' '$.selected_names' 'Host adjudication selected no skill for injection.'
        return New-StrictSkillDispatchResult -Status 'abstained' -FallbackEntered $true -Candidates $eligible -Trace $trace -Findings @($finding) -ReceiptId $adjudication.receipt_id
    }

    $selectedSkills = @($eligible | Where-Object { $selectedNames -contains [string]$_.name })
    $injection = New-AppServerSkillInjectionRequest -Adapter $Adapter -Skills $selectedSkills
    if ([string]$injection.status -ne 'ready') {
        $trace = New-StrictSkillDispatchTrace -TraceId $TraceId -Request $Request -CandidateNames $eligibleNames -SelectedNames $selectedNames -AbstainedReason 'app_server_skill_injection_unsupported' -CapturedAt $CapturedAt
        return New-StrictSkillDispatchResult -Status 'platform_na' -FallbackEntered $true -PlatformNa $true -Candidates $eligible -SelectedNames $selectedNames -Injection $null -Trace $trace -Findings @($injection.findings) -ReceiptId $adjudication.receipt_id
    }

    $injectedNames = [string[]]@($injection.items | ForEach-Object { [string]$_.name })
    $trace = New-StrictSkillDispatchTrace -TraceId $TraceId -Request $Request -CandidateNames $eligibleNames -SelectedNames $selectedNames -InjectedNames $injectedNames -CapturedAt $CapturedAt
    return New-StrictSkillDispatchResult -Status 'planned' -FallbackEntered $true -Candidates $eligible -SelectedNames $selectedNames -Injection $injection -Trace $trace -ReceiptId $adjudication.receipt_id
}

function Test-StrictSkillDispatchResultContract {
    param($Result)

    $findings = New-Object System.Collections.Generic.List[object]
    if ($null -eq $Result) { return New-OperationValidationResult @((New-OperationFinding 'dispatch_result_missing' 'error' '$' 'Strict dispatch result is required.')) }
    if ((Get-StrictSkillDispatchProperty $Result @('schema_version')) -ne 1) { $findings.Add((New-OperationFinding 'schema_version_invalid' 'error' '$.schema_version' 'Only strict dispatch result schema version 1 is supported.')) | Out-Null }
    if ([string]::IsNullOrWhiteSpace([string](Get-StrictSkillDispatchProperty $Result @('status')))) { $findings.Add((New-OperationFinding 'status_missing' 'error' '$.status' 'Strict dispatch status is required.')) | Out-Null }
    if ((Get-StrictSkillDispatchProperty $Result @('fallback_entered')) -isnot [bool]) { $findings.Add((New-OperationFinding 'fallback_boundary_invalid' 'error' '$.fallback_entered' 'Fallback entry must be explicitly boolean.')) | Out-Null }
    $trace = Get-StrictSkillDispatchProperty $Result @('trace')
    $traceContract = Test-NativeInvocationTraceContract $trace
    foreach ($finding in @($traceContract.findings)) { $findings.Add($finding) | Out-Null }
    foreach ($field in @('provider_calls', 'native_mutations', 'writes')) {
        if ([long](Get-StrictSkillDispatchProperty $Result @($field)) -ne 0) { $findings.Add((New-OperationFinding 'side_effect_forbidden' 'error' ('$.{0}' -f $field) 'Strict dispatch must remain zero-side-effect.')) | Out-Null }
    }
    return New-OperationValidationResult $findings.ToArray()
}

function ConvertFrom-CodexPluginInventorySnapshot {
    param($Snapshot, [ValidateSet('official', 'personal', 'workspace')][string]$Scope)

    $descriptors = New-Object System.Collections.Generic.List[object]
    $findings = New-Object System.Collections.Generic.List[object]
    foreach ($state in @('installed', 'available')) {
        $items = Get-OperationObjectProperty $Snapshot $state
        if (-not (Test-OperationArray $items)) {
            $findings.Add((New-OperationFinding 'plugin_snapshot_array_missing' 'error' ('$.{0}' -f $state) ('Snapshot scope {0} must contain an array.' -f $Scope))) | Out-Null
            continue
        }
        foreach ($item in @($items)) {
            $pluginId = [string](Get-OperationObjectProperty $item 'pluginId')
            $name = [string](Get-OperationObjectProperty $item 'name')
            $marketplace = [string](Get-OperationObjectProperty $item 'marketplaceName')
            $version = [string](Get-OperationObjectProperty $item 'version')
            if ([string]::IsNullOrWhiteSpace($pluginId) -or [string]::IsNullOrWhiteSpace($name) -or [string]::IsNullOrWhiteSpace($marketplace)) {
                $findings.Add((New-OperationFinding 'plugin_snapshot_item_invalid' 'error' ('$.{0}' -f $state) 'pluginId, name, and marketplaceName are required.')) | Out-Null
                continue
            }
            $source = [pscustomobject]@{
                type = 'codex_plugin_snapshot'
                path_or_url = 'codex-plugin://{0}/{1}' -f $Scope, $pluginId
                revision = $(if ([string]::IsNullOrWhiteSpace($version)) { $null } else { $version })
                checksum = $null
                license = $null
                trust_tier = $Scope
            }
            $origin = if ($Scope -eq 'official') { 'official' } elseif ([bool](Get-OperationObjectProperty $item 'installed')) { 'host_installed' } else { 'candidate' }
            $components = @([pscustomobject][ordered]@{
                kind = 'plugin_bundle'
                distribution_scope = $Scope
                inventory_state = $state
                marketplace = $marketplace
                installed = [bool](Get-OperationObjectProperty $item 'installed')
                enabled = [bool](Get-OperationObjectProperty $item 'enabled')
                install_policy = [string](Get-OperationObjectProperty $item 'installPolicy')
                auth_policy = [string](Get-OperationObjectProperty $item 'authPolicy')
            })
            $descriptors.Add((New-CapabilityDescriptor -Kind plugin -Name $name -TruthOrigin $origin -Source $source -Lifecycle active -HostCompatibility @('codex') -Components $components -VerificationState static_validated)) | Out-Null
        }
    }
    return [pscustomobject][ordered]@{ scope = $Scope; descriptors = $descriptors.ToArray(); findings = $findings.ToArray() }
}

function New-PluginInventoryFromSnapshots {
    param($Official, $Personal = $null, $Workspace = $null)

    $descriptors = New-Object System.Collections.Generic.List[object]
    $findings = New-Object System.Collections.Generic.List[object]
    foreach ($entry in @(
        [pscustomobject]@{ scope = 'official'; value = $Official },
        [pscustomobject]@{ scope = 'personal'; value = $Personal },
        [pscustomobject]@{ scope = 'workspace'; value = $Workspace }
    )) {
        if ($null -eq $entry.value) { continue }
        $result = ConvertFrom-CodexPluginInventorySnapshot $entry.value $entry.scope
        foreach ($item in @($result.descriptors)) { $descriptors.Add($item) | Out-Null }
        foreach ($finding in @($result.findings)) { $findings.Add($finding) | Out-Null }
    }
    $inventory = New-CapabilityInventory $descriptors.ToArray()
    foreach ($finding in @($findings.ToArray())) { $inventory.findings += $finding }
    return [pscustomobject][ordered]@{
        schema_version = 1
        read_only = $true
        pass = (@($inventory.findings | Where-Object severity -eq 'error').Count -eq 0)
        descriptors = @($inventory.descriptors)
        decisions = @($inventory.decisions)
        findings = @($inventory.findings)
        provider_calls = 0
        native_mutations = 0
        writes = 0
        profile_changed = $false
    }
}

function Get-PluginFileInventory([string]$Root) {
    $items = New-Object System.Collections.Generic.List[object]
    foreach ($file in @(Get-ChildItem -LiteralPath $Root -File -Recurse -Force | Sort-Object FullName)) {
        $relative = $file.FullName.Substring(([System.IO.Path]::GetFullPath($Root).TrimEnd('\', '/') + [System.IO.Path]::DirectorySeparatorChar).Length).Replace('\', '/')
        $items.Add([pscustomobject][ordered]@{ relative_path = $relative; length = [int64]$file.Length; sha256 = (Get-FileContentHash $file.FullName) }) | Out-Null
    }
    return $items.ToArray()
}

function Test-PluginCandidateContract($Candidate, [string]$FixtureRoot) {
    $findings = New-Object System.Collections.Generic.List[object]
    if ([int](Get-OperationObjectProperty $Candidate 'schema_version') -ne 1) { $findings.Add((New-PluginContractFinding 'candidate_schema_invalid' '$.schema_version' 'Candidate schema_version must be 1.')) | Out-Null }
    foreach ($field in @('name', 'version', 'description', 'repository', 'license')) {
        if ([string]::IsNullOrWhiteSpace([string](Get-OperationObjectProperty $Candidate $field))) { $findings.Add((New-PluginContractFinding 'candidate_field_missing' ('$.{0}' -f $field) 'Candidate field is required.')) | Out-Null }
    }
    foreach ($field in @('audiences', 'source_skills', 'evidence_refs')) {
        if (-not (Test-OperationArray (Get-OperationObjectProperty $Candidate $field)) -or @((Get-OperationObjectProperty $Candidate $field)).Count -eq 0) { $findings.Add((New-PluginContractFinding 'candidate_array_invalid' ('$.{0}' -f $field) 'Candidate array must be non-empty.')) | Out-Null }
    }
    if ([string](Get-OperationObjectProperty $Candidate 'distribution_need') -ne 'repeated') { $findings.Add((New-PluginContractFinding 'candidate_distribution_need_unproven' '$.distribution_need' 'Exporter requires repeated distribution evidence.')) | Out-Null }
    if ([string](Get-OperationObjectProperty $Candidate 'official_equivalent') -ne 'absent_after_review') { $findings.Add((New-PluginContractFinding 'candidate_official_equivalent_unresolved' '$.official_equivalent' 'Official equivalent review must be explicitly absent.')) | Out-Null }
    $manifest = [pscustomobject][ordered]@{
        name = [string](Get-OperationObjectProperty $Candidate 'name')
        version = [string](Get-OperationObjectProperty $Candidate 'version')
        description = [string](Get-OperationObjectProperty $Candidate 'description')
        repository = [string](Get-OperationObjectProperty $Candidate 'repository')
        license = [string](Get-OperationObjectProperty $Candidate 'license')
        skills = './skills/'
    }
    $manifestValidation = Test-PluginManifestContract $manifest '' $true
    foreach ($finding in @($manifestValidation.findings | Where-Object code -notin @('plugin_component_missing'))) { $findings.Add($finding) | Out-Null }
    $sources = New-Object System.Collections.Generic.List[object]
    foreach ($relative in @((Get-OperationObjectProperty $Candidate 'source_skills'))) {
        $text = [string]$relative
        if (-not (Test-PluginRelativeComponentPath $text)) { $findings.Add((New-PluginContractFinding 'candidate_source_path_invalid' '$.source_skills' ('Invalid source path: {0}' -f $text))) | Out-Null; continue }
        $full = [System.IO.Path]::GetFullPath((Join-Path $FixtureRoot $text.Substring(2)))
        if (-not (Test-PluginPathWithin $full $FixtureRoot) -or -not (Test-Path -LiteralPath $full -PathType Container)) { $findings.Add((New-PluginContractFinding 'candidate_source_missing' '$.source_skills' ('Source skill is missing or outside fixture: {0}' -f $text))) | Out-Null; continue }
        if (Test-PluginReparsePoint $full) { $findings.Add((New-PluginContractFinding 'candidate_source_reparse_forbidden' '$.source_skills' ('Source skill is a reparse point: {0}' -f $text))) | Out-Null; continue }
        if (Test-PluginExistingAncestorReparsePoint $full $FixtureRoot) { $findings.Add((New-PluginContractFinding 'candidate_source_ancestor_reparse_forbidden' '$.source_skills' ('Source skill crosses a reparse point: {0}' -f $text))) | Out-Null; continue }
        if (Test-PluginTreeContainsReparsePoint $full) { $findings.Add((New-PluginContractFinding 'candidate_source_tree_reparse_forbidden' '$.source_skills' ('Source skill contains a reparse point: {0}' -f $text))) | Out-Null; continue }
        if (-not (Test-Path -LiteralPath (Join-Path $full 'SKILL.md') -PathType Leaf)) { $findings.Add((New-PluginContractFinding 'candidate_skill_manifest_missing' '$.source_skills' ('Source skill lacks SKILL.md: {0}' -f $text))) | Out-Null; continue }
        $sources.Add([pscustomobject]@{ relative = $text; full_path = $full; name = (Split-Path $full -Leaf) }) | Out-Null
    }
    if ($sources.Count -gt 8) { $findings.Add((New-PluginContractFinding 'candidate_skill_limit_exceeded' '$.source_skills' 'At most 8 skills may be exported.')) | Out-Null }
    return [pscustomobject][ordered]@{ pass = (@($findings | Where-Object severity -eq 'error').Count -eq 0); findings = $findings.ToArray(); manifest = $manifest; sources = $sources.ToArray() }
}

function Test-PluginSkillBehaviorFixture([string]$PluginRoot) {
    $findings = New-Object System.Collections.Generic.List[object]
    $skillsRoot = Join-Path $PluginRoot 'skills'
    foreach ($skillDir in @(Get-ChildItem -LiteralPath $skillsRoot -Directory -Force -ErrorAction SilentlyContinue)) {
        $path = Join-Path $skillDir.FullName 'SKILL.md'
        if (-not (Test-YamlFrontmatterSkillFile $path)) { $findings.Add((New-PluginContractFinding 'skill_frontmatter_invalid' ('skills/{0}/SKILL.md' -f $skillDir.Name) 'Skill must start with YAML frontmatter.')) | Out-Null; continue }
        $text = Get-ContentUtf8 $path
        if ($text -notmatch '(?m)^name:\s*\S+' -or $text -notmatch '(?m)^description:\s*\S+') { $findings.Add((New-PluginContractFinding 'skill_metadata_incomplete' ('skills/{0}/SKILL.md' -f $skillDir.Name) 'Skill frontmatter must declare name and description.')) | Out-Null }
    }
    return [pscustomobject][ordered]@{ pass = ($findings.Count -eq 0); state = $(if ($findings.Count -eq 0) { 'pass' } else { 'fail' }); findings = $findings.ToArray() }
}

function New-PluginEvaluationReport([string]$PluginRoot, $ModelSnapshot = $null) {
    $manifestPath = Join-Path $PluginRoot '.codex-plugin\plugin.json'
    if (-not (Test-Path -LiteralPath $manifestPath -PathType Leaf)) { throw 'Plugin manifest does not exist.' }
    $manifest = [System.IO.File]::ReadAllText($manifestPath) | ConvertFrom-Json
    $static = Test-PluginManifestContract $manifest $PluginRoot $true
    $behavior = if ($static.pass -and (Get-PluginShape $manifest) -eq 'skills_only') { Test-PluginSkillBehaviorFixture $PluginRoot } else { [pscustomobject]@{ pass = $false; state = 'blocked'; findings = @() } }
    $modelState = if ($null -eq $ModelSnapshot) { 'not_run' } else { [string](Get-OperationObjectProperty $ModelSnapshot 'state') }
    if ($modelState -notin @('pass', 'fail', 'not_run')) { $modelState = 'invalid_snapshot' }
    return [pscustomobject][ordered]@{
        schema_version = 1
        pass = ([bool]$static.pass -and [bool]$behavior.pass)
        truth_boundary = 'repo_fixture_evaluation'
        layers = [pscustomobject][ordered]@{
            static = [pscustomobject]@{ state = $(if ($static.pass) { 'pass' } else { 'fail' }); blocking = $true; findings = @($static.findings) }
            behavior_fixture = [pscustomobject]@{ state = $behavior.state; blocking = $true; findings = @($behavior.findings) }
            model_snapshot = [pscustomobject]@{ state = $modelState; blocking = $false }
            host_load = [pscustomobject]@{ state = 'not_run'; blocking = $false }
            live_workflow = [pscustomobject]@{ state = 'not_run'; blocking = $false }
        }
        provider_calls = 0
        native_mutations = 0
        writes = 0
    }
}

function Export-PluginFixture {
    param($Candidate, [string]$FixtureRoot, [string]$OutPath, [string]$Token)

    $root = [System.IO.Path]::GetFullPath($FixtureRoot)
    $out = [System.IO.Path]::GetFullPath($OutPath)
    $findings = New-Object System.Collections.Generic.List[object]
    if (-not (Test-Path -LiteralPath $root -PathType Container) -or -not (Test-Path -LiteralPath (Join-Path $root '.skills-manager-fixture') -PathType Leaf)) { $findings.Add((New-PluginContractFinding 'fixture_marker_missing' '$.fixture_root' 'Fixture root must exist and contain .skills-manager-fixture.')) | Out-Null }
    if ($Token -ne 'EXPORT_PLUGIN_FIXTURE') { $findings.Add((New-PluginContractFinding 'export_token_invalid' '$.token' 'Exact token EXPORT_PLUGIN_FIXTURE is required.')) | Out-Null }
    if (-not (Test-PluginPathWithin $out $root) -or $out.Equals($root, [System.StringComparison]::OrdinalIgnoreCase)) { $findings.Add((New-PluginContractFinding 'export_output_outside_fixture' '$.out' 'Output must be a new child path inside the fixture root.')) | Out-Null }
    if (Test-Path -LiteralPath $out) { $findings.Add((New-PluginContractFinding 'export_output_exists' '$.out' 'Exporter never overwrites an existing output.')) | Out-Null }
    if (Test-PluginReparsePoint $root) { $findings.Add((New-PluginContractFinding 'fixture_root_reparse_forbidden' '$.fixture_root' 'Reparse fixture roots are not supported.')) | Out-Null }
    if ((Test-PluginPathWithin $out $root) -and (Test-PluginExistingAncestorReparsePoint $out $root)) { $findings.Add((New-PluginContractFinding 'export_path_reparse_forbidden' '$.out' 'Output must not cross an existing reparse-point ancestor.')) | Out-Null }
    $candidateValidation = Test-PluginCandidateContract $Candidate $root
    foreach ($finding in @($candidateValidation.findings)) { $findings.Add($finding) | Out-Null }

    $sourceFiles = New-Object System.Collections.Generic.List[object]
    foreach ($source in @($candidateValidation.sources)) {
        foreach ($item in @(Get-PluginFileInventory $source.full_path)) {
            $sourceFiles.Add([pscustomobject]@{ skill_name = $source.name; source_path = $source.full_path; relative_path = $item.relative_path; length = $item.length; sha256 = $item.sha256 }) | Out-Null
        }
    }
    if ($sourceFiles.Count -gt 256) { $findings.Add((New-PluginContractFinding 'export_file_limit_exceeded' '$.source_skills' 'Export is limited to 256 files.')) | Out-Null }
    $totalBytes = [int64](($sourceFiles.ToArray() | Measure-Object length -Sum).Sum)
    if ($totalBytes -gt 2097152) { $findings.Add((New-PluginContractFinding 'export_byte_limit_exceeded' '$.source_skills' 'Export is limited to 2 MiB.')) | Out-Null }
    if ($findings.Count -gt 0) { return [pscustomobject][ordered]@{ schema_version = 1; pass = $false; status = 'blocked'; findings = $findings.ToArray(); writes = 0; provider_calls = 0; native_mutations = 0 } }

    $parent = Split-Path $out -Parent
    $stage = Join-Path $parent ('.{0}.staging-{1}' -f (Split-Path $out -Leaf), [guid]::NewGuid().ToString('N'))
    try {
        [System.IO.Directory]::CreateDirectory((Join-Path $stage '.codex-plugin')) | Out-Null
        [System.IO.Directory]::CreateDirectory((Join-Path $stage 'skills')) | Out-Null
        $manifestJson = $candidateValidation.manifest | ConvertTo-Json -Depth 20
        Write-Utf8FileAtomic -Path (Join-Path $stage '.codex-plugin\plugin.json') -Content $manifestJson
        foreach ($sourceFile in @($sourceFiles.ToArray())) {
            $destination = Join-Path (Join-Path (Join-Path $stage 'skills') $sourceFile.skill_name) $sourceFile.relative_path
            [System.IO.Directory]::CreateDirectory((Split-Path $destination -Parent)) | Out-Null
            [System.IO.File]::Copy((Join-Path $sourceFile.source_path $sourceFile.relative_path), $destination, $false)
        }
        $lint = Test-PluginManifestContract $candidateValidation.manifest $stage $true
        if (-not $lint.pass) { throw ('Exported manifest failed lint: {0}' -f (@($lint.findings.code) -join ',')) }
        foreach ($sourceFile in @($sourceFiles.ToArray())) {
            $destination = Join-Path (Join-Path (Join-Path $stage 'skills') $sourceFile.skill_name) $sourceFile.relative_path
            if ((Get-FileContentHash $destination) -ne $sourceFile.sha256) { throw ('Round-trip hash mismatch: {0}' -f $sourceFile.relative_path) }
        }
        [System.IO.Directory]::Move($stage, $out)
        $evaluation = New-PluginEvaluationReport $out
        return [pscustomobject][ordered]@{
            schema_version = 1; pass = [bool]$evaluation.pass; status = 'exported'; output_path = $out
            skill_count = @($candidateValidation.sources).Count; file_count = $sourceFiles.Count; byte_count = $totalBytes
            verification = [pscustomobject][ordered]@{ static_validated = 'pass'; repo_gates_passed = 'not_run'; host_loaded = 'not_run'; live_accepted = 'not_run' }
            evaluation = $evaluation; findings = @(); writes = 1; provider_calls = 0; native_mutations = 0
        }
    }
    catch {
        if (Test-Path -LiteralPath $stage -PathType Container) { [System.IO.Directory]::Delete($stage, $true) }
        return [pscustomobject][ordered]@{ schema_version = 1; pass = $false; status = 'failed'; findings = @((New-PluginContractFinding 'plugin_export_failed' '$.out' $_.Exception.Message)); writes = 0; provider_calls = 0; native_mutations = 0 }
    }
}

function Get-RuleFileSha256([string]$Path) {
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try { return (($sha.ComputeHash([System.IO.File]::ReadAllBytes($Path)) | ForEach-Object { $_.ToString('x2') }) -join '') }
    finally { $sha.Dispose() }
}

function Test-RuleDiscoveryPathWithin([string]$Path, [string]$Root) {
    $candidate = [System.IO.Path]::GetFullPath($Path).TrimEnd('\', '/')
    $boundary = [System.IO.Path]::GetFullPath($Root).TrimEnd('\', '/')
    return $candidate.Equals($boundary, [System.StringComparison]::OrdinalIgnoreCase) -or $candidate.StartsWith(($boundary + [System.IO.Path]::DirectorySeparatorChar), [System.StringComparison]::OrdinalIgnoreCase)
}

function Test-RuleDiscoveryNonEmptyFile([string]$Path) {
    return [System.IO.File]::Exists($Path) -and -not [string]::IsNullOrWhiteSpace([System.IO.File]::ReadAllText($Path))
}

function New-ObservedRuleDocument([string]$Path, [string]$HostName, [string]$Scope, [int]$Precedence, [string]$Responsibility = 'project_action') {
    $bytes = [System.IO.File]::ReadAllBytes($Path)
    return New-RuleDocument -Host $HostName -Scope $Scope -Responsibility $Responsibility -Path ([System.IO.Path]::GetFullPath($Path)) -Owner $(if ($Scope -eq 'global') { 'user' } else { 'repo' }) -ContentHash (Get-RuleFileSha256 $Path) -ByteSize $bytes.Length -Precedence $Precedence -DiscoveryState observed -SourceOfTruth 'filesystem' -VerificationState static_validated -Evidence @([pscustomobject]@{ type = 'file'; path = [System.IO.Path]::GetFullPath($Path) })
}

function Get-RuleDiscovery {
    param(
        [Parameter(Mandatory = $true)][string]$RepoRoot,
        [string]$CurrentDirectory = $RepoRoot,
        [Parameter(Mandatory = $true)][ValidateSet('codex', 'claude')][string]$HostName,
        [string]$UserRuleRoot,
        [string[]]$FallbackNames = @(),
        [int]$MaxCombinedBytes = 32768
    )
    $repo = [System.IO.Path]::GetFullPath($RepoRoot)
    $cwd = [System.IO.Path]::GetFullPath($CurrentDirectory)
    if (-not (Test-RuleDiscoveryPathWithin $cwd $repo)) { throw 'CurrentDirectory is outside the authorized repository root.' }
    $documents = New-Object System.Collections.Generic.List[object]
    $candidates = New-Object System.Collections.Generic.List[object]
    $precedence = 0
    if (-not [string]::IsNullOrWhiteSpace($UserRuleRoot)) {
        $user = [System.IO.Path]::GetFullPath($UserRuleRoot)
        $globalNames = if ($HostName -eq 'codex') { @('AGENTS.override.md', 'AGENTS.md') } else { @('CLAUDE.md') }
        foreach ($name in $globalNames) {
            $path = Join-Path $user $name
            $exists = [System.IO.File]::Exists($path)
            $nonEmpty = $exists -and (Test-RuleDiscoveryNonEmptyFile $path)
            $reason = if (-not $exists) { 'absent' } elseif (-not $nonEmpty) { 'empty_candidate' } else { 'candidate' }
            $candidates.Add([pscustomobject]@{ path = $path; scope = 'global'; exists = $exists; selected = $false; reason = $reason }) | Out-Null
            if ($nonEmpty) { $documents.Add((New-ObservedRuleDocument $path $HostName $(if ($name -match 'override') { 'override' } else { 'global' }) $precedence $(if ($HostName -eq 'codex') { 'common' } else { 'platform_delta' }))) | Out-Null; $candidates[$candidates.Count - 1].selected = $true; $candidates[$candidates.Count - 1].reason = 'first_non_empty_candidate'; $precedence++; break }
        }
    }
    $dirs = New-Object System.Collections.Generic.List[string]
    $cursor = $cwd
    while ($true) {
        $dirs.Insert(0, $cursor)
        if ($cursor.Equals($repo, [System.StringComparison]::OrdinalIgnoreCase)) { break }
        $parent = [System.IO.Directory]::GetParent($cursor)
        if ($null -eq $parent -or -not (Test-RuleDiscoveryPathWithin $parent.FullName $repo)) { throw 'Unable to construct a bounded repository rule chain.' }
        $cursor = $parent.FullName
    }
    foreach ($dir in $dirs) {
        $names = if ($HostName -eq 'codex') { @('AGENTS.override.md', 'AGENTS.md') + @($FallbackNames) } else { @('CLAUDE.md') }
        $selected = $false
        foreach ($name in $names) {
            $path = Join-Path $dir $name
            $exists = [System.IO.File]::Exists($path)
            $nonEmpty = $exists -and (Test-RuleDiscoveryNonEmptyFile $path)
            $reason = if (-not $exists) { 'absent' } elseif (-not $nonEmpty) { 'empty_candidate' } else { 'shadowed_by_higher_priority_candidate' }
            $candidate = [pscustomobject]@{ path = $path; scope = $(if ($dir -eq $repo) { 'repo' } else { 'subtree' }); exists = $exists; selected = $false; reason = $reason }
            if ($nonEmpty -and -not $selected) {
                $scope = if ($name -match 'override') { 'override' } elseif ($dir -eq $repo) { 'repo' } else { 'subtree' }
                $document = New-ObservedRuleDocument $path $HostName $scope $precedence $(if ($HostName -eq 'codex') { 'project_action' } else { 'platform_delta' })
                if ($HostName -eq 'claude') { $document.discovery_state = 'inferred'; $document.precedence = $null }
                $documents.Add($document) | Out-Null; $candidate.selected = $true; $candidate.reason = $(if ($HostName -eq 'codex') { 'first_non_empty_candidate' } else { 'candidate_precedence_not_verified' }); $selected = $true; $precedence++
            }
            $candidates.Add($candidate) | Out-Null
        }
    }
    $consumed = 0
    $truncated = New-Object System.Collections.Generic.List[string]
    foreach ($document in @($documents.ToArray() | Sort-Object precedence)) {
        if ($consumed + [int]$document.byte_size -gt $MaxCombinedBytes) { $truncated.Add([string]$document.path) | Out-Null }
        else { $consumed += [int]$document.byte_size }
    }
    return [pscustomobject][ordered]@{
        schema_version = 1; host = $HostName; repo_root = $repo; current_directory = $cwd; read_only = $true
        documents = @($documents.ToArray()); candidates = @($candidates.ToArray()); combined_bytes = $consumed
        max_combined_bytes = $MaxCombinedBytes; truncated_paths = @($truncated.ToArray())
        load_verification = 'not_run'; writes = 0; provider_calls = 0; native_mutations = 0; profile_changed = $false
    }
}

function Invoke-RuleDiagnostics {
    param($Discovery, $Profile = $null)
    $maxBytes = [int](Get-OperationObjectProperty $Profile 'max_bytes')
    if ($maxBytes -le 0) { $maxBytes = 10240 }
    $maxLines = [int](Get-OperationObjectProperty $Profile 'max_lines')
    if ($maxLines -le 0) { $maxLines = 80 }
    $blockingCodes = @((Get-OperationObjectProperty $Profile 'blocking_codes') | ForEach-Object { [string]$_ })
    $wrapperFirstLine = [string](Get-OperationObjectProperty $Profile 'wrapper_first_line')
    $globalMaxBytes = [int](Get-OperationObjectProperty $Profile 'global_max_bytes')
    $globalMaxLines = [int](Get-OperationObjectProperty $Profile 'global_max_lines')
    $projectMaxBytes = [int](Get-OperationObjectProperty $Profile 'project_max_bytes')
    $projectMaxLines = [int](Get-OperationObjectProperty $Profile 'project_max_lines')
    $results = New-Object System.Collections.Generic.List[object]
    $allFindings = New-Object System.Collections.Generic.List[object]
    $hashIndex = @{}
    foreach ($document in @((Get-OperationObjectProperty $Discovery 'documents'))) {
        $path = [string]$document.path
        $documentScope = [string]$document.scope
        $documentMaxBytes = if ($documentScope -eq 'global' -and $globalMaxBytes -gt 0) { $globalMaxBytes } elseif ($documentScope -ne 'global' -and $projectMaxBytes -gt 0) { $projectMaxBytes } else { $maxBytes }
        $documentMaxLines = if ($documentScope -eq 'global' -and $globalMaxLines -gt 0) { $globalMaxLines } elseif ($documentScope -ne 'global' -and $projectMaxLines -gt 0) { $projectMaxLines } else { $maxLines }
        $findings = New-Object System.Collections.Generic.List[object]
        if (-not [System.IO.File]::Exists($path)) {
            $findings.Add((New-RuleFinding -Kind deterministic -Code file_missing -Severity error -Path $path -Message 'Discovered rule file no longer exists.' -Blocking:($blockingCodes -contains 'file_missing'))) | Out-Null
        }
        else {
            $bytes = [System.IO.File]::ReadAllBytes($path)
            $text = [System.IO.File]::ReadAllText($path)
            $lines = @($text -split "`r?`n")
            if ($bytes.Length -gt $documentMaxBytes) { $findings.Add((New-RuleFinding -Kind deterministic -Code byte_budget_exceeded -Severity warning -Path $path -Message ('Rule file uses {0} bytes; profile budget is {1}.' -f $bytes.Length, $documentMaxBytes) -Disposition adapt -Blocking:($blockingCodes -contains 'byte_budget_exceeded'))) | Out-Null }
            if ($lines.Count -gt $documentMaxLines) { $findings.Add((New-RuleFinding -Kind deterministic -Code line_budget_exceeded -Severity warning -Path $path -Message ('Rule file uses {0} lines; profile budget is {1}.' -f $lines.Count, $documentMaxLines) -Disposition adapt -Blocking:($blockingCodes -contains 'line_budget_exceeded'))) | Out-Null }
            if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF) { $findings.Add((New-RuleFinding -Kind deterministic -Code utf8_bom_present -Severity info -Path $path -Message 'UTF-8 BOM is present.' -Disposition defer -Blocking:($blockingCodes -contains 'utf8_bom_present'))) | Out-Null }
            if (-not [string]::IsNullOrWhiteSpace($wrapperFirstLine) -and $lines.Count -gt 0 -and $lines[0] -ne $wrapperFirstLine) { $findings.Add((New-RuleFinding -Kind deterministic -Code wrapper_first_line_mismatch -Severity error -Path $path -Line 1 -Message ('First physical line must be: {0}' -f $wrapperFirstLine) -Disposition adapt -Blocking:($blockingCodes -contains 'wrapper_first_line_mismatch'))) | Out-Null }
            if ([string]$document.scope -eq 'global' -and $text -match '(?i)[A-Z]:\\(?:CODE|src|repo)\\') { $findings.Add((New-RuleFinding -Kind deterministic -Code global_repo_private_path -Severity warning -Path $path -Message 'Global rule contains a repository-private absolute path.' -Disposition adapt -Blocking:($blockingCodes -contains 'global_repo_private_path'))) | Out-Null }
            if ([string]$document.scope -in @('repo', 'subtree') -and $text -match '(?i)\bCODEX_HOME\b.*(?:loads?|加载)') { $findings.Add((New-RuleFinding -Kind deterministic -Code project_host_loading_tutorial -Severity warning -Path $path -Message 'Project rule contains host-loading tutorial text.' -Disposition adapt -Blocking:($blockingCodes -contains 'project_host_loading_tutorial'))) | Out-Null }
            if ($text -match '(?im)^\s*\[deterministic-enforcement\]' -and $text -notmatch '(?i)(\.github/workflows|hooks?|scripts?/|\.rules\b|config\.)') { $findings.Add((New-RuleFinding -Kind deterministic -Code prose_only_enforcement -Severity error -Path $path -Message 'Deterministic enforcement claim has no hook/config/script/CI reference.' -Disposition adapt -Blocking:($blockingCodes -contains 'prose_only_enforcement'))) | Out-Null }
            $hash = [string]$document.content_hash
            if (-not [string]::IsNullOrWhiteSpace($hash)) {
                if (-not $hashIndex.ContainsKey($hash)) { $hashIndex[$hash] = New-Object System.Collections.Generic.List[string] }
                $hashIndex[$hash].Add($path) | Out-Null
            }
        }
        foreach ($finding in $findings) { $allFindings.Add($finding) | Out-Null }
        $copy = $document.PSObject.Copy(); $copy.findings = @($findings.ToArray() | Sort-Object finding_id); $results.Add($copy) | Out-Null
    }
    foreach ($hash in @($hashIndex.Keys)) {
        $paths = @($hashIndex[$hash])
        if ($paths.Count -gt 1) {
            foreach ($path in $paths) { $finding = New-RuleFinding -Kind deterministic -Code exact_duplicate_document -Severity warning -Path $path -Message ('Exact content is duplicated across: {0}' -f ($paths -join ', ')) -Disposition adapt -Blocking:($blockingCodes -contains 'exact_duplicate_document'); $allFindings.Add($finding) | Out-Null; $target = @($results | Where-Object path -eq $path)[0]; $target.findings = @($target.findings) + @($finding) }
        }
    }
    return [pscustomobject][ordered]@{ schema_version = 1; documents = @($results.ToArray()); findings = @($allFindings.ToArray() | Sort-Object finding_id); blocking_count = @($allFindings | Where-Object blocking).Count; commands_executed = 0; writes = 0; provider_calls = 0; native_mutations = 0 }
}

function Get-RuleAdvisorSurface([string]$NeedKind) {
    switch ($NeedKind) {
        'task_local' { return 'prompt_or_thread' }
        'repeatable_workflow' { return 'skill' }
        'installable_bundle' { return 'plugin' }
        'external_data_or_action' { return 'mcp_or_connector' }
        'deterministic_enforcement' { return 'hook_config_script_or_ci' }
        default { return 'AGENTS.md' }
    }
}

function Invoke-RuleAdvisor {
    param([object[]]$Documents = @(), [object[]]$Constraints = @())
    $semantic = New-Object System.Collections.Generic.List[object]
    foreach ($document in @($Documents)) {
        $scope = [string]$document.scope; $responsibility = [string]$document.responsibility
        $misplaced = ($scope -eq 'global' -and $responsibility -eq 'project_action') -or ($scope -in @('repo', 'subtree') -and $responsibility -eq 'common')
        if ($misplaced) { $semantic.Add((New-RuleFinding -Kind semantic -Code responsibility_scope_mismatch -Severity warning -Path ([string]$document.path) -Message ('Responsibility {0} is misplaced at scope {1}.' -f $responsibility, $scope) -Disposition adapt -Confidence 0.8)) | Out-Null }
    }
    $coverage = New-Object System.Collections.Generic.List[object]
    $recommendations = New-Object System.Collections.Generic.List[object]
    foreach ($constraint in @($Constraints)) {
        $id = [string](Get-OperationObjectProperty $constraint 'constraint_id')
        $commonIntent = [string](Get-OperationObjectProperty $constraint 'common_intent')
        $platformDeltas = @((Get-OperationObjectProperty $constraint 'platform_deltas'))
        $projectActions = @((Get-OperationObjectProperty $constraint 'project_actions'))
        $enforcementRefs = @((Get-OperationObjectProperty $constraint 'enforcement_refs'))
        $recovery = [string](Get-OperationObjectProperty $constraint 'recovery_condition')
        $declaredNotApplicable = [bool](Get-OperationObjectProperty $constraint 'not_applicable')
        $conflict = [bool](Get-OperationObjectProperty $constraint 'conflict')
        $allRefs = @($platformDeltas + $projectActions + $enforcementRefs | ForEach-Object { [string]$_ })
        $hasDuplicates = @($allRefs | Group-Object | Where-Object Count -gt 1).Count -gt 0
        $state = if ($declaredNotApplicable) { 'not_applicable' } elseif ($conflict) { 'conflict' } elseif ([string]::IsNullOrWhiteSpace($commonIntent) -or $projectActions.Count -eq 0) { 'gap' } elseif ($hasDuplicates) { 'duplicated' } else { 'covered' }
        $item = New-RuleResponsibility -ConstraintId $id -CommonIntent $(if ([string]::IsNullOrWhiteSpace($commonIntent)) { 'unspecified' } else { $commonIntent }) -PlatformDeltas $platformDeltas -ProjectActions $projectActions -EnforcementRefs $enforcementRefs -Coverage $state -Evidence @((Get-OperationObjectProperty $constraint 'evidence')) -Confidence $(if ($state -eq 'covered') { 1.0 } else { 0.75 }) -RecoveryCondition $recovery
        $coverage.Add($item) | Out-Null
        $disposition = if ($state -eq 'covered') { 'adopt' } elseif ($state -eq 'not_applicable' -and [string]::IsNullOrWhiteSpace($recovery)) { 'defer' } else { 'adapt' }
        $recommendations.Add([pscustomobject][ordered]@{ constraint_id = $id; disposition = $disposition; surface = Get-RuleAdvisorSurface ([string](Get-OperationObjectProperty $constraint 'need_kind')); evidence = @((Get-OperationObjectProperty $constraint 'evidence')); confidence = $item.confidence; truth_boundary = 'recommendation_only'; blocking = $false }) | Out-Null
    }
    return [pscustomobject][ordered]@{ schema_version = 1; coverage = @($coverage.ToArray()); findings = @($semantic.ToArray() | Sort-Object finding_id); recommendations = @($recommendations.ToArray() | Sort-Object constraint_id); blocking_count = 0; provider_calls = 0; writes = 0 }
}

function New-RuleRepoTruthIndex {
    param([Parameter(Mandatory = $true)][string]$RepoRoot, $RepoScan = $null)
    $root = [System.IO.Path]::GetFullPath($RepoRoot)
    $commands = @()
    if ($null -ne $RepoScan) {
        $detected = Get-OperationObjectProperty $RepoScan 'detected'
        $commands = @((Get-OperationObjectProperty $detected 'build_commands')) + @((Get-OperationObjectProperty $detected 'test_commands'))
    }
    return [pscustomobject][ordered]@{ schema_version = 1; repo_root = $root; commands = @($commands | ForEach-Object { [string]$_ } | Sort-Object -Unique); source = $(if ($null -eq $RepoScan) { 'filesystem_only' } else { 'target_audit_repo_scan' }); scanned_at = Get-OperationObjectProperty $RepoScan 'scanned_at' }
}

function Test-RuleRepoReferences {
    param([Parameter(Mandatory = $true)]$TruthIndex, [object[]]$References = @())
    $root = [string]$TruthIndex.repo_root
    $results = New-Object System.Collections.Generic.List[object]
    foreach ($reference in @($References)) {
        $kind = [string](Get-OperationObjectProperty $reference 'kind'); $value = [string](Get-OperationObjectProperty $reference 'value'); $sourceType = [string](Get-OperationObjectProperty $reference 'source_type')
        $state = 'unknown'; $evidence = @()
        if ($sourceType -eq 'recommendation') { $state = 'not_checked'; $evidence = @([pscustomobject]@{ reason = 'recommendation_not_evidence' }) }
        elseif ($kind -eq 'path') {
            $candidate = if ([System.IO.Path]::IsPathRooted($value)) { [System.IO.Path]::GetFullPath($value) } else { [System.IO.Path]::GetFullPath((Join-Path $root $value)) }
            if (-not (Test-RuleDiscoveryPathWithin $candidate $root)) { $state = 'out_of_root' }
            elseif ([System.IO.File]::Exists($candidate) -or [System.IO.Directory]::Exists($candidate)) { $state = 'verified'; $evidence = @([pscustomobject]@{ type = 'filesystem'; path = $candidate }) }
            else { $state = 'absent'; $evidence = @([pscustomobject]@{ type = 'filesystem'; path = $candidate }) }
        }
        elseif ($kind -eq 'command') {
            if (@($TruthIndex.commands | Where-Object { [string]::Equals($_.Trim(), $value.Trim(), [System.StringComparison]::OrdinalIgnoreCase) }).Count -gt 0) { $state = 'verified'; $evidence = @([pscustomobject]@{ type = $TruthIndex.source; command = $value }) }
            else {
                $entrypoint = $null
                $fileMatch = [regex]::Match($value, '(?i)(?:^|\s)-File\s+(?:"([^"]+)"|([^\s]+))')
                $scriptMatch = [regex]::Match($value, '^(?i)(?:python|py|node)\s+(?:"([^"]+)"|([^\s]+))')
                if ($fileMatch.Success) { $entrypoint = $(if ($fileMatch.Groups[1].Success) { $fileMatch.Groups[1].Value } else { $fileMatch.Groups[2].Value }) }
                elseif ($scriptMatch.Success) { $entrypoint = $(if ($scriptMatch.Groups[1].Success) { $scriptMatch.Groups[1].Value } else { $scriptMatch.Groups[2].Value }) }
                if (-not [string]::IsNullOrWhiteSpace($entrypoint)) {
                    $candidate = if ([System.IO.Path]::IsPathRooted($entrypoint)) { [System.IO.Path]::GetFullPath($entrypoint) } else { [System.IO.Path]::GetFullPath((Join-Path $root $entrypoint)) }
                    if ((Test-RuleDiscoveryPathWithin $candidate $root) -and [System.IO.File]::Exists($candidate)) {
                        $state = 'verified'; $evidence = @([pscustomobject]@{ type = 'filesystem_entrypoint'; path = $candidate; command = $value })
                    }
                    else { $state = 'not_observed'; $evidence = @([pscustomobject]@{ type = $TruthIndex.source; command = $value }) }
                }
                else { $state = 'not_observed'; $evidence = @([pscustomobject]@{ type = $TruthIndex.source; command = $value }) }
            }
        }
        $results.Add([pscustomobject][ordered]@{ kind = $kind; value = $value; state = $state; evidence = $evidence; executed = $false }) | Out-Null
    }
    return [pscustomobject][ordered]@{ schema_version = 1; references = @($results.ToArray()); commands_executed = 0; writes = 0; recommendations_used_as_evidence = 0 }
}

function Get-RuleAuditResponsibilityConstraints {
    param([object[]]$Documents = @())
    $constraints = [ordered]@{}
    foreach ($document in @($Documents)) {
        $path = [string](Get-OperationObjectProperty $document 'path')
        if (-not [System.IO.File]::Exists($path)) { continue }
        $inMapping = $false
        $lines = [System.IO.File]::ReadAllLines($path)
        for ($index = 0; $index -lt $lines.Count; $index++) {
            $line = $lines[$index]
            if ($line -match '^#{1,6}\s+(.+?)\s*$') {
                $heading = [string]$Matches[1]
                $inMapping = ($heading -match '(?i)Global\s+Rule\s*[-=]+>\s*Repo\s+Action|Repo\s+Action|规则.+项目')
                continue
            }
            if (-not $inMapping -or $line -notmatch '^\s*-\s+') { continue }
            $segments = New-Object System.Collections.Generic.List[object]
            $inlineMappings = [regex]::Matches($line, '(?:^\s*-\s*|[;；]\s*)`(?<id>[^`]+)`\s*[:：]\s*(?<action>.*?)(?=(?:[;；]\s*`[^`]+`\s*[:：])|$)')
            foreach ($mapping in @($inlineMappings)) {
                $segments.Add([pscustomobject]@{ id = [string]$mapping.Groups['id'].Value; action = [string]$mapping.Groups['action'].Value }) | Out-Null
            }
            if ($segments.Count -eq 0 -and $line -match '^\s*-\s+(?<id>[^:：]+?)\s*[:：]\s*(?<action>.+?)\s*$') {
                $segments.Add([pscustomobject]@{ id = [string]$Matches['id']; action = [string]$Matches['action'] }) | Out-Null
            }
            foreach ($segment in @($segments.ToArray())) {
                $id = ([string]$segment.id).Trim()
                $action = ([string]$segment.action).Trim()
                if ([string]::IsNullOrWhiteSpace($id) -or [string]::IsNullOrWhiteSpace($action)) { continue }
                if (-not $constraints.Contains($id)) {
                    $constraints[$id] = [pscustomobject][ordered]@{
                        constraint_id = $id; common_intent = $action; platform_deltas = @(); project_actions = @($action)
                        enforcement_refs = @(); evidence = @([pscustomobject]@{ type = 'rule_mapping'; path = $path; line = $index + 1 })
                        need_kind = 'project_guidance'
                    }
                }
                else {
                    $constraints[$id].project_actions = @($constraints[$id].project_actions) + @($action)
                    $constraints[$id].evidence = @($constraints[$id].evidence) + @([pscustomobject]@{ type = 'rule_mapping'; path = $path; line = $index + 1 })
                }
            }
        }
    }
    return @($constraints.Values)
}

function Get-RuleAuditReferences {
    param([object[]]$Documents = @())
    $references = [ordered]@{}
    foreach ($document in @($Documents)) {
        $path = [string](Get-OperationObjectProperty $document 'path')
        if (-not [System.IO.File]::Exists($path)) { continue }
        $text = [System.IO.File]::ReadAllText($path)
        foreach ($match in @([regex]::Matches($text, '`([^`\r\n]+)`'))) {
            $value = ([string]$match.Groups[1].Value).Trim()
            $kind = $null
            if ($value -match '^(?i)(pwsh|powershell|python|py|node|npm|npx|dotnet|git)\s+') { $kind = 'command' }
            else {
                $rooted = [System.IO.Path]::IsPathRooted($value)
                $boundedToken = ($value -notmatch '\s' -and $value -notmatch '[*?<>|]')
                $pathShape = ($value -match '^[.][\\/]' -or $value -match '[\\/]$' -or $value -match '(?i)\.(ps1|py|json|ya?ml|md|toml|xml|csproj|sln)$')
                if ($rooted -or ($boundedToken -and $pathShape)) { $kind = 'path' }
            }
            if ($null -eq $kind) { continue }
            $key = '{0}|{1}' -f $kind, $value.ToLowerInvariant()
            if (-not $references.Contains($key)) { $references[$key] = [pscustomobject]@{ kind = $kind; value = $value; source_type = 'rule' } }
        }
    }
    return @($references.Values)
}

function Get-RuleEstateNormalizedPath([string]$Path, [string]$BasePath = '') {
    if ([string]::IsNullOrWhiteSpace($Path)) { return '' }
    $expanded = [Environment]::ExpandEnvironmentVariables($Path.Trim())
    if ($expanded -eq '~' -or $expanded.StartsWith('~\') -or $expanded.StartsWith('~/')) {
        $home = [Environment]::GetFolderPath('UserProfile')
        $expanded = if ($expanded.Length -eq 1) { $home } else { Join-Path $home $expanded.Substring(2) }
    }
    if (-not [System.IO.Path]::IsPathRooted($expanded)) {
        if ([string]::IsNullOrWhiteSpace($BasePath)) { throw 'Relative paths require an explicit base path.' }
        $expanded = Join-Path $BasePath $expanded
    }
    return [System.IO.Path]::GetFullPath($expanded).TrimEnd('\', '/')
}

function Get-RuleEstateTargets {
    param(
        [Parameter(Mandatory = $true)][string]$WorkspaceRoot,
        [string[]]$ExcludeNames = @('external', '文档'),
        [object[]]$RegistryTargets = @(),
        [int]$MaxTargets = 64
    )
    $root = Get-RuleEstateNormalizedPath $WorkspaceRoot
    if (-not [System.IO.Directory]::Exists($root)) { throw ('Workspace root does not exist: {0}' -f $root) }
    if ($MaxTargets -lt 1 -or $MaxTargets -gt 512) { throw 'MaxTargets must be between 1 and 512.' }
    $excluded = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($name in @($ExcludeNames)) { if (-not [string]::IsNullOrWhiteSpace($name)) { $excluded.Add($name.Trim()) | Out-Null } }
    $targets = New-Object System.Collections.Generic.List[object]
    foreach ($directory in @([System.IO.Directory]::GetDirectories($root) | Sort-Object)) {
        $name = [System.IO.Path]::GetFileName($directory)
        if ($excluded.Contains($name)) { continue }
        $gitMarker = Join-Path $directory '.git'
        if (-not [System.IO.Directory]::Exists($gitMarker) -and -not [System.IO.File]::Exists($gitMarker)) { continue }
        $targets.Add([pscustomobject][ordered]@{
            name = $name
            path = [System.IO.Path]::GetFullPath($directory).TrimEnd('\', '/')
            git_marker = $gitMarker
            agents_path = Join-Path $directory 'AGENTS.md'
            agents_exists = [System.IO.File]::Exists((Join-Path $directory 'AGENTS.md'))
            claude_path = Join-Path $directory 'CLAUDE.md'
            claude_exists = [System.IO.File]::Exists((Join-Path $directory 'CLAUDE.md'))
        }) | Out-Null
    }
    if ($targets.Count -gt $MaxTargets) { throw ('Discovered target count exceeds the bounded limit: {0} > {1}.' -f $targets.Count, $MaxTargets) }

    $discovered = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($target in $targets) { $discovered.Add([string]$target.path) | Out-Null }
    $registered = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($entry in @($RegistryTargets)) {
        $enabled = if ($null -ne $entry -and $entry.PSObject.Properties.Match('enabled').Count -gt 0) { [bool]$entry.enabled } else { $true }
        if (-not $enabled) { continue }
        $path = Get-RuleEstateNormalizedPath ([string]$entry.path) $root
        if (-not [string]::IsNullOrWhiteSpace($path)) { $registered.Add($path) | Out-Null }
    }
    $registrySupplied = (@($RegistryTargets).Count -gt 0)
    $unregistered = if ($registrySupplied) { @($targets | Where-Object { -not $registered.Contains([string]$_.path) } | ForEach-Object { [string]$_.path }) } else { @() }
    $missing = if ($registrySupplied) { @($registered | Where-Object { -not $discovered.Contains([string]$_) } | Sort-Object) } else { @() }
    return [pscustomobject][ordered]@{
        schema_version = 1
        workspace_root = $root
        exclusion_names = @($excluded | Sort-Object)
        targets = @($targets.ToArray())
        target_count = $targets.Count
        registry = [pscustomobject][ordered]@{
            supplied = $registrySupplied
            registered_count = $registered.Count
            unregistered_paths = @($unregistered)
            missing_paths = @($missing)
            in_sync = ($unregistered.Count -eq 0 -and $missing.Count -eq 0)
        }
        writes = 0
    }
}

function Get-RuleEstateMarkdownSection([string]$Text, [string]$SectionName) {
    if ([string]::IsNullOrWhiteSpace($Text)) { return '' }
    $pattern = '(?ms)^##\s+' + [regex]::Escape($SectionName) + '(?:\.|\b).*?(?=^##\s+|\z)'
    $match = [regex]::Match($Text, $pattern)
    if (-not $match.Success) { return '' }
    return ($match.Value -replace "`r`n", "`n").Trim()
}

function Get-RuleEstateInlineField([string]$Line, [string]$Name) {
    $match = [regex]::Match($Line, '(?i)(?:^|[`、,，;；\s])' + [regex]::Escape($Name) + '\s*=\s*(?:`(?<quoted>[^`]+)`|(?<plain>[^`、,，;；\r\n]+))')
    if (-not $match.Success) { return '' }
    $value = if ($match.Groups['quoted'].Success) { [string]$match.Groups['quoted'].Value } else { [string]$match.Groups['plain'].Value }
    return $value.Trim()
}

function Get-RuleEstateNaFindings([string]$ProjectText, [string]$AgentsPath) {
    $findings = New-Object System.Collections.Generic.List[object]
    $lines = @($ProjectText -split "`r?`n")
    for ($index = 0; $index -lt $lines.Count; $index++) {
        $line = [string]$lines[$index]
        if ($line -notmatch '(?i)`(?:platform_na|gate_na)`') { continue }
        $invalid = New-Object System.Collections.Generic.List[string]
        $values = [ordered]@{}
        foreach ($field in @('reason','alternative_verification','evidence_link','expires_at','recovery_condition')) {
            $values[$field] = Get-RuleEstateInlineField $line $field
            if ([string]::IsNullOrWhiteSpace([string]$values[$field])) { $invalid.Add($field) | Out-Null }
        }
        $expires = [string]$values['expires_at']
        $parsedExpiry = [datetime]::MinValue
        if (-not [string]::IsNullOrWhiteSpace($expires) -and ($expires -notmatch '^\d{4}-\d{2}-\d{2}$' -or -not [datetime]::TryParseExact($expires, 'yyyy-MM-dd', [Globalization.CultureInfo]::InvariantCulture, [Globalization.DateTimeStyles]::None, [ref]$parsedExpiry))) {
            $invalid.Add('expires_at_iso_date') | Out-Null
        }
        elseif ($parsedExpiry -ne [datetime]::MinValue -and $parsedExpiry.Date -lt [datetime]::UtcNow.Date) {
            $findings.Add([pscustomobject][ordered]@{
                code = 'project_na_expired'; severity = 'error'; path = $AgentsPath; line = $index + 1
                expires_at = $expires; disposition = 'adapt'
                message = 'N/A record has expired and must be revalidated or removed.'
            }) | Out-Null
        }
        $evidence = [string]$values['evidence_link']
        if (-not [string]::IsNullOrWhiteSpace($evidence)) {
            $evidencePath = ($evidence -split '#', 2)[0].Trim()
            if ([string]::IsNullOrWhiteSpace($evidencePath) -or $evidencePath.EndsWith('/') -or $evidencePath.EndsWith('\') -or [System.IO.Path]::GetExtension($evidencePath) -notin @('.md','.json','.csv','.txt','.log')) { $invalid.Add('evidence_link_file') | Out-Null }
            elseif ($invalid.Count -eq 0) {
                try {
                    $repoRoot = [System.IO.Path]::GetDirectoryName([System.IO.Path]::GetFullPath($AgentsPath))
                    $resolvedEvidence = if ([System.IO.Path]::IsPathRooted($evidencePath)) { [System.IO.Path]::GetFullPath($evidencePath) } else { [System.IO.Path]::GetFullPath((Join-Path $repoRoot $evidencePath)) }
                    if (-not (Test-RuleDiscoveryPathWithin $resolvedEvidence $repoRoot) -or -not [System.IO.File]::Exists($resolvedEvidence)) {
                        $findings.Add([pscustomobject][ordered]@{
                            code = 'project_na_evidence_missing'; severity = 'error'; path = $AgentsPath; line = $index + 1
                            evidence_link = $evidence; resolved_path = $resolvedEvidence; disposition = 'adapt'
                            message = 'N/A evidence_link must resolve to an existing file inside the repository.'
                        }) | Out-Null
                    }
                }
                catch {
                    $findings.Add([pscustomobject][ordered]@{
                        code = 'project_na_evidence_missing'; severity = 'error'; path = $AgentsPath; line = $index + 1
                        evidence_link = $evidence; resolved_path = ''; disposition = 'adapt'
                        message = 'N/A evidence_link could not be resolved inside the repository.'
                    }) | Out-Null
                }
            }
            else {
                try {
                    $repoRoot = [System.IO.Path]::GetDirectoryName([System.IO.Path]::GetFullPath($AgentsPath))
                    $resolvedEvidence = if ([System.IO.Path]::IsPathRooted($evidencePath)) { [System.IO.Path]::GetFullPath($evidencePath) } else { [System.IO.Path]::GetFullPath((Join-Path $repoRoot $evidencePath)) }
                    if (-not (Test-RuleDiscoveryPathWithin $resolvedEvidence $repoRoot) -or -not [System.IO.File]::Exists($resolvedEvidence)) {
                        $findings.Add([pscustomobject][ordered]@{ code = 'project_na_evidence_missing'; severity = 'error'; path = $AgentsPath; line = $index + 1; evidence_link = $evidence; resolved_path = $resolvedEvidence; disposition = 'adapt'; message = 'N/A evidence_link must resolve to an existing repository file.' }) | Out-Null
                    }
                }
                catch {
                    $findings.Add([pscustomobject][ordered]@{ code = 'project_na_evidence_missing'; severity = 'error'; path = $AgentsPath; line = $index + 1; evidence_link = $evidence; resolved_path = ''; disposition = 'adapt'; message = 'N/A evidence_link could not be resolved inside the repository.' }) | Out-Null
                }
            }
        }
        if ($invalid.Count -gt 0) {
            $findings.Add([pscustomobject][ordered]@{
                code = 'project_na_invalid'; severity = 'error'; path = $AgentsPath; line = $index + 1
                invalid_fields = @($invalid.ToArray() | Sort-Object -Unique); disposition = 'adapt'
                message = 'N/A record must provide reason, alternative verification, a concrete evidence file, an ISO expiry date, and a recovery condition.'
            }) | Out-Null
        }
    }
    return @($findings.ToArray())
}

function Invoke-RuleEstateGitQuery([string]$RepoRoot, [string[]]$Arguments) {
    $start = [System.Diagnostics.ProcessStartInfo]::new()
    $start.FileName = 'git'
    $start.UseShellExecute = $false
    $start.RedirectStandardOutput = $true
    $start.RedirectStandardError = $true
    $start.CreateNoWindow = $true
    $start.ArgumentList.Add('-C')
    $start.ArgumentList.Add($RepoRoot)
    foreach ($argument in @($Arguments)) { $start.ArgumentList.Add([string]$argument) }
    $process = [System.Diagnostics.Process]::new()
    $process.StartInfo = $start
    if (-not $process.Start()) { return [pscustomobject]@{ exit_code = 1; output = ''; error = 'git process did not start' } }
    $output = $process.StandardOutput.ReadToEnd().Trim()
    $errorText = $process.StandardError.ReadToEnd().Trim()
    $process.WaitForExit()
    return [pscustomobject]@{ exit_code = $process.ExitCode; output = $output; error = $errorText }
}

function Get-RuleEstateGitProfileFindings([string]$ProjectText, [string]$AgentsPath) {
    $findings = New-Object System.Collections.Generic.List[object]
    $repoRoot = [System.IO.Path]::GetDirectoryName([System.IO.Path]::GetFullPath($AgentsPath))
    $profileLine = @($ProjectText -split "`r?`n" | Where-Object { $_ -match '(?i)Git\s+profile\s*:' } | Select-Object -First 1)
    if ($profileLine.Count -eq 0) {
        $findings.Add([pscustomobject]@{ code = 'project_git_profile_missing'; severity = 'error'; path = $AgentsPath; disposition = 'adapt'; message = 'Project contract must declare Git profile baseline and upstream.' }) | Out-Null
        return @($findings.ToArray())
    }
    $line = [string]$profileLine[0]
    $baseline = Get-RuleEstateInlineField $line 'baseline'
    $upstream = Get-RuleEstateInlineField $line 'upstream'
    if ([string]::IsNullOrWhiteSpace($baseline) -or [string]::IsNullOrWhiteSpace($upstream)) {
        $findings.Add([pscustomobject]@{ code = 'project_git_profile_invalid'; severity = 'error'; path = $AgentsPath; disposition = 'adapt'; message = 'Git profile must provide non-empty baseline and upstream fields.' }) | Out-Null
        return @($findings.ToArray())
    }

    $head = Invoke-RuleEstateGitQuery $repoRoot @('symbolic-ref', '--quiet', '--short', 'HEAD')
    $baselineRef = Invoke-RuleEstateGitQuery $repoRoot @('show-ref', '--verify', '--quiet', ('refs/heads/{0}' -f $baseline))
    if (($head.exit_code -ne 0 -or $head.output -ne $baseline) -and $baselineRef.exit_code -ne 0) {
        $findings.Add([pscustomobject]@{ code = 'project_git_baseline_mismatch'; severity = 'error'; path = $AgentsPath; declared = $baseline; observed_head = $head.output; disposition = 'adapt'; message = 'Declared Git baseline is neither the symbolic HEAD nor an existing local branch.' }) | Out-Null
    }

    $remotesResult = Invoke-RuleEstateGitQuery $repoRoot @('remote')
    $remotes = @($remotesResult.output -split "`r?`n" | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    if ($upstream -eq 'none') {
        $hasNoRemoteNa = [regex]::IsMatch($ProjectText, '(?im)^.*`gate_na`.*(?:Git\s+remote|upstream|remote).*?$')
        if ($remotes.Count -ne 0 -or -not $hasNoRemoteNa) {
            $findings.Add([pscustomobject]@{ code = 'project_git_upstream_mismatch'; severity = 'error'; path = $AgentsPath; declared = 'none'; observed_remotes = $remotes; disposition = 'adapt'; message = 'A no-upstream Git profile requires zero configured remotes and a bounded gate_na record.' }) | Out-Null
        }
    }
    else {
        $parts = @($upstream -split '/', 2)
        $remoteExists = $parts.Count -eq 2 -and $remotes -contains $parts[0]
        $remoteRef = if ($parts.Count -eq 2) { Invoke-RuleEstateGitQuery $repoRoot @('show-ref', '--verify', '--quiet', ('refs/remotes/{0}' -f $upstream)) } else { [pscustomobject]@{ exit_code = 1 } }
        $tracking = Invoke-RuleEstateGitQuery $repoRoot @('for-each-ref', '--format=%(upstream:short)', ('refs/heads/{0}' -f $baseline))
        if (-not $remoteExists -or $remoteRef.exit_code -ne 0 -or $tracking.output -ne $upstream) {
            $findings.Add([pscustomobject]@{ code = 'project_git_upstream_mismatch'; severity = 'error'; path = $AgentsPath; declared = $upstream; observed_tracking = $tracking.output; observed_remotes = $remotes; disposition = 'adapt'; message = 'Declared Git upstream must exist as a remote-tracking ref and match the baseline branch tracking configuration.' }) | Out-Null
        }
    }
    return @($findings.ToArray())
}

function Get-RuleEstateGlobalDocument([string]$UserRoot, [ValidateSet('codex', 'claude')][string]$HostName) {
    if ([string]::IsNullOrWhiteSpace($UserRoot)) { return $null }
    $root = Get-RuleEstateNormalizedPath $UserRoot
    $names = if ($HostName -eq 'codex') { @('AGENTS.override.md', 'AGENTS.md') } else { @('CLAUDE.md') }
    foreach ($name in $names) {
        $path = Join-Path $root $name
        if ([System.IO.File]::Exists($path)) {
            $text = [System.IO.File]::ReadAllText($path)
            if ([string]::IsNullOrWhiteSpace($text)) { continue }
            return [pscustomobject][ordered]@{ host = $HostName; path = $path; text = $text; hash = Get-RulePatchTextHash $text }
        }
    }
    return $null
}

function Get-RuleEstateGlobalAlignment([string]$CodexUserRoot, [string]$ClaudeUserRoot) {
    $codex = Get-RuleEstateGlobalDocument $CodexUserRoot codex
    $claude = Get-RuleEstateGlobalDocument $ClaudeUserRoot claude
    $sections = New-Object System.Collections.Generic.List[object]
    $findings = New-Object System.Collections.Generic.List[object]
    foreach ($document in @(
        [pscustomobject]@{ host = 'codex'; value = $codex },
        [pscustomobject]@{ host = 'claude'; value = $claude }
    )) {
        $text = if ($null -eq $document.value) { '' } else { [string]$document.value.text }
        if ([string]::IsNullOrWhiteSpace((Get-RuleEstateMarkdownSection $text '1'))) {
            $findings.Add([pscustomobject][ordered]@{ code = 'global_contract_section_missing'; severity = 'error'; host = [string]$document.host; section = '1'; path = if ($null -eq $document.value) { '' } else { [string]$document.value.path }; disposition = 'adapt'; message = 'Global rule contract section 1 is missing.' }) | Out-Null
        }
    }
    foreach ($name in @('A', 'C', 'D')) {
        $codexText = if ($null -eq $codex) { '' } else { Get-RuleEstateMarkdownSection ([string]$codex.text) $name }
        $claudeText = if ($null -eq $claude) { '' } else { Get-RuleEstateMarkdownSection ([string]$claude.text) $name }
        $aligned = -not [string]::IsNullOrWhiteSpace($codexText) -and $codexText -ceq $claudeText
        $sections.Add([pscustomobject][ordered]@{
            section = $name
            aligned = $aligned
            codex_hash = if ([string]::IsNullOrWhiteSpace($codexText)) { '' } else { Get-RulePatchTextHash $codexText }
            claude_hash = if ([string]::IsNullOrWhiteSpace($claudeText)) { '' } else { Get-RulePatchTextHash $claudeText }
        }) | Out-Null
        if (-not $aligned) { $findings.Add([pscustomobject][ordered]@{ code = 'global_common_section_drift'; severity = 'error'; section = $name; disposition = 'adapt'; message = ('Codex and Claude global common section {0} is absent or different.' -f $name) }) | Out-Null }
        if ($name -eq 'A' -and $codexText -match '(?i)send_message_to_thread|codex_delegation|source_thread_id|non-managed hook|specialized tool path') {
            $tokens = @([regex]::Matches($codexText, '(?i)send_message_to_thread|codex_delegation|source_thread_id|non-managed hook|specialized tool path') | ForEach-Object { $_.Value.ToLowerInvariant() } | Sort-Object -Unique)
            $findings.Add([pscustomobject][ordered]@{ code = 'global_common_platform_leak'; severity = 'error'; section = 'A'; tokens = $tokens; disposition = 'adapt'; message = 'Common section A contains Codex-specific tool or hook implementation details that belong in platform delta B.' }) | Out-Null
        }
    }
    $codexDelta = if ($null -eq $codex) { '' } else { Get-RuleEstateMarkdownSection ([string]$codex.text) 'B' }
    $claudeDelta = if ($null -eq $claude) { '' } else { Get-RuleEstateMarkdownSection ([string]$claude.text) 'B' }
    if ([string]::IsNullOrWhiteSpace($codexDelta)) { $findings.Add([pscustomobject]@{ code = 'codex_platform_delta_missing'; severity = 'error'; section = 'B'; disposition = 'adapt'; message = 'Codex global platform delta section B is missing.' }) | Out-Null }
    if ([string]::IsNullOrWhiteSpace($claudeDelta)) { $findings.Add([pscustomobject]@{ code = 'claude_platform_delta_missing'; severity = 'error'; section = 'B'; disposition = 'adapt'; message = 'Claude global platform delta section B is missing.' }) | Out-Null }
    if (-not [string]::IsNullOrWhiteSpace($codexDelta) -and $codexDelta -ceq $claudeDelta) { $findings.Add([pscustomobject]@{ code = 'platform_delta_not_distinct'; severity = 'error'; section = 'B'; disposition = 'adapt'; message = 'Codex and Claude platform delta sections are identical; verify that host-specific loading and enforcement facts were not flattened.' }) | Out-Null }

    $budgets = New-Object System.Collections.Generic.List[object]
    foreach ($document in @($codex, $claude)) {
        if ($null -eq $document) { continue }
        $text = [string]$document.text
        $byteCount = [System.Text.Encoding]::UTF8.GetByteCount($text)
        $lineCount = @($text -split "`r?`n").Count
        $withinBudget = $byteCount -le 16384 -and $lineCount -le 130
        $byteHeadroom = 16384 - $byteCount; $lineHeadroom = 130 - $lineCount
        $budgetRatio = [math]::Max(($byteCount / 16384), ($lineCount / 130))
        $budgetState = if (-not $withinBudget) { 'exceeded' } elseif ($budgetRatio -ge 0.95) { 'addition_blocked' } elseif ($budgetRatio -ge 0.85) { 'warning' } else { 'healthy' }
        $lowHeadroom = $budgetState -in @('warning', 'addition_blocked')
        $budgets.Add([pscustomobject][ordered]@{ host = [string]$document.host; path = [string]$document.path; bytes = $byteCount; lines = $lineCount; max_bytes = 16384; max_lines = 130; byte_headroom = $byteHeadroom; line_headroom = $lineHeadroom; ratio = [math]::Round($budgetRatio, 4); state = $budgetState; within_budget = $withinBudget; low_headroom = $lowHeadroom }) | Out-Null
        if (-not $withinBudget) { $findings.Add([pscustomobject]@{ code = 'global_rule_budget_exceeded'; severity = 'error'; path = [string]$document.path; disposition = 'adapt'; message = ('Global rule uses {0} bytes/{1} lines; profile budget is 16384 bytes/130 lines.' -f $byteCount, $lineCount) }) | Out-Null }
        elseif ($lowHeadroom) {
            $stateCode = if ($budgetState -eq 'addition_blocked') { 'global_rule_budget_addition_blocked' } else { 'global_rule_budget_warning' }
            $findings.Add([pscustomobject]@{ code = $stateCode; severity = 'warning'; path = [string]$document.path; disposition = 'adapt'; message = ('Global rule budget state is {0}: {1} bytes and {2} lines remain.' -f $budgetState, $byteHeadroom, $lineHeadroom) }) | Out-Null
            $findings.Add([pscustomobject]@{ code = 'global_rule_budget_low_headroom'; severity = 'warning'; path = [string]$document.path; disposition = 'adapt'; message = ('Global rule has low headroom: {0} bytes and {1} lines remain.' -f $byteHeadroom, $lineHeadroom) }) | Out-Null
        }
    }

    $codexRelease = if ($null -eq $codex) { '' } else { Get-RuleEstateRelease ([string]$codex.text) global }
    $claudeRelease = if ($null -eq $claude) { '' } else { Get-RuleEstateRelease ([string]$claude.text) global }
    $releaseAligned = -not [string]::IsNullOrWhiteSpace($codexRelease) -and $codexRelease -eq $claudeRelease
    if (-not $releaseAligned) { $findings.Add([pscustomobject]@{ code = 'global_release_mismatch'; severity = 'error'; disposition = 'adapt'; expected = $codexRelease; observed = $claudeRelease; message = 'Codex and Claude global rule releases are absent or different.' }) | Out-Null }
    return [pscustomobject][ordered]@{
        codex_path = if ($null -eq $codex) { '' } else { [string]$codex.path }
        claude_path = if ($null -eq $claude) { '' } else { [string]$claude.path }
        common_sections = @($sections.ToArray())
        common_aligned = (@($sections | Where-Object { -not $_.aligned }).Count -eq 0)
        codex_delta_present = -not [string]::IsNullOrWhiteSpace($codexDelta)
        claude_delta_present = -not [string]::IsNullOrWhiteSpace($claudeDelta)
        platform_deltas_distinct = (-not [string]::IsNullOrWhiteSpace($codexDelta) -and -not [string]::IsNullOrWhiteSpace($claudeDelta) -and $codexDelta -cne $claudeDelta)
        releases = [pscustomobject][ordered]@{ codex = $codexRelease; claude = $claudeRelease; aligned = $releaseAligned }
        budgets = @($budgets.ToArray())
        findings = @($findings.ToArray())
    }
}

function Expand-RuleEstateConstraintId([string]$ConstraintId) {
    $value = $ConstraintId.Trim()
    if ($value -match '^(?<prefix>[A-Za-z]+)(?<start>\d+)\s*-\s*(?:[A-Za-z]+)?(?<end>\d+)$') {
        $result = New-Object System.Collections.Generic.List[string]
        $start = [int]$Matches['start']; $end = [int]$Matches['end']; $prefix = [string]$Matches['prefix']
        if ($end -ge $start -and ($end - $start) -le 32) { for ($i = $start; $i -le $end; $i++) { $result.Add(('{0}{1}' -f $prefix.ToUpperInvariant(), $i)) | Out-Null }; return @($result.ToArray()) }
    }
    $parts = @($value -split '/' | ForEach-Object { $_.Trim().ToUpperInvariant() } | Where-Object { $_ -match '^[A-Z]+\d+$' })
    if ($parts.Count -gt 0) { return $parts }
    return @($value.ToUpperInvariant())
}

function Get-RuleEstateProjectActions([string]$AgentsPath) {
    if (-not [System.IO.File]::Exists($AgentsPath)) { return @() }
    $document = New-ObservedRuleDocument $AgentsPath codex repo 0 project_action
    $raw = @(Get-RuleAuditResponsibilityConstraints -Documents @($document))
    $actions = New-Object System.Collections.Generic.List[object]
    foreach ($item in $raw) {
        $expandedIds = @(Expand-RuleEstateConstraintId ([string]$item.constraint_id))
        $projectActions = @($item.project_actions)
        if ($projectActions.Count -eq 0) { $projectActions = @([string]$item.common_intent) }
        $evidenceItems = @($item.evidence)
        foreach ($id in $expandedIds) {
            if ($id -notmatch '^[RES]\d+$') { continue }
            for ($index = 0; $index -lt $projectActions.Count; $index++) {
                $evidence = if ($index -lt $evidenceItems.Count) { @($evidenceItems[$index]) } else { @($evidenceItems) }
                $actions.Add([pscustomobject][ordered]@{ constraint_id = $id; source_constraint_id = [string]$item.constraint_id; grouped = ($expandedIds.Count -gt 1); action = [string]$projectActions[$index]; evidence = $evidence }) | Out-Null
            }
        }
    }
    return @($actions.ToArray())
}

function Get-RuleEstateExpectedConstraintIds([string]$CodexGlobalText, [string]$ClaudeGlobalText) {
    $ids = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
    $contractText = (Get-RuleEstateMarkdownSection $CodexGlobalText 'C') + "`n" + (Get-RuleEstateMarkdownSection $ClaudeGlobalText 'C')
    foreach ($match in @([regex]::Matches($contractText, '(?i)\b(?:[RS]\d+(?:\s*-\s*[RS]?\d+)?|E\d+(?:/E\d+)+)\b'))) {
        foreach ($id in @(Expand-RuleEstateConstraintId ([string]$match.Value))) { $ids.Add($id) | Out-Null }
    }
    return @($ids | Sort-Object)
}

function Get-RuleEstateEnforcementChecks([string]$RepoRoot, [object[]]$ActionMatches) {
    $checks = New-Object System.Collections.Generic.List[object]
    foreach ($actionMatch in @($ActionMatches)) {
        foreach ($match in @([regex]::Matches([string]$actionMatch.action, '`(?<value>[^`\r\n]+)`'))) {
            $value = ([string]$match.Groups['value'].Value).Trim()
            if ($value -match '\s' -or $value -notmatch '(?i)(?:^|[\\/])(?:scripts?|hooks?|config|ci)(?:[\\/]|$)|\.(?:ps1|py|json|ya?ml|toml)$') { continue }
            try {
                $resolved = if ([System.IO.Path]::IsPathRooted($value)) { [System.IO.Path]::GetFullPath($value) } else { [System.IO.Path]::GetFullPath((Join-Path $RepoRoot $value)) }
                $contained = Test-RuleDiscoveryPathWithin $resolved $RepoRoot
                $fileExists = $contained -and [System.IO.File]::Exists($resolved)
                $directoryExists = $contained -and [System.IO.Directory]::Exists($resolved)
                $exists = $fileExists -or $directoryExists
                $kind = if ($fileExists) { 'file' } elseif ($directoryExists) { 'directory' } elseif (-not $contained) { 'outside_repository' } else { 'missing' }
            }
            catch { $resolved = ''; $contained = $false; $exists = $false; $fileExists = $false; $directoryExists = $false; $kind = 'invalid' }
            $checks.Add([pscustomobject][ordered]@{ value = $value; resolved_path = $resolved; contained = $contained; exists = $exists; is_file = $fileExists; is_directory = $directoryExists; kind = $kind; enforceable_file = $fileExists }) | Out-Null
        }
    }
    return @($checks.ToArray() | Sort-Object value -Unique)
}

function Get-RuleEstateRelease([string]$Text, [ValidateSet('global', 'project')][string]$Scope) {
    if ([string]::IsNullOrWhiteSpace($Text)) { return '' }
    $patterns = if ($Scope -eq 'global') {
        @('(?im)^\*\*版本\*\*\s*:\s*(?<version>\d+\.\d+)\s*$', '(?i)GlobalUser/(?:AGENTS|CLAUDE)\.md\s+v(?<version>\d+\.\d+)')
    }
    else {
        @('(?im)^\*\*全局规则复核\*\*\s*:\s*(?<version>\d+\.\d+)\s*$', '(?i)GlobalUser/(?:AGENTS|CLAUDE)\.md\s+v(?<version>\d+\.\d+)')
    }
    foreach ($pattern in $patterns) { $match = [regex]::Match($Text, $pattern); if ($match.Success) { return [string]$match.Groups['version'].Value } }
    return ''
}

function Get-RuleEstateCoverage {
    param([string]$AgentsPath, $GlobalAlignment, [string]$CodexGlobalText, [string]$ClaudeGlobalText)
    $actions = @(Get-RuleEstateProjectActions $AgentsPath)
    $repoRoot = [System.IO.Path]::GetDirectoryName([System.IO.Path]::GetFullPath($AgentsPath))
    $constraints = New-Object System.Collections.Generic.List[object]
    $enforcementChecks = New-Object System.Collections.Generic.List[object]
    $groupedMappings = @($actions | Where-Object grouped | Select-Object source_constraint_id,evidence -Unique)
    $expectedIds = @(Get-RuleEstateExpectedConstraintIds $CodexGlobalText $ClaudeGlobalText)
    $expectedSet = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($id in $expectedIds) { $expectedSet.Add([string]$id) | Out-Null }
    $unknownMappings = @($actions | Where-Object { -not $expectedSet.Contains([string]$_.constraint_id) } | Group-Object constraint_id | ForEach-Object {
        [pscustomobject][ordered]@{ constraint_id = [string]$_.Name; count = $_.Count; evidence = @($_.Group | ForEach-Object { $_.evidence } | ForEach-Object { $_ }) }
    })
    $duplicateMappings = @($actions | Group-Object constraint_id | Where-Object Count -gt 1 | ForEach-Object {
        [pscustomobject][ordered]@{ constraint_id = [string]$_.Name; count = $_.Count; evidence = @($_.Group | ForEach-Object { $_.evidence } | ForEach-Object { $_ }) }
    })
    foreach ($id in $expectedIds) {
        $actionMatches = @($actions | Where-Object { [string]$_.constraint_id -eq $id })
        $checks = @(Get-RuleEstateEnforcementChecks -RepoRoot $repoRoot -ActionMatches $actionMatches)
        foreach ($check in $checks) { $enforcementChecks.Add($check) | Out-Null }
        $constraintPattern = '(?i)(?<![A-Z0-9])' + [regex]::Escape($id) + '(?![A-Z0-9])'
        $codexHas = [regex]::IsMatch($CodexGlobalText, $constraintPattern)
        $claudeHas = [regex]::IsMatch($ClaudeGlobalText, $constraintPattern)
        $platformDeltas = New-Object System.Collections.Generic.List[string]
        if ($GlobalAlignment.codex_delta_present) { $platformDeltas.Add([string]$GlobalAlignment.codex_path) | Out-Null }
        if ($GlobalAlignment.claude_delta_present) { $platformDeltas.Add([string]$GlobalAlignment.claude_path) | Out-Null }
        $constraints.Add([pscustomobject][ordered]@{
            constraint_id = $id
            common_intent = if ($codexHas -and $claudeHas) { 'declared_by_both_global_rules' } else { '' }
            platform_deltas = @($platformDeltas.ToArray())
            project_actions = @($actionMatches | ForEach-Object { [string]$_.action })
            enforcement_refs = @($checks | ForEach-Object { [string]$_.value })
            evidence = @($actionMatches | ForEach-Object { $_.evidence } | ForEach-Object { $_ })
            recovery_condition = if ($actionMatches.Count -eq 0) { 'Add an evidence-backed repository action or an explicit N/A with recovery condition.' } else { '' }
            need_kind = 'project_guidance'
        }) | Out-Null
    }
    $advisor = Invoke-RuleAdvisor -Constraints @($constraints.ToArray())
    $advisor | Add-Member -NotePropertyName enforcement_checks -NotePropertyValue @($enforcementChecks.ToArray())
    $advisor | Add-Member -NotePropertyName grouped_mappings -NotePropertyValue @($groupedMappings)
    $advisor | Add-Member -NotePropertyName unknown_mappings -NotePropertyValue @($unknownMappings)
    $advisor | Add-Member -NotePropertyName duplicate_mappings -NotePropertyValue @($duplicateMappings)
    $advisor | Add-Member -NotePropertyName coverage_kind -NotePropertyValue 'textual_mapping_coverage'
    return $advisor
}

function New-RuleEstateTargetAudit {
    param($Target, [string]$CodexUserRoot, [string]$ClaudeUserRoot, $GlobalAlignment, [string]$CodexGlobalText, [string]$ClaudeGlobalText)
    $codexDiscovery = Get-RuleDiscovery -RepoRoot $Target.path -CurrentDirectory $Target.path -HostName codex -UserRuleRoot $CodexUserRoot
    $claudeDiscovery = Get-RuleDiscovery -RepoRoot $Target.path -CurrentDirectory $Target.path -HostName claude -UserRuleRoot $ClaudeUserRoot
    $scopeProfile = [pscustomobject]@{ max_bytes = 10240; max_lines = 80; global_max_bytes = 16384; global_max_lines = 130; project_max_bytes = 10240; project_max_lines = 80; blocking_codes = @('file_missing') }
    $codexDiagnostics = Invoke-RuleDiagnostics $codexDiscovery $scopeProfile
    $claudeDiagnostics = Invoke-RuleDiagnostics $claudeDiscovery $scopeProfile
    $coverage = Get-RuleEstateCoverage $Target.agents_path $GlobalAlignment $CodexGlobalText $ClaudeGlobalText
    $projectText = if ([System.IO.File]::Exists([string]$Target.agents_path)) { [System.IO.File]::ReadAllText([string]$Target.agents_path) } else { '' }
    $globalRelease = Get-RuleEstateRelease $CodexGlobalText global
    $projectRelease = Get-RuleEstateRelease $projectText project
    $projectBytes = [System.Text.Encoding]::UTF8.GetByteCount($projectText)
    $projectLines = @($projectText -split "`r?`n").Count
    $projectWithinBudget = $projectBytes -le 10240 -and $projectLines -le 80
    $projectByteHeadroom = 10240 - $projectBytes; $projectLineHeadroom = 80 - $projectLines
    $projectLowHeadroom = $projectWithinBudget -and ($projectBytes -ge [math]::Floor(10240 * 0.85) -or $projectByteHeadroom -lt 1024 -or $projectLineHeadroom -lt 5)
    $findings = New-Object System.Collections.Generic.List[object]
    foreach ($finding in @($codexDiagnostics.findings) + @($claudeDiagnostics.findings)) {
        $findingPath = [string](Get-OperationObjectProperty $finding 'path')
        if (-not [string]::IsNullOrWhiteSpace($findingPath) -and (Test-RuleDiscoveryPathWithin $findingPath $Target.path)) { $findings.Add($finding) | Out-Null }
    }
    if (-not [bool]$Target.agents_exists) { $findings.Add([pscustomobject]@{ code = 'project_agents_missing'; severity = 'error'; path = $Target.agents_path; disposition = 'adapt'; message = 'Target repository has no AGENTS.md project contract.' }) | Out-Null }
    if (-not [bool]$Target.claude_exists) { $findings.Add([pscustomobject]@{ code = 'project_claude_wrapper_missing'; severity = 'error'; path = $Target.claude_path; disposition = 'adapt'; message = 'Target repository has no CLAUDE.md adapter or Claude-specific project rule.' }) | Out-Null }
    if ([bool]$Target.agents_exists) {
        foreach ($sectionName in @('1', 'A', 'B', 'C', 'D')) {
            if ([string]::IsNullOrWhiteSpace((Get-RuleEstateMarkdownSection $projectText $sectionName))) { $findings.Add([pscustomobject]@{ code = 'project_contract_section_missing'; severity = 'error'; path = $Target.agents_path; section = $sectionName; disposition = 'adapt'; message = ('Project contract section {0} is missing from the active profile.' -f $sectionName) }) | Out-Null }
        }
    }
    if ([bool]$Target.claude_exists) {
        $claudeBytes = [System.IO.File]::ReadAllBytes([string]$Target.claude_path)
        $claudeText = [System.IO.File]::ReadAllText([string]$Target.claude_path)
        $claudeLines = @($claudeText -split "`r?`n")
        if ($claudeBytes.Length -ge 3 -and $claudeBytes[0] -eq 0xEF -and $claudeBytes[1] -eq 0xBB -and $claudeBytes[2] -eq 0xBF) { $findings.Add([pscustomobject]@{ code = 'project_claude_wrapper_bom'; severity = 'error'; path = $Target.claude_path; disposition = 'adapt'; message = 'Claude project wrapper must begin without a UTF-8 BOM.' }) | Out-Null }
        if ($claudeLines.Count -eq 0 -or $claudeLines[0] -cne '@AGENTS.md') { $findings.Add([pscustomobject]@{ code = 'project_claude_wrapper_first_line_mismatch'; severity = 'error'; path = $Target.claude_path; disposition = 'adapt'; message = 'Claude project wrapper first physical line must be @AGENTS.md for the active shared-contract profile.' }) | Out-Null }
    }
    if (-not [string]::IsNullOrWhiteSpace($globalRelease) -and $projectRelease -ne $globalRelease) { $findings.Add([pscustomobject]@{ code = 'project_global_release_mismatch'; severity = 'warning'; path = $Target.agents_path; disposition = 'adapt'; expected = $globalRelease; observed = $projectRelease; message = ('Project global-rule review is {0}; current global release is {1}.' -f $(if ([string]::IsNullOrWhiteSpace($projectRelease)) { 'undeclared' } else { $projectRelease }), $globalRelease) }) | Out-Null }
    foreach ($item in @($coverage.coverage | Where-Object { $_.coverage -ne 'covered' })) { $findings.Add([pscustomobject]@{ code = 'global_repo_action_gap'; severity = 'warning'; path = $Target.agents_path; constraint_id = $item.constraint_id; disposition = 'adapt'; message = ('Constraint {0} coverage is {1}.' -f $item.constraint_id, $item.coverage) }) | Out-Null }
    foreach ($item in @($coverage.coverage | Where-Object { $_.constraint_id -eq 'S5' -and @($_.enforcement_refs).Count -eq 0 })) { $findings.Add([pscustomobject]@{ code = 'enforcement_reference_required'; severity = 'error'; path = $Target.agents_path; constraint_id = 'S5'; disposition = 'adapt'; message = 'S5 must map to at least one concrete script/config/hook/CI reference.' }) | Out-Null }
    foreach ($check in @($coverage.enforcement_checks | Where-Object { -not $_.exists })) { $findings.Add([pscustomobject]@{ code = 'enforcement_reference_missing'; severity = 'error'; path = $Target.agents_path; reference = $check.value; resolved_path = $check.resolved_path; disposition = 'adapt'; message = ('Mapped deterministic enforcement reference is absent or outside the repository: {0}' -f $check.value) }) | Out-Null }
    foreach ($check in @($coverage.enforcement_checks | Where-Object is_directory)) { $findings.Add([pscustomobject]@{ code = 'enforcement_reference_not_file'; severity = 'error'; path = $Target.agents_path; reference = $check.value; resolved_path = $check.resolved_path; observed_kind = $check.kind; disposition = 'adapt'; message = ('Mapped deterministic enforcement reference must be a concrete file: {0}' -f $check.value) }) | Out-Null }
    foreach ($mapping in @($coverage.grouped_mappings)) { $findings.Add([pscustomobject]@{ code = 'project_mapping_grouped'; severity = 'warning'; path = $Target.agents_path; constraint_id = [string]$mapping.source_constraint_id; disposition = 'adapt'; message = 'Grouped mappings are textual coverage only; map each global constraint to its own repository action.' }) | Out-Null }
    foreach ($mapping in @($coverage.unknown_mappings)) { $findings.Add([pscustomobject]@{ code = 'project_mapping_unknown'; severity = 'warning'; path = $Target.agents_path; constraint_id = [string]$mapping.constraint_id; disposition = 'adapt'; message = 'Project mapping id is not declared by the current global project contract.' }) | Out-Null }
    foreach ($mapping in @($coverage.duplicate_mappings)) { $findings.Add([pscustomobject]@{ code = 'project_mapping_duplicate'; severity = 'warning'; path = $Target.agents_path; constraint_id = [string]$mapping.constraint_id; count = [int]$mapping.count; disposition = 'adapt'; message = 'Map each global constraint exactly once to avoid duplicate or conflicting repository actions.' }) | Out-Null }
    foreach ($finding in @(Get-RuleEstateNaFindings $projectText $Target.agents_path)) { $findings.Add($finding) | Out-Null }
    foreach ($finding in @(Get-RuleEstateGitProfileFindings $projectText $Target.agents_path)) { $findings.Add($finding) | Out-Null }
    if (-not $projectWithinBudget) { $findings.Add([pscustomobject]@{ code = 'project_rule_budget_exceeded'; severity = 'error'; path = $Target.agents_path; disposition = 'adapt'; message = ('Project rule uses {0} bytes/{1} lines; root budget is 10240 bytes/80 lines.' -f $projectBytes, $projectLines) }) | Out-Null }
    elseif ($projectLowHeadroom) { $findings.Add([pscustomobject]@{ code = 'project_rule_budget_low_headroom'; severity = 'warning'; path = $Target.agents_path; disposition = 'adapt'; message = ('Project rule has low headroom: {0} bytes and {1} lines remain.' -f $projectByteHeadroom, $projectLineHeadroom) }) | Out-Null }
    $patchCandidates = @()
    if ([bool]$Target.agents_exists -and -not [bool]$Target.claude_exists) {
        $desired = "@AGENTS.md`n"
        $patchCandidates = @([pscustomobject][ordered]@{
            finding_code = 'project_claude_wrapper_missing'; operation = 'create'; target_path = $Target.claude_path
            desired_text = $desired; desired_hash = Get-RulePatchTextHash $desired; risk = 'low'; review_required = $true
            verification = @('UTF-8 without BOM', 'first physical line equals @AGENTS.md', 'Claude native load remains separate')
        })
    }
    return [pscustomobject][ordered]@{
        name = $Target.name; path = $Target.path
        codex = [pscustomobject][ordered]@{ documents = @($codexDiscovery.documents); findings = @($codexDiagnostics.findings); load_verification = 'not_run' }
        claude = [pscustomobject][ordered]@{ documents = @($claudeDiscovery.documents); findings = @($claudeDiagnostics.findings); load_verification = 'not_run' }
        responsibility = $coverage
        release = [pscustomobject][ordered]@{ global = $globalRelease; project_review = $projectRelease; aligned = (-not [string]::IsNullOrWhiteSpace($globalRelease) -and $projectRelease -eq $globalRelease) }
        budget = [pscustomobject][ordered]@{ bytes = $projectBytes; lines = $projectLines; max_bytes = 10240; max_lines = 80; byte_headroom = $projectByteHeadroom; line_headroom = $projectLineHeadroom; within_budget = $projectWithinBudget; low_headroom = $projectLowHeadroom }
        findings = @($findings.ToArray())
        patch_candidates = @($patchCandidates)
        writes = 0; provider_calls = 0; native_mutations = 0
    }
}

function Invoke-RuleEstateAudit {
    param([string]$WorkspaceRoot, [string[]]$ExcludeNames, [object[]]$RegistryTargets = @(), [string]$CodexUserRoot, [string]$ClaudeUserRoot, [int]$MaxTargets = 64)
    $inventory = Get-RuleEstateTargets -WorkspaceRoot $WorkspaceRoot -ExcludeNames $ExcludeNames -RegistryTargets $RegistryTargets -MaxTargets $MaxTargets
    $alignment = Get-RuleEstateGlobalAlignment $CodexUserRoot $ClaudeUserRoot
    $codexGlobal = Get-RuleEstateGlobalDocument $CodexUserRoot codex
    $claudeGlobal = Get-RuleEstateGlobalDocument $ClaudeUserRoot claude
    $codexText = if ($null -eq $codexGlobal) { '' } else { [string]$codexGlobal.text }
    $claudeText = if ($null -eq $claudeGlobal) { '' } else { [string]$claudeGlobal.text }
    $audits = New-Object System.Collections.Generic.List[object]
    foreach ($target in @($inventory.targets)) { $audits.Add((New-RuleEstateTargetAudit $target $CodexUserRoot $ClaudeUserRoot $alignment $codexText $claudeText)) | Out-Null }
    $findings = @($alignment.findings) + @($audits | ForEach-Object { $_.findings })
    if (-not $inventory.registry.in_sync) { $findings += [pscustomobject]@{ code = 'target_registry_drift'; severity = 'warning'; path = $inventory.workspace_root; disposition = 'adapt'; message = 'Configured audit targets differ from the discovered workspace Git roots.' } }
    $gapCount = @($audits | ForEach-Object { $_.responsibility.coverage } | Where-Object coverage -ne 'covered').Count
    $enforcementCodes = @('enforcement_reference_missing', 'enforcement_reference_required', 'enforcement_reference_not_file')
    $mappingCodes = @('project_mapping_grouped', 'project_mapping_unknown', 'project_mapping_duplicate')
    $mappingIssueCount = @($findings | Where-Object code -in $mappingCodes).Count
    $structuralPass = @($findings | Where-Object severity -eq 'error' | Where-Object code -notin $enforcementCodes).Count -eq 0
    $semanticCoveragePass = $gapCount -eq 0 -and $mappingIssueCount -eq 0
    $enforcementVerified = @($findings | Where-Object code -in $enforcementCodes).Count -eq 0
    return [pscustomobject][ordered]@{
        schema_version = 1; truth_boundary = 'workspace_static_audit'; generated_at = [datetimeoffset]::UtcNow.ToString('o')
        inventory = $inventory; global_alignment = $alignment; targets = @($audits.ToArray())
        summary = [pscustomobject][ordered]@{
            target_count = $inventory.target_count; finding_count = @($findings).Count
            patch_candidate_count = @($audits | ForEach-Object { $_.patch_candidates }).Count
            textual_mapping_covered_count = @($audits | ForEach-Object { $_.responsibility.coverage } | Where-Object coverage -eq 'covered').Count
            semantic_gap_count = $gapCount + $mappingIssueCount
            covered_count = @($audits | ForEach-Object { $_.responsibility.coverage } | Where-Object coverage -eq 'covered').Count
            gap_count = $gapCount
        }
        findings = @($findings); patch_candidates = @($audits | ForEach-Object { $_.patch_candidates })
        command_succeeded = $true; structural_pass = $structuralPass; findings_present = (@($findings).Count -gt 0)
        semantic_coverage_pass = $semanticCoveragePass; enforcement_verified = $enforcementVerified
        reference_basis = @(
            [pscustomobject]@{ authority = 'official'; source = 'https://learn.chatgpt.com/docs/agent-configuration/agents-md'; disposition = 'adopt'; use = 'Codex global/project/nested discovery and precedence' },
            [pscustomobject]@{ authority = 'official'; source = 'https://learn.chatgpt.com/docs/agent-configuration/rules'; disposition = 'adopt'; use = 'Separate prose guidance from deterministic command policy' },
            [pscustomobject]@{ authority = 'repository_evidence'; source = 'docs/product/rule-governance-adoption-matrix.md'; disposition = 'adapt'; use = 'Pinned provenance for the common/platform_delta/project_action responsibility model; referenced runtime remains retired' }
        )
        writes = 0; provider_calls = 0; native_mutations = 0; host_loaded = 'not_run'; live_accepted = 'not_run'
    }
}

function New-RuleEstateFinding([string]$Code, [string]$Path, [string]$Message) {
    return [pscustomobject]@{ code=$Code; severity='error'; path=$Path; message=$Message }
}

function Get-RuleEstateProperty($Object, [string]$Name) {
    if ($null -eq $Object) { return $null }
    $property = $Object.PSObject.Properties[$Name]
    if ($null -eq $property) { return $null }
    return $property.Value
}

function Assert-RuleEstateSafeRoot([string]$Path, [string]$Label) {
    $root=[IO.Path]::GetFullPath($Path).TrimEnd('\','/')
    $drive=[IO.Path]::GetPathRoot($root).TrimEnd('\','/')
    if($root.Equals($drive,[StringComparison]::OrdinalIgnoreCase)){throw ('Drive roots are not valid {0} roots.' -f $Label)}
    if(-not [IO.Directory]::Exists($root)){throw ('{0} root does not exist: {1}' -f $Label,$root)}
    return $root
}

function Test-RuleEstateReparsePath([string]$Path,[string]$BoundaryRoot) {
    $cursor=[IO.Path]::GetFullPath($Path);$boundary=[IO.Path]::GetFullPath($BoundaryRoot).TrimEnd('\','/')
    while($true){
        if([IO.File]::Exists($cursor) -or [IO.Directory]::Exists($cursor)){if(([IO.File]::GetAttributes($cursor) -band [IO.FileAttributes]::ReparsePoint) -ne 0){return $true}}
        if($cursor.TrimEnd('\','/').Equals($boundary,[StringComparison]::OrdinalIgnoreCase)){break}
        $parent=[IO.Directory]::GetParent($cursor);if($null -eq $parent -or -not (Test-RuleDiscoveryPathWithin $parent.FullName $boundary)){break};$cursor=$parent.FullName
    }
    return $false
}

function Test-RuleEstateReviewContract($Review, [string]$ReviewRoot) {
    $findings = New-Object System.Collections.Generic.List[object]
    if ($null -eq $Review) { return [pscustomobject]@{ pass=$false; findings=@((New-RuleEstateFinding 'review_missing' '$' 'Reviewed change-set is required.')) } }
    if ((Get-RuleEstateProperty $Review 'schema_version') -ne 1) { $findings.Add((New-RuleEstateFinding 'review_schema_invalid' '$.schema_version' 'Only review schema version 1 is supported.')) | Out-Null }
    if ([string](Get-RuleEstateProperty $Review 'review_status') -ne 'reviewed') { $findings.Add((New-RuleEstateFinding 'review_status_invalid' '$.review_status' 'Change-set must be explicitly reviewed.')) | Out-Null }
    if ([string](Get-RuleEstateProperty $Review 'reviewed_by_type') -notin @('human','automation_policy') -or [string](Get-RuleEstateProperty $Review 'authorization_source') -notin @('user_supplied','registered_policy')) {
        $findings.Add((New-RuleEstateFinding 'review_authority_invalid' '$.reviewed_by_type' 'AI self-review is not apply authority; use a human review or registered policy.')) | Out-Null
    }
    if ([string]::IsNullOrWhiteSpace([string](Get-RuleEstateProperty $Review 'reviewed_by'))) { $findings.Add((New-RuleEstateFinding 'reviewer_missing' '$.reviewed_by' 'Reviewer identity is required.')) | Out-Null }
    $authorizationRelative = [string](Get-RuleEstateProperty $Review 'authorization_receipt')
    if ([string]::IsNullOrWhiteSpace($authorizationRelative)) {
        $findings.Add((New-RuleEstateFinding 'authorization_receipt_missing' '$.authorization_receipt' 'An independently issued authorization receipt is required.')) | Out-Null
    }
    else {
        $authorizationPath = [IO.Path]::GetFullPath((Join-Path $ReviewRoot $authorizationRelative))
        if (-not (Test-RuleDiscoveryPathWithin $authorizationPath $ReviewRoot) -or -not [IO.File]::Exists($authorizationPath)) { $findings.Add((New-RuleEstateFinding 'authorization_receipt_invalid' '$.authorization_receipt' 'Authorization receipt must exist below the reviewed change-set directory.')) | Out-Null }
        elseif (Test-RuleEstateReparsePath $authorizationPath $ReviewRoot) { $findings.Add((New-RuleEstateFinding 'authorization_receipt_reparse_forbidden' '$.authorization_receipt' 'Authorization receipts reached through reparse points are not accepted.')) | Out-Null }
    }
    $changes = @(Get-RuleEstateProperty $Review 'changes')
    if ($changes.Count -eq 0) { $findings.Add((New-RuleEstateFinding 'review_changes_empty' '$.changes' 'At least one reviewed change is required.')) | Out-Null }
    if ($changes.Count -gt 128) { $findings.Add((New-RuleEstateFinding 'review_changes_limit' '$.changes' 'Reviewed change-set exceeds the 128 action safety limit.')) | Out-Null }
    for ($i=0; $i -lt $changes.Count; $i++) {
        $change = $changes[$i]; $base = '$.changes[{0}]' -f $i
        $scope = [string](Get-RuleEstateProperty $change 'target_scope')
        if ($scope -notin @('repository','global_codex','global_claude')) { $findings.Add((New-RuleEstateFinding 'target_scope_invalid' "$base.target_scope" 'Target scope is not managed by rule estate.')) | Out-Null }
        $file = [string](Get-RuleEstateProperty $change 'target_file')
        $allowed = switch ($scope) { 'global_codex' { @('AGENTS.md') }; 'global_claude' { @('CLAUDE.md') }; default { @('AGENTS.md','CLAUDE.md') } }
        if ($file -notin $allowed -or [IO.Path]::GetFileName($file) -cne $file) { $findings.Add((New-RuleEstateFinding 'target_file_forbidden' "$base.target_file" 'Only exact root rule filenames are accepted; provider, auth, model, sandbox and native host files are excluded.')) | Out-Null }
        if ($scope -eq 'repository' -and [string]::IsNullOrWhiteSpace([string](Get-RuleEstateProperty $change 'repository'))) { $findings.Add((New-RuleEstateFinding 'repository_missing' "$base.repository" 'Repository name is required.')) | Out-Null }
        if (-not [string]::IsNullOrWhiteSpace([string](Get-RuleEstateProperty $change 'risk')) -and [string](Get-RuleEstateProperty $change 'risk') -notin @('low','medium','high')) { $findings.Add((New-RuleEstateFinding 'risk_invalid' "$base.risk" 'Risk must be low, medium, or high.')) | Out-Null }
        $desired = [string](Get-RuleEstateProperty $change 'desired_file')
        if ([string]::IsNullOrWhiteSpace($desired)) { $findings.Add((New-RuleEstateFinding 'desired_file_missing' "$base.desired_file" 'Reviewed desired file is required.')) | Out-Null; continue }
        $desiredPath = [IO.Path]::GetFullPath((Join-Path $ReviewRoot $desired))
        if (-not (Test-RuleDiscoveryPathWithin $desiredPath $ReviewRoot) -or -not [IO.File]::Exists($desiredPath)) { $findings.Add((New-RuleEstateFinding 'desired_file_out_of_review_root' "$base.desired_file" 'Desired files must exist below the reviewed change-set directory.')) | Out-Null }
        elseif (Test-RuleEstateReparsePath $desiredPath $ReviewRoot) { $findings.Add((New-RuleEstateFinding 'desired_file_reparse_forbidden' "$base.desired_file" 'Desired files reached through reparse points are not accepted.')) | Out-Null }
    }
    return [pscustomobject]@{ pass=($findings.Count -eq 0); findings=@($findings.ToArray()) }
}

function Get-RuleEstateAuthorizationReceipt {
    param($Review,[string]$ReviewPath,[string]$WorkspaceRoot,[string]$CodexUserRoot,[string]$ClaudeUserRoot)
    $reviewRoot=[IO.Path]::GetDirectoryName([IO.Path]::GetFullPath($ReviewPath));$relative=[string](Get-RuleEstateProperty $Review 'authorization_receipt')
    if([string]::IsNullOrWhiteSpace($relative)){throw 'Independent authorization receipt is required.'}
    $path=[IO.Path]::GetFullPath((Join-Path $reviewRoot $relative))
    if(-not (Test-RuleDiscoveryPathWithin $path $reviewRoot) -or -not [IO.File]::Exists($path) -or (Test-RuleEstateReparsePath $path $reviewRoot)){throw 'Independent authorization receipt path is invalid.'}
    try{$raw=[IO.File]::ReadAllText($path);$receipt=$raw|ConvertFrom-Json}catch{throw ('Independent authorization receipt is invalid JSON: {0}' -f $_.Exception.Message)}
    if((Get-RuleEstateProperty $receipt 'schema_version') -ne 1 -or [string](Get-RuleEstateProperty $receipt 'domain') -ne 'rule_estate_authorization' -or [string](Get-RuleEstateProperty $receipt 'decision') -ne 'approved'){throw 'Independent authorization receipt is not an approved v1 rule estate receipt.'}
    $authorizationId=[string](Get-RuleEstateProperty $receipt 'authorization_id')
    if($authorizationId -notmatch '^rule-estate-auth-[a-f0-9]{32}$'){throw 'Independent authorization receipt identity is invalid.'}
    if([string](Get-RuleEstateProperty $receipt 'issued_by') -ne [string](Get-RuleEstateProperty $Review 'reviewed_by') -or [string](Get-RuleEstateProperty $receipt 'issued_by_type') -ne [string](Get-RuleEstateProperty $Review 'reviewed_by_type') -or [string](Get-RuleEstateProperty $receipt 'authorization_source') -ne [string](Get-RuleEstateProperty $Review 'authorization_source')){throw 'Independent authorization receipt reviewer identity does not match the review.'}
    $reviewHash=Get-OperationSha256 ([IO.File]::ReadAllText([IO.Path]::GetFullPath($ReviewPath)))
    if([string](Get-RuleEstateProperty $receipt 'review_sha256') -ne $reviewHash){throw 'Independent authorization receipt review hash does not match.'}
    $workspace=[IO.Path]::GetFullPath($WorkspaceRoot);$codex=[IO.Path]::GetFullPath($CodexUserRoot);$claude=[IO.Path]::GetFullPath($ClaudeUserRoot)
    try{$receiptWorkspace=[IO.Path]::GetFullPath([string](Get-RuleEstateProperty $receipt 'workspace_root'));$receiptCodex=[IO.Path]::GetFullPath([string](Get-RuleEstateProperty $receipt 'codex_user_root'));$receiptClaude=[IO.Path]::GetFullPath([string](Get-RuleEstateProperty $receipt 'claude_user_root'))}catch{throw 'Independent authorization receipt roots are invalid.'}
    if($receiptWorkspace -ne $workspace -or $receiptCodex -ne $codex -or $receiptClaude -ne $claude){throw 'Independent authorization receipt roots do not match the requested roots.'}
    if([int](Get-RuleEstateProperty $receipt 'approved_action_count') -ne @((Get-RuleEstateProperty $Review 'changes')).Count){throw 'Independent authorization receipt action count does not match the review.'}
    $issued=[datetimeoffset]::MinValue;$expires=[datetimeoffset]::MinValue
    if(-not [datetimeoffset]::TryParse([string](Get-RuleEstateProperty $receipt 'issued_at'),[ref]$issued) -or -not [datetimeoffset]::TryParse([string](Get-RuleEstateProperty $receipt 'expires_at'),[ref]$expires) -or $expires -le $issued){throw 'Independent authorization receipt validity window is invalid.'}
    if($expires -le [datetimeoffset]::UtcNow){throw 'Independent authorization receipt has expired.'}
    $applyToken=[string](Get-RuleEstateProperty $receipt 'apply_token')
    if($applyToken -cnotmatch '^APPLY_RULE_ESTATE_PATCH_[A-F0-9]{16}$'){throw 'Independent authorization receipt apply token is invalid.'}
    return [pscustomobject][ordered]@{path=$path;content_hash=Get-OperationSha256 $raw;authorization_id=$authorizationId;issued_by=[string](Get-RuleEstateProperty $receipt 'issued_by');issued_by_type=[string](Get-RuleEstateProperty $receipt 'issued_by_type');authorization_source=[string](Get-RuleEstateProperty $receipt 'authorization_source');issued_at=$issued.ToString('o');expires_at=$expires.ToString('o');review_sha256=$reviewHash;approved_action_count=[int](Get-RuleEstateProperty $receipt 'approved_action_count');apply_token=$applyToken}
}

function Get-RuleEstateTargetSetSnapshot([string]$WorkspaceRoot, [string[]]$ExcludeNames=@('external','文档')) {
    $inventory = Get-RuleEstateTargets -WorkspaceRoot $WorkspaceRoot -ExcludeNames $ExcludeNames
    $paths = @($inventory.targets | ForEach-Object { [IO.Path]::GetFullPath([string]$_.path).ToLowerInvariant() } | Sort-Object -Unique)
    return [pscustomobject][ordered]@{ paths=$paths; hash=(Get-OperationSha256 ($paths -join "`n")); count=$paths.Count }
}

function Get-RuleEstateRepositoryDirtyPaths([string]$Root) {
    $output = @(& git -C $Root status --porcelain --untracked-files=all 2>$null)
    if ($LASTEXITCODE -ne 0) { throw ('Unable to inspect repository status: {0}' -f $Root) }
    return @($output | ForEach-Object { [string]$_ } | Sort-Object)
}

function New-RuleEstatePlan {
    param([Parameter(Mandatory=$true)][string]$ReviewPath,[Parameter(Mandatory=$true)][string]$WorkspaceRoot,[Parameter(Mandatory=$true)][string]$CodexUserRoot,[Parameter(Mandatory=$true)][string]$ClaudeUserRoot,[string[]]$ExcludeNames=@('external','文档'))
    $reviewFile = [IO.Path]::GetFullPath($ReviewPath)
    if (-not [IO.File]::Exists($reviewFile)) { throw 'Reviewed change-set does not exist.' }
    $reviewRoot = [IO.Path]::GetDirectoryName($reviewFile)
    $review = [IO.File]::ReadAllText($reviewFile) | ConvertFrom-Json
    $validation = Test-RuleEstateReviewContract $review $reviewRoot
    if (-not $validation.pass) { throw ('Reviewed change-set is invalid: {0}' -f ((@($validation.findings.code) -join ', '))) }
    $workspace = Assert-RuleEstateSafeRoot $WorkspaceRoot 'workspace'
    $codex = Assert-RuleEstateSafeRoot $CodexUserRoot 'Codex user'
    $claude = Assert-RuleEstateSafeRoot $ClaudeUserRoot 'Claude user'
    $authorization = Get-RuleEstateAuthorizationReceipt -Review $review -ReviewPath $reviewFile -WorkspaceRoot $workspace -CodexUserRoot $codex -ClaudeUserRoot $claude
    $inventory = Get-RuleEstateTargets -WorkspaceRoot $workspace -ExcludeNames $ExcludeNames
    $repoByName = @{}
    foreach ($target in @($inventory.targets)) { $repoByName[[string]$target.name] = [string]$target.path }
    $actions = New-Object System.Collections.Generic.List[object]
    $plannedTargets = @{}
    foreach ($change in @(Get-RuleEstateProperty $review 'changes')) {
        $scope = [string](Get-RuleEstateProperty $change 'target_scope')
        $root = switch ($scope) {
            'global_codex' { $codex }
            'global_claude' { $claude }
            default {
                $name = [string](Get-RuleEstateProperty $change 'repository')
                if (-not $repoByName.ContainsKey($name)) { throw ('Reviewed repository is not a current direct Git target: {0}' -f $name) }
                [string]$repoByName[$name]
            }
        }
        $targetPath = Join-Path $root ([string](Get-RuleEstateProperty $change 'target_file'))
        if(Test-RuleEstateReparsePath $targetPath $root){throw ('Reparse points are not accepted by rule estate: {0}' -f $targetPath)}
        $targetKey = [IO.Path]::GetFullPath($targetPath).ToLowerInvariant()
        if ($plannedTargets.ContainsKey($targetKey)) { throw ('Reviewed change-set contains duplicate target: {0}' -f $targetPath) }
        $plannedTargets[$targetKey] = $true
        $desiredPath = [IO.Path]::GetFullPath((Join-Path $reviewRoot ([string](Get-RuleEstateProperty $change 'desired_file'))))
        $exists = [IO.File]::Exists($targetPath)
        $allowCreate = [bool](Get-RuleEstateProperty $change 'allow_create')
        if (-not $exists -and -not $allowCreate) { throw ('Target does not exist and allow_create is false: {0}' -f $targetPath) }
        if ($exists -and $allowCreate) { throw ('allow_create requires an absent target: {0}' -f $targetPath) }
        $current = if ($exists) { [IO.File]::ReadAllText($targetPath) } else { '' }
        $desired = [IO.File]::ReadAllText($desiredPath)
        if ($current -ceq $desired) { throw ('Reviewed target has no changes: {0}' -f $targetPath) }
        $identity = '{0}|{1}|{2}' -f $scope,$targetPath.ToLowerInvariant(),(Get-OperationSha256 $desired)
        $dirtyPaths = if ($scope -eq 'repository') { @(Get-RuleEstateRepositoryDirtyPaths $root) } else { @() }
        $actions.Add([pscustomobject][ordered]@{
            action_id=('estate-{0}' -f (Get-OperationSha256 $identity).Substring(0,16)); target_scope=$scope
            repository=$(if($scope -eq 'repository'){[string](Get-RuleEstateProperty $change 'repository')}else{$null})
            authorized_root=$root; target_path=[IO.Path]::GetFullPath($targetPath); operation=$(if($exists){'update'}else{'create'})
            before_hash=Get-OperationSha256 $current; desired_hash=Get-OperationSha256 $desired; desired_text=$desired
            risk=$(if([string]::IsNullOrWhiteSpace([string](Get-RuleEstateProperty $change 'risk'))){'medium'}else{[string](Get-RuleEstateProperty $change 'risk')})
            evidence_refs=@(Get-RuleEstateProperty $change 'evidence_refs')
            dirty_paths_at_plan=@($dirtyPaths)
        }) | Out-Null
    }
    $targetSet = Get-RuleEstateTargetSetSnapshot $workspace $ExcludeNames
    $planSeed = '{0}|{1}|{2}' -f $workspace,$targetSet.hash,(@($actions | ForEach-Object action_id) -join '|')
    return [pscustomobject][ordered]@{
        schema_version=1; operation_id=('rule-estate-{0}' -f (Get-OperationSha256 $planSeed).Substring(0,16)); domain='rule_estate'; mode='plan'
        generated_at=[datetimeoffset]::UtcNow.ToString('o'); workspace_root=$workspace; exclude_names=@($ExcludeNames); codex_user_root=$codex; claude_user_root=$claude
        review=[pscustomobject]@{ path=$reviewFile; content_hash=Get-OperationSha256 ([IO.File]::ReadAllText($reviewFile)); reviewed_by=[string](Get-RuleEstateProperty $review 'reviewed_by'); reviewed_by_type=[string](Get-RuleEstateProperty $review 'reviewed_by_type'); authorization_source=[string](Get-RuleEstateProperty $review 'authorization_source') }
        authorization=$authorization
        target_set=$targetSet; actions=@($actions.ToArray()); execution='preflight_all_then_apply_one_by_one_fail_fast'
        apply=[pscustomobject]@{ required_token=[string]$authorization.apply_token; dirty_worktree='observe_preserve_unrelated'; target_file_freshness='fail_closed'; target_set_drift='fail_closed'; rollback_scope='per_target' }
        verification=[pscustomobject]@{ repo_verified='not_run'; host_loaded='not_run'; live_accepted='not_run' }
        provider_calls=0; native_mutations=0
    }
}

function Get-RuleEstateLockPath($Action) {
    return Join-Path ([string](Get-RuleEstateProperty $Action 'authorized_root')) '.skills-manager-rule-estate.lock'
}

function Get-RuleEstateTextHashAtPath([string]$Path) {
    if (-not [IO.File]::Exists($Path)) { return Get-OperationSha256 '' }
    return Get-OperationSha256 ([IO.File]::ReadAllText($Path))
}

function Get-RuleEstateBytesHash([byte[]]$Bytes) {
    if ($null -eq $Bytes) { $Bytes = [byte[]]@() }
    return [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($Bytes)).ToLowerInvariant()
}

function Test-RuleEstateApplyPreflight {
    param($Plan,[string]$WorkspaceRoot,[string]$CodexUserRoot,[string]$ClaudeUserRoot,[string[]]$CompletedActionIds=@(),[switch]$IgnoreLocks)
    $findings = New-Object System.Collections.Generic.List[object]
    if ($null -eq $Plan -or (Get-RuleEstateProperty $Plan 'schema_version') -ne 1 -or [string](Get-RuleEstateProperty $Plan 'domain') -ne 'rule_estate') { return [pscustomobject]@{ pass=$false; findings=@((New-RuleEstateFinding 'plan_invalid' '$' 'Rule estate plan is invalid.')) } }
    $workspace = [IO.Path]::GetFullPath($WorkspaceRoot); $codex=[IO.Path]::GetFullPath($CodexUserRoot); $claude=[IO.Path]::GetFullPath($ClaudeUserRoot)
    if ($workspace -ne [IO.Path]::GetFullPath([string](Get-RuleEstateProperty $Plan 'workspace_root')) -or $codex -ne [IO.Path]::GetFullPath([string](Get-RuleEstateProperty $Plan 'codex_user_root')) -or $claude -ne [IO.Path]::GetFullPath([string](Get-RuleEstateProperty $Plan 'claude_user_root'))) { $findings.Add((New-RuleEstateFinding 'authorization_root_mismatch' '$' 'CLI roots must exactly match the plan roots.')) | Out-Null }
    $freshSet = Get-RuleEstateTargetSetSnapshot $workspace @(Get-RuleEstateProperty $Plan 'exclude_names')
    if ($freshSet.hash -ne [string](Get-RuleEstateProperty (Get-RuleEstateProperty $Plan 'target_set') 'hash')) { $findings.Add((New-RuleEstateFinding 'target_set_drift' '$.target_set' 'Workspace direct Git target set changed after planning.')) | Out-Null }
    $review=Get-RuleEstateProperty $Plan 'review';$reviewPath=[string](Get-RuleEstateProperty $review 'path');$reviewDocument=$null
    if(-not [IO.File]::Exists($reviewPath) -or (Get-OperationSha256 ([IO.File]::ReadAllText($reviewPath))) -ne [string](Get-RuleEstateProperty $review 'content_hash')){$findings.Add((New-RuleEstateFinding 'review_stale' '$.review' 'Reviewed change-set changed or disappeared after planning.'))|Out-Null}
    else {
        try{$reviewDocument=[IO.File]::ReadAllText($reviewPath)|ConvertFrom-Json;$reviewValidation=Test-RuleEstateReviewContract $reviewDocument ([IO.Path]::GetDirectoryName($reviewPath));if(-not $reviewValidation.pass){throw ((@($reviewValidation.findings.code))-join ',')}}catch{$findings.Add((New-RuleEstateFinding 'review_stale' '$.review' ('Reviewed change-set is no longer valid: {0}' -f $_.Exception.Message)))|Out-Null}
    }
    $authorization=Get-RuleEstateProperty $Plan 'authorization';$authorizationPath=[string](Get-RuleEstateProperty $authorization 'path');$expires=[datetimeoffset]::MinValue
    if([string]::IsNullOrWhiteSpace($authorizationPath) -or -not [IO.File]::Exists($authorizationPath) -or (Get-OperationSha256 ([IO.File]::ReadAllText($authorizationPath))) -ne [string](Get-RuleEstateProperty $authorization 'content_hash')){$findings.Add((New-RuleEstateFinding 'authorization_receipt_stale' '$.authorization' 'Authorization receipt changed or disappeared after planning.'))|Out-Null}
    elseif(-not [datetimeoffset]::TryParse([string](Get-RuleEstateProperty $authorization 'expires_at'),[ref]$expires) -or $expires -le [datetimeoffset]::UtcNow){$findings.Add((New-RuleEstateFinding 'authorization_receipt_expired' '$.authorization.expires_at' 'Authorization receipt is expired or invalid.'))|Out-Null}
    elseif($null -ne $reviewDocument){
        try {
            $freshAuthorization=Get-RuleEstateAuthorizationReceipt -Review $reviewDocument -ReviewPath $reviewPath -WorkspaceRoot $workspace -CodexUserRoot $codex -ClaudeUserRoot $claude
            if([string]$freshAuthorization.content_hash -ne [string](Get-RuleEstateProperty $authorization 'content_hash') -or [string]$freshAuthorization.authorization_id -ne [string](Get-RuleEstateProperty $authorization 'authorization_id') -or [string]$freshAuthorization.apply_token -ne [string](Get-RuleEstateProperty (Get-RuleEstateProperty $Plan 'apply') 'required_token')){throw 'authorization fields differ from the independently issued receipt'}
        } catch {$findings.Add((New-RuleEstateFinding 'authorization_receipt_invalid' '$.authorization' $_.Exception.Message))|Out-Null}
    }
    if($null -ne $reviewDocument){
        $actions=@(Get-RuleEstateProperty $Plan 'actions');$changes=@(Get-RuleEstateProperty $reviewDocument 'changes')
        if($actions.Count -ne $changes.Count){$findings.Add((New-RuleEstateFinding 'plan_review_binding_mismatch' '$.actions' 'Plan action count does not match the authorized review.'))|Out-Null}
        $actionByTarget=@{}
        foreach($candidate in $actions){$candidatePath=[IO.Path]::GetFullPath([string](Get-RuleEstateProperty $candidate 'target_path')).ToLowerInvariant();if($actionByTarget.ContainsKey($candidatePath)){$actionByTarget[$candidatePath]=$null}else{$actionByTarget[$candidatePath]=$candidate}}
        foreach($change in $changes){
            $scope=[string](Get-RuleEstateProperty $change 'target_scope');$repository=[string](Get-RuleEstateProperty $change 'repository')
            $expectedRoot=switch($scope){'global_codex'{$codex};'global_claude'{$claude};default{[IO.Path]::GetFullPath((Join-Path $workspace $repository))}}
            if([string]::IsNullOrWhiteSpace($expectedRoot)){continue}
            $expectedTarget=[IO.Path]::GetFullPath((Join-Path $expectedRoot ([string](Get-RuleEstateProperty $change 'target_file'))));$desiredPath=[IO.Path]::GetFullPath((Join-Path ([IO.Path]::GetDirectoryName($reviewPath)) ([string](Get-RuleEstateProperty $change 'desired_file'))));$desired=[IO.File]::ReadAllText($desiredPath);$desiredHash=Get-OperationSha256 $desired;$identity='{0}|{1}|{2}' -f $scope,$expectedTarget.ToLowerInvariant(),$desiredHash;$expectedId='estate-{0}' -f (Get-OperationSha256 $identity).Substring(0,16)
            $boundAction=if($actionByTarget.ContainsKey($expectedTarget.ToLowerInvariant())){$actionByTarget[$expectedTarget.ToLowerInvariant()]}else{$null}
            if($null -eq $boundAction -or [string](Get-RuleEstateProperty $boundAction 'target_scope') -ne $scope -or ($scope -eq 'repository' -and [string](Get-RuleEstateProperty $boundAction 'repository') -ne $repository) -or [string](Get-RuleEstateProperty $boundAction 'action_id') -ne $expectedId -or [string](Get-RuleEstateProperty $boundAction 'desired_hash') -ne $desiredHash -or [string](Get-RuleEstateProperty $boundAction 'desired_text') -cne $desired){$findings.Add((New-RuleEstateFinding 'plan_review_binding_mismatch' '$.actions' ('Plan action is not an exact projection of the authorized review target: {0}' -f $expectedTarget)))|Out-Null}
        }
    }
    foreach ($action in @(Get-RuleEstateProperty $Plan 'actions')) {
        $id=[string](Get-RuleEstateProperty $action 'action_id'); $done=$id -in @($CompletedActionIds)
        $path=[IO.Path]::GetFullPath([string](Get-RuleEstateProperty $action 'target_path')); $root=[IO.Path]::GetFullPath([string](Get-RuleEstateProperty $action 'authorized_root')); $scope=[string](Get-RuleEstateProperty $action 'target_scope')
        $expectedRoot = switch($scope){'global_codex'{$codex};'global_claude'{$claude};default{$root}}
        $allowedName = switch($scope){'global_codex'{'AGENTS.md'};'global_claude'{'CLAUDE.md'};default{[IO.Path]::GetFileName($path)}}
        if ($root -ne $expectedRoot -or -not (Test-RuleDiscoveryPathWithin $path $root) -or [IO.Path]::GetFileName($path) -cne $allowedName -or ($scope -eq 'repository' -and [IO.Path]::GetFileName($path) -notin @('AGENTS.md','CLAUDE.md'))) { $findings.Add((New-RuleEstateFinding 'target_out_of_scope' '$.actions' 'Plan target is outside the exact managed rule allowlist.')) | Out-Null }
        if(Test-RuleEstateReparsePath $path $root){$findings.Add((New-RuleEstateFinding 'target_reparse_forbidden' $path 'Reparse points are not accepted by rule estate.'))|Out-Null}
        $currentHash=Get-RuleEstateTextHashAtPath $path; $expectedHash=if($done){[string](Get-RuleEstateProperty $action 'desired_hash')}else{[string](Get-RuleEstateProperty $action 'before_hash')}
        if ($currentHash -ne $expectedHash) { $findings.Add((New-RuleEstateFinding 'target_hash_stale' $path 'Target content no longer matches the planned state.')) | Out-Null }
        if((Get-OperationSha256 ([string](Get-RuleEstateProperty $action 'desired_text'))) -ne [string](Get-RuleEstateProperty $action 'desired_hash')){$findings.Add((New-RuleEstateFinding 'desired_hash_mismatch' '$.actions' 'Desired text does not match the planned hash.'))|Out-Null}
        if (-not $IgnoreLocks -and [IO.File]::Exists((Get-RuleEstateLockPath $action))) { $findings.Add((New-RuleEstateFinding 'target_locked' (Get-RuleEstateLockPath $action) 'Another rule estate writer holds this target lock.')) | Out-Null }
    }
    return [pscustomobject]@{ pass=($findings.Count -eq 0); findings=@($findings.ToArray()) }
}

function Write-RuleEstateReceipt([string]$Path, $Receipt) {
    Write-Utf8FileAtomic -Path $Path -Content ($Receipt | ConvertTo-Json -Depth 40)
}

function Invoke-RuleEstateApply {
    param($Plan,[string]$WorkspaceRoot,[string]$CodexUserRoot,[string]$ClaudeUserRoot,[string]$Token,[string]$ReceiptPath,[string]$ResumeReceiptPath=$null,[string]$TestFailBeforeActionId=$null,[scriptblock]$TestHookAfterLocksAcquired=$null)
    $expectedToken=[string](Get-RuleEstateProperty (Get-RuleEstateProperty $Plan 'apply') 'required_token')
    if ([string]::IsNullOrWhiteSpace($expectedToken) -or $Token -cne $expectedToken) { return [pscustomobject]@{ pass=$false; status='blocked'; findings=@((New-RuleEstateFinding 'apply_token_invalid' '$.apply.required_token' 'Explicit estate apply token does not match the independent authorization receipt.')); writes=0; receipt=$null } }
    $receiptFile=[IO.Path]::GetFullPath($ReceiptPath); $existing=$null
    if (-not [string]::IsNullOrWhiteSpace($ResumeReceiptPath)) {
        $resumeFile=[IO.Path]::GetFullPath($ResumeReceiptPath)
        if (-not [IO.File]::Exists($resumeFile)) { throw 'Resume receipt does not exist.' }
        $existing=[IO.File]::ReadAllText($resumeFile)|ConvertFrom-Json
        if ([string](Get-RuleEstateProperty $existing 'operation_id') -ne [string](Get-RuleEstateProperty $Plan 'operation_id')) { throw 'Resume receipt belongs to another plan.' }
    }
    $completedIds=@()
    if($null -ne $existing){$completedIds=@(Get-RuleEstateProperty $existing 'actions'|Where-Object{[string](Get-RuleEstateProperty $_ 'status') -eq 'applied'}|ForEach-Object{[string](Get-RuleEstateProperty $_ 'action_id')})}
    $preflight=Test-RuleEstateApplyPreflight $Plan $WorkspaceRoot $CodexUserRoot $ClaudeUserRoot $completedIds
    if(-not $preflight.pass){return [pscustomobject]@{pass=$false;status='blocked';findings=@($preflight.findings);writes=0;receipt=$existing}}
    $receipt=if($null -ne $existing){$existing}else{[pscustomobject][ordered]@{schema_version=1;operation_id=[string](Get-RuleEstateProperty $Plan 'operation_id');status='in_progress';started_at=[datetimeoffset]::UtcNow.ToString('o');completed_at=$null;workspace_root=[string](Get-RuleEstateProperty $Plan 'workspace_root');codex_user_root=[string](Get-RuleEstateProperty $Plan 'codex_user_root');claude_user_root=[string](Get-RuleEstateProperty $Plan 'claude_user_root');actions=@();verification=[pscustomobject]@{repo_verified='not_run';host_loaded='not_run';live_accepted='not_run'}}}
    $actionResults=New-Object System.Collections.Generic.List[object]
    foreach($old in @(Get-RuleEstateProperty $receipt 'actions')){$actionResults.Add($old)|Out-Null}
    $lockStreams=New-Object System.Collections.Generic.List[object];$writes=0
    try {
        $lockPaths=@(Get-RuleEstateProperty $Plan 'actions'|ForEach-Object{Get-RuleEstateLockPath $_}|Sort-Object -Unique)
        foreach($lockPath in $lockPaths){
            $stream=[IO.File]::Open($lockPath,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None);$lockStreams.Add([pscustomobject]@{stream=$stream;path=$lockPath})|Out-Null
        }
        if($null -ne $TestHookAfterLocksAcquired){& $TestHookAfterLocksAcquired}
        $lockedPreflight=Test-RuleEstateApplyPreflight $Plan $WorkspaceRoot $CodexUserRoot $ClaudeUserRoot $completedIds -IgnoreLocks
        if(-not $lockedPreflight.pass){throw ('post_lock_preflight_failed:{0}' -f ((@($lockedPreflight.findings.code)-join ',')))}
        foreach($action in @(Get-RuleEstateProperty $Plan 'actions')){
            $id=[string](Get-RuleEstateProperty $action 'action_id')
            if($id -in $completedIds){continue}
            if(-not [string]::IsNullOrWhiteSpace($TestFailBeforeActionId) -and $id -eq $TestFailBeforeActionId){throw ('test_fail_before_action:{0}' -f $id)}
            $target=[string](Get-RuleEstateProperty $action 'target_path');$operation=[string](Get-RuleEstateProperty $action 'operation')
            $backupRoot=Join-Path ([IO.Path]::GetDirectoryName($receiptFile)) ('.rule-estate-backups\{0}' -f [string](Get-RuleEstateProperty $Plan 'operation_id'))
            New-Item -ItemType Directory -Path $backupRoot -Force|Out-Null
            $backup=Join-Path $backupRoot ('{0}.bak' -f $id)
            [byte[]]$beforeBytes=$null
            if([IO.File]::Exists($target)){$beforeBytes=[IO.File]::ReadAllBytes($target)}else{$beforeBytes=[byte[]]::new(0)}
            [IO.File]::WriteAllBytes($backup,$beforeBytes)
            $backupHash=Get-RuleEstateBytesHash $beforeBytes
            Write-Utf8FileAtomic -Path $target -Content ([string](Get-RuleEstateProperty $action 'desired_text'))
            if((Get-RuleEstateTextHashAtPath $target) -ne [string](Get-RuleEstateProperty $action 'desired_hash')){throw ('desired_hash_not_applied:{0}' -f $id)}
            $writes++
            $actionResults.Add([pscustomobject][ordered]@{action_id=$id;status='applied';target_path=$target;target_scope=[string](Get-RuleEstateProperty $action 'target_scope');authorized_root=[string](Get-RuleEstateProperty $action 'authorized_root');operation=$operation;before_hash=[string](Get-RuleEstateProperty $action 'before_hash');desired_hash=[string](Get-RuleEstateProperty $action 'desired_hash');dirty_paths_at_plan=@(Get-RuleEstateProperty $action 'dirty_paths_at_plan');backup_path=$backup;backup_sha256=$backupHash;backup_length=[long]$beforeBytes.LongLength;applied_at=[datetimeoffset]::UtcNow.ToString('o')})|Out-Null
            $receipt.actions=@($actionResults.ToArray());Write-RuleEstateReceipt $receiptFile $receipt
        }
        $receipt.status='applied';$receipt.completed_at=[datetimeoffset]::UtcNow.ToString('o');$receipt.actions=@($actionResults.ToArray());Write-RuleEstateReceipt $receiptFile $receipt
        return [pscustomobject]@{pass=$true;status='applied';findings=@();writes=$writes;receipt=$receipt}
    } catch {
        $receipt.status='failed';$receipt.completed_at=[datetimeoffset]::UtcNow.ToString('o');$receipt.actions=@($actionResults.ToArray());$receipt | Add-Member -NotePropertyName failure -NotePropertyValue $_.Exception.Message -Force;Write-RuleEstateReceipt $receiptFile $receipt
        return [pscustomobject]@{pass=$false;status='failed';findings=@((New-RuleEstateFinding 'estate_apply_failed' '$.actions' $_.Exception.Message));writes=$writes;receipt=$receipt}
    } finally {
        foreach($lock in $lockStreams.ToArray()){$lock.stream.Dispose();if([IO.File]::Exists($lock.path)){[IO.File]::Delete($lock.path)}}
    }
}

function Invoke-RuleEstateRollback {
    param([string]$ReceiptPath,[string]$ActionId,[string]$Token,[string]$WorkspaceRoot,[string]$CodexUserRoot,[string]$ClaudeUserRoot)
    if($Token -cne 'ROLLBACK_RULE_ESTATE_PATCH'){return [pscustomobject]@{pass=$false;status='blocked';findings=@((New-RuleEstateFinding 'rollback_token_invalid' '$' 'Explicit rollback token does not match.'));writes=0}}
    $receiptFile=[IO.Path]::GetFullPath($ReceiptPath);if(-not [IO.File]::Exists($receiptFile)){throw 'Receipt does not exist.'}
    $receipt=[IO.File]::ReadAllText($receiptFile)|ConvertFrom-Json
    $workspace=[IO.Path]::GetFullPath($WorkspaceRoot);$codex=[IO.Path]::GetFullPath($CodexUserRoot);$claude=[IO.Path]::GetFullPath($ClaudeUserRoot)
    if($workspace -ne [IO.Path]::GetFullPath([string](Get-RuleEstateProperty $receipt 'workspace_root')) -or $codex -ne [IO.Path]::GetFullPath([string](Get-RuleEstateProperty $receipt 'codex_user_root')) -or $claude -ne [IO.Path]::GetFullPath([string](Get-RuleEstateProperty $receipt 'claude_user_root'))){return [pscustomobject]@{pass=$false;status='blocked';findings=@((New-RuleEstateFinding 'rollback_root_mismatch' '$' 'Rollback roots must exactly match the receipt.'));writes=0}}
    $action=@(Get-RuleEstateProperty $receipt 'actions'|Where-Object{[string](Get-RuleEstateProperty $_ 'action_id') -eq $ActionId})|Select-Object -First 1
    if($null -eq $action -or [string](Get-RuleEstateProperty $action 'status') -ne 'applied'){return [pscustomobject]@{pass=$false;status='blocked';findings=@((New-RuleEstateFinding 'rollback_action_invalid' '$.actions' 'Action is not an applied receipt target.'));writes=0}}
    $target=[IO.Path]::GetFullPath([string](Get-RuleEstateProperty $action 'target_path'));$root=[IO.Path]::GetFullPath([string](Get-RuleEstateProperty $action 'authorized_root'));$scope=[string](Get-RuleEstateProperty $action 'target_scope')
    $expectedRoot=switch($scope){'global_codex'{$codex};'global_claude'{$claude};'repository'{$root};default{''}}
    $allowedName=switch($scope){'global_codex'{'AGENTS.md'};'global_claude'{'CLAUDE.md'};default{[IO.Path]::GetFileName($target)}}
    $repoValid=$scope -ne 'repository' -or (([IO.Directory]::GetParent($root)).FullName.TrimEnd('\','/') -eq $workspace.TrimEnd('\','/') -and ([IO.Directory]::Exists((Join-Path $root '.git')) -or [IO.File]::Exists((Join-Path $root '.git'))) -and [IO.Path]::GetFileName($target) -in @('AGENTS.md','CLAUDE.md'))
    if([string]::IsNullOrWhiteSpace($expectedRoot) -or $root -ne $expectedRoot -or -not $repoValid -or -not (Test-RuleDiscoveryPathWithin $target $root) -or [IO.Path]::GetFileName($target) -cne $allowedName -or (Test-RuleEstateReparsePath $target $root)){return [pscustomobject]@{pass=$false;status='blocked';findings=@((New-RuleEstateFinding 'rollback_target_out_of_scope' $target 'Receipt target is outside the exact managed rule allowlist.'));writes=0}}
    if((Get-RuleEstateTextHashAtPath $target) -ne [string](Get-RuleEstateProperty $action 'desired_hash')){return [pscustomobject]@{pass=$false;status='blocked';findings=@((New-RuleEstateFinding 'rollback_target_stale' $target 'Target changed after apply.'));writes=0}}
    $operationId=[string](Get-RuleEstateProperty $receipt 'operation_id');if($operationId -notmatch '^rule-estate-[a-f0-9]{16}$' -or $ActionId -notmatch '^estate-[a-f0-9]{16}$'){return [pscustomobject]@{pass=$false;status='blocked';findings=@((New-RuleEstateFinding 'rollback_identity_invalid' '$' 'Receipt operation or action identity is invalid.'));writes=0}}
    $expectedBackup=[IO.Path]::GetFullPath((Join-Path ([IO.Path]::GetDirectoryName($receiptFile)) ('.rule-estate-backups\{0}\{1}.bak' -f $operationId,$ActionId)));$backup=[IO.Path]::GetFullPath([string](Get-RuleEstateProperty $action 'backup_path'))
    if($backup -ne $expectedBackup -or -not [IO.File]::Exists($backup)){return [pscustomobject]@{pass=$false;status='blocked';findings=@((New-RuleEstateFinding 'rollback_backup_invalid' $backup 'Per-target backup path is missing or outside the receipt backup directory.'));writes=0}}
    $backupBytes=[IO.File]::ReadAllBytes($backup);$expectedBackupHash=[string](Get-RuleEstateProperty $action 'backup_sha256');$expectedBackupLength=[long](Get-RuleEstateProperty $action 'backup_length')
    if([string]::IsNullOrWhiteSpace($expectedBackupHash) -or $backupBytes.LongLength -ne $expectedBackupLength -or (Get-RuleEstateBytesHash $backupBytes) -ne $expectedBackupHash){return [pscustomobject]@{pass=$false;status='blocked';findings=@((New-RuleEstateFinding 'rollback_backup_stale' $backup 'Per-target backup content no longer matches the apply receipt.'));writes=0}}
    if([string](Get-RuleEstateProperty $action 'operation') -eq 'create'){[IO.File]::Delete($target)}else{Write-BytesAtomic -Path $target -Bytes $backupBytes}
    $action.status='rolled_back';$action | Add-Member -NotePropertyName rolled_back_at -NotePropertyValue ([datetimeoffset]::UtcNow.ToString('o')) -Force;Write-RuleEstateReceipt $receiptFile $receipt
    return [pscustomobject]@{pass=$true;status='rolled_back';findings=@();writes=1;action_id=$ActionId}
}

function Get-SkillProfileReconciliationProperty($Object, [string]$Name) {
    if ($null -eq $Object) { return $null }
    $property = $Object.PSObject.Properties[$Name]
    if ($null -eq $property) { return $null }
    return $property.Value
}

function Read-SkillProfileReconciliationProposal([string]$Path) {
    if ([string]::IsNullOrWhiteSpace($Path)) { return $null }
    $full = if ([System.IO.Path]::IsPathRooted($Path)) { [System.IO.Path]::GetFullPath($Path) } else { [System.IO.Path]::GetFullPath((Join-Path $Root $Path)) }
    Need (Test-Path -LiteralPath $full -PathType Leaf) ("Proposal file does not exist: {0}" -f $full)
    try { return (Get-ContentUtf8 $full | ConvertFrom-Json) }
    catch { throw ("Proposal JSON is invalid: {0}" -f $_.Exception.Message) }
}

function New-SkillProfileReconciliationTransactionFinding([string]$Code, [string]$Message, [string]$Skill = "", [string]$Profile = "") {
    return [pscustomobject]([ordered]@{
            code = $Code
            message = $Message
            blocking = $true
            skill = $Skill
            profile = $Profile
        })
}

function Copy-SkillsManagerConfig($Config) {
    Need ($null -ne $Config) "skills-manager config is required"
    return (($Config | ConvertTo-Json -Depth 50) | ConvertFrom-Json)
}

function Set-SkillProfileReconciliationActions($Config, $Actions) {
    $copy = Copy-SkillsManagerConfig $Config
    Need ($copy.PSObject.Properties.Match("skill_projection").Count -gt 0 -and $null -ne $copy.skill_projection) "skill_projection is required"
    foreach ($action in @($Actions)) {
        $profileName = [string]$action.profile
        $property = $copy.skill_projection.profiles.PSObject.Properties[$profileName]
        Need ($null -ne $property) ("Unknown profile in validated action: {0}" -f $profileName)
        $before = @($property.Value.enabled_names | ForEach-Object { [string]$_ })
        $expectedBefore = @($action.before | ForEach-Object { [string]$_ })
        Need (($before -join "`n") -ceq ($expectedBefore -join "`n")) ("Profile changed after validation: {0}" -f $profileName)
        $property.Value.enabled_names = @($action.after | ForEach-Object { [string]$_ })
    }
    return $copy
}

function New-SkillProfileReconciliationApplyPlan {
    param(
        [Parameter(Mandatory = $true)]$Config,
        [Parameter(Mandatory = $true)][string]$ConfigPath,
        [Parameter(Mandatory = $true)]$Proposal,
        [ValidateRange(1, 20)][int]$MaxSkillChanges = 5,
        [ValidateRange(1, 50)][int]$MaxActions = 10,
        [ValidateRange(0, 2000)][int]$MinBudgetHeadroomChars = 256
    )

    $configFile = [System.IO.Path]::GetFullPath($ConfigPath)
    Need (Test-Path -LiteralPath $configFile -PathType Leaf) ("skills.json does not exist: {0}" -f $configFile)
    Need ($Config.PSObject.Properties.Match("skill_projection").Count -gt 0 -and $null -ne $Config.skill_projection) "skill_projection is required"
    $configHash = Get-FileContentHash $configFile
    $planner = New-SkillProfileReconciliationPlan $Config.skill_projection $configHash $Proposal
    $findings = New-Object System.Collections.Generic.List[object]
    foreach ($finding in @($planner.findings)) { $findings.Add($finding) | Out-Null }

    $actions = if ([bool]$planner.pass) { @($planner.actions) } else { @() }
    $changedSkills = @($actions | ForEach-Object { [string]$_.skill } | Sort-Object -Unique)
    $changedProfiles = @($actions | ForEach-Object { [string]$_.profile } | Sort-Object -Unique)
    if ([bool]$planner.pass -and $actions.Count -eq 0) {
        $findings.Add((New-SkillProfileReconciliationTransactionFinding "apply_actions_missing" "A canary apply requires at least one validated action.")) | Out-Null
    }
    if ($changedSkills.Count -gt $MaxSkillChanges) {
        $findings.Add((New-SkillProfileReconciliationTransactionFinding "apply_skill_limit_exceeded" ("Canary changes {0} skills; limit is {1}." -f $changedSkills.Count, $MaxSkillChanges))) | Out-Null
    }
    if ($actions.Count -gt $MaxActions) {
        $findings.Add((New-SkillProfileReconciliationTransactionFinding "apply_action_limit_exceeded" ("Canary has {0} actions; limit is {1}." -f $actions.Count, $MaxActions))) | Out-Null
    }
    $activeProfile = [string]$Config.skill_projection.active_profile
    foreach ($action in @($actions | Where-Object { [string]::Equals([string]$_.profile, $activeProfile, [System.StringComparison]::OrdinalIgnoreCase) })) {
        $findings.Add((New-SkillProfileReconciliationTransactionFinding "active_profile_membership_change_forbidden" ("Canary apply cannot change the active profile '{0}'. Use a non-active profile and validate at a fresh-task boundary." -f $activeProfile) ([string]$action.skill) ([string]$action.profile))) | Out-Null
    }
    $profileHeadroom = New-Object System.Collections.Generic.List[object]
    foreach ($profile in $changedProfiles) {
        $budget = @($planner.proposed.profile_budgets | Where-Object { [string]::Equals([string]$_.profile, [string]$profile, [System.StringComparison]::OrdinalIgnoreCase) } | Select-Object -First 1)
        if ($budget.Count -ne 1) { continue }
        $headroom = [int]$budget[0].budget_limit_chars - [int]$budget[0].estimated_metadata_chars
        $profileHeadroom.Add([pscustomobject]@{ profile = [string]$profile; headroom_chars = $headroom; minimum_chars = $MinBudgetHeadroomChars }) | Out-Null
        if ($headroom -lt $MinBudgetHeadroomChars) {
            $findings.Add((New-SkillProfileReconciliationTransactionFinding "proposed_budget_headroom_insufficient" ("Canary profile '{0}' leaves {1} metadata characters; minimum automatic headroom is {2}." -f $profile, $headroom, $MinBudgetHeadroomChars) "" ([string]$profile))) | Out-Null
        }
    }

    $proposalJson = $Proposal | ConvertTo-Json -Depth 50 -Compress
    $proposalHash = Get-OperationSha256 $proposalJson
    $seed = "{0}|{1}|{2}" -f $configHash, $proposalHash, (@($actions | ForEach-Object { "{0}|{1}|{2}" -f $_.operation, $_.skill, $_.profile }) -join "|")
    $operationId = "skill-profile-{0}" -f (Get-OperationSha256 $seed).Substring(0, 16)
    $pass = @($findings | Where-Object blocking).Count -eq 0
    return [pscustomobject]([ordered]@{
            schema_version = 1
            command = "plan-skill-profile-reconciliation-apply"
            operation_id = $operationId
            decision_owner = "host_ai"
            semantic_routing_performed = $false
            pass = $pass
            apply_allowed = $pass
            writes_performed = $false
            config_path = $configFile
            config_sha256 = $configHash
            proposal_sha256 = $proposalHash
            active_profile = $activeProfile
            activation_boundary = "fresh_task"
            changed_skills = $changedSkills
            changed_profiles = $changedProfiles
            profile_headroom = @($profileHeadroom.ToArray())
            actions = $actions
            finding_count = $findings.Count
            findings = @($findings.ToArray())
        })
}

function Write-SkillProfileReconciliationReceipt([string]$Path, $Receipt) {
    Write-Utf8FileAtomic -Path $Path -Content ($Receipt | ConvertTo-Json -Depth 50)
}

function Invoke-SkillProfileReconciliationApply {
    param(
        [Parameter(Mandatory = $true)]$Config,
        [Parameter(Mandatory = $true)][string]$ConfigPath,
        [Parameter(Mandatory = $true)]$Proposal,
        [Parameter(Mandatory = $true)][string]$ReceiptPath,
        [Parameter(Mandatory = $true)][string]$Token,
        [ValidateRange(1, 20)][int]$MaxSkillChanges = 5,
        [ValidateRange(1, 50)][int]$MaxActions = 10,
        [ValidateRange(0, 2000)][int]$MinBudgetHeadroomChars = 256
    )

    if ($Token -cne "APPLY_PROFILE_RECONCILIATION_CANARY") {
        return [pscustomobject]@{ pass = $false; status = "blocked"; writes_performed = 0; findings = @((New-SkillProfileReconciliationTransactionFinding "apply_token_invalid" "Explicit canary apply token does not match.")); receipt = $null }
    }
    $configFile = [System.IO.Path]::GetFullPath($ConfigPath)
    $receiptFile = [System.IO.Path]::GetFullPath($ReceiptPath)
    if (Test-Path -LiteralPath $receiptFile) {
        return [pscustomobject]@{ pass = $false; status = "blocked"; writes_performed = 0; findings = @((New-SkillProfileReconciliationTransactionFinding "receipt_already_exists" "Receipt path already exists; use a new canary receipt.")); receipt = $null }
    }
    $plan = New-SkillProfileReconciliationApplyPlan -Config $Config -ConfigPath $configFile -Proposal $Proposal -MaxSkillChanges $MaxSkillChanges -MaxActions $MaxActions -MinBudgetHeadroomChars $MinBudgetHeadroomChars
    if (-not [bool]$plan.pass) {
        return [pscustomobject]@{ pass = $false; status = "blocked"; writes_performed = 0; findings = @($plan.findings); receipt = $null }
    }

    $lockPath = "{0}.profile-reconciliation.lock" -f $configFile
    $lockStream = $null
    $backupPath = Join-Path ([System.IO.Path]::GetDirectoryName($receiptFile)) (".skill-profile-backups\{0}.skills.json.bak" -f [string]$plan.operation_id)
    $beforeBytes = [System.IO.File]::ReadAllBytes($configFile)
    $configWritten = $false
    $receipt = $null
    try {
        $lockStream = [System.IO.File]::Open($lockPath, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
        Need ((Get-FileContentHash $configFile) -eq [string]$plan.config_sha256) "skills.json changed after apply planning"
        Write-BytesAtomic -Path $backupPath -Bytes $beforeBytes
        $proposedConfig = Set-SkillProfileReconciliationActions $Config $plan.actions
        Need ([string]::Equals([string]$proposedConfig.skill_projection.active_profile, [string]$plan.active_profile, [System.StringComparison]::Ordinal)) "active_profile changed during canary apply"
        Write-Utf8FileAtomic -Path $configFile -Content ($proposedConfig | ConvertTo-Json -Depth 50)
        $configWritten = $true
        $afterHash = Get-FileContentHash $configFile
        $postPlan = New-SkillProfileReconciliationPlan $proposedConfig.skill_projection $afterHash
        Need ([bool]$postPlan.pass) ("Applied profile projection is invalid: {0}" -f (@($postPlan.findings.code) -join ", "))
        Need ([string]::Equals([string]$postPlan.current.active_profile, [string]$plan.active_profile, [System.StringComparison]::Ordinal)) "active_profile changed after canary apply"
        $now = [datetimeoffset]::UtcNow.ToString("o")
        $receipt = [pscustomobject]([ordered]@{
                schema_version = 1
                domain = "skill_profile_reconciliation"
                operation_id = [string]$plan.operation_id
                status = "canary_applied"
                started_at = $now
                completed_at = $now
                config_path = $configFile
                before_config_sha256 = [string]$plan.config_sha256
                after_config_sha256 = $afterHash
                proposal_sha256 = [string]$plan.proposal_sha256
                active_profile = [string]$plan.active_profile
                changed_skills = @($plan.changed_skills)
                changed_profiles = @($plan.changed_profiles)
                profile_headroom = @($plan.profile_headroom)
                actions = @($plan.actions)
                backup_path = [System.IO.Path]::GetFullPath($backupPath)
                replay = [pscustomobject]@{ required = $true; status = "not_run"; boundary = "fresh_ephemeral_task"; report_path = $null; report_sha256 = $null }
                live_accepted = "not_run"
            })
        Write-SkillProfileReconciliationReceipt $receiptFile $receipt
        return [pscustomobject]@{ pass = $true; status = "canary_applied"; writes_performed = 1; findings = @(); receipt = $receipt }
    }
    catch {
        if ($configWritten) { Write-BytesAtomic -Path $configFile -Bytes $beforeBytes }
        return [pscustomobject]@{ pass = $false; status = $(if ($configWritten) { "failed_rolled_back" } else { "failed" }); writes_performed = $(if ($configWritten) { 1 } else { 0 }); findings = @((New-SkillProfileReconciliationTransactionFinding "canary_apply_failed" $_.Exception.Message)); receipt = $receipt }
    }
    finally {
        if ($null -ne $lockStream) {
            $lockStream.Dispose()
            if (Test-Path -LiteralPath $lockPath -PathType Leaf) { Remove-Item -LiteralPath $lockPath -Force -ErrorAction SilentlyContinue }
        }
    }
}

function Invoke-SkillProfileReconciliationRollback {
    param(
        [Parameter(Mandatory = $true)][string]$ConfigPath,
        [Parameter(Mandatory = $true)][string]$ReceiptPath,
        [Parameter(Mandatory = $true)][string]$Token
    )

    if ($Token -cne "ROLLBACK_PROFILE_RECONCILIATION_CANARY") {
        return [pscustomobject]@{ pass = $false; status = "blocked"; writes_performed = 0; findings = @((New-SkillProfileReconciliationTransactionFinding "rollback_token_invalid" "Explicit canary rollback token does not match.")) }
    }
    $configFile = [System.IO.Path]::GetFullPath($ConfigPath)
    $receiptFile = [System.IO.Path]::GetFullPath($ReceiptPath)
    if (-not (Test-Path -LiteralPath $receiptFile -PathType Leaf)) { throw "Canary receipt does not exist: $receiptFile" }
    $receipt = Get-Content -LiteralPath $receiptFile -Raw -Encoding UTF8 | ConvertFrom-Json
    $findings = New-Object System.Collections.Generic.List[object]
    if ([int](Get-SkillProfileReconciliationProperty $receipt "schema_version") -ne 1 -or [string](Get-SkillProfileReconciliationProperty $receipt "domain") -ne "skill_profile_reconciliation") {
        $findings.Add((New-SkillProfileReconciliationTransactionFinding "rollback_receipt_invalid" "Receipt is not a supported skill profile reconciliation receipt.")) | Out-Null
    }
    if ([string](Get-SkillProfileReconciliationProperty $receipt "status") -notin @("canary_applied", "accepted", "replay_failed")) {
        $findings.Add((New-SkillProfileReconciliationTransactionFinding "rollback_status_invalid" "Receipt is not in a rollback-eligible state.")) | Out-Null
    }
    if (-not [string]::Equals([System.IO.Path]::GetFullPath([string]$receipt.config_path), $configFile, [System.StringComparison]::OrdinalIgnoreCase)) {
        $findings.Add((New-SkillProfileReconciliationTransactionFinding "rollback_target_invalid" "Receipt config path does not match the requested skills.json.")) | Out-Null
    }
    if ((Get-FileContentHash $configFile) -ne [string]$receipt.after_config_sha256) {
        $findings.Add((New-SkillProfileReconciliationTransactionFinding "rollback_target_stale" "skills.json changed after canary apply; automatic rollback is blocked.")) | Out-Null
    }
    $expectedBackup = [System.IO.Path]::GetFullPath((Join-Path ([System.IO.Path]::GetDirectoryName($receiptFile)) (".skill-profile-backups\{0}.skills.json.bak" -f [string]$receipt.operation_id)))
    $backupPath = [System.IO.Path]::GetFullPath([string]$receipt.backup_path)
    if (-not [string]::Equals($backupPath, $expectedBackup, [System.StringComparison]::OrdinalIgnoreCase) -or -not (Test-Path -LiteralPath $backupPath -PathType Leaf) -or (Get-FileContentHash $backupPath) -ne [string]$receipt.before_config_sha256) {
        $findings.Add((New-SkillProfileReconciliationTransactionFinding "rollback_backup_invalid" "Canary backup is missing, stale, or outside the receipt backup path.")) | Out-Null
    }
    if ($findings.Count -gt 0) { return [pscustomobject]@{ pass = $false; status = "blocked"; writes_performed = 0; findings = @($findings.ToArray()) } }

    Write-BytesAtomic -Path $configFile -Bytes ([System.IO.File]::ReadAllBytes($backupPath))
    Need ((Get-FileContentHash $configFile) -eq [string]$receipt.before_config_sha256) "Canary rollback did not restore the original skills.json hash."
    $receipt.status = "rolled_back"
    $receipt | Add-Member -NotePropertyName rolled_back_at -NotePropertyValue ([datetimeoffset]::UtcNow.ToString("o")) -Force
    Write-SkillProfileReconciliationReceipt $receiptFile $receipt
    return [pscustomobject]@{ pass = $true; status = "rolled_back"; writes_performed = 1; findings = @(); receipt = $receipt }
}

function Test-SkillProfileReconciliationReplay {
    param(
        [Parameter(Mandatory = $true)]$Receipt,
        [Parameter(Mandatory = $true)]$Report,
        [Parameter(Mandatory = $true)]$Corpus
    )

    $findings = New-Object System.Collections.Generic.List[object]
    if ([string]$Receipt.status -ne "canary_applied") { $findings.Add((New-SkillProfileReconciliationTransactionFinding "replay_receipt_status_invalid" "Replay requires a canary_applied receipt.")) | Out-Null }
    if ([int]$Report.schema_version -ne 1 -or [string]$Report.execution_boundary -ne "fresh_ephemeral_task") { $findings.Add((New-SkillProfileReconciliationTransactionFinding "replay_boundary_invalid" "Replay report must come from fresh_ephemeral_task execution.")) | Out-Null }
    if (-not [string]::Equals([string]$Report.original_profile, [string]$Receipt.active_profile, [System.StringComparison]::OrdinalIgnoreCase) -or -not [string]::Equals([string]$Report.restored_profile, [string]$Receipt.active_profile, [System.StringComparison]::OrdinalIgnoreCase)) {
        $findings.Add((New-SkillProfileReconciliationTransactionFinding "replay_profile_not_restored" "Replay must start from and restore the receipt active_profile.")) | Out-Null
    }
    $results = @($Report.results)
    if ($results.Count -eq 0) { $findings.Add((New-SkillProfileReconciliationTransactionFinding "replay_results_missing" "Replay report has no results.")) | Out-Null }
    foreach ($result in @($results | Where-Object { -not [bool]$_.expectation_pass -or [int]$_.exit_code -ne 0 -or -not [bool]$_.parse_ok })) {
        $findings.Add((New-SkillProfileReconciliationTransactionFinding "replay_expectation_failed" ("Replay failed for profile '{0}', case '{1}'." -f [string]$result.profile, [string]$result.case_id) "" ([string]$result.profile))) | Out-Null
    }

    $corpusCases = @($Corpus.cases)
    foreach ($profile in @($Receipt.changed_profiles)) {
        $profileResults = @($results | Where-Object { [string]::Equals([string]$_.profile, [string]$profile, [System.StringComparison]::OrdinalIgnoreCase) })
        if (@($profileResults.case_id | Sort-Object -Unique).Count -lt 4) {
            $findings.Add((New-SkillProfileReconciliationTransactionFinding "replay_case_coverage_insufficient" ("Profile '{0}' requires at least four distinct replay cases." -f $profile) "" ([string]$profile))) | Out-Null
        }
        foreach ($action in @($Receipt.actions | Where-Object { [string]::Equals([string]$_.profile, [string]$profile, [System.StringComparison]::OrdinalIgnoreCase) })) {
            $skill = [string]$action.skill
            $requiredCases = @($corpusCases | Where-Object {
                    $expectation = $_.expectations.PSObject.Properties[[string]$profile]
                    $null -ne $expectation -and $skill -in @($expectation.Value.required)
                } | ForEach-Object { [string]$_.id })
            $forbiddenCases = @($corpusCases | Where-Object {
                    $expectation = $_.expectations.PSObject.Properties[[string]$profile]
                    $null -ne $expectation -and $skill -in @($expectation.Value.forbidden)
                } | ForEach-Object { [string]$_.id })
            if ([string]$action.operation -eq "add" -and @($profileResults | Where-Object { [string]$_.case_id -in $requiredCases }).Count -eq 0) {
                $findings.Add((New-SkillProfileReconciliationTransactionFinding "replay_positive_coverage_missing" ("Added skill '{0}' has no direct/indirect positive replay in profile '{1}'." -f $skill, $profile) $skill ([string]$profile))) | Out-Null
            }
            if (@($profileResults | Where-Object { [string]$_.case_id -in $forbiddenCases }).Count -eq 0) {
                $findings.Add((New-SkillProfileReconciliationTransactionFinding "replay_negative_coverage_missing" ("Changed skill '{0}' has no negative replay in profile '{1}'." -f $skill, $profile) $skill ([string]$profile))) | Out-Null
            }
        }
    }
    return [pscustomobject]@{ pass = ($findings.Count -eq 0); host_replay_status = $(if ($findings.Count -eq 0) { "host_evaluation_partial_pass" } else { "host_evaluation_partial_fail" }); findings = @($findings.ToArray()) }
}

function Complete-SkillProfileReconciliationCanary {
    param(
        [Parameter(Mandatory = $true)][string]$ConfigPath,
        [Parameter(Mandatory = $true)][string]$ReceiptPath,
        [Parameter(Mandatory = $true)][string]$ReplayReportPath,
        [Parameter(Mandatory = $true)][string]$CorpusPath,
        [Parameter(Mandatory = $true)][string]$Token,
        [switch]$RollbackOnFailure
    )

    if ($Token -cne "ACCEPT_PROFILE_RECONCILIATION_CANARY") {
        return [pscustomobject]@{ pass = $false; status = "blocked"; replay_status = "not_run"; rollback_performed = $false; findings = @((New-SkillProfileReconciliationTransactionFinding "accept_token_invalid" "Explicit canary acceptance token does not match.")) }
    }
    $configFile = [System.IO.Path]::GetFullPath($ConfigPath)
    $receiptFile = [System.IO.Path]::GetFullPath($ReceiptPath)
    $reportFile = [System.IO.Path]::GetFullPath($ReplayReportPath)
    $corpusFile = [System.IO.Path]::GetFullPath($CorpusPath)
    foreach ($file in @($receiptFile, $reportFile, $corpusFile)) { Need (Test-Path -LiteralPath $file -PathType Leaf) ("Required canary file does not exist: {0}" -f $file) }
    $receipt = Get-Content -LiteralPath $receiptFile -Raw -Encoding UTF8 | ConvertFrom-Json
    $report = Get-Content -LiteralPath $reportFile -Raw -Encoding UTF8 | ConvertFrom-Json
    $corpus = Get-Content -LiteralPath $corpusFile -Raw -Encoding UTF8 | ConvertFrom-Json
    $validation = Test-SkillProfileReconciliationReplay -Receipt $receipt -Report $report -Corpus $corpus
    if (-not [bool]$validation.pass) {
        if ($RollbackOnFailure) {
            $receipt.status = "replay_failed"
            $receipt.replay.status = [string]$validation.host_replay_status
            $receipt.replay.report_path = $reportFile
            $receipt.replay.report_sha256 = Get-FileContentHash $reportFile
            Write-SkillProfileReconciliationReceipt $receiptFile $receipt
            $rollback = Invoke-SkillProfileReconciliationRollback -ConfigPath $configFile -ReceiptPath $receiptFile -Token "ROLLBACK_PROFILE_RECONCILIATION_CANARY"
            return [pscustomobject]@{ pass = $false; status = [string]$rollback.status; replay_status = [string]$validation.host_replay_status; rollback_performed = [bool]$rollback.pass; findings = @($validation.findings); receipt = $rollback.receipt }
        }
        return [pscustomobject]@{ pass = $false; status = "replay_failed"; replay_status = [string]$validation.host_replay_status; rollback_performed = $false; findings = @($validation.findings); receipt = $receipt }
    }
    if ((Get-FileContentHash $configFile) -ne [string]$receipt.after_config_sha256) {
        return [pscustomobject]@{ pass = $false; status = "blocked"; replay_status = "host_evaluation_partial_pass"; rollback_performed = $false; findings = @((New-SkillProfileReconciliationTransactionFinding "accept_target_stale" "skills.json changed after canary apply; acceptance is blocked.")); receipt = $receipt }
    }
    $receipt.status = "accepted"
    $receipt.replay.status = [string]$validation.host_replay_status
    $receipt.replay.report_path = $reportFile
    $receipt.replay.report_sha256 = Get-FileContentHash $reportFile
    $receipt | Add-Member -NotePropertyName accepted_at -NotePropertyValue ([datetimeoffset]::UtcNow.ToString("o")) -Force
    Write-SkillProfileReconciliationReceipt $receiptFile $receipt
    return [pscustomobject]@{ pass = $true; status = "accepted"; replay_status = [string]$validation.host_replay_status; rollback_performed = $false; findings = @(); receipt = $receipt }
}

function New-SkillProfileMigrationFinding([string]$Code, [string]$Message, [bool]$Blocking = $true) {
    return [pscustomobject][ordered]@{
        code = $Code
        message = $Message
        blocking = $Blocking
    }
}

function Get-SkillProfileCompatibilityView {
    param(
        [Parameter(Mandatory = $true)]$ProjectionConfig
    )

    Need ($null -ne $ProjectionConfig) "skill_projection config is required"
    $directProfilesProperty = $ProjectionConfig.PSObject.Properties["profiles"]
    $compatibilityProperty = $ProjectionConfig.PSObject.Properties["profile_compatibility"]
    $directActiveProperty = $ProjectionConfig.PSObject.Properties["active_profile"]
    $directCurrentProperty = $ProjectionConfig.PSObject.Properties["current_profile"]

    if ($null -eq $directProfilesProperty -and $null -eq $compatibilityProperty -and $null -eq $directActiveProperty -and $null -eq $directCurrentProperty) {
        return [pscustomobject][ordered]@{
            schema_version = 1
            kind = "ProfileCompatibilityView"
            status = "absent"
            source_schema = "none"
            source_fields = @()
            reachability_authority = "none"
            active_profile = ""
            current_profile = ""
            profiles = [pscustomobject]@{}
            writes_performed = $false
            provider_calls = 0
            native_mutations = 0
        }
    }

    $source = if ($null -ne $compatibilityProperty -and $null -eq $directProfilesProperty) { "profile_compatibility" } else { "legacy_skill_projection" }
    $sourceObject = if ($source -eq "profile_compatibility") { $compatibilityProperty.Value } else { $ProjectionConfig }
    Need ($null -ne $sourceObject) "Profile compatibility source is required"

    $activeProfile = ([string]$sourceObject.active_profile).Trim()
    $currentProfile = ([string]$sourceObject.current_profile).Trim()
    if ([string]::IsNullOrWhiteSpace($activeProfile)) { $activeProfile = $currentProfile }
    if (-not [string]::IsNullOrWhiteSpace($activeProfile) -and -not [string]::IsNullOrWhiteSpace($currentProfile)) {
        Need ([string]::Equals($activeProfile, $currentProfile, [System.StringComparison]::OrdinalIgnoreCase)) "active_profile and current_profile disagree"
    }

    $profiles = $sourceObject.PSObject.Properties["profiles"]
    Need ($null -ne $profiles -and $null -ne $profiles.Value) "Profile compatibility data must contain profiles"
    $profilesCopy = Copy-SkillsManagerConfig $profiles.Value
    foreach ($property in @($profilesCopy.PSObject.Properties)) {
        Need ($null -ne $property.Value -and $property.Value.PSObject.Properties.Match("enabled_names").Count -gt 0) ("Profile '{0}' is missing enabled_names" -f [string]$property.Name)
        $property.Value.enabled_names = @($property.Value.enabled_names | ForEach-Object { ([string]$_).Trim() } | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    }

    return [pscustomobject][ordered]@{
        schema_version = 1
        kind = "ProfileCompatibilityView"
        status = "read_only"
        source_schema = if ($source -eq "profile_compatibility") { "profile_compatibility.v1" } else { "skill_projection.profile_fields.v1" }
        source_fields = if ($source -eq "profile_compatibility") { @("profile_compatibility") } else { @("active_profile", "current_profile", "profiles") | Where-Object { $null -ne $ProjectionConfig.PSObject.Properties[$_] } }
        reachability_authority = "none"
        active_profile = $activeProfile
        current_profile = $currentProfile
        profiles = $profilesCopy
        writes_performed = $false
        provider_calls = 0
        native_mutations = 0
    }
}

function New-SkillProfileMigrationPlan {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]$Config,
        [Parameter(Mandatory = $true)][string]$ConfigPath
    )

    $findings = New-Object System.Collections.Generic.List[object]
    $configFile = [System.IO.Path]::GetFullPath($ConfigPath)
    if (-not (Test-Path -LiteralPath $configFile -PathType Leaf)) {
        $findings.Add((New-SkillProfileMigrationFinding "config_missing" ("skills.json does not exist: {0}" -f $configFile))) | Out-Null
        return [pscustomobject][ordered]@{ schema_version = 1; command = "migrate-skill-profile-config"; status = "blocked"; pass = $false; migration_required = $false; writes_performed = $false; findings = @($findings.ToArray()) }
    }
    if ($null -eq $Config -or $null -eq $Config.PSObject.Properties["skill_projection"] -or $null -eq $Config.skill_projection) {
        $findings.Add((New-SkillProfileMigrationFinding "skill_projection_missing" "Config must contain skill_projection.")) | Out-Null
        return [pscustomobject][ordered]@{ schema_version = 1; command = "migrate-skill-profile-config"; status = "blocked"; pass = $false; migration_required = $false; writes_performed = $false; findings = @($findings.ToArray()) }
    }

    $projection = $Config.skill_projection
    $directFieldNames = @("active_profile", "current_profile", "profiles")
    $directFieldPresent = @($directFieldNames | Where-Object { $null -ne $projection.PSObject.Properties[$_] })
    $compatibilityPresent = $null -ne $projection.PSObject.Properties["profile_compatibility"]
    $view = $null
    try { $view = Get-SkillProfileCompatibilityView $projection }
    catch { $findings.Add((New-SkillProfileMigrationFinding "legacy_profile_invalid" $_.Exception.Message)) | Out-Null }

    if ($directFieldPresent.Count -gt 0 -and $compatibilityPresent) {
        $findings.Add((New-SkillProfileMigrationFinding "mixed_profile_schema" "Legacy profile fields and profile_compatibility cannot coexist during migration.")) | Out-Null
    }

    $targetConfig = Copy-SkillsManagerConfig $Config
    $migrationRequired = $directFieldPresent.Count -gt 0
    $status = if ($migrationRequired) { "ready" } elseif ($compatibilityPresent) { "already_migrated" } else { "not_applicable" }
    if ($migrationRequired -and $null -ne $view) {
        foreach ($field in $directFieldNames) {
            if ($null -ne $targetConfig.skill_projection.PSObject.Properties[$field]) { $targetConfig.skill_projection.PSObject.Properties.Remove($field) }
        }
        $targetConfig.skill_projection | Add-Member -NotePropertyName profile_compatibility -NotePropertyValue $view -Force
    }

    $beforeHash = Get-FileContentHash $configFile
    $targetJson = $targetConfig | ConvertTo-Json -Depth 50
    $targetHash = Get-OperationSha256 $targetJson
    $operationId = "profile-migration-{0}" -f (Get-OperationSha256 ("{0}|{1}|profile-compatibility-v1" -f $beforeHash, $targetHash)).Substring(0, 16)
    $activeProfile = if ($null -eq $view) { "" } else { [string]$view.active_profile }
    $profileCount = if ($null -eq $view) { 0 } else { @($view.profiles.PSObject.Properties).Count }
    if ($findings.Count -gt 0) { $status = "blocked" }

    return [pscustomobject][ordered]@{
        schema_version = 1
        command = "migrate-skill-profile-config"
        operation_id = $operationId
        status = $status
        pass = ($findings.Count -eq 0)
        migration_required = $migrationRequired
        config_path = $configFile
        before_config_sha256 = $beforeHash
        target_config_sha256 = $targetHash
        active_profile = $activeProfile
        legacy_profile_count = $profileCount
        compatibility_view = $view
        migrated_config = $targetConfig
        rollback = [pscustomobject][ordered]@{
            required = $migrationRequired
            status = if ($migrationRequired) { "available" } else { "not_required" }
            source = "migration_receipt.backup_path"
        }
        decision_owner = "deterministic_migration"
        host_mutation = $false
        provider_calls = 0
        native_mutations = 0
        writes_performed = $false
        finding_count = $findings.Count
        findings = @($findings.ToArray())
    }
}

function Invoke-SkillProfileMigration {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][string]$ConfigPath,
        [Parameter(Mandatory = $true)][string]$ReceiptPath,
        [Parameter(Mandatory = $true)][string]$Token
    )

    if ($Token -cne "MIGRATE_SKILL_PROFILE_CONFIG") {
        return [pscustomobject]@{ pass = $false; status = "blocked"; writes_performed = 0; findings = @((New-SkillProfileMigrationFinding "migration_token_invalid" "Explicit profile migration token does not match.")) }
    }
    $configFile = [System.IO.Path]::GetFullPath($ConfigPath)
    $receiptFile = [System.IO.Path]::GetFullPath($ReceiptPath)
    if (Test-Path -LiteralPath $receiptFile -PathType Leaf) {
        return [pscustomobject]@{ pass = $false; status = "blocked"; writes_performed = 0; findings = @((New-SkillProfileMigrationFinding "receipt_already_exists" "Receipt path already exists; use a new migration receipt.")) }
    }

    $beforeBytes = $null
    $configWritten = $false
    $lockStream = $null
    try {
        Need (Test-Path -LiteralPath $configFile -PathType Leaf) ("skills.json does not exist: {0}" -f $configFile)
        $beforeBytes = [System.IO.File]::ReadAllBytes($configFile)
        $config = Get-Content -LiteralPath $configFile -Raw -Encoding UTF8 | ConvertFrom-Json
        $plan = New-SkillProfileMigrationPlan -Config $config -ConfigPath $configFile
        if (-not [bool]$plan.pass) { return [pscustomobject]@{ pass = $false; status = "blocked"; writes_performed = 0; findings = @($plan.findings); plan = $plan } }
        if (-not [bool]$plan.migration_required) { return [pscustomobject]@{ pass = $true; status = "noop"; writes_performed = 0; findings = @(); plan = $plan; receipt = $null } }

        $lockPath = "{0}.profile-migration.lock" -f $configFile
        $backupPath = Join-Path ([System.IO.Path]::GetDirectoryName($receiptFile)) (".skill-profile-migration-backups\{0}.skills.json.bak" -f [string]$plan.operation_id)
        $lockStream = [System.IO.File]::Open($lockPath, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
        Need ((Get-FileContentHash $configFile) -eq [string]$plan.before_config_sha256) "skills.json changed after migration planning"
        Write-BytesAtomic -Path $backupPath -Bytes $beforeBytes
        Write-Utf8FileAtomic -Path $configFile -Content ($plan.migrated_config | ConvertTo-Json -Depth 50)
        $configWritten = $true
        $afterHash = Get-FileContentHash $configFile
        $afterConfig = Get-Content -LiteralPath $configFile -Raw -Encoding UTF8 | ConvertFrom-Json
        $postPlan = New-SkillProfileMigrationPlan -Config $afterConfig -ConfigPath $configFile
        Need ([bool]$postPlan.pass -and -not [bool]$postPlan.migration_required) "Migrated skills.json did not enter compatibility-only form"
        Need ([string]::Equals([string]$postPlan.active_profile, [string]$plan.active_profile, [System.StringComparison]::OrdinalIgnoreCase)) "active_profile changed during profile migration"
        $now = [datetimeoffset]::UtcNow.ToString("o")
        $receipt = [pscustomobject][ordered]@{
            schema_version = 1
            domain = "skill_profile_migration"
            operation_id = [string]$plan.operation_id
            status = "migrated"
            started_at = $now
            completed_at = $now
            config_path = $configFile
            before_config_sha256 = [string]$plan.before_config_sha256
            after_config_sha256 = $afterHash
            active_profile = [string]$plan.active_profile
            legacy_profile_count = [int]$plan.legacy_profile_count
            backup_path = [System.IO.Path]::GetFullPath($backupPath)
            compatibility_view = $plan.compatibility_view
            rollback = [pscustomobject]@{ status = "available"; token = "ROLLBACK_SKILL_PROFILE_CONFIG" }
            host_mutation = $false
            provider_calls = 0
            native_mutations = 0
            writes = 1
        }
        Write-Utf8FileAtomic -Path $receiptFile -Content ($receipt | ConvertTo-Json -Depth 50)
        return [pscustomobject]@{ pass = $true; status = "migrated"; writes_performed = 1; findings = @(); receipt = $receipt; receipt_path = $receiptFile; plan = $plan }
    }
    catch {
        if ($configWritten -and $null -ne $beforeBytes) { Write-BytesAtomic -Path $configFile -Bytes $beforeBytes }
        return [pscustomobject]@{ pass = $false; status = if ($configWritten) { "failed_rolled_back" } else { "failed" }; writes_performed = if ($configWritten) { 1 } else { 0 }; findings = @((New-SkillProfileMigrationFinding "migration_failed" $_.Exception.Message)); receipt = $null }
    }
    finally {
        if ($null -ne $lockStream) {
            $lockStream.Dispose()
            $lockPath = "{0}.profile-migration.lock" -f $configFile
            if (Test-Path -LiteralPath $lockPath -PathType Leaf) { Remove-Item -LiteralPath $lockPath -Force -ErrorAction SilentlyContinue }
        }
    }
}

function Invoke-SkillProfileMigrationRollback {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][string]$ConfigPath,
        [Parameter(Mandatory = $true)][string]$ReceiptPath,
        [Parameter(Mandatory = $true)][string]$Token
    )

    if ($Token -cne "ROLLBACK_SKILL_PROFILE_CONFIG") {
        return [pscustomobject]@{ pass = $false; status = "blocked"; writes_performed = 0; findings = @((New-SkillProfileMigrationFinding "rollback_token_invalid" "Explicit profile migration rollback token does not match.")) }
    }
    $configFile = [System.IO.Path]::GetFullPath($ConfigPath)
    $receiptFile = [System.IO.Path]::GetFullPath($ReceiptPath)
    if (-not (Test-Path -LiteralPath $receiptFile -PathType Leaf)) { throw "Profile migration receipt does not exist: $receiptFile" }
    $receipt = Get-Content -LiteralPath $receiptFile -Raw -Encoding UTF8 | ConvertFrom-Json
    $findings = New-Object System.Collections.Generic.List[object]
    if ([int]$receipt.schema_version -ne 1 -or [string]$receipt.domain -ne "skill_profile_migration") { $findings.Add((New-SkillProfileMigrationFinding "rollback_receipt_invalid" "Receipt is not a supported profile migration receipt.")) | Out-Null }
    if ([string]$receipt.status -ne "migrated") { $findings.Add((New-SkillProfileMigrationFinding "rollback_status_invalid" "Receipt is not in a rollback-eligible state.")) | Out-Null }
    if (-not [string]::Equals([System.IO.Path]::GetFullPath([string]$receipt.config_path), $configFile, [System.StringComparison]::OrdinalIgnoreCase)) { $findings.Add((New-SkillProfileMigrationFinding "rollback_target_invalid" "Receipt config path does not match the requested skills.json.")) | Out-Null }
    if ((Get-FileContentHash $configFile) -ne [string]$receipt.after_config_sha256) { $findings.Add((New-SkillProfileMigrationFinding "rollback_target_stale" "skills.json changed after profile migration; automatic rollback is blocked.")) | Out-Null }
    $expectedBackup = [System.IO.Path]::GetFullPath((Join-Path ([System.IO.Path]::GetDirectoryName($receiptFile)) (".skill-profile-migration-backups\{0}.skills.json.bak" -f [string]$receipt.operation_id)))
    $backupPath = [System.IO.Path]::GetFullPath([string]$receipt.backup_path)
    if (-not [string]::Equals($backupPath, $expectedBackup, [System.StringComparison]::OrdinalIgnoreCase) -or -not (Test-Path -LiteralPath $backupPath -PathType Leaf) -or (Get-FileContentHash $backupPath) -ne [string]$receipt.before_config_sha256) { $findings.Add((New-SkillProfileMigrationFinding "rollback_backup_invalid" "Migration backup is missing, stale, or outside the receipt backup path.")) | Out-Null }
    if ($findings.Count -gt 0) { return [pscustomobject]@{ pass = $false; status = "blocked"; writes_performed = 0; findings = @($findings.ToArray()); receipt = $receipt } }

    Write-BytesAtomic -Path $configFile -Bytes ([System.IO.File]::ReadAllBytes($backupPath))
    Need ((Get-FileContentHash $configFile) -eq [string]$receipt.before_config_sha256) "Profile migration rollback did not restore the original skills.json hash."
    $receipt.status = "rolled_back"
    $receipt | Add-Member -NotePropertyName rolled_back_at -NotePropertyValue ([datetimeoffset]::UtcNow.ToString("o")) -Force
    Write-Utf8FileAtomic -Path $receiptFile -Content ($receipt | ConvertTo-Json -Depth 50)
    return [pscustomobject]@{ pass = $true; status = "rolled_back"; writes_performed = 1; findings = @(); receipt = $receipt }
}

function Get-AgentTaskIndex($TaskGraph) {
    $index = @{}
    foreach ($task in @((Get-OperationObjectProperty $TaskGraph 'tasks'))) { $index[([string](Get-OperationObjectProperty $task 'task_id')).ToLowerInvariant()] = $task }
    return $index
}

function Get-AgentAccessKey([string]$Key) {
    $match = [regex]::Match($Key, '^(?<mode>read|write):(?<resource>.+)$', [Text.RegularExpressions.RegexOptions]::IgnoreCase)
    if (-not $match.Success) { return $null }
    return [pscustomobject]@{ mode = $match.Groups['mode'].Value.ToLowerInvariant(); resource = $match.Groups['resource'].Value.Trim().ToLowerInvariant() }
}

function Add-AgentAccessConflictFindings($Findings, [object[]]$Items, [string]$Code, [string]$Path, [string]$Message) {
    $byResource = @{}
    foreach ($item in @($Items)) {
        $resource = ([string](Get-OperationObjectProperty $item 'resource')).Trim().ToLowerInvariant()
        $mode = ([string](Get-OperationObjectProperty $item 'mode')).Trim().ToLowerInvariant()
        if ([string]::IsNullOrWhiteSpace($resource)) { continue }
        if (-not $byResource.ContainsKey($resource)) { $byResource[$resource] = New-Object System.Collections.Generic.List[string] }
        $byResource[$resource].Add($mode) | Out-Null
    }
    foreach ($resource in @($byResource.Keys)) { if ($byResource[$resource].Count -gt 1 -and @($byResource[$resource] | Where-Object { $_ -eq 'write' }).Count -gt 0) { $Findings.Add((New-OperationFinding $Code 'error' $Path ($Message + ': ' + $resource))) | Out-Null } }
}

function Test-AgentCompletionVerificationReceipt {
    param($Evidence, $EvaluationTime)

    if ($null -eq $Evidence -or $Evidence -is [string]) { return $false }
    if ((Get-OperationObjectProperty $Evidence 'schema_version') -ne 1) { return $false }
    if ([string](Get-OperationObjectProperty $Evidence 'receipt_id') -notmatch '^verify-[A-Za-z0-9][A-Za-z0-9._-]{1,127}$') { return $false }
    if ([string]::IsNullOrWhiteSpace([string](Get-OperationObjectProperty $Evidence 'verifier'))) { return $false }
    if ([string](Get-OperationObjectProperty $Evidence 'evidence_sha256') -notmatch '^[a-fA-F0-9]{64}$') { return $false }
    $commands = Get-OperationObjectProperty $Evidence 'commands'
    if (-not (Test-OperationArray $commands) -or @($commands).Count -eq 0 -or @($commands | Where-Object { $_ -isnot [string] -or [string]::IsNullOrWhiteSpace($_) }).Count -gt 0) { return $false }
    $verifiedAt = ConvertTo-AgentWorkflowRfc3339Value (Get-OperationObjectProperty $Evidence 'verified_at')
    $evaluatedAt = ConvertTo-AgentWorkflowRfc3339Value $EvaluationTime
    if ($null -eq $verifiedAt -or $null -eq $evaluatedAt -or $verifiedAt -gt $evaluatedAt.AddMinutes(5)) { return $false }
    if (Test-OperationSerializedSensitiveValue ($Evidence | ConvertTo-Json -Depth 20 -Compress)) { return $false }
    return $true
}

function Test-AgentParallelAdmission {
    param($TaskGraph, [string[]]$TaskIds = @(), [string[]]$CompletedTaskIds = @(), [object[]]$CompletedTaskReceipts = @(), $EvaluationTime, [switch]$PlanningOnly)
    $findings = New-Object System.Collections.Generic.List[object]
    $graphValidation = Test-AgentTaskGraphContract $TaskGraph
    foreach ($finding in @($graphValidation.findings)) { $findings.Add($finding) | Out-Null }
    $taskIndex = Get-AgentTaskIndex $TaskGraph
    $completed = New-Object System.Collections.Generic.HashSet[string]([StringComparer]::OrdinalIgnoreCase)
    foreach ($taskId in @($CompletedTaskIds)) {
        $completedId = ([string]$taskId).Trim()
        if (-not $completed.Add($completedId)) { $findings.Add((New-OperationFinding 'completed_task_duplicate' 'error' '$.completed_task_ids' 'Completed task ID is duplicated.')) | Out-Null }
        if (-not $taskIndex.ContainsKey($completedId.ToLowerInvariant())) { $findings.Add((New-OperationFinding 'completed_task_unknown' 'error' '$.completed_task_ids' 'Completed task is not declared in this TaskGraph.')) | Out-Null }
    }
    $receiptIndex = @{}
    if (-not $PlanningOnly) {
        $receiptEvaluationTime = $null
        if (@($CompletedTaskReceipts).Count -gt 0) {
            $receiptEvaluationTime = ConvertTo-AgentWorkflowRfc3339Value $EvaluationTime
            if ($null -eq $receiptEvaluationTime) { $findings.Add((New-OperationFinding 'completion_evaluation_time_invalid' 'error' '$.now' 'Completion receipt validation requires an explicit RFC3339 evaluation time.')) | Out-Null }
        }
        foreach ($receipt in @($CompletedTaskReceipts)) {
            $receiptTaskId = ([string](Get-OperationObjectProperty $receipt 'task_id')).Trim()
            $receiptKey = $receiptTaskId.ToLowerInvariant()
            if ([string]::IsNullOrWhiteSpace($receiptTaskId) -or -not $taskIndex.ContainsKey($receiptKey)) { $findings.Add((New-OperationFinding 'completion_receipt_task_invalid' 'error' '$.completion_receipts' 'Completion receipt task_id must belong to the TaskGraph.')) | Out-Null; continue }
            if ($receiptIndex.ContainsKey($receiptKey)) { $findings.Add((New-OperationFinding 'completion_receipt_duplicate' 'error' '$.completion_receipts' 'Completion receipt is duplicated.')) | Out-Null; continue }
            $receiptIndex[$receiptKey] = $receipt
            if ([string](Get-OperationObjectProperty $receipt 'base_revision') -cne [string](Get-OperationObjectProperty $TaskGraph 'base_revision')) { $findings.Add((New-OperationFinding 'completion_receipt_revision_mismatch' 'error' '$.completion_receipts' 'Completion receipt base_revision does not match the TaskGraph.')) | Out-Null }
            if ([string](Get-OperationObjectProperty $receipt 'status') -cne 'verified') { $findings.Add((New-OperationFinding 'completion_receipt_unverified' 'error' '$.completion_receipts' 'Completion receipt status must be verified.')) | Out-Null }
            $evidence = Get-OperationObjectProperty $receipt 'verification_receipt'
            if ($null -eq $evidence) { $findings.Add((New-OperationFinding 'completion_receipt_evidence_missing' 'error' '$.completion_receipts' 'Completion receipt requires verification evidence.')) | Out-Null }
            elseif (-not (Test-AgentCompletionVerificationReceipt -Evidence $evidence -EvaluationTime $receiptEvaluationTime)) { $findings.Add((New-OperationFinding 'completion_receipt_evidence_invalid' 'error' '$.completion_receipts' 'Completion verification evidence must be a structured, hashed, command-backed receipt evaluated against the request time.')) | Out-Null }
        }
        foreach ($completedId in @($completed)) { if (-not $receiptIndex.ContainsKey($completedId.ToLowerInvariant())) { $findings.Add((New-OperationFinding 'completion_receipt_missing' 'error' '$.completion_receipts' ('Verified completion receipt is missing for task: {0}' -f $completedId))) | Out-Null } }
        foreach ($receiptTaskId in @($receiptIndex.Keys)) { if (-not $completed.Contains($receiptTaskId)) { $findings.Add((New-OperationFinding 'completion_receipt_unclaimed' 'error' '$.completion_receipts' ('Completion receipt is not declared in completed_task_ids: {0}' -f $receiptTaskId))) | Out-Null } }
    }
    foreach ($completedId in @($completed)) {
        $completedKey = $completedId.ToLowerInvariant()
        if (-not $taskIndex.ContainsKey($completedKey)) { continue }
        foreach ($dependency in @((Get-OperationObjectProperty $taskIndex[$completedKey] 'depends_on'))) {
            if (-not $completed.Contains([string]$dependency)) { $findings.Add((New-OperationFinding 'completed_dependency_not_closed' 'error' '$.completed_task_ids' ('Completed task dependency is not also completed: {0} -> {1}' -f $completedId, [string]$dependency))) | Out-Null }
        }
    }
    $selected = New-Object System.Collections.Generic.List[object]
    $seen = New-Object System.Collections.Generic.HashSet[string]([StringComparer]::OrdinalIgnoreCase)
    foreach ($taskId in @($TaskIds)) {
        if (-not $seen.Add([string]$taskId)) { $findings.Add((New-OperationFinding 'parallel_task_duplicate' 'error' '$.requested_parallel_task_ids' 'Parallel task ID is duplicated.')) | Out-Null; continue }
        $key = ([string]$taskId).ToLowerInvariant()
        if (-not $taskIndex.ContainsKey($key)) { $findings.Add((New-OperationFinding 'parallel_task_unknown' 'error' '$.requested_parallel_task_ids' 'Parallel task is not declared.')) | Out-Null; continue }
        $task = $taskIndex[$key]; $selected.Add($task) | Out-Null
        if ($completed.Contains([string]$taskId)) { $findings.Add((New-OperationFinding 'selected_task_already_completed' 'error' '$.requested_parallel_task_ids' 'A task cannot be selected and completed in the same admission request.')) | Out-Null }
        if (-not [bool](Get-OperationObjectProperty $task 'parallelizable')) { $findings.Add((New-OperationFinding 'task_not_parallelizable' 'error' ('$.tasks[{0}]' -f $taskId) 'Task is explicitly serial.')) | Out-Null }
        if ([string](Get-OperationObjectProperty $task 'risk') -eq 'high') { $findings.Add((New-OperationFinding 'high_risk_parallel_forbidden' 'error' ('$.tasks[{0}].risk' -f $taskId) 'High-risk work requires supervisor-owned serial execution.')) | Out-Null }
        if ([string](Get-OperationObjectProperty $task 'ambiguity') -eq 'high') { $findings.Add((New-OperationFinding 'high_ambiguity_parallel_forbidden' 'error' ('$.tasks[{0}].ambiguity' -f $taskId) 'Highly ambiguous work requires clarification before parallel execution.')) | Out-Null }
        foreach ($dependency in @((Get-OperationObjectProperty $task 'depends_on'))) { if (-not $completed.Contains([string]$dependency)) { $findings.Add((New-OperationFinding 'dependency_not_completed' 'error' ('$.tasks[{0}].depends_on' -f $taskId) 'Dependency is not completed.')) | Out-Null } }
        if ([string]::IsNullOrWhiteSpace([string](Get-OperationObjectProperty $task 'result_owner'))) { $findings.Add((New-OperationFinding 'result_owner_required' 'error' ('$.tasks[{0}].result_owner' -f $taskId) 'Parallel tasks require a result owner.')) | Out-Null }
        if (@((Get-OperationObjectProperty $task 'verification')).Count -eq 0) { $findings.Add((New-OperationFinding 'verification_required' 'error' ('$.tasks[{0}].verification' -f $taskId) 'Parallel tasks require independent verification.')) | Out-Null }
    }
    if ($selected.Count -eq 1) { $findings.Add((New-OperationFinding 'parallel_batch_too_small' 'error' '$.requested_parallel_task_ids' 'Parallel admission requires at least two tasks.')) | Out-Null }
    $writeDeclarations = New-Object System.Collections.Generic.List[object]
    foreach ($task in @($selected.ToArray())) {
        foreach ($writePath in @((Get-OperationObjectProperty $task 'exact_write_set'))) {
            $normalized = Get-AgentCanonicalWritePath ([string]$writePath)
            if ($null -ne $normalized) { $writeDeclarations.Add([pscustomobject]@{ task_id = [string](Get-OperationObjectProperty $task 'task_id'); path = $normalized }) | Out-Null }
        }
    }
    for ($i = 0; $i -lt $writeDeclarations.Count; $i++) {
        for ($j = $i + 1; $j -lt $writeDeclarations.Count; $j++) {
            $left = $writeDeclarations[$i]; $right = $writeDeclarations[$j]
            if ($left.task_id -eq $right.task_id) { continue }
            if ($left.path -eq $right.path -or $left.path.StartsWith($right.path + '/', [StringComparison]::OrdinalIgnoreCase) -or $right.path.StartsWith($left.path + '/', [StringComparison]::OrdinalIgnoreCase)) {
                $findings.Add((New-OperationFinding 'write_set_conflict' 'error' '$.tasks.exact_write_set' ('Parallel write paths overlap: {0} <> {1}' -f $left.path, $right.path))) | Out-Null
            }
        }
    }
    $coordination = New-Object System.Collections.Generic.List[object]
    $external = New-Object System.Collections.Generic.List[object]
    foreach ($task in @($selected.ToArray())) {
        foreach ($key in @((Get-OperationObjectProperty $task 'coordination_keys'))) { $parsed = Get-AgentAccessKey ([string]$key); if ($null -ne $parsed) { $coordination.Add($parsed) | Out-Null } }
        foreach ($state in @((Get-OperationObjectProperty $task 'external_state'))) { $external.Add([pscustomobject]@{ resource = [string](Get-OperationObjectProperty $state 'resource'); mode = [string](Get-OperationObjectProperty $state 'mode') }) | Out-Null }
    }
    Add-AgentAccessConflictFindings $findings $coordination.ToArray() 'coordination_key_conflict' '$.tasks.coordination_keys' 'Parallel tasks share an exclusive coordination seam'
    Add-AgentAccessConflictFindings $findings $external.ToArray() 'external_state_conflict' '$.tasks.external_state' 'Parallel tasks conflict on external state'
    $result = New-OperationValidationResult $findings.ToArray()
    $result | Add-Member -NotePropertyName mode -NotePropertyValue $(if ($result.pass -and $selected.Count -eq 0) { 'not_requested' } elseif ($result.pass) { 'isolated_parallel' } else { 'sequential_required' })
    $result | Add-Member -NotePropertyName task_ids -NotePropertyValue @($selected.ToArray() | ForEach-Object { [string](Get-OperationObjectProperty $_ 'task_id') })
    $result | Add-Member -NotePropertyName completion_evidence_semantics -NotePropertyValue $(if ($PlanningOnly) { 'planned_dependency_order_only' } else { 'verified_receipts_required' })
    return $result
}

function New-AgentExecutionPlan {
    param($TaskGraph)
    $validation = Test-AgentTaskGraphContract $TaskGraph
    if (-not $validation.pass) { return [pscustomobject][ordered]@{ schema_version = 1; pass = $false; decision_owner = 'host_ai'; executor = 'host_native_runtime'; waves = @(); findings = @($validation.findings); provider_calls = 0; native_mutations = 0; writes = 0 } }
    $taskIndex = Get-AgentTaskIndex $TaskGraph
    $remaining = New-Object System.Collections.Generic.HashSet[string]([StringComparer]::OrdinalIgnoreCase)
    foreach ($taskId in @($taskIndex.Keys)) { $remaining.Add($taskId) | Out-Null }
    $completed = New-Object System.Collections.Generic.HashSet[string]([StringComparer]::OrdinalIgnoreCase)
    $waves = New-Object System.Collections.Generic.List[object]
    $waveNumber = 0
    while ($remaining.Count -gt 0) {
        $ready = @($remaining | Where-Object { $task = $taskIndex[$_]; @((Get-OperationObjectProperty $task 'depends_on') | Where-Object { -not $completed.Contains([string]$_) }).Count -eq 0 } | ForEach-Object { $taskIndex[$_] } | Sort-Object { [int](Get-OperationObjectProperty $_ 'integration_order') }, { [string](Get-OperationObjectProperty $_ 'task_id') })
        if ($ready.Count -eq 0) { break }
        $waveNumber++
        $mustRunSerial = @($ready | Where-Object { -not [bool](Get-OperationObjectProperty $_ 'parallelizable') -or [string](Get-OperationObjectProperty $_ 'risk') -eq 'high' -or [string](Get-OperationObjectProperty $_ 'ambiguity') -eq 'high' } | Select-Object -First 1)
        $selectedTasks = New-Object System.Collections.Generic.List[object]
        if ($mustRunSerial.Count -gt 0) { $selectedTasks.Add($mustRunSerial[0]) | Out-Null }
        else {
            foreach ($task in @($ready)) {
                if ($selectedTasks.Count -eq 0) { $selectedTasks.Add($task) | Out-Null; continue }
                $candidateIds = @($selectedTasks.ToArray() | ForEach-Object { [string](Get-OperationObjectProperty $_ 'task_id') }) + [string](Get-OperationObjectProperty $task 'task_id')
                if ((Test-AgentParallelAdmission -TaskGraph $TaskGraph -TaskIds $candidateIds -CompletedTaskIds @($completed) -PlanningOnly).pass) { $selectedTasks.Add($task) | Out-Null }
            }
        }
        $selectedIds = @($selectedTasks.ToArray() | ForEach-Object { [string](Get-OperationObjectProperty $_ 'task_id') })
        $mode = if ($selectedIds.Count -gt 1) { 'isolated_parallel' } else { 'sequential' }
        $admission = if ([int](Get-OperationObjectProperty $TaskGraph 'schema_version') -eq 2) {
            @($selectedTasks.ToArray() | ForEach-Object {
                [pscustomobject][ordered]@{
                    task_id = [string](Get-OperationObjectProperty $_ 'task_id')
                    delivery_stage = [string](Get-OperationObjectProperty $_ 'delivery_stage')
                    main_chain_checkpoint = [string](Get-OperationObjectProperty $_ 'main_chain_checkpoint')
                }
            })
        }
        else { @() }
        $waves.Add([pscustomobject][ordered]@{ wave = $waveNumber; groups = @([pscustomobject][ordered]@{ mode = $mode; task_ids = $selectedIds; admission = @($admission) }) }) | Out-Null
        foreach ($taskId in @($selectedIds)) { $remaining.Remove($taskId.ToLowerInvariant()) | Out-Null; $completed.Add($taskId) | Out-Null }
    }
    return [pscustomobject][ordered]@{ schema_version = 1; pass = ($remaining.Count -eq 0); decision_owner = 'host_ai'; executor = 'host_native_runtime'; waves = @($waves.ToArray()); findings = @(); provider_calls = 0; native_mutations = 0; writes = 0 }
}

function Get-AgentModelTierAnchor([string]$Tier) {
    switch ($Tier.ToLowerInvariant()) {
        'sol_xhigh' { return [pscustomobject]@{ tier = 'sol_xhigh'; label = 'Sol xhigh'; model_family = 'gpt-5.6-sol'; reasoning_effort = 'xhigh' } }
        'sol_medium' { return [pscustomobject]@{ tier = 'sol_medium'; label = 'Sol medium'; model_family = 'gpt-5.6-sol'; reasoning_effort = 'medium' } }
        'sol_low' { return [pscustomobject]@{ tier = 'sol_low'; label = 'Sol low'; model_family = 'gpt-5.6-sol'; reasoning_effort = 'low' } }
        default { return $null }
    }
}

function Test-AgentLocalOutcomeContract {
    param($Outcome, $Anchor, $Now)
    $findings = New-Object System.Collections.Generic.List[object]
    if ($null -eq $Outcome) { return New-OperationValidationResult @((New-OperationFinding 'local_outcome_missing' 'error' '$.local_outcomes' 'Local outcome is required.')) }
    foreach ($field in @('task_class', 'model_family', 'reasoning_effort', 'base_revision', 'sampled_at')) {
        if ([string]::IsNullOrWhiteSpace([string](Get-OperationObjectProperty $Outcome $field))) { $findings.Add((New-OperationFinding 'local_outcome_field_missing' 'error' ('$.local_outcomes.{0}' -f $field) 'Comparable local outcome field is required.')) | Out-Null }
    }
    if ($null -ne $Anchor -and ([string](Get-OperationObjectProperty $Outcome 'model_family') -cne $Anchor.model_family -or [string](Get-OperationObjectProperty $Outcome 'reasoning_effort') -cne $Anchor.reasoning_effort)) { $findings.Add((New-OperationFinding 'local_outcome_pair_mismatch' 'error' '$.local_outcomes' 'Local outcome must describe the proposed model and reasoning pair.')) | Out-Null }
    if ((Get-OperationObjectProperty $Outcome 'gate_passed') -isnot [bool]) { $findings.Add((New-OperationFinding 'local_outcome_gate_invalid' 'error' '$.local_outcomes.gate_passed' 'gate_passed must be a boolean.')) | Out-Null }
    $rework = 0
    if (-not [int]::TryParse([string](Get-OperationObjectProperty $Outcome 'rework_count'), [ref]$rework) -or $rework -lt 0) { $findings.Add((New-OperationFinding 'local_outcome_rework_invalid' 'error' '$.local_outcomes.rework_count' 'rework_count must be a non-negative integer.')) | Out-Null }
    foreach ($field in @('actual_cost', 'actual_duration_seconds')) { if (-not (Test-AgentWorkflowNonNegativeFiniteNumber (Get-OperationObjectProperty $Outcome $field))) { $findings.Add((New-OperationFinding 'local_outcome_metric_invalid' 'error' ('$.local_outcomes.{0}' -f $field) 'Local outcome metric must be a finite non-negative number.')) | Out-Null } }
    $sampled = ConvertTo-AgentWorkflowRfc3339Value (Get-OperationObjectProperty $Outcome 'sampled_at')
    $nowValue = ConvertTo-AgentWorkflowRfc3339Value $Now
    if ($null -eq $nowValue) { $findings.Add((New-OperationFinding 'local_outcome_evaluation_time_invalid' 'error' '$.now' 'Local outcome freshness requires a valid RFC3339 evaluation time.')) | Out-Null }
    if ($null -eq $sampled) { $findings.Add((New-OperationFinding 'local_outcome_sampled_at_invalid' 'error' '$.local_outcomes.sampled_at' 'sampled_at must be RFC3339.')) | Out-Null }
    elseif ($null -ne $nowValue -and ($sampled -gt $nowValue.AddMinutes(5) -or $sampled -lt $nowValue.AddDays(-90))) { $findings.Add((New-OperationFinding 'local_outcome_stale' 'error' '$.local_outcomes.sampled_at' 'Local outcome must be within the 90-day comparison window.')) | Out-Null }
    return New-OperationValidationResult $findings.ToArray()
}

function New-ModelPolicyProposal {
    param(
        [Parameter(Mandatory = $true)][string]$TaskId,
        [Parameter(Mandatory = $true)][string]$RequestedTier,
        [Parameter(Mandatory = $true)][string]$Rationale,
        $RadarSnapshot,
        [string]$HostSurface,
        [string[]]$HostAvailablePairs = @(),
        [object[]]$LocalOutcomes = @(),
        [Parameter(Mandatory = $true)]$Now,
        [string]$UserOverrideTier
    )
    $effectiveTier = if ([string]::IsNullOrWhiteSpace($UserOverrideTier)) { $RequestedTier } else { $UserOverrideTier }
    $anchor = Get-AgentModelTierAnchor $effectiveTier
    $fallbackReasons = New-Object System.Collections.Generic.List[string]
    $validLocalOutcomes = New-Object System.Collections.Generic.List[object]
    $localFindings = New-Object System.Collections.Generic.List[object]
    foreach ($outcome in @($LocalOutcomes)) {
        $validation = Test-AgentLocalOutcomeContract -Outcome $outcome -Anchor $anchor -Now $Now
        if ($validation.pass) { $validLocalOutcomes.Add($outcome) | Out-Null } else { foreach ($finding in @($validation.findings)) { $localFindings.Add($finding) | Out-Null } }
    }
    $hasLocal = $validLocalOutcomes.Count -gt 0
    if ($null -eq $anchor) { $fallbackReasons.Add('tier_unknown') | Out-Null }
    if ([string]::IsNullOrWhiteSpace($Rationale)) { $fallbackReasons.Add('rationale_missing') | Out-Null }
    if (@($LocalOutcomes).Count -gt 0 -and -not $hasLocal) { $fallbackReasons.Add('local_outcome_invalid') | Out-Null }
    $hostConfirmed = $false
    $hostAvailabilityState = 'unknown'
    $hostSurfaceKnown = -not [string]::IsNullOrWhiteSpace($HostSurface) -and $HostSurface -match '^[a-z][a-z0-9_]{1,63}$'
    if (-not $hostSurfaceKnown) { $fallbackReasons.Add('host_surface_unknown') | Out-Null }
    if ($null -ne $anchor) {
        $pair = '{0}|{1}' -f $anchor.model_family, $anchor.reasoning_effort
        if ($hostSurfaceKnown -and @($HostAvailablePairs).Count -eq 0) {
            $fallbackReasons.Add('host_pair_availability_unknown') | Out-Null
        }
        elseif ($hostSurfaceKnown -and $pair -in @($HostAvailablePairs)) {
            $hostConfirmed = $true
            $hostAvailabilityState = 'confirmed_available'
        }
        elseif ($hostSurfaceKnown) {
            $hostAvailabilityState = 'confirmed_unavailable'
            $fallbackReasons.Add('host_pair_unavailable') | Out-Null
        }
    }
    $fallback = $fallbackReasons.Count -gt 0
    return [pscustomobject][ordered]@{
        schema_version = 1; task_id = $TaskId; decision_owner = 'host_ai'; advisory_only = $true
        requested_tier = $RequestedTier; selected_tier = $(if ($fallback) { 'host_default' } else { $anchor.tier })
        model_family = $(if ($fallback) { $null } else { $anchor.model_family }); reasoning_effort = $(if ($fallback) { $null } else { $anchor.reasoning_effort })
        rationale = $Rationale; user_override = (-not [string]::IsNullOrWhiteSpace($UserOverrideTier)); fallback_reason = $(if ($fallback) { @($fallbackReasons) -join ',' } else { $null })
        evidence_priority = 'user_override_then_local_outcomes_then_host_availability_then_host_default'; selection_semantics = 'host_proposal_validation_only'
        local_outcomes = @(Copy-AgentWorkflowValue $validLocalOutcomes.ToArray())
        evidence_sources = [pscustomobject][ordered]@{ local = [pscustomobject]@{ valid = $hasLocal; supplied = @($LocalOutcomes).Count; accepted = $validLocalOutcomes.Count; rejected_findings = @($localFindings.ToArray()) }; host_availability = [pscustomobject]@{ surface = $(if ($hostSurfaceKnown) { $HostSurface } else { $null }); state = $hostAvailabilityState; declared = ($hostSurfaceKnown -and @($HostAvailablePairs).Count -gt 0); pair_confirmed = $hostConfirmed } }
        provider_calls = 0; native_mutations = 0; writes = 0
    }
}

function Get-AgentEscalationDecision {
    param([Parameter(Mandatory = $true)]$FailurePacket)
    $validation = Test-AgentFailurePacketContract $FailurePacket
    if (-not $validation.pass) { return [pscustomobject][ordered]@{ action = 'supervisor_review'; next_tier = $null; parallel_allowed = $false; requires_parallel_readmission = $false; requires_new_task_graph = $false; findings = @($validation.findings) } }
    $kind = [string](Get-OperationObjectProperty $FailurePacket 'failure_kind')
    $attempt = [int](Get-OperationObjectProperty $FailurePacket 'attempt_count')
    $escalations = [int](Get-OperationObjectProperty $FailurePacket 'escalation_count')
    $tier = [string](Get-OperationObjectProperty $FailurePacket 'attempted_tier')
    $action = 'supervisor_review'; $nextTier = $null; $requiresGraph = $false
    if ($kind -in @('permission', 'credential', 'production_authorization', 'user_decision')) { $action = 'fail_closed' }
    elseif ($kind -in @('task', 'context')) { $action = $(if ($attempt -ge 2) { 'supervisor_takeover' } else { 'rescope_task_graph' }); $requiresGraph = $true }
    elseif ($kind -eq 'tool') { $action = $(if ($attempt -ge 2) { 'supervisor_takeover' } else { 'repair_tool_or_reassign' }); $requiresGraph = ($attempt -ge 2) }
    elseif ($kind -eq 'capacity') {
        if ($tier -notin @('sol_low', 'sol_medium', 'sol_xhigh')) { $action = 'supervisor_review' }
        elseif ($escalations -ge 2 -or ($tier -eq 'sol_xhigh' -and $attempt -gt 1)) { $action = 'supervisor_takeover'; $requiresGraph = $true }
        elseif ($attempt -le 1) { $action = 'corrected_retry' }
        else {
            $action = 'replan_and_escalate'; $requiresGraph = $true
            $nextTier = switch ($tier) {
                'sol_low' { 'sol_medium' }
                'sol_medium' { 'sol_xhigh' }
            }
        }
    }
    return [pscustomobject][ordered]@{ action = $action; next_tier = $nextTier; parallel_allowed = $false; requires_parallel_readmission = ($action -in @('corrected_retry', 'repair_tool_or_reassign')); requires_new_task_graph = $requiresGraph; issue_id = [string](Get-OperationObjectProperty $FailurePacket 'issue_id'); findings = @() }
}

function Test-AgentWorkflowRequest($Request) {
    $findings = New-Object System.Collections.Generic.List[object]
    if ($null -eq $Request) { return New-OperationValidationResult @((New-OperationFinding 'request_missing' 'error' '$' 'Agent workflow request is required.')) }
    foreach ($result in @(
            (Test-AgentTaskGraphContract (Get-OperationObjectProperty $Request 'task_graph')),
            (Test-AgentParallelAdmission -TaskGraph (Get-OperationObjectProperty $Request 'task_graph') -TaskIds @((Get-OperationObjectProperty $Request 'requested_parallel_task_ids')) -CompletedTaskIds @((Get-OperationObjectProperty $Request 'completed_task_ids')) -CompletedTaskReceipts @((Get-OperationObjectProperty $Request 'completion_receipts')) -EvaluationTime (Get-OperationObjectProperty $Request 'now'))
        )) { foreach ($finding in @($result.findings)) { $findings.Add($finding) | Out-Null } }
    $taskIndex = Get-AgentTaskIndex (Get-OperationObjectProperty $Request 'task_graph')
    $proposalSeen = New-Object System.Collections.Generic.HashSet[string]([StringComparer]::OrdinalIgnoreCase)
    foreach ($proposal in @((Get-OperationObjectProperty $Request 'model_proposals'))) {
        $taskId = ([string](Get-OperationObjectProperty $proposal 'task_id')).Trim()
        if (-not $taskIndex.ContainsKey($taskId.ToLowerInvariant())) { $findings.Add((New-OperationFinding 'model_proposal_task_unknown' 'error' '$.model_proposals.task_id' 'Model proposal task_id must belong to the TaskGraph.')) | Out-Null }
        if (-not $proposalSeen.Add($taskId)) { $findings.Add((New-OperationFinding 'model_proposal_duplicate' 'error' '$.model_proposals.task_id' 'Only one model proposal is allowed per task.')) | Out-Null }
        $rationale = [string](Get-OperationObjectProperty $proposal 'rationale')
        if ([string]::IsNullOrWhiteSpace($rationale)) { $findings.Add((New-OperationFinding 'model_proposal_rationale_required' 'error' '$.model_proposals.rationale' 'Model proposal rationale is required.')) | Out-Null; continue }
        $evaluated = New-ModelPolicyProposal -TaskId $taskId -RequestedTier ([string](Get-OperationObjectProperty $proposal 'requested_tier')) -Rationale $rationale -RadarSnapshot (Get-OperationObjectProperty $Request 'radar_snapshot') -HostSurface ([string](Get-OperationObjectProperty $proposal 'host_surface')) -HostAvailablePairs @((Get-OperationObjectProperty $proposal 'host_available_pairs')) -LocalOutcomes @((Get-OperationObjectProperty $proposal 'local_outcomes')) -Now (Get-OperationObjectProperty $Request 'now') -UserOverrideTier ([string](Get-OperationObjectProperty $proposal 'user_override_tier'))
        if ($evaluated.selected_tier -eq 'host_default') { $findings.Add((New-OperationFinding 'model_proposal_unusable' 'error' '$.model_proposals' ('Model proposal failed closed: {0}' -f $evaluated.fallback_reason))) | Out-Null }
    }
    $failurePacket = Get-OperationObjectProperty $Request 'failure_packet'
    if ($null -ne $failurePacket) { foreach ($finding in @((Test-AgentFailurePacketContract $failurePacket).findings)) { $findings.Add($finding) | Out-Null } }
    return New-OperationValidationResult $findings.ToArray()
}

function New-AgentWorkflowAdvisoryPlan($Request) {
    $requestValidation = Test-AgentWorkflowRequest $Request
    $graph = Get-OperationObjectProperty $Request 'task_graph'
    $proposals = New-Object System.Collections.Generic.List[object]
    foreach ($proposal in @((Get-OperationObjectProperty $Request 'model_proposals'))) {
        $proposals.Add((New-ModelPolicyProposal -TaskId ([string](Get-OperationObjectProperty $proposal 'task_id')) -RequestedTier ([string](Get-OperationObjectProperty $proposal 'requested_tier')) -Rationale ([string](Get-OperationObjectProperty $proposal 'rationale')) -RadarSnapshot (Get-OperationObjectProperty $Request 'radar_snapshot') -HostSurface ([string](Get-OperationObjectProperty $proposal 'host_surface')) -HostAvailablePairs @((Get-OperationObjectProperty $proposal 'host_available_pairs')) -LocalOutcomes @((Get-OperationObjectProperty $proposal 'local_outcomes')) -Now (Get-OperationObjectProperty $Request 'now') -UserOverrideTier ([string](Get-OperationObjectProperty $proposal 'user_override_tier')))) | Out-Null
    }
    return [pscustomobject][ordered]@{
        schema_version = 1; pass = $requestValidation.pass; decision_owner = 'host_ai'; executor = 'host_native_runtime'; advisory_only = $true
        execution_plan = New-AgentExecutionPlan -TaskGraph $graph
        current_parallel_admission = Test-AgentParallelAdmission -TaskGraph $graph -TaskIds @((Get-OperationObjectProperty $Request 'requested_parallel_task_ids')) -CompletedTaskIds @((Get-OperationObjectProperty $Request 'completed_task_ids')) -CompletedTaskReceipts @((Get-OperationObjectProperty $Request 'completion_receipts')) -EvaluationTime (Get-OperationObjectProperty $Request 'now')
        model_proposals = @($proposals.ToArray()); findings = @($requestValidation.findings); provider_calls = 0; native_mutations = 0; writes = 0
    }
}

function New-RulePatchGuardFinding([string]$Code, [string]$Path, [string]$Message) {
    return [pscustomobject]@{ code = $Code; severity = 'error'; path = $Path; message = $Message }
}

function Test-RulePatchReparsePath([string]$Path, [string]$BoundaryRoot) {
    $cursor = [System.IO.Path]::GetFullPath($Path)
    $boundary = [System.IO.Path]::GetFullPath($BoundaryRoot).TrimEnd('\', '/')
    while ($true) {
        if ([System.IO.File]::Exists($cursor) -or [System.IO.Directory]::Exists($cursor)) {
            $attributes = [System.IO.File]::GetAttributes($cursor)
            if (($attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) { return $true }
        }
        if ($cursor.TrimEnd('\', '/').Equals($boundary, [System.StringComparison]::OrdinalIgnoreCase)) { break }
        $parent = [System.IO.Directory]::GetParent($cursor)
        if ($null -eq $parent -or -not (Test-RuleDiscoveryPathWithin $parent.FullName $boundary)) { break }
        $cursor = $parent.FullName
    }
    return $false
}

function Test-RulePatchApplyGuard {
    param([Parameter(Mandatory = $true)]$Plan, [Parameter(Mandatory = $true)][string]$BoundaryRoot, [Parameter(Mandatory = $true)][string]$Token)
    $findings = New-Object System.Collections.Generic.List[object]
    $contract = Test-RulePatchPlanContract $Plan
    foreach ($finding in @($contract.findings)) { $findings.Add($finding) | Out-Null }
    $boundary = [System.IO.Path]::GetFullPath($BoundaryRoot).TrimEnd('\', '/')
    $target = Get-OperationObjectProperty $Plan 'target'; $path = [System.IO.Path]::GetFullPath([string](Get-OperationObjectProperty $target 'path'))
    $authorized = [System.IO.Path]::GetFullPath([string](Get-OperationObjectProperty $target 'authorized_root')).TrimEnd('\', '/')
    $scope = [string](Get-OperationObjectProperty (Get-OperationObjectProperty $Plan 'apply') 'boundary_scope')
    $root = [System.IO.Path]::GetPathRoot($boundary).TrimEnd('\', '/')
    if ($boundary.Equals($root, [System.StringComparison]::OrdinalIgnoreCase)) { $findings.Add((New-RulePatchGuardFinding $(if ($scope -eq 'fixture') { 'fixture_root_is_drive_root' } else { 'authorized_root_is_drive_root' }) '$.target.authorized_root' 'Drive roots are never valid authorization roots.')) | Out-Null }
    if ($scope -eq 'fixture') {
        if (-not [System.IO.File]::Exists((Join-Path $boundary '.skills-manager-fixture'))) { $findings.Add((New-RulePatchGuardFinding 'fixture_marker_missing' '$.target.authorized_root' 'Fixture executor requires a .skills-manager-fixture marker.')) | Out-Null }
    }
    elseif ($scope -eq 'repository') {
        if (-not [System.IO.Directory]::Exists((Join-Path $boundary '.git')) -and -not [System.IO.File]::Exists((Join-Path $boundary '.git'))) { $findings.Add((New-RulePatchGuardFinding 'repository_marker_missing' '$.target.authorized_root' 'Repository executor requires a .git marker.')) | Out-Null }
        if (-not $authorized.Equals($boundary, [System.StringComparison]::OrdinalIgnoreCase)) { $findings.Add((New-RulePatchGuardFinding 'repository_root_mismatch' '$.target.authorized_root' 'Plan and CLI repository roots must match exactly.')) | Out-Null }
        if ([System.IO.Path]::GetFileName($path) -notin @('AGENTS.md', 'AGENTS.override.md', 'CLAUDE.md')) { $findings.Add((New-RulePatchGuardFinding 'repository_target_name_forbidden' '$.target.path' 'Repository apply only accepts known rule filenames.')) | Out-Null }
    }
    if (-not (Test-RuleDiscoveryPathWithin $authorized $boundary) -or -not (Test-RuleDiscoveryPathWithin $path $authorized)) { $findings.Add((New-RulePatchGuardFinding $(if ($scope -eq 'fixture') { 'target_out_of_fixture_root' } else { 'target_out_of_authorized_root' }) '$.target.path' 'Target and authorized root must remain inside the explicit boundary.')) | Out-Null }
    if (Test-RulePatchReparsePath $path $boundary) { $findings.Add((New-RulePatchGuardFinding 'reparse_path_forbidden' '$.target.path' 'Reparse points are not accepted by the rule executor.')) | Out-Null }
    $requiredToken = [string](Get-OperationObjectProperty (Get-OperationObjectProperty $Plan 'apply') 'required_token')
    if ([string]::IsNullOrWhiteSpace($requiredToken) -or $Token -cne $requiredToken) { $findings.Add((New-RulePatchGuardFinding 'apply_token_invalid' '$.apply.required_token' 'Explicit apply token does not match.')) | Out-Null }
    $operation = [string](Get-OperationObjectProperty $target 'operation')
    if ($operation -eq 'create' -and [System.IO.File]::Exists($path)) { $findings.Add((New-RulePatchGuardFinding 'create_target_exists' '$.target.path' 'Create target already exists.')) | Out-Null }
    elseif ($operation -eq 'create' -and (Get-RulePatchTextHash '') -ne [string](Get-OperationObjectProperty $target 'before_hash')) { $findings.Add((New-RulePatchGuardFinding 'create_before_hash_invalid' '$.target.before_hash' 'Create plans must use the empty-text before hash.')) | Out-Null }
    elseif ($operation -eq 'update' -and -not [System.IO.File]::Exists($path)) { $findings.Add((New-RulePatchGuardFinding 'target_missing' '$.target.path' 'Update target must already exist.')) | Out-Null }
    elseif ($operation -eq 'update') {
        $current = [System.IO.File]::ReadAllText($path); $currentHash = Get-RulePatchTextHash $current
        if ($currentHash -ne [string](Get-OperationObjectProperty $target 'before_hash')) { $findings.Add((New-RulePatchGuardFinding 'target_hash_stale' '$.target.before_hash' 'Target content changed after planning.')) | Out-Null }
    }
    $desiredText = [string](Get-OperationObjectProperty $Plan 'desired_text')
    if ((Get-RulePatchTextHash $desiredText) -ne [string](Get-OperationObjectProperty $target 'desired_hash')) { $findings.Add((New-RulePatchGuardFinding 'desired_hash_mismatch' '$.target.desired_hash' 'Desired text does not match its declared hash.')) | Out-Null }
    return [pscustomobject][ordered]@{ pass = ($findings.Count -eq 0); findings = @($findings.ToArray()); target_path = $path; boundary_root = $boundary; writes = 0 }
}

function Remove-RulePatchTransactionFile([string]$Path) {
    if (-not [string]::IsNullOrWhiteSpace($Path) -and [System.IO.File]::Exists($Path)) { [System.IO.File]::Delete($Path) }
}

function Invoke-RulePatchApply {
    param(
        [Parameter(Mandatory = $true)]$Plan,
        [Parameter(Mandatory = $true)][string]$BoundaryRoot,
        [Parameter(Mandatory = $true)][string]$Token,
        [ValidateSet('none', 'before_stage', 'after_stage', 'before_replace', 'after_replace', 'before_receipt', 'after_replace_rollback_failure')][string]$TestFaultPoint = 'none'
    )
    $guard = Test-RulePatchApplyGuard $Plan $BoundaryRoot $Token
    if (-not $guard.pass) { return [pscustomobject][ordered]@{ pass = $false; status = 'blocked'; findings = @($guard.findings); receipt = $null; writes = 0; rollback = 'not_required' } }
    $targetPath = [string]$guard.target_path
    $targetDir = [System.IO.Path]::GetDirectoryName($targetPath)
    $suffix = [string](Get-OperationObjectProperty $Plan 'patch_id')
    $stagePath = Join-Path $targetDir ('.{0}.stage' -f $suffix)
    $backupPath = Join-Path $targetDir ('.{0}.backup' -f $suffix)
    $operation = [string](Get-OperationObjectProperty (Get-OperationObjectProperty $Plan 'target') 'operation')
    $beforeBytes = if ($operation -eq 'update') { [System.IO.File]::ReadAllBytes($targetPath) } else { [byte[]]@() }
    $started = [datetimeoffset]::UtcNow.ToString('o')
    $replaced = $false; $rollbackState = 'not_required'; $failure = $null
    try {
        if ($TestFaultPoint -eq 'before_stage') { throw 'test_fault:before_stage' }
        $desiredBytes = (New-Object System.Text.UTF8Encoding($false)).GetBytes([string](Get-OperationObjectProperty $Plan 'desired_text'))
        [System.IO.File]::WriteAllBytes($stagePath, $desiredBytes)
        if ($TestFaultPoint -eq 'after_stage') { throw 'test_fault:after_stage' }
        if ($operation -eq 'update') {
            $freshText = [System.IO.File]::ReadAllText($targetPath)
            if ((Get-RulePatchTextHash $freshText) -ne [string](Get-OperationObjectProperty (Get-OperationObjectProperty $Plan 'target') 'before_hash')) { throw 'target_hash_stale_before_replace' }
        }
        elseif ([System.IO.File]::Exists($targetPath)) { throw 'create_target_appeared_before_replace' }
        if ($TestFaultPoint -eq 'before_replace') { throw 'test_fault:before_replace' }
        if ($operation -eq 'update') { [System.IO.File]::Replace($stagePath, $targetPath, $backupPath, $true) }
        else { [System.IO.File]::Move($stagePath, $targetPath) }
        $replaced = $true
        if ($TestFaultPoint -in @('after_replace', 'after_replace_rollback_failure')) { throw ('test_fault:{0}' -f $TestFaultPoint) }
        $appliedHash = Get-RulePatchTextHash ([System.IO.File]::ReadAllText($targetPath))
        if ($appliedHash -ne [string](Get-OperationObjectProperty (Get-OperationObjectProperty $Plan 'target') 'desired_hash')) { throw 'desired_hash_not_applied' }
        if ($TestFaultPoint -eq 'before_receipt') { throw 'test_fault:before_receipt' }
        Remove-RulePatchTransactionFile $backupPath
        $receipt = New-OperationReceipt -OperationId ([string](Get-OperationObjectProperty $Plan 'operation_id')) -Status applied -StartedAt $started -CompletedAt ([datetimeoffset]::UtcNow.ToString('o')) -Actions @([pscustomobject]@{ action_id = [string](Get-OperationObjectProperty $Plan 'patch_id'); status = 'applied'; target_ref = 'rule-target' }) -Verification ([pscustomobject]@{ static_validated = 'pass'; repo_gates_passed = 'not_run'; host_loaded = 'not_run'; live_accepted = 'not_run' }) -Rollback @($(if ($operation -eq 'create') { 'delete_created_file' } else { 'restore_before_bytes' }))
        return [pscustomobject][ordered]@{ pass = $true; status = 'applied'; findings = @(); receipt = $receipt; writes = 1; rollback = 'not_required' }
    }
    catch {
        $failure = $_.Exception.Message
        if ($replaced) {
            if ($TestFaultPoint -eq 'after_replace_rollback_failure') { $rollbackState = 'rollback_failed' }
            else {
                try {
                    if ($operation -eq 'create') { [System.IO.File]::Delete($targetPath) }
                    else { Write-BytesAtomic -Path $targetPath -Bytes $beforeBytes }
                    $rollbackState = 'restored'
                }
                catch { $rollbackState = 'rollback_failed'; $failure = '{0}; rollback: {1}' -f $failure, $_.Exception.Message }
            }
        }
        $receiptStatus = if ($rollbackState -eq 'restored') { 'rolled_back' } else { 'failed' }
        $receipt = New-OperationReceipt -OperationId ([string](Get-OperationObjectProperty $Plan 'operation_id')) -Status $receiptStatus -StartedAt $started -CompletedAt ([datetimeoffset]::UtcNow.ToString('o')) -Actions @([pscustomobject]@{ action_id = [string](Get-OperationObjectProperty $Plan 'patch_id'); status = 'failed'; target_ref = 'rule-target'; error = $failure }) -Verification ([pscustomobject]@{ static_validated = 'fail'; repo_gates_passed = 'not_run'; host_loaded = 'not_run'; live_accepted = 'not_run' }) -Rollback @([pscustomobject]@{ state = $rollbackState })
        return [pscustomobject][ordered]@{ pass = $false; status = $receiptStatus; findings = @([pscustomobject]@{ code = $failure; severity = 'error'; path = $targetPath; message = $failure }); receipt = $receipt; writes = $(if ($replaced) { 1 } else { 0 }); rollback = $rollbackState }
    }
    finally {
        Remove-RulePatchTransactionFile $stagePath
        if ($rollbackState -ne 'rollback_failed') { Remove-RulePatchTransactionFile $backupPath }
    }
}

function Normalize-RepoUrl([string]$repo) {
    $r = $repo.Trim()
    if ($r -match "^(git@github.com:).+") {
        if (-not $r.EndsWith(".git")) { return ($r + ".git") }
        return $r
    }
    if ($r -match "^https?://github.com/.+") {
        if (-not $r.EndsWith(".git")) { return ($r + ".git") }
        return $r
    }
    if ($r -match "^github.com/.+") {
        $u = "https://{0}" -f $r
        if (-not $u.EndsWith(".git")) { $u += ".git" }
        return $u
    }
    if ($r -match "^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$") {
        return ("https://github.com/{0}.git" -f $r)
    }
    return $r
}
function Remove-GitHubTreeSuffix([string]$repo) {
    if ([string]::IsNullOrWhiteSpace($repo)) { return $repo }
    $r = $repo.Trim().Trim("'`"")
    if ($r -match "^(https?://github\.com/[^/]+/[^/]+?)(?:\.git)?/tree/[^/]+/.+$") {
        return ($Matches[1] + ".git")
    }
    return $r
}
function Guess-VendorName([string]$repo) {
    $r = $repo.Trim().TrimEnd("/")
    if ($r.EndsWith(".git")) { $r = $r.Substring(0, $r.Length - 4) }
    $leaf = Split-Path $r -Leaf
    $name = Normalize-Name $leaf
    if ([string]::IsNullOrWhiteSpace($name)) {
        if ($repo -match "^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+@.+$") {
            throw "无法从 URL 推断 vendor 名称。检测到 repo@skill 写法，请改用：<repo> --skill <name>（例如：vercel-labs/skills --skill skills/find-skills）"
        }
        throw "无法从 URL 推断 vendor 名称，请手动输入名称。"
    }
    return $name
}
function Mask-SensitiveGitText([string]$text) {
    if ([string]::IsNullOrWhiteSpace($text)) { return $text }
    if ($null -ne (Get-Command Protect-SensitiveText -CommandType Function -ErrorAction SilentlyContinue)) {
        return (Protect-SensitiveText $text)
    }
    $masked = [string]$text
    $masked = [regex]::Replace($masked, '(?i)([a-z][a-z0-9+.-]*://)([^/@\s:]+):([^/@\s]+)@', '$1<redacted>@')
    $masked = [regex]::Replace($masked, '(?i)([?&](?:access_token|auth|authorization|password|passwd|secret|token|api[-_]?key)=)[^&\s]+', '$1<redacted>')
    $masked = [regex]::Replace($masked, '(?i)((?:authorization|proxy-authorization)\s*[:=]\s*(?:basic|bearer)?\s*)[^\s"'']+', '$1<redacted>')
    $masked = [regex]::Replace($masked, '(?i)((?:password|passwd|secret|token|api[-_]?key)\s*[=:]\s*)[^\s"'']+', '$1<redacted>')
    $masked = [regex]::Replace($masked, '(?i)(\b(?:password|passwd|secret|token|api[-_]?key)\s+)[^\s"'',;]+', '$1<redacted>')
    $masked = [regex]::Replace($masked, '(?i)\b(?:github_pat_[A-Za-z0-9_]+|gh[pousr]_[A-Za-z0-9_]+)\b', '<redacted>')
    return $masked
}
function Invoke-Git([string[]]$GitArgs) {
    $safeArgs = @($GitArgs | ForEach-Object { Mask-SensitiveGitText ([string]$_) })
    if ($DryRun) {
        Log ("DRYRUN git {0}" -f ($safeArgs -join " "))
        return
    }
    $cmdText = ("git {0}" -f ($safeArgs -join " "))
    $retriedAfterLockRecovery = $false
    $canTuneNativeErrPref = ($PSVersionTable.PSVersion.Major -ge 7)
    while ($true) {
        Log $cmdText
        $prevNativeErrorPref = $null
        $prevErrorActionPreference = $ErrorActionPreference
        try {
            if ($canTuneNativeErrPref) {
                $prevNativeErrorPref = $PSNativeCommandUseErrorActionPreference
                $PSNativeCommandUseErrorActionPreference = $false
            }
            $ErrorActionPreference = "Continue"
            $output = & git @GitArgs 2>&1
            $exitCode = $LASTEXITCODE
        }
        finally {
            $ErrorActionPreference = $prevErrorActionPreference
            if ($canTuneNativeErrPref) {
                $PSNativeCommandUseErrorActionPreference = $prevNativeErrorPref
            }
        }
        if ($output) {
            foreach ($line in @($output)) {
                $text = Convert-GitOutputLineToText $line
                if ([string]::IsNullOrWhiteSpace($text)) { continue }
                Write-Host (Mask-SensitiveGitText $text)
            }
        }
        if ($exitCode -eq 0) { return }
        if (-not $retriedAfterLockRecovery) {
            $repaired = $false
            if (Repair-StaleGitLockFromOutput (Get-Location).Path $output) {
                $repaired = $true
            }
            elseif (Repair-StaleGitLockAfterFailure (Get-Location).Path $output) {
                $repaired = $true
            }
            if ($repaired) {
                $retriedAfterLockRecovery = $true
                continue
            }
        }
        $summary = Get-GitOutputSummary $output
        if ([string]::IsNullOrWhiteSpace($summary)) {
            throw ("git 失败：{0}" -f $cmdText)
        }
        throw ("git 失败：{0}；详情：{1}" -f $cmdText, $summary)
    }
}
function Invoke-GitCapture([string[]]$GitArgs) {
    $safeArgs = @($GitArgs | ForEach-Object { Mask-SensitiveGitText ([string]$_) })
    if ($DryRun) {
        Log ("DRYRUN git {0}" -f ($safeArgs -join " "))
        return ""
    }
    Log ("git {0}" -f ($safeArgs -join " "))
    $canTuneNativeErrPref = ($PSVersionTable.PSVersion.Major -ge 7)
    $prevNativeErrorPref = $null
    $prevErrorActionPreference = $ErrorActionPreference
    try {
        if ($canTuneNativeErrPref) {
            $prevNativeErrorPref = $PSNativeCommandUseErrorActionPreference
            $PSNativeCommandUseErrorActionPreference = $false
        }
        $ErrorActionPreference = "Continue"
        $out = & git @GitArgs 2>$null
        if ($LASTEXITCODE -ne 0) { return $null }
    }
    finally {
        $ErrorActionPreference = $prevErrorActionPreference
        if ($canTuneNativeErrPref) {
            $PSNativeCommandUseErrorActionPreference = $prevNativeErrorPref
        }
    }
    if ($null -eq $out) { return "" }
    return (($out | Select-Object -First 1).ToString().Trim())
}
function Invoke-GitCaptureLines([string[]]$GitArgs) {
    $safeArgs = @($GitArgs | ForEach-Object { Mask-SensitiveGitText ([string]$_) })
    if ($DryRun) {
        Log ("DRYRUN git {0}" -f ($safeArgs -join " "))
        return @()
    }
    Log ("git {0}" -f ($safeArgs -join " "))
    $canTuneNativeErrPref = ($PSVersionTable.PSVersion.Major -ge 7)
    $prevNativeErrorPref = $null
    $prevErrorActionPreference = $ErrorActionPreference
    try {
        if ($canTuneNativeErrPref) {
            $prevNativeErrorPref = $PSNativeCommandUseErrorActionPreference
            $PSNativeCommandUseErrorActionPreference = $false
        }
        $ErrorActionPreference = "Continue"
        $out = & git @GitArgs 2>$null
        if ($LASTEXITCODE -ne 0) { return @() }
    }
    finally {
        $ErrorActionPreference = $prevErrorActionPreference
        if ($canTuneNativeErrPref) {
            $PSNativeCommandUseErrorActionPreference = $prevNativeErrorPref
        }
    }
    $lines = @()
    foreach ($line in @($out)) {
        $text = Convert-GitOutputLineToText $line
        if ([string]::IsNullOrWhiteSpace($text)) { continue }
        $lines += $text
    }
    return ,$lines
}
function Get-SkillCandidatesFromGitRepo([string]$repo, [string]$ref) {
    Need (-not [string]::IsNullOrWhiteSpace($repo)) "Repo URL 不能为空。"
    Need (-not [string]::IsNullOrWhiteSpace($ref)) "ref 不能为空。"

    $tmpName = ("_tree_{0}" -f ([Guid]::NewGuid().ToString("N").Substring(0, 8)))
    $tmpBase = Join-Path $ImportDir $tmpName
    $barePath = Join-Path $tmpBase "repo.git"
    EnsureDir $tmpBase
    try {
        Invoke-Git @("clone", "--bare", $repo, $barePath)
        $gitDirArg = "--git-dir={0}" -f $barePath
        $allFiles = Invoke-GitCaptureLines @($gitDirArg, "ls-tree", "-r", "--name-only", $ref)
        $seenDirs = New-Object System.Collections.Generic.HashSet[string]
        $candidates = @()
        foreach ($f in $allFiles) {
            if ([string]::IsNullOrWhiteSpace($f)) { continue }
            if ($f -notmatch "(^|/)(SKILL|AGENTS|GEMINI|CLAUDE)\.md$") { continue }
            $dir = Split-Path ($f -replace "/", "\") -Parent
            if ([string]::IsNullOrWhiteSpace($dir)) { $dir = "." }
            $dirGit = ($dir -replace "\\", "/")
            if ($dirGit -match "(^|/)_archive(/|$)") { continue }
            if (-not $seenDirs.Add($dir)) { continue }
            $candidates += [pscustomobject]@{
                rel = $dir
                leaf = (Split-Path $dir -Leaf)
            }
        }
        return ,@($candidates | Sort-Object rel)
    }
    finally {
        Invoke-RemoveItemWithRetry $tmpBase -Recurse -IgnoreFailure | Out-Null
    }
}
function Assert-RepoReachable([string]$repo) {
    Need (-not [string]::IsNullOrWhiteSpace($repo)) "Repo URL 不能为空。"
    if (Test-LocalZipRepoInput $repo) {
        return
    }
    $out = Invoke-GitCapture @("ls-remote", "--exit-code", $repo, "HEAD")
    if ([string]::IsNullOrWhiteSpace($out)) {
        throw ("仓库不可访问或不存在：{0}。请检查 owner/repo 是否正确，或确认仓库是否私有且当前 git 凭据可访问。" -f $repo)
    }
}
function Test-LocalZipRepoInput([string]$repo) {
    if ([string]::IsNullOrWhiteSpace($repo)) { return $false }
    $r = $repo.Trim().Trim("'`"")
    if ($r -notmatch "(?i)\.zip$") { return $false }
    return (Test-Path -LiteralPath $r -PathType Leaf)
}
function Invoke-WithRetry([scriptblock]$Action, [int]$MaxAttempts = 3, [int]$DelayMs = 250) {
    for ($attempt = 1; $attempt -le $MaxAttempts; $attempt++) {
        try {
            & $Action
            return
        }
        catch {
            if ($attempt -ge $MaxAttempts) { throw }
            Start-Sleep -Milliseconds $DelayMs
        }
    }
}
function Resolve-ZipExtractionRoot([string]$extractDir) {
    Need (Test-Path $extractDir) ("解压目录不存在：{0}" -f $extractDir)
    $children = @(Get-ChildItem -LiteralPath $extractDir -Force -ErrorAction SilentlyContinue)
    $dirs = @($children | Where-Object { $_.PSIsContainer })
    $files = @($children | Where-Object { -not $_.PSIsContainer })
    if ($files.Count -eq 0 -and $dirs.Count -eq 1) {
        return $dirs[0].FullName
    }
    return $extractDir
}

function Assert-ZipArchiveSafety {
    param(
        [Parameter(Mandatory=$true)][string]$ZipPath,
        [long]$MaxArchiveBytes=536870912,
        [int]$MaxEntries=50000,
        [long]$MaxEntryBytes=536870912,
        [long]$MaxExpandedBytes=2147483648,
        [double]$MaxCompressionRatio=200,
        [int]$MaxDepth=32
    )
    $file=Get-Item -LiteralPath $ZipPath -Force -ErrorAction Stop
    Need ($file.Length -le $MaxArchiveBytes) ("zip archive exceeds byte budget: {0}" -f $file.Length)
    $archive=[IO.Compression.ZipFile]::OpenRead($file.FullName)
    try{
        Need ($archive.Entries.Count -le $MaxEntries) ("zip archive exceeds entry budget: {0}" -f $archive.Entries.Count)
        [long]$expanded=0
        $canonicalPaths=New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
        foreach($entry in $archive.Entries){
            $name=[string]$entry.FullName
            Need (-not [string]::IsNullOrWhiteSpace($name)) 'zip entry path is empty.'
            Need (-not [IO.Path]::IsPathRooted($name) -and $name -notmatch '^[\\/]' -and $name -notmatch ':') ("zip entry path is absolute or contains ADS syntax: {0}" -f $name)
            $segments=@((($name -replace '\\','/') -split '/')|Where-Object{$_ -ne ''})
            Need ($segments.Count -le $MaxDepth) ("zip entry exceeds depth budget: {0}" -f $name)
            Need (@($segments|Where-Object{$_ -eq '..' -or $_ -eq '.'}).Count -eq 0) ("zip entry traversal is forbidden: {0}" -f $name)
            foreach($segment in $segments){
                Need ($segment -eq $segment.TrimEnd(' ','.')) ("zip entry has a trailing dot or space: {0}" -f $name)
                Need ($segment -notmatch '^(?i:CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(?:\.|$)') ("zip entry uses a reserved Windows name: {0}" -f $name)
            }
            $canonicalName=((@($segments|ForEach-Object{$_.Normalize([Text.NormalizationForm]::FormC)}) -join '/').TrimEnd('/'))
            Need ($canonicalPaths.Add($canonicalName)) ("zip entry has a duplicate canonical path: {0}" -f $name)
            $unixType=(($entry.ExternalAttributes -shr 16) -band 0xF000)
            Need ($unixType -ne 0xA000) ("zip symlink entry is forbidden: {0}" -f $name)
            Need ($entry.Length -le $MaxEntryBytes) ("zip entry exceeds byte budget: {0}" -f $name)
            $expanded+=[long]$entry.Length
            Need ($expanded -le $MaxExpandedBytes) ("zip archive exceeds expanded byte budget: {0}" -f $expanded)
            if($entry.Length -gt 0){
                Need ($entry.CompressedLength -gt 0) ("zip entry has invalid zero compressed length: {0}" -f $name)
                Need (([double]$entry.Length/[double]$entry.CompressedLength) -le $MaxCompressionRatio) ("zip entry exceeds compression ratio budget: {0}" -f $name)
            }
        }
    }finally{$archive.Dispose()}
}

function Assert-StagedDirectoryNoReparse([string]$Path) {
    foreach($entry in @(Get-ChildItem -LiteralPath $Path -Force -Recurse -ErrorAction Stop)){
        Need (($entry.Attributes -band [IO.FileAttributes]::ReparsePoint) -eq 0) ("staged archive contains a reparse point: {0}" -f $entry.FullName)
    }
}

function Install-StagedDirectoryAtomic([string]$SourcePath,[string]$TargetPath,[bool]$ForceClean=$true) {
    $targetExists=Test-Path -LiteralPath $TargetPath
    if($targetExists){Need $ForceClean ("缓存目录已存在且 update_force=false：{0}" -f $TargetPath)}
    EnsureDir (Split-Path $TargetPath -Parent)
    $backupPath=("{0}.previous-{1}" -f $TargetPath,[guid]::NewGuid().ToString('N'))
    $movedOld=$false
    try{
        if($targetExists){Invoke-MoveItem $TargetPath $backupPath;$movedOld=$true}
        Invoke-MoveItem $SourcePath $TargetPath
        if($movedOld){Invoke-RemoveItemWithRetry $backupPath -Recurse}
    }catch{
        if(Test-Path -LiteralPath $TargetPath){Invoke-RemoveItemWithRetry $TargetPath -Recurse -IgnoreFailure|Out-Null}
        if($movedOld -and (Test-Path -LiteralPath $backupPath)){Invoke-MoveItem $backupPath $TargetPath}
        throw
    }
}

function Ensure-RepoFromZip([string]$path, [string]$zipPath, [bool]$forceClean = $true) {
    $zip = $zipPath.Trim().Trim("'`"")
    Need (Test-Path -LiteralPath $zip -PathType Leaf) ("zip 文件不存在：{0}" -f $zipPath)

    if (Test-Path $path) { Need $forceClean ("缓存目录已存在且 update_force=false：{0}" -f $path) }

    $tmpName = ("_zip_{0}" -f ([Guid]::NewGuid().ToString("N").Substring(0, 8)))
    $tmpBase = Join-Path $ImportDir $tmpName
    $tmpZip = Join-Path $tmpBase "source.zip"
    $extractDir = Join-Path $tmpBase "extract"
    EnsureDir $tmpBase
    try {
        Log ("Copy-Item {0} -> {1}" -f $zip, $tmpZip)
        Invoke-WithRetry { Copy-Item -LiteralPath $zip -Destination $tmpZip -Force } 3 250

        Assert-ZipArchiveSafety -ZipPath $tmpZip
        Log ("Expand-Archive {0} -> {1}" -f $tmpZip, $extractDir)
        Invoke-WithRetry { Expand-Archive -LiteralPath $tmpZip -DestinationPath $extractDir -Force } 3 250
        Assert-StagedDirectoryNoReparse $extractDir

        $sourceRoot = Resolve-ZipExtractionRoot $extractDir
        Install-StagedDirectoryAtomic $sourceRoot $path $forceClean
    }
    catch {
        $msg = $_.Exception.Message
        if ($msg -match "由另一进程使用|being used by another process") {
            throw ("zip 文件当前被占用：{0}。请关闭占用进程后重试。" -f $zipPath)
        }
        throw
    }
    finally {
        Invoke-RemoveItemWithRetry $tmpBase -Recurse -IgnoreFailure
    }
}
function Ensure-RepoFromGitArchive([string]$path, [string]$repo, [string]$ref, [string]$skillPath, [bool]$forceClean = $true) {
    Need (-not [string]::IsNullOrWhiteSpace($repo)) "Repo URL 不能为空。"
    Need (-not [string]::IsNullOrWhiteSpace($ref)) "ref 不能为空。"
    $normalizedSkill = Normalize-SkillPath $skillPath
    Need ($normalizedSkill -ne ".") "git archive 回退模式不支持根路径 '.'，请指定具体子目录。"

    if (Test-Path $path) { Need $forceClean ("缓存目录已存在且 update_force=false：{0}" -f $path) }

    $tmpName = ("_archive_{0}" -f ([Guid]::NewGuid().ToString("N").Substring(0, 8)))
    $tmpBase = Join-Path $ImportDir $tmpName
    $barePath = Join-Path $tmpBase "repo.git"
    $zipPath = Join-Path $tmpBase "export.zip"
    $extractPath = Join-Path $tmpBase "extract"
    EnsureDir $tmpBase
    try {
        Invoke-Git @("clone", "--bare", $repo, $barePath)
        $gitDirArg = "--git-dir={0}" -f $barePath
        $gitPath = To-GitPath $normalizedSkill
        Invoke-Git @($gitDirArg, "archive", "--format=zip", "--output", $zipPath, $ref, $gitPath)
        Assert-ZipArchiveSafety -ZipPath $zipPath
        Expand-Archive -LiteralPath $zipPath -DestinationPath $extractPath -Force
        Assert-StagedDirectoryNoReparse $extractPath
        Install-StagedDirectoryAtomic (Resolve-ZipExtractionRoot $extractPath) $path $forceClean
    }
    finally {
        Invoke-RemoveItemWithRetry $tmpBase -Recurse -IgnoreFailure
    }
}
function Resolve-GitHubOwnerRepo([string]$repo) {
    if ([string]::IsNullOrWhiteSpace($repo)) { return $null }
    $r = Remove-GitHubTreeSuffix $repo
    $r = $r.Trim().Trim("'`"")
    if ($r -match "^git@github\.com:(.+?)/(.+?)(?:\.git)?$") {
        return [pscustomobject]@{ owner = $Matches[1]; name = $Matches[2] }
    }
    if ($r -match "^https?://github\.com/(.+?)/(.+?)(?:\.git)?/?$") {
        return [pscustomobject]@{ owner = $Matches[1]; name = $Matches[2] }
    }
    if ($r -match "^github\.com/(.+?)/(.+?)(?:\.git)?/?$") {
        return [pscustomobject]@{ owner = $Matches[1]; name = $Matches[2] }
    }
    return $null
}

function Get-GitBlobSha1ForFile([string]$Path) {
    $bytes=[IO.File]::ReadAllBytes($Path)
    $header=[Text.Encoding]::ASCII.GetBytes(("blob {0}`0" -f $bytes.LongLength))
    $stream=[IO.MemoryStream]::new()
    try{
        $stream.Write($header,0,$header.Length);$stream.Write($bytes,0,$bytes.Length);$stream.Position=0
        $sha=[Security.Cryptography.SHA1]::Create()
        try{return (($sha.ComputeHash($stream)|ForEach-Object{$_.ToString('x2')})-join '')}finally{$sha.Dispose()}
    }finally{$stream.Dispose()}
}

function Ensure-RepoFromGitHubTreeSnapshot([string]$path, [string]$repo, [string]$ref, [string]$skillPath, [bool]$forceClean = $true) {
    Need (-not [string]::IsNullOrWhiteSpace($repo)) "Repo URL 不能为空。"
    Need (-not [string]::IsNullOrWhiteSpace($ref)) "ref 不能为空。"
    $normalizedSkill = Normalize-SkillPath $skillPath
    Need ($normalizedSkill -ne ".") "GitHub 快照回退不支持根路径 '.'，请指定具体子目录。"

    $ownerRepo = Resolve-GitHubOwnerRepo $repo
    Need ($null -ne $ownerRepo) ("GitHub 快照回退仅支持 github.com 仓库：{0}" -f $repo)

    if (Test-Path $path) { Need $forceClean ("缓存目录已存在且 update_force=false：{0}" -f $path) }

    $headers = @{
        "User-Agent" = "skills-manager"
        "Accept" = "application/vnd.github+json"
    }
    $encodedRef = [System.Uri]::EscapeDataString($ref)
    $commitUrl=("https://api.github.com/repos/{0}/{1}/commits/{2}" -f $ownerRepo.owner,$ownerRepo.name,$encodedRef)
    $commitResp=Invoke-RestMethod -Uri $commitUrl -Headers $headers -Method Get -ErrorAction Stop
    $commitSha=[string]$commitResp.sha;$treeSha=[string]$commitResp.commit.tree.sha
    Need ($commitSha -match '^[a-fA-F0-9]{40}$' -and $treeSha -match '^[a-fA-F0-9]{40}$') 'GitHub commit response does not provide immutable commit/tree SHA.'
    $treeUrl = ("https://api.github.com/repos/{0}/{1}/git/trees/{2}?recursive=1" -f $ownerRepo.owner, $ownerRepo.name, $treeSha)
    $treeResp = Invoke-RestMethod -Uri $treeUrl -Headers $headers -Method Get -ErrorAction Stop
    Need ($treeResp -and $treeResp.tree) ("GitHub 树接口返回为空：{0}" -f $treeUrl)
    Need (-not [bool]$treeResp.truncated) 'GitHub tree response is truncated; refusing an incomplete snapshot.'

    $prefix = (To-GitPath $normalizedSkill).Trim("/")
    Need (-not [string]::IsNullOrWhiteSpace($prefix)) "技能路径无效。"
    $prefixSlash = "$prefix/"

    $blobs = @($treeResp.tree | Where-Object {
            $_.type -eq "blob" -and $_.path -is [string] -and ($_.path -eq $prefix -or $_.path.StartsWith($prefixSlash))
        })
    Need ($blobs.Count -gt 0) ("GitHub 快照回退未找到目标路径：{0}" -f $normalizedSkill)
    Need ($blobs.Count -le 50000) ("GitHub snapshot exceeds blob count budget: {0}" -f $blobs.Count)
    [long]$snapshotBytes = 0
    $snapshotPaths=New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
    foreach ($blob in $blobs) {
        $blobPath=[string]$blob.path
        Need ($blobPath -notmatch '[\\:]' -and -not [IO.Path]::IsPathRooted($blobPath)) ("GitHub tree path is not portable: {0}" -f $blobPath)
        $blobSegments=@($blobPath -split '/')
        Need (@($blobSegments|Where-Object{[string]::IsNullOrWhiteSpace($_) -or $_ -eq '.' -or $_ -eq '..'}).Count -eq 0) ("GitHub tree path contains an invalid segment: {0}" -f $blobPath)
        foreach($segment in $blobSegments){
            Need ($segment -eq $segment.TrimEnd(' ','.')) ("GitHub tree path has a trailing dot or space: {0}" -f $blobPath)
            Need ($segment -notmatch '^(?i:CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(?:\.|$)') ("GitHub tree path uses a reserved Windows name: {0}" -f $blobPath)
        }
        $canonicalPath=(@($blobSegments|ForEach-Object{$_.Normalize([Text.NormalizationForm]::FormC)}) -join '/')
        Need ($snapshotPaths.Add($canonicalPath)) ("GitHub tree contains a duplicate canonical path: {0}" -f $blobPath)
        [long]$blobBytes = 0
        Need ([long]::TryParse([string]$blob.size, [ref]$blobBytes) -and $blobBytes -ge 0) ("GitHub tree blob lacks a valid size: {0}" -f [string]$blob.path)
        Need ($blobBytes -le 536870912) ("GitHub snapshot blob exceeds byte budget: {0}" -f [string]$blob.path)
        $snapshotBytes += $blobBytes
        Need ($snapshotBytes -le 2147483648) ("GitHub snapshot exceeds expanded byte budget: {0}" -f $snapshotBytes)
    }

    $tmpBase=Join-Path $ImportDir ("_github_snapshot_{0}" -f [guid]::NewGuid().ToString('N').Substring(0,8));$extractDir=Join-Path $tmpBase 'extract';EnsureDir $extractDir
    try{
        foreach ($blob in $blobs) {
            $blobPath = [string]$blob.path
            if ([string]::IsNullOrWhiteSpace($blobPath)) { continue }
            Need ([string]$blob.sha -match '^[a-fA-F0-9]{40}$') ("GitHub tree blob lacks immutable SHA: {0}" -f $blobPath)
            $relPath = $blobPath -replace "/", "\"
            $dstPath = [IO.Path]::GetFullPath((Join-Path $extractDir $relPath))
            Need (Is-PathInsideOrEqual $dstPath $extractDir) ("GitHub tree path escapes snapshot root: {0}" -f $blobPath)
            EnsureDir (Split-Path $dstPath -Parent)
            $encodedBlobPath = ((@($blobPath -split '/') | ForEach-Object { [Uri]::EscapeDataString($_) }) -join '/')
            $rawUrl = ("https://raw.githubusercontent.com/{0}/{1}/{2}/{3}" -f $ownerRepo.owner, $ownerRepo.name, $commitSha, $encodedBlobPath)
            Invoke-WebRequest -Uri $rawUrl -Headers @{ "User-Agent" = "skills-manager" } -OutFile $dstPath -ErrorAction Stop | Out-Null
            Need ((Get-GitBlobSha1ForFile $dstPath) -eq ([string]$blob.sha).ToLowerInvariant()) ("GitHub blob SHA mismatch: {0}" -f $blobPath)
        }
        Install-StagedDirectoryAtomic $extractDir $path $forceClean
    }finally{Invoke-RemoveItemWithRetry $tmpBase -Recurse -IgnoreFailure|Out-Null}
}
function Parse-DefaultBranchFromSymref([string]$line) {
    if ([string]::IsNullOrWhiteSpace($line)) { return $null }
    $text = $line.Trim()
    if ($text -match "^ref:\s+refs/heads/(.+?)\s+HEAD$") {
        $branch = $Matches[1].Trim()
        if (-not [string]::IsNullOrWhiteSpace($branch)) { return $branch }
    }
    return $null
}
function Get-RepoDefaultBranch([string]$repo) {
    Need (-not [string]::IsNullOrWhiteSpace($repo)) "Repo URL 不能为空。"

    $symrefLine = Invoke-GitCapture @("ls-remote", "--symref", $repo, "HEAD")
    $branch = Parse-DefaultBranchFromSymref $symrefLine
    if (-not [string]::IsNullOrWhiteSpace($branch)) { return $branch }

    foreach ($fallback in @("main", "master")) {
        $probe = Invoke-GitCapture @("ls-remote", "--exit-code", $repo, ("refs/heads/{0}" -f $fallback))
        if (-not [string]::IsNullOrWhiteSpace($probe)) {
            Log ("未能从 symref 解析默认分支，回退为已存在分支：{0}" -f $fallback)
            return $fallback
        }
    }

    Log "未能探测仓库默认分支，回退为 main。"
    return "main"
}
function Get-GitHeadBranch {
    $head = Invoke-GitCapture @("rev-parse", "--abbrev-ref", "HEAD")
    if ([string]::IsNullOrWhiteSpace($head) -or $head -eq "HEAD") { return $null }
    return $head
}
function Get-RepoIdentity([string]$repo) {
    if ([string]::IsNullOrWhiteSpace($repo)) { return $null }
    $r = Remove-GitHubTreeSuffix $repo
    $r = $r.Trim().Trim("'`"")
    if ($r -match "^ssh://git@github\.com/(.+?)/(.+?)(?:\.git)?/?$") {
        return ("github.com/{0}/{1}" -f $Matches[1], $Matches[2]).ToLowerInvariant()
    }
    if ($r -match "^git@github\.com:(.+)$") {
        $r = "https://github.com/$($Matches[1])"
    }
    $n = Normalize-RepoUrl $r
    if ([string]::IsNullOrWhiteSpace($n)) { return $r.ToLowerInvariant() }
    if ($n -match "^https?://github\.com/(.+)$") {
        $path = $Matches[1]
        $path = $path.TrimEnd("/")
        if ($path.EndsWith(".git")) { $path = $path.Substring(0, $path.Length - 4) }
        $parts = $path.Split("/") | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
        if ($parts.Count -ge 2) {
            return ("github.com/{0}/{1}" -f $parts[0], $parts[1]).ToLowerInvariant()
        }
        return ("github.com/{0}" -f $path).ToLowerInvariant()
    }
    if ($n.EndsWith(".git")) { $n = $n.Substring(0, $n.Length - 4) }
    return $n.TrimEnd("/").ToLowerInvariant()
}
function Get-RepoIdentityKey([string]$repo) {
    return (Get-RepoIdentity $repo)
}
function Is-SameRepoIdentity([string]$a, [string]$b) {
    $ia = Get-RepoIdentity $a
    $ib = Get-RepoIdentity $b
    if ([string]::IsNullOrWhiteSpace($ia) -or [string]::IsNullOrWhiteSpace($ib)) { return $false }
    return ($ia -eq $ib)
}
function Is-SameRepository([string]$a, [string]$b) {
    return (Is-SameRepoIdentity $a $b)
}
function Test-LooksLikeRepoUrl([string]$value) {
    if ([string]::IsNullOrWhiteSpace($value)) { return $false }
    $v = $value.Trim().Trim("'`"")
    if ($v -match "^(git@github\.com:|https?://github\.com/|github\.com/)") { return $true }
    if ($v -match "^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+\.git$") { return $true }
    return $false
}
function Test-InstalledVendorPath([string]$path, [string]$repo) {
    if ([string]::IsNullOrWhiteSpace($path) -or [string]::IsNullOrWhiteSpace($repo)) { return $false }
    if (-not (Test-Path -LiteralPath $path -PathType Container)) { return $false }
    if (-not (Test-Path -LiteralPath (Join-Path $path ".git") -PathType Container)) { return $false }

    $origin = $null
    Push-Location $path
    try {
        $origin = Invoke-GitCapture @("remote", "get-url", "origin")
    }
    catch {
        return $false
    }
    finally {
        Pop-Location
    }

    if ([string]::IsNullOrWhiteSpace($origin)) { return $false }
    return (Is-SameRepoIdentity $origin $repo)
}
function Has-GitUpstream {
    $up = Invoke-GitCapture @("rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{u}")
    return -not [string]::IsNullOrWhiteSpace($up)
}
function Update-CurrentBranchFromUpstream([bool]$AllowNetworkFetch = $true) {
    $branch = Get-GitHeadBranch
    if (-not $branch -or -not (Has-GitUpstream)) {
        Log "跳过 git pull：当前为 detached HEAD 或无 upstream。"
        return
    }
    if ($AllowNetworkFetch) {
        try {
            Invoke-Git @("pull", "--ff-only")
        }
        catch {
            throw ("网络 ff-only 快进失败，未执行破坏性 reset：{0}；原因：{1}" -f $branch, (Mask-SensitiveGitText $_.Exception.Message))
        }
        return
    }
    try {
        Invoke-Git @("merge", "--ff-only", "@{u}")
        Log ("已基于本地 refs 快进分支：{0}" -f $branch)
    }
    catch {
        throw ("本地 ff-only 快进失败，未执行破坏性 reset：{0}；原因：{1}" -f $branch, (Mask-SensitiveGitText $_.Exception.Message))
    }
}
function Has-GitChanges {
    $out = Invoke-GitCapture @("status", "--porcelain")
    return -not [string]::IsNullOrWhiteSpace($out)
}
function Get-GitLockPathFromOutputLine([string]$line) {
    if ([string]::IsNullOrWhiteSpace($line)) { return $null }
    $m = [regex]::Match($line, "Unable to create '([^']+index\.lock)'", [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
    if ($m.Success) { return $m.Groups[1].Value }
    $m = [regex]::Match($line, '无法创建[“"]([^“"'']+index\.lock)[”"]')
    if ($m.Success) { return $m.Groups[1].Value }
    $m = [regex]::Match($line, "unable to unlink '([^']+index\.lock)'", [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
    if ($m.Success) { return $m.Groups[1].Value }
    $m = [regex]::Match($line, '无法取消链接[“"]([^“"'']+index\.lock)[”"]')
    if ($m.Success) { return $m.Groups[1].Value }
    return $null
}
function Test-GitIndexLockIssue($outputLines) {
    foreach ($line in @($outputLines)) {
        $text = [string]$line
        if ([string]::IsNullOrWhiteSpace($text)) { continue }
        if ($text -match "index\.lock|Could not write new index file|无法写入新的索引文件") {
            return $true
        }
    }
    return $false
}
function Convert-GitOutputLineToText($line) {
    if ($null -eq $line) { return $null }
    if ($line -is [System.Management.Automation.ErrorRecord]) {
        if ($line.Exception -and -not [string]::IsNullOrWhiteSpace($line.Exception.Message)) {
            return $line.Exception.Message.Trim()
        }
        $fallback = $line.ToString()
        if ([string]::IsNullOrWhiteSpace($fallback)) { return $null }
        if ($fallback -eq "System.Management.Automation.RemoteException") { return $null }
        return $fallback.Trim()
    }
    $text = ([string]$line).Trim()
    if ([string]::IsNullOrWhiteSpace($text)) { return $null }
    if ($text -eq "System.Management.Automation.RemoteException") { return $null }
    return $text
}
function Get-GitOutputSummary($outputLines) {
    $lines = @()
    foreach ($line in @($outputLines)) {
        $text = Convert-GitOutputLineToText $line
        if ([string]::IsNullOrWhiteSpace($text)) { continue }
        $lines += $text
    }
    if ($lines.Count -eq 0) { return $null }
    $permissionLines = @($lines | Where-Object { $_ -match "failed to remove|Permission denied|拒绝访问|Directory not empty" } | Select-Object -Unique)
    if ($permissionLines.Count -gt 0) {
        return ($permissionLines -join " | ")
    }
    return (($lines | Select-Object -Last 2) -join " | ")
}
function Get-GitCleanFailurePathsFromMessage([string]$message) {
    if ([string]::IsNullOrWhiteSpace($message)) { return @() }
    $paths = New-Object System.Collections.Generic.List[string]
    foreach ($segment in @($message -split "\|")) {
        $text = [string]$segment
        if ([string]::IsNullOrWhiteSpace($text)) { continue }
        $trimmed = $text.Trim()
        $match = [regex]::Match($trimmed, "failed to remove(?: directory)?\s+'([^']+)'", [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
        if (-not $match.Success) {
            $match = [regex]::Match($trimmed, "failed to remove(?: directory)?\s+([^:]+?)(?::|$)", [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
        }
        if (-not $match.Success) { continue }
        $pathText = $match.Groups[1].Value
        if ([string]::IsNullOrWhiteSpace($pathText)) { continue }
        $paths.Add($pathText.Trim()) | Out-Null
    }
    return @($paths | Select-Object -Unique)
}
function Resolve-GitCleanFailurePath([string]$repoPath, [string]$rawPath) {
    if ([string]::IsNullOrWhiteSpace($repoPath) -or [string]::IsNullOrWhiteSpace($rawPath)) { return $null }
    $candidate = $rawPath.Trim().Trim("'`"").Trim()
    if ([string]::IsNullOrWhiteSpace($candidate)) { return $null }
    $candidate = $candidate -replace "/", "\"
    try {
        $repoFull = [System.IO.Path]::GetFullPath($repoPath)
    }
    catch {
        return $null
    }

    $fullPath = $null
    try {
        if ([System.IO.Path]::IsPathRooted($candidate)) {
            $fullPath = [System.IO.Path]::GetFullPath($candidate)
        }
        else {
            $fullPath = [System.IO.Path]::GetFullPath((Join-Path $repoFull $candidate))
        }
    }
    catch {
        return $null
    }
    if (-not (Is-PathInsideOrEqual $fullPath $repoFull)) { return $null }
    return $fullPath
}
function Clear-ReadOnlyAttribute([string]$path) {
    if ([string]::IsNullOrWhiteSpace($path)) { return }
    if (-not (Test-Path -LiteralPath $path)) { return }
    try {
        $item = Get-Item -LiteralPath $path -Force -ErrorAction Stop
        if (($item.Attributes -band [System.IO.FileAttributes]::ReadOnly) -ne 0) {
            $item.Attributes = ($item.Attributes -band (-bnot [System.IO.FileAttributes]::ReadOnly))
        }
    }
    catch {}
}
function Clear-ReadOnlyAttributesRecursively([string]$path) {
    if ([string]::IsNullOrWhiteSpace($path)) { return }
    if (-not (Test-Path -LiteralPath $path)) { return }
    Clear-ReadOnlyAttribute $path
    try {
        foreach ($child in @(Get-ChildItem -LiteralPath $path -Recurse -Force -ErrorAction SilentlyContinue)) {
            Clear-ReadOnlyAttribute $child.FullName
        }
    }
    catch {}
}
function Repair-GitFailedRemovePaths([string]$repoPath, [string[]]$rawPaths, [string]$contextLabel) {
    if ([string]::IsNullOrWhiteSpace($repoPath)) { return $false }
    if ($null -eq $rawPaths -or $rawPaths.Count -eq 0) { return $false }
    if ([string]::IsNullOrWhiteSpace($contextLabel)) { $contextLabel = "git" }

    $repaired = $false
    foreach ($raw in @($rawPaths)) {
        $fullPath = Resolve-GitCleanFailurePath $repoPath $raw
        if ([string]::IsNullOrWhiteSpace($fullPath)) {
            Log ("{0} 修复跳过（路径超出仓库边界或无效）：{1}" -f $contextLabel, $raw) "WARN"
            continue
        }
        if (-not (Test-Path -LiteralPath $fullPath)) { continue }
        Clear-ReadOnlyAttributesRecursively $fullPath
        $removed = Invoke-RemoveItemWithRetry $fullPath -Recurse -IgnoreFailure -SilentIgnore
        if ($removed -or -not (Test-Path -LiteralPath $fullPath)) {
            Log ("{0} 权限修复完成：{1}" -f $contextLabel, $fullPath) "WARN"
            $repaired = $true
        }
        else {
            Log ("{0} 权限修复未完成：{1}" -f $contextLabel, $fullPath) "WARN"
        }
    }
    return $repaired
}
function Repair-GitCleanPermissionDenied([string]$repoPath, [string]$errorMessage) {
    if ([string]::IsNullOrWhiteSpace($errorMessage)) { return $false }
    if ($errorMessage -notmatch "git clean\s+-f") { return $false }
    if ($errorMessage -notmatch "failed to remove|Permission denied|拒绝访问|Directory not empty") { return $false }

    $rawPaths = @(Get-GitCleanFailurePathsFromMessage $errorMessage)
    return (Repair-GitFailedRemovePaths $repoPath $rawPaths "git clean")
}
function Test-GitProcessRunning {
    try {
        $gitProcesses = @(Get-Process -Name git,git-remote-http,git-remote-https,git-lfs,ssh,sh -ErrorAction SilentlyContinue)
        return ($gitProcesses.Count -gt 0)
    }
    catch {
        return $false
    }
}
function Remove-GitLockFile([string]$lockPath) {
    if ([string]::IsNullOrWhiteSpace($lockPath)) { return $false }
    if (-not (Test-Path -LiteralPath $lockPath -PathType Leaf)) { return $false }
    try {
        [System.IO.File]::SetAttributes($lockPath, [System.IO.FileAttributes]::Normal)
    }
    catch {}
    Invoke-RemoveItemWithRetry $lockPath -MaxAttempts 6 -DelayMs 200 | Out-Null
    return (-not (Test-Path -LiteralPath $lockPath -PathType Leaf))
}
function Resolve-GitAdminDir([string]$repoPath) {
    if ([string]::IsNullOrWhiteSpace($repoPath)) { return $null }
    $gitEntry = Join-Path $repoPath ".git"
    if (Test-Path -LiteralPath $gitEntry -PathType Container) { return $gitEntry }
    if (-not (Test-Path -LiteralPath $gitEntry -PathType Leaf)) { return $null }

    $raw = Get-ContentUtf8 $gitEntry
    if ([string]::IsNullOrWhiteSpace($raw)) { return $null }
    $firstLine = (($raw -split "\r?\n" | Select-Object -First 1) -as [string])
    if ([string]::IsNullOrWhiteSpace($firstLine)) { return $null }
    $match = [regex]::Match($firstLine, '^\s*gitdir:\s*(.+?)\s*$')
    if (-not $match.Success) { return $null }

    $gitDirPath = $match.Groups[1].Value.Trim().Trim('"')
    if ([string]::IsNullOrWhiteSpace($gitDirPath)) { return $null }
    try {
        if ([System.IO.Path]::IsPathRooted($gitDirPath)) {
            return [System.IO.Path]::GetFullPath($gitDirPath)
        }
        $gitBase = Split-Path -Parent $gitEntry
        return [System.IO.Path]::GetFullPath((Join-Path $gitBase $gitDirPath))
    }
    catch {
        return $null
    }
}
function Repair-StaleGitLockFromOutput([string]$repoPath, $outputLines) {
    $gitAdminDir = Resolve-GitAdminDir $repoPath
    if ([string]::IsNullOrWhiteSpace($gitAdminDir)) { return $false }
    try {
        $expectedLockPath = [System.IO.Path]::GetFullPath((Join-Path $gitAdminDir "index.lock"))
    }
    catch {
        return $false
    }

    $lockPath = $null
    foreach ($line in @($outputLines)) {
        $lockPath = Get-GitLockPathFromOutputLine ([string]$line)
        if (-not [string]::IsNullOrWhiteSpace($lockPath)) { break }
    }
    if ([string]::IsNullOrWhiteSpace($lockPath)) { return $false }
    try {
        $reportedLockPath = [System.IO.Path]::GetFullPath($lockPath)
    }
    catch {
        return $false
    }
    if (-not [string]::Equals($reportedLockPath, $expectedLockPath, [System.StringComparison]::OrdinalIgnoreCase)) {
        Log ("Git stderr 报告的锁路径不属于当前仓库，已拒绝自动删除：{0}" -f $reportedLockPath) "WARN"
        return $false
    }
    if (-not (Test-Path -LiteralPath $lockPath -PathType Leaf)) { return $false }
    if (Test-GitProcessRunning) {
        Log ("检测到活动 Git 进程，已拒绝自动删除锁文件：{0}" -f $lockPath) "WARN"
        return $false
    }
    Log ("检测到陈旧 Git 锁文件，已自动移除：{0}" -f $lockPath) "WARN"
    if (Remove-GitLockFile $lockPath) { return $true }
    throw ("检测到 Git 锁文件，但自动移除失败：{0}" -f $lockPath)
}
function Repair-StaleGitLockInRepo([string]$repoPath) {
    if ([string]::IsNullOrWhiteSpace($repoPath)) { return $false }
    $gitAdminDir = Resolve-GitAdminDir $repoPath
    if ([string]::IsNullOrWhiteSpace($gitAdminDir)) { return $false }
    $lockPath = Join-Path $gitAdminDir "index.lock"
    if (-not (Test-Path -LiteralPath $lockPath -PathType Leaf)) { return $false }
    if (Test-GitProcessRunning) {
        Log ("检测到活动 Git 进程，已拒绝自动删除仓库锁文件：{0}" -f $lockPath) "WARN"
        return $false
    }
    Log ("检测到仓库残留 Git 锁文件，已自动移除：{0}" -f $lockPath) "WARN"
    if (Remove-GitLockFile $lockPath) { return $true }
    throw ("检测到 Git 锁文件，但自动移除失败：{0}" -f $lockPath)
}
function Repair-InProgressGitOperation([string]$repoPath) {
    if ([string]::IsNullOrWhiteSpace($repoPath)) { return $false }
    $gitAdminDir = Resolve-GitAdminDir $repoPath
    if ([string]::IsNullOrWhiteSpace($gitAdminDir)) { return $false }

    $operations = @(
        @{ marker = "rebase-merge"; args = @("rebase", "--abort"); label = "rebase" },
        @{ marker = "rebase-apply"; args = @("rebase", "--abort"); label = "rebase" },
        @{ marker = "MERGE_HEAD"; args = @("merge", "--abort"); label = "merge" },
        @{ marker = "CHERRY_PICK_HEAD"; args = @("cherry-pick", "--abort"); label = "cherry-pick" },
        @{ marker = "REVERT_HEAD"; args = @("revert", "--abort"); label = "revert" }
    )
    $repaired = $false
    foreach ($op in $operations) {
        $markerPath = Join-Path $gitAdminDir ([string]$op.marker)
        if (-not (Test-Path -LiteralPath $markerPath)) { continue }
        try {
            Invoke-Git @($op.args)
            Log ("检测到未完成 Git {0}，已自动中止。" -f ([string]$op.label)) "WARN"
            $repaired = $true
        }
        catch {
            throw ("检测到未完成 Git {0}，自动中止失败：{1}" -f ([string]$op.label), $_.Exception.Message)
        }
    }
    return $repaired
}
function Confirm-CleanRepo([string]$path) {
    if (-not (Test-Path $path)) { return $true }
    Push-Location $path
    try {
        if (-not (Has-GitChanges)) { return $true }
    }
    finally { Pop-Location }
    if (-not (Confirm-Action "检测到本地改动，继续将丢弃这些改动吗？" "CLEAN" -DefaultNo)) { return $false }
    return $true
}
function Git-HardResetClean([bool]$forceClean) {
    if (-not $forceClean) { return }
    $repoPath = (Get-Location).Path
    Repair-StaleGitLockInRepo $repoPath | Out-Null
    Repair-InProgressGitOperation $repoPath | Out-Null
    Invoke-Git @("reset", "--hard")
    Repair-StaleGitLockInRepo $repoPath | Out-Null
    $maxCleanAttempts = 12
    for ($attempt = 1; $attempt -le $maxCleanAttempts; $attempt++) {
        try {
            Invoke-Git @("clean", "-ffdx")
            return
        }
        catch {
            if ($attempt -ge $maxCleanAttempts) { throw }
            if (-not (Repair-GitCleanPermissionDenied $repoPath $_.Exception.Message)) { throw }
            Log ("git clean 失败，已执行权限修复并重试（{0}/{1}）" -f $attempt, $maxCleanAttempts) "WARN"
        }
    }
}
function Normalize-GitSparsePath([string]$path) {
    if ([string]::IsNullOrWhiteSpace($path)) { return $null }
    $p = (To-GitPath $path).Trim().Trim("/")
    if ([string]::IsNullOrWhiteSpace($p) -or $p -eq ".") { return $null }
    return $p
}
function Get-NormalizedGitSparsePaths([string[]]$sparsePaths) {
    $set = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($path in @($sparsePaths)) {
        $p = Normalize-GitSparsePath $path
        if ([string]::IsNullOrWhiteSpace($p)) { continue }
        $set.Add($p) | Out-Null
    }
    return @($set)
}
function Test-GitPathCoveredBySparsePath([string]$gitPath, [string[]]$sparsePaths) {
    if ([string]::IsNullOrWhiteSpace($gitPath)) { return $false }
    $p = (To-GitPath $gitPath).Trim().Trim("/")
    foreach ($sparsePath in @($sparsePaths)) {
        if ($p.Equals($sparsePath, [System.StringComparison]::OrdinalIgnoreCase)) { return $true }
        if ($p.StartsWith(($sparsePath + "/"), [System.StringComparison]::OrdinalIgnoreCase)) { return $true }
    }
    return $false
}
function Test-GitSparseCandidateContainsKeptPath([string]$candidate, [string[]]$sparsePaths) {
    if ([string]::IsNullOrWhiteSpace($candidate)) { return $false }
    foreach ($sparsePath in @($sparsePaths)) {
        if ($sparsePath.Equals($candidate, [System.StringComparison]::OrdinalIgnoreCase)) { return $true }
        if ($sparsePath.StartsWith(($candidate + "/"), [System.StringComparison]::OrdinalIgnoreCase)) { return $true }
    }
    return $false
}
function Get-GitSparsePruneCandidates([string[]]$trackedPaths, [string[]]$sparsePaths) {
    $normalizedSparsePaths = @(Get-NormalizedGitSparsePaths $sparsePaths)
    if ($normalizedSparsePaths.Count -eq 0) { return @() }

    $candidates = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($trackedPath in @($trackedPaths)) {
        $gitPath = Normalize-GitSparsePath $trackedPath
        if ([string]::IsNullOrWhiteSpace($gitPath)) { continue }
        if (Test-GitPathCoveredBySparsePath $gitPath $normalizedSparsePaths) { continue }

        $parts = @($gitPath -split "/" | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
        if ($parts.Count -eq 0) { continue }
        $maxAncestorDepth = [Math]::Max(1, $parts.Count - 1)
        for ($depth = 1; $depth -le $maxAncestorDepth; $depth++) {
            $candidate = ($parts[0..($depth - 1)] -join "/")
            if (Test-GitSparseCandidateContainsKeptPath $candidate $normalizedSparsePaths) { continue }
            $candidates.Add($candidate) | Out-Null
            break
        }
    }
    return @($candidates | Sort-Object { $_.Length } -Descending)
}
function Remove-GitSparseCheckoutResiduals([string[]]$sparsePaths) {
    $normalizedSparsePaths = @(Get-NormalizedGitSparsePaths $sparsePaths)
    if ($normalizedSparsePaths.Count -eq 0) { return }

    $repoPath = (Get-Location).Path
    try {
        $repoFull = [System.IO.Path]::GetFullPath($repoPath)
    }
    catch {
        return
    }
    $trackedPaths = @(Invoke-GitCaptureLines @("ls-files"))
    $candidates = @(Get-GitSparsePruneCandidates $trackedPaths $normalizedSparsePaths)
    foreach ($candidate in $candidates) {
        $candidatePath = $candidate -replace "/", "\"
        $fullPath = $null
        try {
            $fullPath = [System.IO.Path]::GetFullPath((Join-Path $repoFull $candidatePath))
        }
        catch {
            continue
        }
        if (-not (Is-PathInsideOrEqual $fullPath $repoFull) -or $fullPath.Equals($repoFull, [System.StringComparison]::OrdinalIgnoreCase)) { continue }
        if (-not (Test-Path -LiteralPath $fullPath)) { continue }
        Clear-ReadOnlyAttributesRecursively $fullPath
        $removed = Invoke-RemoveItemWithRetry $fullPath -Recurse -IgnoreFailure -SilentIgnore
        if ($removed -or -not (Test-Path -LiteralPath $fullPath)) {
            Log ("sparse-checkout 预清理残留目录：{0}" -f $candidate) "INFO"
        }
        else {
            Log ("sparse-checkout 残留目录预清理失败（已交由 git 后续处理）：{0}" -f $candidate) "WARN"
        }
    }
}
function Repair-GitSparseCheckoutRemoveWarnings([string]$repoPath, $outputLines) {
    $warningLines = @()
    foreach ($line in @($outputLines)) {
        $text = Convert-GitOutputLineToText $line
        if ([string]::IsNullOrWhiteSpace($text)) { continue }
        if ($text -match "warning:\s+failed to remove directory") { $warningLines += $text }
    }
    if ($warningLines.Count -eq 0) { return $false }

    $rawPaths = @(Get-GitCleanFailurePathsFromMessage ($warningLines -join " | "))
    if ($rawPaths.Count -eq 0) { return $false }
    return (Repair-GitFailedRemovePaths $repoPath $rawPaths "sparse-checkout")
}
function Invoke-GitSparseCheckoutCommand([string[]]$GitArgs) {
    $safeArgs = @($GitArgs | ForEach-Object { Mask-SensitiveGitText ([string]$_) })
    if ($DryRun) {
        Log ("DRYRUN git {0}" -f ($safeArgs -join " "))
        return
    }
    $cmdText = ("git {0}" -f ($safeArgs -join " "))
    Log $cmdText
    $canTuneNativeErrPref = ($PSVersionTable.PSVersion.Major -ge 7)
    $prevNativeErrorPref = $null
    $prevErrorActionPreference = $ErrorActionPreference
    try {
        if ($canTuneNativeErrPref) {
            $prevNativeErrorPref = $PSNativeCommandUseErrorActionPreference
            $PSNativeCommandUseErrorActionPreference = $false
        }
        $ErrorActionPreference = "Continue"
        $output = & git @GitArgs 2>&1
        $exitCode = $LASTEXITCODE
    }
    finally {
        $ErrorActionPreference = $prevErrorActionPreference
        if ($canTuneNativeErrPref) {
            $PSNativeCommandUseErrorActionPreference = $prevNativeErrorPref
        }
    }

    $deferredRemoveWarnings = @()
    foreach ($line in @($output)) {
        $text = Convert-GitOutputLineToText $line
        if ([string]::IsNullOrWhiteSpace($text)) { continue }
        if ($text -match "warning:\s+failed to remove directory") {
            $deferredRemoveWarnings += $text
            continue
        }
        Write-Host (Mask-SensitiveGitText $text)
    }

    if ($exitCode -ne 0) {
        foreach ($text in $deferredRemoveWarnings) { Write-Host (Mask-SensitiveGitText $text) }
        $summary = Mask-SensitiveGitText (Get-GitOutputSummary $output)
        if ([string]::IsNullOrWhiteSpace($summary)) {
            throw ("git 失败：{0}" -f $cmdText)
        }
        throw ("git 失败：{0}；详情：{1}" -f $cmdText, $summary)
    }

    if ($deferredRemoveWarnings.Count -gt 0) {
        $repoPath = (Get-Location).Path
        if (-not (Repair-GitSparseCheckoutRemoveWarnings $repoPath $deferredRemoveWarnings)) {
            foreach ($text in $deferredRemoveWarnings) { Write-Host (Mask-SensitiveGitText $text) }
        }
    }
}
function Set-GitSparseCheckout([string[]]$sparsePaths) {
    $normalizedSparsePaths = @(Get-NormalizedGitSparsePaths $sparsePaths)
    if ($normalizedSparsePaths.Count -eq 0) {
        try { Invoke-Git @("sparse-checkout", "disable") } catch {}
        return
    }
    Remove-GitSparseCheckoutResiduals $normalizedSparsePaths
    Invoke-GitSparseCheckoutCommand @("sparse-checkout", "init", "--cone")
    Remove-GitSparseCheckoutResiduals $normalizedSparsePaths
    Invoke-GitSparseCheckoutCommand (@("sparse-checkout", "set") + $normalizedSparsePaths)
}
function Repair-StaleGitLockAfterFailure([string]$repoPath, $outputLines) {
    if (-not (Test-GitIndexLockIssue $outputLines)) { return $false }
    return (Repair-StaleGitLockInRepo $repoPath)
}
function Ensure-Repo([string]$path, [string]$repo, [string]$ref, [string]$sparsePath, [bool]$forceClean = $true, [bool]$confirmClean = $false, [bool]$doFetch = $true) {
    if ($DryRun) {
        Log ("DRYRUN Ensure-Repo {0} <= {1} ({2})" -f $path, (Mask-SensitiveGitText $repo), $ref)
        return
    }
    if (Test-LocalZipRepoInput $repo) {
        Need (-not $sparsePath -or $sparsePath -eq ".") "zip 导入不支持 --sparse，请去掉 --sparse 后重试。"
        Ensure-RepoFromZip $path $repo $forceClean
        return
    }
    if (-not (Test-Path $path)) {
        if ($sparsePath -and $sparsePath -ne ".") {
            Invoke-Git @("clone", "--filter=blob:none", "--no-checkout", $repo, $path)
            Push-Location $path
            try {
                Set-GitSparseCheckout @($sparsePath)
                Invoke-Git @("checkout", $ref)
            }
            finally { Pop-Location }
        }
        else {
            Invoke-Git @("clone", $repo, $path)
            Push-Location $path
            try { Invoke-Git @("checkout", $ref) } finally { Pop-Location }
        }
    }
    else {
        $gitDir = Join-Path $path ".git"
        if (-not (Test-Path -LiteralPath $gitDir -PathType Container)) {
            Need $forceClean ("缓存目录已存在但不是 git 仓库且 update_force=false：{0}" -f $path)
            Log ("缓存目录不是 git 仓库，已重建：{0}" -f $path) "WARN"
            Invoke-RemoveItemWithRetry $path -Recurse
            Ensure-Repo $path $repo $ref $sparsePath $forceClean $confirmClean $doFetch
            return
        }
        $existingOrigin = $null
        Push-Location $path
        try {
            $existingOrigin = Invoke-GitCapture @("remote", "get-url", "origin")
        }
        finally { Pop-Location }
        if (-not (Is-SameRepoIdentity $existingOrigin $repo)) {
            Need $forceClean ("缓存目录已存在但来源仓库不匹配且 update_force=false：{0}" -f $path)
            Log ("检测到缓存目录来源不匹配，已重建：{0} (old={1}, new={2})" -f $path, (Mask-SensitiveGitText $existingOrigin), (Mask-SensitiveGitText $repo)) "WARN"
            Invoke-RemoveItemWithRetry $path -Recurse
            Ensure-Repo $path $repo $ref $sparsePath $forceClean $confirmClean $doFetch
            return
        }
        Push-Location $path
        try {
            if ($forceClean -and $confirmClean) {
                if (-not (Confirm-CleanRepo $path)) { throw "已取消：存在本地改动，未执行清理。" }
            }
            Git-HardResetClean $forceClean
            Set-GitSparseCheckout @($sparsePath)
            if ($doFetch) {
                Invoke-Git @("fetch", "--all", "--tags")
            }
            Invoke-Git @("checkout", $ref)
            # We already fetched explicitly when needed; prefer local fast-forward first
            # to avoid duplicate network round-trips per repo.
            Update-CurrentBranchFromUpstream $false
        }
        finally { Pop-Location }
    }
}

function Get-CfgCountSnapshot($cfg) {
    if ($null -eq $cfg) { return @{} }
    return [ordered]@{
        vendors = @($cfg.vendors).Count
        targets = @($cfg.targets).Count
        mappings = @($cfg.mappings).Count
        imports = @($cfg.imports).Count
        mcp_servers = @($cfg.mcp_servers).Count
        mcp_targets = @($cfg.mcp_targets).Count
    }
}
function Get-CfgChangeSummaryLines([string]$oldRaw, $newCfg) {
    $keys = @("vendors", "targets", "mappings", "imports", "mcp_servers", "mcp_targets")
    $newSnap = Get-CfgCountSnapshot $newCfg
    $oldSnap = [ordered]@{}
    foreach ($k in $keys) { $oldSnap[$k] = 0 }

    if (-not [string]::IsNullOrWhiteSpace($oldRaw)) {
        try {
            $clean = $oldRaw -replace "(?m)^\s*//.*", ""
            $oldCfg = $clean | ConvertFrom-Json
            $oldSnap = Get-CfgCountSnapshot $oldCfg
        }
        catch {}
    }

    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($k in $keys) {
        $oldVal = if ($oldSnap.Contains($k)) { [int]$oldSnap[$k] } else { 0 }
        $newVal = if ($newSnap.Contains($k)) { [int]$newSnap[$k] } else { 0 }
        if ($oldVal -ne $newVal) {
            $lines.Add(("{0}: {1} -> {2}" -f $k, $oldVal, $newVal)) | Out-Null
        }
    }
    return $lines.ToArray()
}
function Write-CfgChangeSummary([string]$oldRaw, $newCfg) {
    $lines = Get-CfgChangeSummaryLines $oldRaw $newCfg
    if ($lines.Count -eq 0) { return }
    Write-Host "配置变更摘要："
    foreach ($l in $lines) { Write-Host ("- {0}" -f $l) }
}
function Test-InProgressGitOperation([string]$path) {
    if ([string]::IsNullOrWhiteSpace($path)) { return $false }
    $gitAdminDir = Resolve-GitAdminDir $path
    if ([string]::IsNullOrWhiteSpace($gitAdminDir)) { return $false }
    foreach ($marker in @("MERGE_HEAD", "rebase-merge", "rebase-apply", "CHERRY_PICK_HEAD", "REVERT_HEAD")) {
        if (Test-Path -LiteralPath (Join-Path $gitAdminDir $marker)) {
            return $true
        }
    }
    return $false
}
function Get-DirtyUpdateTargets($cfg) {
    $items = New-Object System.Collections.Generic.List[object]
    if ($null -eq $cfg) { return @() }

    foreach ($v in @($cfg.vendors)) {
        $path = VendorPath $v.name
        if (-not (Test-Path $path)) { continue }
        if (-not (Test-IsGitRepoRoot $path)) { continue }
        if (Test-InProgressGitOperation $path) { continue }
        Push-Location $path
        try {
            if (Has-GitChanges) {
                $items.Add([pscustomobject]@{ kind = "vendor"; name = [string]$v.name; path = $path }) | Out-Null
            }
        }
        finally { Pop-Location }
    }
    return $items.ToArray()
}

function Get-DirtyManualImportTargets($cfg) {
    $items = New-Object System.Collections.Generic.List[object]
    if ($null -eq $cfg) { return @() }

    foreach ($i in @($cfg.imports)) {
        if ($i.mode -ne "manual") { continue }
        $cache = Join-Path $ImportDir $i.name
        if (-not (Test-Path $cache)) { continue }
        if (-not (Test-IsGitRepoRoot $cache)) { continue }
        if (Test-InProgressGitOperation $cache) { continue }
        Push-Location $cache
        try {
            if (Has-GitChanges) {
                $items.Add([pscustomobject]@{ kind = "import"; name = [string]$i.name; path = $cache }) | Out-Null
            }
        }
        finally { Pop-Location }
    }
    return $items.ToArray()
}
function Test-IsGitRepoRoot([string]$path) {
    if ([string]::IsNullOrWhiteSpace($path)) { return $false }
    if (-not (Test-Path -LiteralPath $path -PathType Container)) { return $false }
    Push-Location $path
    try {
        $top = Invoke-GitCapture @("rev-parse", "--show-toplevel")
    }
    finally { Pop-Location }
    if ([string]::IsNullOrWhiteSpace($top)) { return $false }

    try {
        $resolvedPath = (Resolve-Path -LiteralPath $path -ErrorAction Stop).Path
    }
    catch {
        $resolvedPath = $path
    }
    try {
        $resolvedTop = (Resolve-Path -LiteralPath $top -ErrorAction Stop).Path
    }
    catch {
        $resolvedTop = $top
    }

    $resolvedPath = $resolvedPath.TrimEnd('\', '/')
    $resolvedTop = $resolvedTop.TrimEnd('\', '/')
    return [string]::Equals($resolvedPath, $resolvedTop, [System.StringComparison]::OrdinalIgnoreCase)
}
function Confirm-UpdateForce($cfg, [ref]$SkipForceClean) {
    if ($null -eq $SkipForceClean.Value) { $SkipForceClean.Value = @{} }
    if (-not $cfg.update_force) { return $true }

    $dirtyImports = Get-DirtyManualImportTargets $cfg
    $dirtyVendors = Get-DirtyUpdateTargets $cfg
    $dirty = @($dirtyImports) + @($dirtyVendors)
    if ($dirty.Count -eq 0) {
        Write-Host "未检测到本地改动，将按默认策略更新。"
        return $true
    }

    foreach ($d in $dirty) {
        $key = "{0}|{1}" -f $d.kind, $d.name
        $SkipForceClean.Value[$key] = $true
    }
    Write-Host ("检测到 {0} 个本地改动项，已自动保留并跳过强制清理。" -f $dirty.Count) -ForegroundColor Yellow
    return $true
}

function LoadCfg() {
    Need (Test-Path $CfgPath) "缺少配置文件：$CfgPath"
    $raw = Get-ContentUtf8 $CfgPath
    # 保守注释支持：仅移除整行 // 注释，避免误伤字符串内容。
    $clean = $raw -replace "(?m)^\s*//.*", ""
    try {
        $cfg = $clean | ConvertFrom-Json
    }
    catch {
        throw ("skills.json 解析失败：{0}。请检查 JSON 格式；注释仅支持整行 //。" -f $_.Exception.Message)
    }
    Need ($cfg.vendors -ne $null) "skills.json 缺少 vendors"
    Need ($cfg.targets -ne $null) "skills.json 缺少 targets"
    $cfg = Normalize-Cfg $cfg
    $changed = $false
    $dirMigrations = [ordered]@{
        vendors = @()
        imports = @()
    }
    Normalize-ArrayField $cfg "vendors" ([ref]$changed)
    Normalize-ArrayField $cfg "targets" ([ref]$changed)
    Normalize-ArrayField $cfg "mappings" ([ref]$changed)
    Normalize-ArrayField $cfg "imports" ([ref]$changed)
    Normalize-ArrayField $cfg "mcp_servers" ([ref]$changed)
    Normalize-ArrayField $cfg "mcp_targets" ([ref]$changed)
    Fix-Cfg $cfg ([ref]$changed) ([ref]$dirMigrations)
    Assert-Cfg $cfg
    Apply-DirectoryMigrations $dirMigrations ([ref]$changed)
    if ($changed) {
        Log "已自动修复 skills.json 中的无效项/重复项。" "WARN"
        SaveCfgSafe $cfg $raw
    }
    return $cfg
}
function Normalize-Cfg($cfg) {
    if (-not $cfg.PSObject.Properties.Match("mappings").Count) { $cfg | Add-Member -NotePropertyName mappings -NotePropertyValue @() }
    if (-not $cfg.PSObject.Properties.Match("imports").Count) { $cfg | Add-Member -NotePropertyName imports -NotePropertyValue @() }
    if (-not $cfg.PSObject.Properties.Match("mcp_servers").Count) { $cfg | Add-Member -NotePropertyName mcp_servers -NotePropertyValue @() }
    if (-not $cfg.PSObject.Properties.Match("mcp_targets").Count) { $cfg | Add-Member -NotePropertyName mcp_targets -NotePropertyValue @() }
    if (-not $cfg.PSObject.Properties.Match("update_force").Count) { $cfg | Add-Member -NotePropertyName update_force -NotePropertyValue $true }
    if ($cfg.mappings -eq $null) { $cfg.mappings = @() }
    if ($cfg.imports -eq $null) { $cfg.imports = @() }
    if ($cfg.mcp_servers -eq $null) { $cfg.mcp_servers = @() }
    if ($cfg.mcp_targets -eq $null) { $cfg.mcp_targets = @() }
    if ($cfg.update_force -eq $null) { $cfg.update_force = $true }
    if ([string]::IsNullOrWhiteSpace($cfg.sync_mode)) { $cfg.sync_mode = "link" }
    return $cfg
}
function Normalize-ArrayField($cfg, [string]$name, [ref]$changed) {
    if (-not $cfg.PSObject.Properties.Match($name).Count) {
        $cfg | Add-Member -NotePropertyName $name -NotePropertyValue @()
        $changed.Value = $true
        Log ("缺少 {0}，已自动补为空数组。" -f $name) "WARN"
        return
    }
    $val = $cfg.$name
    if ($null -eq $val) {
        $cfg.$name = @()
        $changed.Value = $true
        Log ("{0} 为空，已自动补为空数组。" -f $name) "WARN"
        return
    }
    if (Assert-IsArray $val) { return }
    if ($val -is [hashtable] -or $val -is [pscustomobject]) {
        $cfg.$name = @($val)
        $changed.Value = $true
        Log ("{0} 非数组，已自动包裹为数组。" -f $name) "WARN"
        return
    }
    throw ("skills.json 的 {0} 必须是数组" -f $name)
}
function Assert-IsArray($value) {
    return ($value -is [System.Collections.IList]) -and -not ($value -is [string])
}
function Test-CfgObjectProperty($obj, [string]$name) {
    if ($null -eq $obj) { return $false }
    if ($obj -is [System.Collections.IDictionary] -or
        $obj -is [System.Collections.Specialized.OrderedDictionary] -or
        $obj -is [System.Collections.Specialized.IOrderedDictionary]) {
        foreach ($key in @($obj.Keys)) {
            if ([string]::Equals([string]$key, $name, [System.StringComparison]::OrdinalIgnoreCase)) { return $true }
        }
        return $false
    }
    return ($obj.PSObject.Properties.Match($name).Count -gt 0)
}
function Test-CfgArrayProperty($obj, [string]$name) {
    if ($null -eq $obj) { return $false }
    if ($obj -is [System.Collections.IDictionary] -or
        $obj -is [System.Collections.Specialized.OrderedDictionary] -or
        $obj -is [System.Collections.Specialized.IOrderedDictionary]) {
        foreach ($key in @($obj.Keys)) {
            if ([string]::Equals([string]$key, $name, [System.StringComparison]::OrdinalIgnoreCase)) {
                return (Assert-IsArray (, $obj[$key]))
            }
        }
        return $false
    }
    $property = @($obj.PSObject.Properties | Where-Object { [string]::Equals($_.Name, $name, [System.StringComparison]::OrdinalIgnoreCase) } | Select-Object -First 1)
    if ($property.Count -ne 1) { return $false }
    return (Assert-IsArray (, $property[0].Value))
}
function Get-CfgObjectProperty($obj, [string]$name) {
    if ($null -eq $obj) { return $null }
    if ($obj -is [System.Collections.IDictionary] -or
        $obj -is [System.Collections.Specialized.OrderedDictionary] -or
        $obj -is [System.Collections.Specialized.IOrderedDictionary]) {
        if ($obj.Contains($name)) {
            $value = $obj[$name]
            if (Assert-IsArray $value) { Write-Output -NoEnumerate $value } else { return $value }
            return
        }
        foreach ($key in @($obj.Keys)) {
            if ([string]::Equals([string]$key, $name, [System.StringComparison]::OrdinalIgnoreCase)) {
                $value = $obj[$key]
                if (Assert-IsArray $value) { Write-Output -NoEnumerate $value } else { return $value }
                return
            }
        }
        return $null
    }
    if ($obj.PSObject.Properties.Match($name).Count -eq 0) { return $null }
    $value = $obj.$name
    if (Assert-IsArray $value) { Write-Output -NoEnumerate $value } else { return $value }
}
function New-CfgVendorNameSet($vendors = @()) {
    $set = New-Object System.Collections.Generic.HashSet[string]([System.StringComparer]::OrdinalIgnoreCase)
    $set.Add("manual") | Out-Null
    $set.Add("overrides") | Out-Null
    foreach ($v in @($vendors)) {
        if ($null -eq $v) { continue }
        $name = if ($v -is [string]) { [string]$v } else { [string](Get-CfgObjectProperty $v "name") }
        if ([string]::IsNullOrWhiteSpace($name)) { continue }
        $set.Add($name) | Out-Null
    }
    return $set
}
function New-CfgMcpServerNameSet($servers = @()) {
    $set = New-Object System.Collections.Generic.HashSet[string]([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($server in @($servers)) {
        if ($null -eq $server) { continue }
        $name = if ($server -is [string]) { [string]$server } else { [string](Get-CfgObjectProperty $server "name") }
        if (-not [string]::IsNullOrWhiteSpace($name)) { $set.Add($name.Trim()) | Out-Null }
    }
    return $set
}
function Get-CfgArrayField($cfg, [string]$name, [bool]$required, [System.Collections.Generic.List[string]]$errors) {
    $value = Get-CfgObjectProperty $cfg $name
    if ($null -eq $value) {
        if ($required) { $errors.Add(("skills.json 缺少 {0}" -f $name)) | Out-Null }
        return @()
    }
    if (Assert-IsArray $value) { return @($value) }
    if ($value -is [hashtable] -or $value -is [pscustomobject]) { return @($value) }
    $errors.Add(("skills.json 的 {0} 必须是数组" -f $name)) | Out-Null
    return @()
}
$script:SkillsConfigSchemaVersion = 1
function Test-CfgIntegerValue($value) {
    return ($value -is [byte] -or $value -is [sbyte] -or
        $value -is [int16] -or $value -is [uint16] -or
        $value -is [int32] -or $value -is [uint32] -or
        $value -is [int64] -or $value -is [uint64])
}
function Get-CfgSchemaVersionInfo($cfg) {
    $errors = New-Object System.Collections.Generic.List[string]
    $observations = New-Object System.Collections.Generic.List[object]
    $declared = $false
    $version = $script:SkillsConfigSchemaVersion

    if ($null -ne $cfg -and (Test-CfgObjectProperty $cfg "schema_version")) {
        $declared = $true
        $rawVersion = Get-CfgObjectProperty $cfg "schema_version"
        if (-not (Test-CfgIntegerValue $rawVersion)) {
            $errors.Add("schema_version 必须是整数") | Out-Null
            $version = $null
        }
        else {
            $version = [int64]$rawVersion
            if ($version -ne $script:SkillsConfigSchemaVersion) {
                $errors.Add(("不支持的 schema_version；当前仅支持 {0}" -f $script:SkillsConfigSchemaVersion)) | Out-Null
            }
        }
    }
    else {
        $observations.Add([pscustomobject]@{
            code = "legacy_schema_version_missing"
            path = "$.schema_version"
            message = "Missing schema_version is read as legacy v1; add schema_version only through an explicit migration."
        }) | Out-Null
    }

    return [pscustomobject]@{
        current_version = $script:SkillsConfigSchemaVersion
        effective_version = $version
        declared = $declared
        source = if ($declared) { "declared" } else { "legacy_default" }
        errors = @($errors.ToArray())
        observations = @($observations.ToArray())
    }
}
function Get-CfgVersionedContractReport($cfg) {
    $versionInfo = Get-CfgSchemaVersionInfo $cfg
    $errors = New-Object System.Collections.Generic.List[string]
    foreach ($errorText in @($versionInfo.errors)) { $errors.Add([string]$errorText) | Out-Null }

    if ($versionInfo.declared -and $versionInfo.errors.Count -eq 0) {
        foreach ($fieldName in @("vendors", "targets", "mappings", "imports", "mcp_servers", "mcp_targets")) {
            if ((Test-CfgObjectProperty $cfg $fieldName) -and -not (Assert-IsArray (Get-CfgObjectProperty $cfg $fieldName))) {
                $errors.Add(("schema v1 要求 {0} 为数组" -f $fieldName)) | Out-Null
            }
        }
        if ((Test-CfgObjectProperty $cfg "update_force") -and (Get-CfgObjectProperty $cfg "update_force") -isnot [bool]) {
            $errors.Add("schema v1 要求 update_force 为布尔值") | Out-Null
        }
        if ((Test-CfgObjectProperty $cfg "sync_mode") -and (Get-CfgObjectProperty $cfg "sync_mode") -isnot [string]) {
            $errors.Add("schema v1 要求 sync_mode 为字符串") | Out-Null
        }
        foreach ($fieldName in @("skill_projection", "mcp_profiles")) {
            $fieldValue = Get-CfgObjectProperty $cfg $fieldName
            if ($null -ne $fieldValue -and $fieldValue -isnot [pscustomobject] -and $fieldValue -isnot [System.Collections.IDictionary]) {
                $errors.Add(("schema v1 要求 {0} 为对象" -f $fieldName)) | Out-Null
            }
        }
    }

    foreach ($errorText in @(Get-CfgContractErrors $cfg)) { $errors.Add([string]$errorText) | Out-Null }
    return [pscustomobject]@{
        schema = $versionInfo
        valid = ($errors.Count -eq 0)
        errors = @($errors.ToArray())
        observations = @($versionInfo.observations)
    }
}
function Get-CfgContractErrors($cfg) {
    $errors = New-Object System.Collections.Generic.List[string]
    if ($null -eq $cfg) {
        $errors.Add("skills.json 为空或无法解析为对象") | Out-Null
        return @($errors.ToArray())
    }

    $vendors = Get-CfgArrayField $cfg "vendors" $true $errors
    $targets = Get-CfgArrayField $cfg "targets" $true $errors
    $mappings = Get-CfgArrayField $cfg "mappings" $false $errors
    $imports = Get-CfgArrayField $cfg "imports" $false $errors
    $mcpServers = Get-CfgArrayField $cfg "mcp_servers" $false $errors
    $mcpTargets = Get-CfgArrayField $cfg "mcp_targets" $false $errors

    $skillProjection = Get-CfgObjectProperty $cfg "skill_projection"
    if ($null -ne $skillProjection) {
        $projectionEnabled = Get-CfgObjectProperty $skillProjection "enabled"
        if ($null -ne $projectionEnabled -and $projectionEnabled -isnot [bool]) {
            $errors.Add("skill_projection.enabled 必须是布尔值") | Out-Null
        }
        $routingPolicyPath = [string](Get-CfgObjectProperty $skillProjection "routing_policy_path")
        if ((Test-CfgObjectProperty $skillProjection "routing_policy_path") -and [string]::IsNullOrWhiteSpace($routingPolicyPath)) {
            $errors.Add("skill_projection.routing_policy_path 不能为空") | Out-Null
        }
        $externalInventory = Get-CfgObjectProperty $skillProjection "external_skill_inventory"
        if ($null -ne $externalInventory) {
            if ($externalInventory -isnot [pscustomobject] -and $externalInventory -isnot [System.Collections.IDictionary]) {
                $errors.Add("skill_projection.external_skill_inventory 必须是对象") | Out-Null
            }
            else {
                $externalInventoryEnabled = Get-CfgObjectProperty $externalInventory "enabled"
                if ($null -ne $externalInventoryEnabled -and $externalInventoryEnabled -isnot [bool]) {
                    $errors.Add("skill_projection.external_skill_inventory.enabled 必须是布尔值") | Out-Null
                }
                $pluginCachePath = [string](Get-CfgObjectProperty $externalInventory "plugin_cache_path")
                if ((Test-CfgObjectProperty $externalInventory "plugin_cache_path") -and [string]::IsNullOrWhiteSpace($pluginCachePath)) {
                    $errors.Add("skill_projection.external_skill_inventory.plugin_cache_path 不能为空") | Out-Null
                }
            }
        }
        $projectionSources = Get-CfgObjectProperty $skillProjection "sources"
        if (-not (Assert-IsArray $projectionSources)) {
            $errors.Add("skill_projection.sources 必须是数组") | Out-Null
        }
        else {
            foreach ($source in @($projectionSources)) {
                $sourceId = [string](Get-CfgObjectProperty $source "id")
                $sourcePath = [string](Get-CfgObjectProperty $source "path")
                if ([string]::IsNullOrWhiteSpace($sourceId)) { $errors.Add("skill_projection source 缺少 id") | Out-Null }
                if ([string]::IsNullOrWhiteSpace($sourcePath)) { $errors.Add(("skill_projection source 缺少 path：{0}" -f $sourceId)) | Out-Null }
            }
        }
        $managedLinkExcludes = Get-CfgObjectProperty $skillProjection "managed_link_excludes"
        if ($null -ne $managedLinkExcludes) {
            if (-not (Assert-IsArray $managedLinkExcludes)) {
                $errors.Add("skill_projection.managed_link_excludes 必须是数组") | Out-Null
            }
            else {
                $normalizedExcludes = @()
                foreach ($exclude in @($managedLinkExcludes)) {
                    $name = [string]$exclude
                    if ([string]::IsNullOrWhiteSpace($name)) {
                        $errors.Add("skill_projection.managed_link_excludes 不能包含空字符串") | Out-Null
                        continue
                    }
                    $normalizedExcludes += $name.Trim().ToLowerInvariant()
                }
                $duplicateExcludes = @(Get-DuplicateValues $normalizedExcludes)
                if ($duplicateExcludes.Count -gt 0) {
                    $errors.Add(("skill_projection.managed_link_excludes 重复：{0}" -f ($duplicateExcludes -join ", "))) | Out-Null
                }
            }
        }
        $aliases = Get-CfgObjectProperty $skillProjection "aliases"
        if ($null -ne $aliases -and -not (Assert-IsArray $aliases)) {
            $errors.Add("skill_projection.aliases 必须是数组") | Out-Null
        }
        if ($null -ne $aliases) {
            foreach ($alias in @($aliases)) {
                $aliasName = [string](Get-CfgObjectProperty $alias "name")
                $replacement = [string](Get-CfgObjectProperty $alias "replacement")
                if ([string]::IsNullOrWhiteSpace($aliasName)) { $errors.Add("skill_projection alias 缺少 name") | Out-Null }
                if ([string]::IsNullOrWhiteSpace($replacement)) { $errors.Add(("skill_projection alias 缺少 replacement：{0}" -f $aliasName)) | Out-Null }
            }
        }
        $profiles = Get-CfgObjectProperty $skillProjection "profiles"
        if ($null -ne $profiles) {
            $activeProfile = [string](Get-CfgObjectProperty $skillProjection "active_profile")
            if ([string]::IsNullOrWhiteSpace($activeProfile)) { $errors.Add("skill_projection 配置 profiles 时必须声明 active_profile") | Out-Null }
            $globalBudgetLimit = if (Test-CfgObjectProperty $skillProjection "budget_limit_chars") { [int](Get-CfgObjectProperty $skillProjection "budget_limit_chars") } else { 8000 }
            foreach ($profileProperty in @($profiles.PSObject.Properties)) {
                if (-not (Test-CfgArrayProperty $profileProperty.Value "enabled_names")) { $errors.Add(("skill_projection profile.enabled_names 必须是数组：{0}" -f $profileProperty.Name)) | Out-Null }
                if (Test-CfgObjectProperty $profileProperty.Value "budget_limit_chars") {
                    $profileBudgetLimit = [int](Get-CfgObjectProperty $profileProperty.Value "budget_limit_chars")
                    if ($profileBudgetLimit -le 0) { $errors.Add(("skill_projection profile.budget_limit_chars 必须大于 0：{0}" -f $profileProperty.Name)) | Out-Null }
                    elseif ($profileBudgetLimit -gt $globalBudgetLimit) { $errors.Add(("skill_projection profile.budget_limit_chars 不能超过全局上限：{0}" -f $profileProperty.Name)) | Out-Null }
                }
            }
        }
    }

    $mcpProfiles = Get-CfgObjectProperty $cfg "mcp_profiles"
    if ($null -ne $mcpProfiles) {
        $mcpServerNames = New-CfgMcpServerNameSet $mcpServers
        $activeMcpProfile = [string](Get-CfgObjectProperty $mcpProfiles "active")
        $profiles = Get-CfgObjectProperty $mcpProfiles "profiles"
        if ([string]::IsNullOrWhiteSpace($activeMcpProfile)) { $errors.Add("mcp_profiles.active 不能为空") | Out-Null }
        if ($null -eq $profiles) { $errors.Add("mcp_profiles 缺少 profiles") | Out-Null }
        else {
            foreach ($profileProperty in @($profiles.PSObject.Properties)) {
                $profileName = [string]$profileProperty.Name
                $profile = $profileProperty.Value
                if (-not (Test-CfgArrayProperty $profile "enabled")) {
                    $errors.Add(("MCP profile.enabled 必须是数组：{0}" -f $profileName)) | Out-Null
                }
                else {
                    foreach ($rawName in @($profile.enabled)) {
                        $name = ([string]$rawName).Trim()
                        if (-not $mcpServerNames.Contains($name)) { $errors.Add(("MCP profile 引用了不存在的服务：{0}/{1}" -f $profileName, $name)) | Out-Null }
                    }
                }
                if ($null -ne $profile -and $profile.PSObject.Properties.Match("enabled_tools").Count -gt 0 -and $null -ne $profile.enabled_tools) {
                    foreach ($toolProperty in @($profile.enabled_tools.PSObject.Properties)) {
                        if (-not $mcpServerNames.Contains([string]$toolProperty.Name)) {
                            $errors.Add(("MCP profile enabled_tools 引用了不存在的服务：{0}/{1}" -f $profileName, [string]$toolProperty.Name)) | Out-Null
                        }
                    }
                }
            }
        }
    }

    foreach ($v in $vendors) {
        $name = [string](Get-CfgObjectProperty $v "name")
        $repo = [string](Get-CfgObjectProperty $v "repo")
        if ([string]::IsNullOrWhiteSpace($name)) { $errors.Add("vendor 缺少 name") | Out-Null }
        if ([string]::IsNullOrWhiteSpace($repo)) { $errors.Add(("vendor {0} 缺少 repo" -f $name)) | Out-Null }
    }

    foreach ($t in $targets) {
        $path = [string](Get-CfgObjectProperty $t "path")
        if ([string]::IsNullOrWhiteSpace($path)) { $errors.Add("target 缺少 path") | Out-Null }
    }

    foreach ($m in $mappings) {
        $vendor = [string](Get-CfgObjectProperty $m "vendor")
        $from = [string](Get-CfgObjectProperty $m "from")
        $to = [string](Get-CfgObjectProperty $m "to")
        if ([string]::IsNullOrWhiteSpace($vendor)) { $errors.Add("mapping 缺少 vendor") | Out-Null }
        if ([string]::IsNullOrWhiteSpace($from)) { $errors.Add("mapping 缺少 from") | Out-Null }
        if ([string]::IsNullOrWhiteSpace($to)) { $errors.Add("mapping 缺少 to") | Out-Null }
        if (-not [string]::IsNullOrWhiteSpace($from) -and -not (Test-SafeRelativePath $from -AllowDot)) {
            $errors.Add(("mapping.from 非法（仅允许相对路径，禁止 .. 与绝对路径）：{0}" -f $from)) | Out-Null
        }
        if (-not [string]::IsNullOrWhiteSpace($to) -and -not (Test-SafeRelativePath $to)) {
            $errors.Add(("mapping.to 非法（仅允许相对路径，禁止 .. 与绝对路径）：{0}" -f $to)) | Out-Null
        }
    }

    foreach ($i in $imports) {
        $name = [string](Get-CfgObjectProperty $i "name")
        $repo = [string](Get-CfgObjectProperty $i "repo")
        $skill = Normalize-SkillPath ([string](Get-CfgObjectProperty $i "skill"))
        $mode = [string](Get-CfgObjectProperty $i "mode")
        if ([string]::IsNullOrWhiteSpace($name)) { $errors.Add("import 缺少 name") | Out-Null }
        if ([string]::IsNullOrWhiteSpace($repo)) { $errors.Add("import 缺少 repo") | Out-Null }
        if (-not (Test-SafeRelativePath $skill -AllowDot)) {
            $errors.Add(("import.skill 非法（仅允许相对路径，禁止 .. 与绝对路径）：{0}" -f $skill)) | Out-Null
        }
        if (-not [string]::IsNullOrWhiteSpace($mode) -and $mode -ne "manual" -and $mode -ne "vendor") {
            $errors.Add(("import mode 仅支持 manual 或 vendor：{0}" -f $name)) | Out-Null
        }
    }

    foreach ($s in $mcpServers) {
        $name = [string](Get-CfgObjectProperty $s "name")
        $transport = [string](Get-CfgObjectProperty $s "transport")
        if ([string]::IsNullOrWhiteSpace($transport)) { $transport = "stdio" }
        if ([string]::IsNullOrWhiteSpace($name)) { $errors.Add("mcp_server 缺少 name") | Out-Null }
        if ($transport -ne "stdio" -and $transport -ne "sse" -and $transport -ne "http") {
            $errors.Add(("mcp_server.transport 仅支持 stdio/sse/http：{0}" -f $name)) | Out-Null
            continue
        }
        if ($transport -eq "stdio") {
            $command = [string](Get-CfgObjectProperty $s "command")
            if ([string]::IsNullOrWhiteSpace($command)) { $errors.Add(("mcp_server(stdio) 缺少 command：{0}" -f $name)) | Out-Null }
        }
        else {
            $url = [string](Get-CfgObjectProperty $s "url")
            if ([string]::IsNullOrWhiteSpace($url)) { $errors.Add(("mcp_server({0}) 缺少 url：{1}" -f $transport, $name)) | Out-Null }
        }
    }

    foreach ($mt in $mcpTargets) {
        if ($mt -is [string]) {
            if ([string]::IsNullOrWhiteSpace([string]$mt)) { $errors.Add("mcp_targets 不能包含空字符串") | Out-Null }
            continue
        }
        $path = [string](Get-CfgObjectProperty $mt "path")
        if ([string]::IsNullOrWhiteSpace($path)) { $errors.Add("mcp_targets 项缺少 path") | Out-Null }
    }

    $modeValue = [string](Get-CfgObjectProperty $cfg "sync_mode")
    if ([string]::IsNullOrWhiteSpace($modeValue)) { $modeValue = "link" }
    if ($modeValue -ne "link" -and $modeValue -ne "sync") {
        $errors.Add("sync_mode 仅支持 link 或 sync") | Out-Null
    }

    $vendorNames = New-CfgVendorNameSet $vendors
    foreach ($m in $mappings) {
        $vendor = [string](Get-CfgObjectProperty $m "vendor")
        if (-not [string]::IsNullOrWhiteSpace($vendor) -and -not $vendorNames.Contains($vendor)) {
            $errors.Add(("mapping 引用了不存在的 vendor：{0}" -f $vendor)) | Out-Null
        }
    }

    return @($errors.ToArray())
}
function Get-DuplicateValues([object[]]$items) {
    if ($null -eq $items) { return @() }
    return $items | Group-Object | Where-Object { $_.Count -gt 1 } | Select-Object -ExpandProperty Name
}
function Migrate-DirName([string]$baseDir, [string]$oldName, [string]$newName, [string]$label, [ref]$changed) {
    if ([string]::IsNullOrWhiteSpace($oldName) -or [string]::IsNullOrWhiteSpace($newName)) { return }
    if ($oldName -eq $newName) { return }
    $src = Join-Path $baseDir $oldName
    if (-not (Test-Path -LiteralPath $src)) { return }
    $dst = Join-Path $baseDir $newName
    if (Test-Path -LiteralPath $dst) {
        Log ("{0} 目录迁移跳过：目标已存在 {1}" -f $label, $dst) "WARN"
        return
    }
    Invoke-MoveItem $src $dst
    Log ("{0} 目录已迁移：{1} -> {2}" -f $label, $oldName, $newName) "WARN"
    $changed.Value = $true
}
function Apply-DirectoryMigrations($dirMigrations, [ref]$changed) {
    if ($null -eq $dirMigrations) { return }
    $seen = New-Object System.Collections.Generic.HashSet[string]

    foreach ($v in $dirMigrations.vendors) {
        $key = ("vendor|{0}|{1}" -f $v.old, $v.new)
        if (-not $seen.Add($key)) { continue }
        Migrate-DirName $VendorDir $v.old $v.new "vendor" ([ref]$changed)
    }
    foreach ($i in $dirMigrations.imports) {
        $cacheKey = ("import-cache|{0}|{1}" -f $i.old, $i.new)
        if ($seen.Add($cacheKey)) {
            Migrate-DirName $ImportDir $i.old $i.new "import 缓存" ([ref]$changed)
        }
        if ($i.mode -eq "manual") {
            $manualKey = ("manual|{0}|{1}" -f $i.old, $i.new)
            if ($seen.Add($manualKey)) {
                Migrate-DirName $ManualDir $i.old $i.new "manual 技能" ([ref]$changed)
            }
        }
    }
}
function Fix-Cfg($cfg, [ref]$changed, [ref]$dirMigrations) {
    if ($null -eq $dirMigrations.Value) {
        $dirMigrations.Value = [ordered]@{ vendors = @(); imports = @() }
    }
    $vendorRenameMap = @{}
    foreach ($v in $cfg.vendors) {
        $old = [string]$v.name
        $new = Normalize-Name $old
        Need (-not [string]::IsNullOrWhiteSpace($new)) ("vendor 名称无法规范化：{0}" -f $old)
        if ($old -ne $new) {
            Log ("vendor 名称已自动规范化：{0} -> {1}" -f $old, $new) "WARN"
            $v.name = $new
            $dirMigrations.Value.vendors += [pscustomobject]@{ old = $old; new = $new }
            $changed.Value = $true
        }
        $vendorRenameMap[$old] = $new
    }

    foreach ($i in $cfg.imports) {
        if ($null -eq $i.name) { continue }
        $oldImport = [string]$i.name
        $newImport = Normalize-Name $oldImport
        Need (-not [string]::IsNullOrWhiteSpace($newImport)) ("import 名称无法规范化：{0}" -f $oldImport)
        if ($i.PSObject.Properties.Match("mode").Count -gt 0 -and $i.mode -eq "vendor") {
            if ($vendorRenameMap.ContainsKey($oldImport)) { $newImport = $vendorRenameMap[$oldImport] }
        }
        if ($oldImport -ne $newImport) {
            Log ("import 名称已自动规范化：{0} -> {1}" -f $oldImport, $newImport) "WARN"
            $i.name = $newImport
            $mode = if ($i.PSObject.Properties.Match("mode").Count -gt 0) { [string]$i.mode } else { "manual" }
            $dirMigrations.Value.imports += [pscustomobject]@{ old = $oldImport; new = $newImport; mode = $mode }
            $changed.Value = $true
        }
    }

    foreach ($m in $cfg.mappings) {
        if ($null -eq $m.vendor) { continue }
        $oldVendor = [string]$m.vendor
        $newVendor = $oldVendor
        if ($oldVendor.ToLowerInvariant() -eq "manual") {
            $newVendor = "manual"
        }
        else {
            $normVendor = Normalize-Name $oldVendor
            Need (-not [string]::IsNullOrWhiteSpace($normVendor)) ("mapping.vendor 无法规范化：{0}" -f $oldVendor)
            $newVendor = $normVendor
            if ($vendorRenameMap.ContainsKey($oldVendor)) { $newVendor = $vendorRenameMap[$oldVendor] }
        }
        if ($oldVendor -ne $newVendor) {
            Log ("mapping.vendor 已自动规范化：{0} -> {1}" -f $oldVendor, $newVendor) "WARN"
            $m.vendor = $newVendor
            $changed.Value = $true
        }
    }

    if (($cfg.sync_mode -ne "link") -and ($cfg.sync_mode -ne "sync")) {
        Log ("sync_mode 无效，已重置为 link：{0}" -f $cfg.sync_mode) "WARN"
        $cfg.sync_mode = "link"
        $changed.Value = $true
    }

    $dedupVendors = @()
    $seenVendors = New-Object System.Collections.Generic.HashSet[string]
    foreach ($v in $cfg.vendors) {
        if ($seenVendors.Add($v.name)) {
            $dedupVendors += $v
        }
        else {
            Log ("发现重复 vendor，已移除：{0}" -f $v.name) "WARN"
            $changed.Value = $true
        }
    }
    $cfg.vendors = $dedupVendors

    Repair-VendorImports $cfg $changed
    Prune-VendorRootEntries $cfg $changed

    $dedupImports = @()
    $seenImports = New-Object System.Collections.Generic.HashSet[string]
    foreach ($i in $cfg.imports) {
        if ($seenImports.Add($i.name)) {
            if ($i.PSObject.Properties.Match("mode").Count -gt 0) {
                if ($i.mode -ne "manual" -and $i.mode -ne "vendor") {
                    Log ("import mode 无效，已改为 manual：{0}" -f $i.name) "WARN"
                    $i.mode = "manual"
                    $changed.Value = $true
                }
            }
            $dedupImports += $i
        }
        else {
            Log ("发现重复 import，已移除：{0}" -f $i.name) "WARN"
            $changed.Value = $true
        }
    }
    $cfg.imports = $dedupImports

    $dedupTargets = @()
    $seenTargets = New-Object System.Collections.Generic.HashSet[string]
    foreach ($t in $cfg.targets) {
        if ($seenTargets.Add($t.path)) {
            $dedupTargets += $t
        }
        else {
            Log ("发现重复 target，已移除：{0}" -f $t.path) "WARN"
            $changed.Value = $true
        }
    }
    $cfg.targets = $dedupTargets

    $dedupMcpServers = @()
    $seenMcpServers = New-Object System.Collections.Generic.HashSet[string]
    foreach ($s in $cfg.mcp_servers) {
        if ($null -eq $s) { continue }
        $rawName = [string]$s.name
        $normName = Normalize-Name $rawName
        Need (-not [string]::IsNullOrWhiteSpace($normName)) ("mcp_server.name 无效：{0}" -f $rawName)
        if ($rawName -ne $normName) {
            Log ("MCP 服务名已自动规范化：{0} -> {1}" -f $rawName, $normName) "WARN"
            $s.name = $normName
            $changed.Value = $true
        }
        if ($s.PSObject.Properties.Match("transport").Count -eq 0 -or [string]::IsNullOrWhiteSpace([string]$s.transport)) {
            $s | Add-Member -NotePropertyName transport -NotePropertyValue "stdio" -Force
            $changed.Value = $true
        }
        else {
            $s.transport = ([string]$s.transport).ToLowerInvariant()
        }

        if ($seenMcpServers.Add($s.name)) {
            $dedupMcpServers += $s
        }
        else {
            Log ("发现重复 mcp_server，已移除：{0}" -f $s.name) "WARN"
            $changed.Value = $true
        }
    }
    $cfg.mcp_servers = $dedupMcpServers

    $dedupMcpTargets = @()
    $seenMcpTargets = New-Object System.Collections.Generic.HashSet[string]
    foreach ($mt in $cfg.mcp_targets) {
        if ($mt -is [string]) {
            $pathValue = [string]$mt
            if (-not [string]::IsNullOrWhiteSpace($pathValue) -and $seenMcpTargets.Add($pathValue)) {
                $dedupMcpTargets += $pathValue
            }
            continue
        }
        if ($null -eq $mt -or $mt.PSObject.Properties.Match("path").Count -eq 0) { continue }
        $pathValue = [string]$mt.path
        if ([string]::IsNullOrWhiteSpace($pathValue)) { continue }
        if ($seenMcpTargets.Add($pathValue)) {
            $dedupMcpTargets += $mt
        }
        else {
            Log ("发现重复 mcp_target，已移除：{0}" -f $pathValue) "WARN"
            $changed.Value = $true
        }
    }
    $cfg.mcp_targets = $dedupMcpTargets

    $vendorNames = New-CfgVendorNameSet $cfg.vendors

    $dedupMappings = @()
    $seenMappings = New-Object System.Collections.Generic.HashSet[string]
    foreach ($m in $cfg.mappings) {
        $key = "$($m.vendor)|$($m.from)|$($m.to)"
        if (-not $vendorNames.Contains($m.vendor)) {
            Log ("mapping 引用了不存在的 vendor，已移除：{0}" -f $m.vendor) "WARN"
            $changed.Value = $true
            continue
        }
        if ($seenMappings.Add($key)) {
            $dedupMappings += $m
        }
        else {
            Log ("发现重复 mapping，已移除：{0}" -f $key) "WARN"
            $changed.Value = $true
        }
    }
    $cfg.mappings = $dedupMappings
}

function Prune-VendorRootEntries($cfg, [ref]$changed) {
    if ($null -eq $cfg) { return }

    # Normalize: vendor 根入口不作为实际同步输入，统一移除避免“配置显示与同步结果”分叉。
    $rootMappings = @($cfg.mappings | Where-Object {
            $_ -ne $null -and [string]$_.from -eq "." -and
            [string]$_.vendor -ne "manual" -and [string]$_.vendor -ne "overrides"
        })
    if ($rootMappings.Count -gt 0) {
        foreach ($m in $rootMappings) {
            Log ("移除 vendor 根映射（统一按具体技能路径管理）：{0}|{1}|{2}" -f [string]$m.vendor, [string]$m.from, [string]$m.to) "WARN"
        }
        $cfg.mappings = @($cfg.mappings | Where-Object { $rootMappings -notcontains $_ })
        $changed.Value = $true
    }

    $rootVendorImports = @()
    foreach ($imp in @($cfg.imports)) {
        if ($null -eq $imp) { continue }
        $mode = if ($imp.PSObject.Properties.Match("mode").Count -gt 0) { [string]$imp.mode } else { "manual" }
        if ($mode -ne "vendor") { continue }
        $skillPath = Normalize-SkillPath ([string]$imp.skill)
        if ($skillPath -eq ".") { $rootVendorImports += $imp }
    }
    if ($rootVendorImports.Count -gt 0) {
        foreach ($i in $rootVendorImports) {
            Log ("移除 vendor 根导入（skill='.'）：{0}" -f [string]$i.name) "WARN"
        }
        $cfg.imports = @($cfg.imports | Where-Object { $rootVendorImports -notcontains $_ })
        $changed.Value = $true
    }
}

function Match-VendorByRepo($cfg, [string]$repo) {
    if ([string]::IsNullOrWhiteSpace($repo)) { return $null }
    $normRepo = Normalize-RepoUrl $repo
    foreach ($v in $cfg.vendors) {
        $vRepo = Normalize-RepoUrl $v.repo
        if ($vRepo -eq $normRepo) { return $v }
    }
    return $null
}

function Repair-VendorImports($cfg, [ref]$changed) {
    if ($null -eq $cfg -or $null -eq $cfg.imports) { return }
    foreach ($i in @($cfg.imports)) {
        $mode = if ($i.PSObject.Properties.Match("mode").Count -gt 0) { [string]$i.mode } else { "manual" }
        if ($mode -ne "vendor") { continue }

        $vendorName = [string]$i.name
        $matchedVendor = Match-VendorByRepo $cfg ([string]$i.repo)
        if ($matchedVendor) {
            $canonicalName = [string]$matchedVendor.name
            if ($vendorName -ne $canonicalName) {
                Log ("vendor import 名称已按 repo 自动归并：{0} -> {1}" -f $vendorName, $canonicalName) "WARN"
                $i.name = $canonicalName
                $vendorName = $canonicalName
                $changed.Value = $true
            }
        }

        $skillPath = Normalize-SkillPath ([string]$i.skill)
        if ([string]::IsNullOrWhiteSpace($skillPath)) { $skillPath = "." }
        if ([string]$i.skill -ne $skillPath) {
            $i.skill = $skillPath
            $changed.Value = $true
        }
    }
}

function Migrate-ManualToVendor($cfg, [string]$vendorName, [string]$repo) {
    $normRepo = Normalize-RepoUrl $repo
    $migratedCount = 0
    
    # 1. Start by finding manual imports that match this repo
    # Note: 'manual' items in imports list might not strictly have 'repo' field populated correctly in all legacy cases,
    # but new ones do. We also check if we can infer it.
    
    $manualImports = @()
    foreach ($i in $cfg.imports) {
        if ($i.mode -eq "manual" -and (Normalize-RepoUrl $i.repo) -eq $normRepo) {
            $manualImports += $i
        }
    }

    # Migrate in a single pass to avoid mutating import names before legacy cleanup.
    $importsToRemove = @()
    foreach ($imp in $manualImports) {
        $oldName = $imp.name
        $skillPath = $imp.skill
        if ([string]::IsNullOrWhiteSpace($skillPath)) { $skillPath = "." }
        
        $vPath = VendorPath $vendorName
        $src = if ($skillPath -eq ".") { $vPath } else { Join-Path $vPath $skillPath }
        
        if (Test-IsSkillDir $src) {
            $targetSuffix = if ($skillPath -eq ".") { $vendorName } else { $skillPath }
            $targetName = Make-TargetName $vendorName $targetSuffix
            Ensure-ImportVendorMapping $cfg $vendorName $skillPath $targetName
             
            # Add vendor-mode import
            $newImport = @{ name = $vendorName; repo = $repo; ref = $imp.ref; skill = $skillPath; mode = "vendor"; sparse = $imp.sparse }
            Upsert-Import $cfg $newImport
             
            $importsToRemove += $imp

            # Remove stale manual mappings for this migrated import to avoid dangling manual refs.
            $legacyFrom = Normalize-SkillPath ([string]$oldName)
            $skillFrom = Normalize-SkillPath ([string]$skillPath)
            $beforeMappings = @($cfg.mappings).Count
            $cfg.mappings = @($cfg.mappings | Where-Object {
                    $vendor = [string]$_.vendor
                    if ($vendor -ne "manual") { return $true }
                    $from = Normalize-SkillPath ([string]$_.from)
                    if ([string]::IsNullOrWhiteSpace($from)) { return $true }
                    return ($from -ne $legacyFrom) -and ($from -ne $skillFrom)
                })
            $removedLegacyMappings = $beforeMappings - @($cfg.mappings).Count
            if ($removedLegacyMappings -gt 0) {
                Log ("已清理迁移遗留 manual 映射：{0} 项（manual/{1}）" -f $removedLegacyMappings, $oldName)
            }

            $migratedCount++
            Log ("已迁移手动技能：manual/{0} -> vendor/{1}/{2}" -f $oldName, $vendorName, $skillPath)
             
            # Remove Manual Directory
            $manualDirPath = Join-Path $ManualDir $oldName
            if (Test-Path $manualDirPath) {
                Invoke-RemoveItem $manualDirPath -Recurse
            }
        }
    }
    
    # Remove old manual imports
    $cfg.imports = $cfg.imports | Where-Object { $importsToRemove -notcontains $_ }
    
    return $migratedCount
}

function Optimize-Imports($cfg) {
    if ($null -eq $cfg) { return }
    $total = 0
    foreach ($v in $cfg.vendors) {
        if (-not [string]::IsNullOrWhiteSpace($v.repo)) {
            $total += Migrate-ManualToVendor $cfg $v.name $v.repo
        }
    }
    if ($total -gt 0) {
        Log ("优化完成：共自动迁移 {0} 个手动技能到对应 Vendor。" -f $total) "WARN"
    }
}

function Assert-Cfg($cfg) {
    Need (Assert-IsArray $cfg.vendors) "skills.json 的 vendors 必须是数组"
    Need (Assert-IsArray $cfg.targets) "skills.json 的 targets 必须是数组"
    Need (Assert-IsArray $cfg.mappings) "skills.json 的 mappings 必须是数组"
    Need (Assert-IsArray $cfg.imports) "skills.json 的 imports 必须是数组"
    Need (Assert-IsArray $cfg.mcp_servers) "skills.json 的 mcp_servers 必须是数组"
    Need (Assert-IsArray $cfg.mcp_targets) "skills.json 的 mcp_targets 必须是数组"
    foreach ($v in $cfg.vendors) {
        Need (-not [string]::IsNullOrWhiteSpace($v.name)) "vendor 缺少 name"
        Need (-not [string]::IsNullOrWhiteSpace($v.repo)) "vendor $($v.name) 缺少 repo"
    }
    foreach ($t in $cfg.targets) {
        Need (-not [string]::IsNullOrWhiteSpace($t.path)) "target 缺少 path"
    }
    foreach ($m in $cfg.mappings) {
        Need (-not [string]::IsNullOrWhiteSpace($m.vendor)) "mapping 缺少 vendor"
        Need (-not [string]::IsNullOrWhiteSpace($m.from)) "mapping 缺少 from"
        Need (-not [string]::IsNullOrWhiteSpace($m.to)) "mapping 缺少 to"
        Need (Test-SafeRelativePath $m.from -AllowDot) ("mapping.from 非法（仅允许相对路径，禁止 .. 与绝对路径）：{0}" -f $m.from)
        Need (Test-SafeRelativePath $m.to) ("mapping.to 非法（仅允许相对路径，禁止 .. 与绝对路径）：{0}" -f $m.to)
    }
    foreach ($i in $cfg.imports) {
        Need (-not [string]::IsNullOrWhiteSpace($i.name)) "import 缺少 name"
        Need (-not [string]::IsNullOrWhiteSpace($i.repo)) "import 缺少 repo"
        $importSkill = Normalize-SkillPath ([string]$i.skill)
        Need (Test-SafeRelativePath $importSkill -AllowDot) ("import.skill 非法（仅允许相对路径，禁止 .. 与绝对路径）：{0}" -f $i.skill)
    }
    foreach ($s in $cfg.mcp_servers) {
        Need (-not [string]::IsNullOrWhiteSpace($s.name)) "mcp_server 缺少 name"
        $transport = if ($s.PSObject.Properties.Match("transport").Count -gt 0 -and -not [string]::IsNullOrWhiteSpace([string]$s.transport)) { [string]$s.transport } else { "stdio" }
        Need (($transport -eq "stdio") -or ($transport -eq "sse") -or ($transport -eq "http")) ("mcp_server.transport 仅支持 stdio/sse/http：{0}" -f $s.name)
        if ($transport -eq "stdio") {
            Need ($s.PSObject.Properties.Match("command").Count -gt 0 -and -not [string]::IsNullOrWhiteSpace([string]$s.command)) ("mcp_server(stdio) 缺少 command：{0}" -f $s.name)
        }
        else {
            Need ($s.PSObject.Properties.Match("url").Count -gt 0 -and -not [string]::IsNullOrWhiteSpace([string]$s.url)) ("mcp_server({0}) 缺少 url：{1}" -f $transport, $s.name)
        }
    }
    foreach ($mt in $cfg.mcp_targets) {
        if ($mt -is [string]) {
            Need (-not [string]::IsNullOrWhiteSpace([string]$mt)) "mcp_targets 不能包含空字符串"
            continue
        }
        Need ($mt.PSObject.Properties.Match("path").Count -gt 0 -and -not [string]::IsNullOrWhiteSpace([string]$mt.path)) "mcp_targets 项缺少 path"
    }

    if ($cfg.PSObject.Properties.Match("skill_projection").Count -gt 0 -and $null -ne $cfg.skill_projection) {
        $projection = $cfg.skill_projection
        if ($projection.PSObject.Properties.Match("enabled").Count -gt 0) {
            Need ($projection.enabled -is [bool]) "skill_projection.enabled 必须是布尔值"
        }
        if ($projection.PSObject.Properties.Match("routing_policy_path").Count -gt 0) {
            Need (-not [string]::IsNullOrWhiteSpace([string]$projection.routing_policy_path)) "skill_projection.routing_policy_path 不能为空"
        }
        if ($projection.PSObject.Properties.Match("external_skill_inventory").Count -gt 0 -and $null -ne $projection.external_skill_inventory) {
            $externalInventory = $projection.external_skill_inventory
            Need ($externalInventory -is [pscustomobject] -or $externalInventory -is [System.Collections.IDictionary]) "skill_projection.external_skill_inventory 必须是对象"
            if (Test-CfgObjectProperty $externalInventory "enabled") {
                Need ((Get-CfgObjectProperty $externalInventory "enabled") -is [bool]) "skill_projection.external_skill_inventory.enabled 必须是布尔值"
            }
            if (Test-CfgObjectProperty $externalInventory "plugin_cache_path") {
                Need (-not [string]::IsNullOrWhiteSpace([string](Get-CfgObjectProperty $externalInventory "plugin_cache_path"))) "skill_projection.external_skill_inventory.plugin_cache_path 不能为空"
            }
        }
        Need ($projection.PSObject.Properties.Match("sources").Count -gt 0 -and (Assert-IsArray $projection.sources)) "skill_projection.sources 必须是数组"
        foreach ($source in @($projection.sources)) {
            Need (-not [string]::IsNullOrWhiteSpace([string]$source.id)) "skill_projection source 缺少 id"
            Need (-not [string]::IsNullOrWhiteSpace([string]$source.path)) ("skill_projection source 缺少 path：{0}" -f [string]$source.id)
        }
        $dupProjectionSources = @(Get-DuplicateValues ($projection.sources | ForEach-Object { $_.id }))
        Need ($dupProjectionSources.Count -eq 0) ("skill_projection source id 重复：{0}" -f ($dupProjectionSources -join ", "))
        if ($projection.PSObject.Properties.Match("managed_link_excludes").Count -gt 0 -and $null -ne $projection.managed_link_excludes) {
            Need (Assert-IsArray $projection.managed_link_excludes) "skill_projection.managed_link_excludes 必须是数组"
            foreach ($exclude in @($projection.managed_link_excludes)) {
                Need (-not [string]::IsNullOrWhiteSpace([string]$exclude)) "skill_projection.managed_link_excludes 不能包含空字符串"
            }
            $dupManagedLinkExcludes = @(Get-DuplicateValues ($projection.managed_link_excludes | ForEach-Object { ([string]$_).Trim().ToLowerInvariant() }))
            Need ($dupManagedLinkExcludes.Count -eq 0) ("skill_projection.managed_link_excludes 重复：{0}" -f ($dupManagedLinkExcludes -join ", "))
        }
        if ($projection.PSObject.Properties.Match("resident_names").Count -gt 0 -and $null -ne $projection.resident_names) {
            Need (Assert-IsArray $projection.resident_names) "skill_projection.resident_names 必须是数组"
            foreach ($residentName in @($projection.resident_names)) {
                Need (-not [string]::IsNullOrWhiteSpace([string]$residentName)) "skill_projection.resident_names 不能包含空字符串"
            }
            $dupResidentNames = @(Get-DuplicateValues ($projection.resident_names | ForEach-Object { ([string]$_).Trim().ToLowerInvariant() }))
            Need ($dupResidentNames.Count -eq 0) ("skill_projection.resident_names 重复：{0}" -f ($dupResidentNames -join ", "))
        }
        if ($projection.PSObject.Properties.Match("aliases").Count -gt 0 -and $null -ne $projection.aliases) {
            Need (Assert-IsArray $projection.aliases) "skill_projection.aliases 必须是数组"
            foreach ($alias in @($projection.aliases)) {
                Need (-not [string]::IsNullOrWhiteSpace([string]$alias.name)) "skill_projection alias 缺少 name"
                Need (-not [string]::IsNullOrWhiteSpace([string]$alias.replacement)) ("skill_projection alias 缺少 replacement：{0}" -f [string]$alias.name)
            }
            $dupAliases = @(Get-DuplicateValues ($projection.aliases | ForEach-Object { ([string]$_.name).ToLowerInvariant() }))
            Need ($dupAliases.Count -eq 0) ("skill_projection alias 重复：{0}" -f ($dupAliases -join ", "))
        }
        if ($projection.PSObject.Properties.Match("profiles").Count -gt 0 -and $null -ne $projection.profiles) {
            Need (-not [string]::IsNullOrWhiteSpace([string]$projection.active_profile)) "skill_projection 配置 profiles 时必须声明 active_profile"
            Need ($projection.profiles.PSObject.Properties.Match([string]$projection.active_profile).Count -gt 0) ("skill_projection active_profile 不存在：{0}" -f [string]$projection.active_profile)
            foreach ($profileProperty in @($projection.profiles.PSObject.Properties)) {
                Need (Test-CfgArrayProperty $profileProperty.Value "enabled_names") ("skill_projection profile.enabled_names 必须是数组：{0}" -f $profileProperty.Name)
                if ($profileProperty.Value.PSObject.Properties.Match("budget_limit_chars").Count -gt 0) {
                    $profileBudgetLimit = [int]$profileProperty.Value.budget_limit_chars
                    $globalBudgetLimit = if ($projection.PSObject.Properties.Match("budget_limit_chars").Count -gt 0) { [int]$projection.budget_limit_chars } else { 8000 }
                    Need ($profileBudgetLimit -gt 0) ("skill_projection profile.budget_limit_chars 必须大于 0：{0}" -f $profileProperty.Name)
                    Need ($profileBudgetLimit -le $globalBudgetLimit) ("skill_projection profile.budget_limit_chars 不能超过全局上限：{0}" -f $profileProperty.Name)
                }
            }
        }
        if ($projection.PSObject.Properties.Match("budget_limit_chars").Count -gt 0) {
            Need ([int]$projection.budget_limit_chars -gt 0) "skill_projection.budget_limit_chars 必须大于 0"
        }
        if ($projection.PSObject.Properties.Match("external_metadata_reserve_chars").Count -gt 0) {
            Need ([int]$projection.external_metadata_reserve_chars -ge 0) "skill_projection.external_metadata_reserve_chars 不能小于 0"
        }
    }

    if ($cfg.PSObject.Properties.Match("mcp_profiles").Count -gt 0 -and $null -ne $cfg.mcp_profiles) {
        $mcpProfiles = $cfg.mcp_profiles
        $mcpServerNames = New-CfgMcpServerNameSet $cfg.mcp_servers
        Need (-not [string]::IsNullOrWhiteSpace([string]$mcpProfiles.active)) "mcp_profiles.active 不能为空"
        Need ($mcpProfiles.PSObject.Properties.Match("profiles").Count -gt 0 -and $null -ne $mcpProfiles.profiles) "mcp_profiles 缺少 profiles"
        Need ($mcpProfiles.profiles.PSObject.Properties.Match([string]$mcpProfiles.active).Count -gt 0) ("mcp_profiles.active 不存在：{0}" -f [string]$mcpProfiles.active)
        foreach ($profileProperty in @($mcpProfiles.profiles.PSObject.Properties)) {
            $profileName = [string]$profileProperty.Name
            $profile = $profileProperty.Value
            Need (Test-CfgArrayProperty $profile "enabled") ("MCP profile.enabled 必须是数组：{0}" -f $profileName)
            foreach ($rawName in @($profile.enabled)) {
                $name = ([string]$rawName).Trim()
                Need ($mcpServerNames.Contains($name)) ("MCP profile 引用了不存在的服务：{0}/{1}" -f $profileName, $name)
            }
            if ($profile.PSObject.Properties.Match("enabled_tools").Count -gt 0 -and $null -ne $profile.enabled_tools) {
                foreach ($toolProperty in @($profile.enabled_tools.PSObject.Properties)) {
                    Need ($mcpServerNames.Contains([string]$toolProperty.Name)) ("MCP profile enabled_tools 引用了不存在的服务：{0}/{1}" -f $profileName, [string]$toolProperty.Name)
                }
            }
        }
    }

    $mode = $cfg.sync_mode
    Need (($mode -eq "link") -or ($mode -eq "sync")) "sync_mode 仅支持 link 或 sync"

    $dupVendors = @(Get-DuplicateValues ($cfg.vendors | ForEach-Object { $_.name }))
    Need ($dupVendors.Count -eq 0) ("vendor 名称重复：{0}" -f ($dupVendors -join ", "))

    $dupImports = @(Get-DuplicateValues ($cfg.imports | ForEach-Object { $_.name }))
    Need ($dupImports.Count -eq 0) ("import 名称重复：{0}" -f ($dupImports -join ", "))

    $dupTargets = @(Get-DuplicateValues ($cfg.targets | ForEach-Object { $_.path }))
    if ($dupTargets.Count -gt 0) {
        Log ("目标路径重复（建议去重）：{0}" -f ($dupTargets -join ", ")) "WARN"
    }

    $dupTo = @(Get-DuplicateValues ($cfg.mappings | ForEach-Object { $_.to }))
    if ($dupTo.Count -gt 0) {
        Log ("mappings 的 to 重复（可能覆盖）：{0}" -f ($dupTo -join ", ")) "WARN"
    }

    $vendorNames = New-CfgVendorNameSet $cfg.vendors
    foreach ($m in $cfg.mappings) {
        Need ($vendorNames.Contains($m.vendor)) ("mapping 引用了不存在的 vendor：{0}" -f $m.vendor)
    }

    foreach ($i in $cfg.imports) {
        if ($i.PSObject.Properties.Match("mode").Count -gt 0) {
            Need (($i.mode -eq "manual") -or ($i.mode -eq "vendor")) ("import mode 仅支持 manual 或 vendor：{0}" -f $i.name)
        }
    }
}
function SaveCfg($cfg) {
    if (-not $DryRun) {
        $oldRaw = if (Test-Path -LiteralPath $CfgPath) { Get-ContentUtf8 $CfgPath } else { "" }
        Write-CfgChangeSummary $oldRaw $cfg
        $json = $cfg | ConvertTo-Json -Depth 50
        Write-Utf8FileAtomic -Path $CfgPath -Content $json
    }
}
function SaveCfgSafe($cfg, [string]$rawBackup) {
    if ($DryRun) { return }
    try {
        $oldRaw = $rawBackup
        if ([string]::IsNullOrWhiteSpace($oldRaw) -and (Test-Path -LiteralPath $CfgPath)) {
            $oldRaw = Get-ContentUtf8 $CfgPath
        }
        Write-CfgChangeSummary $oldRaw $cfg
        $json = $cfg | ConvertTo-Json -Depth 50
        Set-ContentUtf8 $CfgPath $json
    }
    catch {
        if ($rawBackup) {
            Set-ContentUtf8 $CfgPath $rawBackup
        }
        throw
    }
}

function Get-LockPath {
    return (Join-Path $Root "skills.lock.json")
}

function Get-ImportLockSourceKind($import) {
    if ($null -eq $import) { return "git" }
    $kind = [string](Get-CfgObjectProperty $import "source_kind")
    if (-not [string]::IsNullOrWhiteSpace($kind)) { return $kind.Trim().ToLowerInvariant() }
    $mode = [string](Get-CfgObjectProperty $import "mode")
    if ([string]::IsNullOrWhiteSpace($mode)) { $mode = "manual" }
    $repo = [string](Get-CfgObjectProperty $import "repo")
    if ($mode -eq "manual" -and (Test-LocalZipRepoInput $repo)) { return "local_zip" }
    return "git"
}

function Get-ImportLockSourceHash([string]$repo, [string]$sourceKind) {
    $kind = if ([string]::IsNullOrWhiteSpace($sourceKind)) { "git" } else { $sourceKind.Trim().ToLowerInvariant() }
    if ($kind -ne "local_zip") { return $null }
    Need (Test-LocalZipRepoInput $repo) ("锁定失败：本地 zip 源不存在或无效：{0}" -f $repo)
    return (Get-FileContentHash $repo)
}

function Get-ImportLockWorkspaceFingerprint([string]$repoPath) {
    Need (-not [string]::IsNullOrWhiteSpace($repoPath)) "repoPath 不能为空"
    Need (Test-Path -LiteralPath $repoPath) ("锁定失败：缺少 import 缓存目录 {0}" -f $repoPath)
    return (Get-DirectoryFingerprint $repoPath)
}

function Get-RepoHeadCommit([string]$repoPath) {
    Need (-not [string]::IsNullOrWhiteSpace($repoPath)) "repoPath 不能为空"
    Need (Test-Path -LiteralPath $repoPath) ("仓库目录不存在：{0}" -f $repoPath)
    Push-Location $repoPath
    try {
        if ($DryRun) {
            Log "DRYRUN(read) git rev-parse HEAD"
            $rawHead = & git rev-parse HEAD 2>$null
            if ($LASTEXITCODE -ne 0) {
                $head = $null
            }
            elseif ($null -eq $rawHead) {
                $head = ""
            }
            else {
                $head = ([string]($rawHead | Select-Object -First 1)).Trim()
            }
        }
        else {
            $head = Invoke-GitCapture @("rev-parse", "HEAD")
        }
        Need (-not [string]::IsNullOrWhiteSpace($head)) ("无法读取仓库 HEAD：{0}" -f $repoPath)
        return $head
    }
    finally { Pop-Location }
}

function Get-VendorSparsePaths($cfg, [string]$vendorName) {
    $paths = @()
    foreach ($i in @($cfg.imports)) {
        if ($i.mode -ne "vendor") { continue }
        if ($i.name -ne $vendorName) { continue }
        if (-not $i.sparse) { continue }
        $p = To-GitPath (Normalize-SkillPath $i.skill)
        if ($p -and $p -ne ".") { $paths += $p }
    }
    foreach ($m in @($cfg.mappings)) {
        if ($m.vendor -ne $vendorName) { continue }
        $p = To-GitPath (Normalize-SkillPath $m.from)
        if ($p -and $p -ne ".") { $paths += $p }
    }
    return @($paths | Select-Object -Unique)
}

function New-LockData($cfg) {
    if ($null -eq $cfg) { $cfg = LoadCfg }
    $vendors = @()
    foreach ($v in @($cfg.vendors | Sort-Object name)) {
        $path = VendorPath $v.name
        Need (Test-Path $path) ("生成锁文件失败：缺少 vendor 目录 {0}" -f $path)
        $vendors += [ordered]@{
            name = [string]($v.name)
            repo = [string]($v.repo)
            ref = if ([string]::IsNullOrWhiteSpace([string]($v.ref))) { "main" } else { [string]($v.ref) }
            commit = Get-RepoHeadCommit $path
        }
    }

    $imports = @()
    foreach ($i in @($cfg.imports | Sort-Object @{Expression="name"}, @{Expression="mode"})) {
        $mode = if ($i.PSObject.Properties.Match("mode").Count -gt 0) { [string]($i.mode) } else { "manual" }
        $repoPath = if ($mode -eq "vendor") { VendorPath ([string]($i.name)) } else { Join-Path $ImportDir ([string]($i.name)) }
        Need (Test-Path $repoPath) ("生成锁文件失败：缺少 import 缓存目录 {0}" -f $repoPath)
        $sourceKind = Get-ImportLockSourceKind $i
        $importEntry = [ordered]@{
            name = [string]($i.name)
            mode = $mode
            repo = [string]($i.repo)
            ref = if ([string]::IsNullOrWhiteSpace([string]($i.ref))) { "main" } else { [string]($i.ref) }
            skill = Normalize-SkillPath ([string]($i.skill))
            sparse = [bool]$i.sparse
        }
        if ($sourceKind -eq "local_zip") {
            $importEntry.source_kind = $sourceKind
            $importEntry.source_hash = Get-ImportLockSourceHash ([string]($i.repo)) $sourceKind
            $importEntry.workspace_fingerprint = Get-ImportLockWorkspaceFingerprint $repoPath
        }
        else {
            $importEntry.commit = Get-RepoHeadCommit $repoPath
        }
        $imports += $importEntry
    }

    return [ordered]@{
        version = 1
        generated_at = (Get-Date).ToUniversalTime().ToString("o")
        vendors = $vendors
        imports = $imports
    }
}

function Save-LockData($cfg = $null) {
    if ($null -eq $cfg) { $cfg = LoadCfg }
    $lock = New-LockData $cfg
    if ($DryRun) {
        Write-Host ("DRYRUN：将写入锁文件 -> {0}" -f (Get-LockPath))
        return $lock
    }
    $json = $lock | ConvertTo-Json -Depth 50
    Set-ContentUtf8 (Get-LockPath) $json
    return $lock
}

function Load-LockData {
    $path = Get-LockPath
    Need (Test-Path $path) ("缺少锁文件：{0}。请先执行 .\skills.ps1 锁定" -f $path)
    $raw = Get-ContentUtf8 $path
    Need (-not [string]::IsNullOrWhiteSpace($raw)) ("锁文件为空：{0}" -f $path)
    try {
        $lock = $raw | ConvertFrom-Json
    }
    catch {
        throw ("锁文件解析失败：{0}" -f $_.Exception.Message)
    }
    Need ($lock.PSObject.Properties.Match("version").Count -gt 0) "锁文件缺少 version"
    Need ($lock.version -eq 1) ("不支持的锁文件版本：{0}" -f $lock.version)
    Need ($lock.PSObject.Properties.Match("vendors").Count -gt 0 -and (Assert-IsArray $lock.vendors)) "锁文件 vendors 无效"
    Need ($lock.PSObject.Properties.Match("imports").Count -gt 0 -and (Assert-IsArray $lock.imports)) "锁文件 imports 无效"
    return $lock
}

function Assert-LockMatchesCfg($cfg, $lock) {
    Need ($null -ne $cfg) "cfg 不能为空"
    Need ($null -ne $lock) "lock 不能为空"

    $vendorExpected = @{}
    foreach ($v in @($cfg.vendors)) {
        $vendorExpected[[string]($v.name)] = [ordered]@{
            repo = [string]($v.repo)
            ref = if ([string]::IsNullOrWhiteSpace([string]($v.ref))) { "main" } else { [string]($v.ref) }
        }
    }
    $vendorActual = @{}
    foreach ($v in @($lock.vendors)) {
        $vendorActual[[string]($v.name)] = [ordered]@{
            repo = [string]($v.repo)
            ref = if ([string]::IsNullOrWhiteSpace([string]($v.ref))) { "main" } else { [string]($v.ref) }
        }
    }
    $expVendorJson = @($vendorExpected.Keys | Sort-Object | ForEach-Object {
            [ordered]@{
                name = [string]$_
                repo = [string]$vendorExpected[$_].repo
                ref = [string]$vendorExpected[$_].ref
            }
        }) | ConvertTo-Json -Depth 20 -Compress
    $actVendorJson = @($vendorActual.Keys | Sort-Object | ForEach-Object {
            [ordered]@{
                name = [string]$_
                repo = [string]$vendorActual[$_].repo
                ref = [string]$vendorActual[$_].ref
            }
        }) | ConvertTo-Json -Depth 20 -Compress
    Need ($expVendorJson -eq $actVendorJson) "锁文件与当前 vendors 配置不一致，请重新执行 .\skills.ps1 锁定"

    $importExpected = @{}
    foreach ($i in @($cfg.imports)) {
        $mode = if ($i.PSObject.Properties.Match("mode").Count -gt 0) { [string]($i.mode) } else { "manual" }
        $key = ("{0}|{1}" -f $mode, [string]($i.name))
        $importExpected[$key] = [ordered]@{
            repo = [string]($i.repo)
            ref = if ([string]::IsNullOrWhiteSpace([string]($i.ref))) { "main" } else { [string]($i.ref) }
            skill = Normalize-SkillPath ([string]($i.skill))
            sparse = [bool]$i.sparse
        }
    }
    $importActual = @{}
    foreach ($i in @($lock.imports)) {
        $mode = if ([string]::IsNullOrWhiteSpace([string]($i.mode))) { "manual" } else { [string]($i.mode) }
        $key = ("{0}|{1}" -f $mode, [string]($i.name))
        $importActual[$key] = [ordered]@{
            repo = [string]($i.repo)
            ref = if ([string]::IsNullOrWhiteSpace([string]($i.ref))) { "main" } else { [string]($i.ref) }
            skill = Normalize-SkillPath ([string]($i.skill))
            sparse = [bool]$i.sparse
        }
    }
    $expImportJson = @($importExpected.Keys | Sort-Object | ForEach-Object {
            [ordered]@{
                key = [string]$_
                repo = [string]$importExpected[$_].repo
                ref = [string]$importExpected[$_].ref
                skill = [string]$importExpected[$_].skill
                sparse = [bool]$importExpected[$_].sparse
            }
        }) | ConvertTo-Json -Depth 20 -Compress
    $actImportJson = @($importActual.Keys | Sort-Object | ForEach-Object {
            [ordered]@{
                key = [string]$_
                repo = [string]$importActual[$_].repo
                ref = [string]$importActual[$_].ref
                skill = [string]$importActual[$_].skill
                sparse = [bool]$importActual[$_].sparse
            }
        }) | ConvertTo-Json -Depth 20 -Compress
    Need ($expImportJson -eq $actImportJson) "锁文件与当前 imports 配置不一致，请重新执行 .\skills.ps1 锁定"
}

function Assert-LockMatchesWorkspace($cfg, $lock) {
    foreach ($v in @($lock.vendors)) {
        $path = VendorPath ([string]($v.name))
        $actual = Get-RepoHeadCommit $path
        Need ($actual -eq [string]($v.commit)) ("vendor 提交不匹配：{0}（lock={1}, actual={2}）" -f [string]($v.name), [string]($v.commit), [string]$actual)
    }
    foreach ($i in @($lock.imports)) {
        $mode = if ([string]::IsNullOrWhiteSpace([string]($i.mode))) { "manual" } else { [string]($i.mode) }
        $path = if ($mode -eq "vendor") { VendorPath ([string]($i.name)) } else { Join-Path $ImportDir ([string]($i.name)) }
        $sourceKind = Get-ImportLockSourceKind $i
        if ($sourceKind -eq "local_zip") {
            $expectedSourceHash = [string](Get-CfgObjectProperty $i "source_hash")
            Need (-not [string]::IsNullOrWhiteSpace($expectedSourceHash)) ("锁文件缺少 local zip 源指纹：{0}/{1}" -f $mode, [string]($i.name))
            $actualSourceHash = Get-ImportLockSourceHash ([string]($i.repo)) $sourceKind
            Need ($actualSourceHash -eq $expectedSourceHash) ("import 源文件不匹配：{0}/{1}（lock={2}, actual={3}）" -f $mode, [string]($i.name), $expectedSourceHash, $actualSourceHash)

            $expectedFingerprint = [string](Get-CfgObjectProperty $i "workspace_fingerprint")
            Need (-not [string]::IsNullOrWhiteSpace($expectedFingerprint)) ("锁文件缺少 import 工作区指纹：{0}/{1}" -f $mode, [string]($i.name))
            $actualFingerprint = Get-ImportLockWorkspaceFingerprint $path
            Need ($actualFingerprint -eq $expectedFingerprint) ("import 内容不匹配：{0}/{1}（lock={2}, actual={3}）" -f $mode, [string]($i.name), $expectedFingerprint, $actualFingerprint)
            continue
        }

        $actual = Get-RepoHeadCommit $path
        Need ($actual -eq [string]($i.commit)) ("import 提交不匹配：{0}/{1}（lock={2}, actual={3}）" -f $mode, [string]($i.name), [string]($i.commit), [string]$actual)
    }
}

function Ensure-LockedState($cfg = $null) {
    if ($null -eq $cfg) { $cfg = LoadCfg }
    $lock = Load-LockData
    Assert-LockMatchesCfg $cfg $lock
    Assert-LockMatchesWorkspace $cfg $lock
    return $lock
}

function 验证锁定 {
    $cfg = LoadCfg
    $lock = Ensure-LockedState $cfg
    Write-Host ("锁定状态验证通过：vendors={0}, imports={1}" -f @($lock.vendors).Count, @($lock.imports).Count)
}

function Apply-LockToWorkspace($cfg, $lock) {
    foreach ($v in @($lock.vendors)) {
        $name = [string]($v.name)
        $repo = [string]($v.repo)
        $ref = if ([string]::IsNullOrWhiteSpace([string]($v.ref))) { "main" } else { [string]($v.ref) }
        $commit = [string]($v.commit)
        $path = VendorPath $name
        Ensure-Repo $path $repo $ref $null ([bool]$cfg.update_force) $false $true
        Push-Location $path
        try {
            $sparsePaths = Get-VendorSparsePaths $cfg $name
            Set-GitSparseCheckout $sparsePaths
            Invoke-Git @("checkout", $commit)
        }
        finally { Pop-Location }
    }

    foreach ($i in @($lock.imports)) {
        $mode = if ([string]::IsNullOrWhiteSpace([string]($i.mode))) { "manual" } else { [string]($i.mode) }
        if ($mode -ne "manual") { continue }
        $name = [string]($i.name)
        $repo = [string]($i.repo)
        $ref = if ([string]::IsNullOrWhiteSpace([string]($i.ref))) { "main" } else { [string]($i.ref) }
        $skillPath = Normalize-SkillPath ([string]($i.skill))
        $gitSkillPath = To-GitPath $skillPath
        $sparse = [bool]$i.sparse
        $sourceKind = Get-ImportLockSourceKind $i
        if ($gitSkillPath -eq "." -and $sparse) { $sparse = $false }
        $sparsePath = if ($sparse) { $gitSkillPath } else { $null }
        $path = Join-Path $ImportDir $name
        $forceClean = [bool]$cfg.update_force

        if ($sourceKind -eq "local_zip") {
            $expectedSourceHash = [string](Get-CfgObjectProperty $i "source_hash")
            Need (-not [string]::IsNullOrWhiteSpace($expectedSourceHash)) ("锁文件缺少 local zip 源指纹：manual/{0}" -f $name)
            $actualSourceHash = Get-ImportLockSourceHash $repo $sourceKind
            Need ($actualSourceHash -eq $expectedSourceHash) ("import 源文件不匹配：manual/{0}（lock={1}, actual={2}）" -f $name, $expectedSourceHash, $actualSourceHash)
            $forceClean = $true
        }

        Ensure-Repo $path $repo $ref $sparsePath $forceClean $false $true
        if ($sourceKind -eq "local_zip") {
            $expectedFingerprint = [string](Get-CfgObjectProperty $i "workspace_fingerprint")
            Need (-not [string]::IsNullOrWhiteSpace($expectedFingerprint)) ("锁文件缺少 import 工作区指纹：manual/{0}" -f $name)
            $actualFingerprint = Get-ImportLockWorkspaceFingerprint $path
            Need ($actualFingerprint -eq $expectedFingerprint) ("import 内容不匹配：manual/{0}（lock={1}, actual={2}）" -f $name, $expectedFingerprint, $actualFingerprint)
            continue
        }

        Push-Location $path
        try { Invoke-Git @("checkout", [string]($i.commit)) }
        finally { Pop-Location }
    }
    Clear-SkillsCache
}

function 锁定 {
    $cfg = LoadCfg
    $lock = Save-LockData $cfg
    Write-Host ("已写入锁文件：{0}" -f (Get-LockPath))
    Write-Host ("锁定摘要：vendors={0}, imports={1}" -f @($lock.vendors).Count, @($lock.imports).Count)
}

function Get-PerfSummaryFromLogLines([string[]]$lines, [int]$RecentPerMetric = 3) {
    $events = New-Object System.Collections.Generic.List[object]
    if ($null -eq $lines) { return @() }
    foreach ($line in $lines) {
        if ([string]::IsNullOrWhiteSpace($line)) { continue }
        try {
            $record = $line | ConvertFrom-Json
        }
        catch { continue }
        if ($null -eq $record -or $null -eq $record.data) { continue }
        if (-not $record.data.PSObject.Properties.Match("metric").Count) { continue }
        if (-not $record.data.PSObject.Properties.Match("duration_ms").Count) { continue }
        $metric = [string]$record.data.metric
        if ([string]::IsNullOrWhiteSpace($metric)) { continue }
        $duration = 0
        try { $duration = [int]$record.data.duration_ms } catch { continue }
        if ($duration -lt 0) { continue }
        $events.Add([pscustomobject]@{
            metric = $metric
            duration_ms = $duration
            ts = [string]$record.ts
        }) | Out-Null
    }
    if ($events.Count -eq 0) { return @() }

    $summary = New-Object System.Collections.Generic.List[object]
    $groups = $events | Group-Object metric
    foreach ($g in $groups) {
        $recent = $g.Group | Select-Object -Last $RecentPerMetric
        if ($recent.Count -eq 0) { continue }
        $avg = [math]::Round((($recent | Measure-Object -Property duration_ms -Average).Average), 0)
        $last = ($recent | Select-Object -Last 1)
        $summary.Add([pscustomobject]@{
            metric = $g.Name
            samples = @($recent).Count
            avg_ms = [int]$avg
            last_ms = [int]$last.duration_ms
            last_ts = [string]$last.ts
        }) | Out-Null
    }
    return ($summary | Sort-Object metric)
}

function Get-DoctorGitVersion([switch]$NoHostLog) {
    if ($DryRun -or $NoHostLog) {
        $gitOut = & git version 2>$null
        if ($LASTEXITCODE -ne 0 -or $null -eq $gitOut) { throw "git version failed" }
        return (($gitOut | Select-Object -First 1).ToString().Trim())
    }
    return (Invoke-GitCapture @("version"))
}

function Get-DoctorOsDescription {
    try {
        $os = Get-CimInstance Win32_OperatingSystem
        if ($os -and -not [string]::IsNullOrWhiteSpace([string]$os.Caption)) {
            return ("{0} {1}" -f [string]$os.Caption, [string]$os.OSArchitecture).Trim()
        }
    }
    catch {}

    try {
        $description = [System.Runtime.InteropServices.RuntimeInformation]::OSDescription
        $architecture = [System.Runtime.InteropServices.RuntimeInformation]::OSArchitecture
        if (-not [string]::IsNullOrWhiteSpace([string]$description)) {
            return ("{0} {1}" -f [string]$description, [string]$architecture).Trim()
        }
    }
    catch {}

    return $null
}

function Parse-DoctorArgs([string[]]$tokens) {
    $opts = [ordered]@{
        json = $false
        fix = $false
        dry_run_fix = $false
        strict = $false
        strict_perf = $false
        offline_contract = $false
        threshold_ms = 5000
    }
    if ($null -eq $tokens) { return [pscustomobject]$opts }

    for ($i = 0; $i -lt $tokens.Count; $i++) {
        $t = [string]$tokens[$i]
        if ([string]::IsNullOrWhiteSpace($t)) { continue }
        $k = $t.Trim().ToLowerInvariant()
        switch ($k) {
            "--json" { $opts.json = $true; continue }
            "-j" { $opts.json = $true; continue }
            "--fix" { $opts.fix = $true; continue }
            "--dry-run-fix" { $opts.dry_run_fix = $true; continue }
            "--strict" { $opts.strict = $true; continue }
            "--strict-perf" { $opts.strict_perf = $true; continue }
            "--offline-contract" { $opts.offline_contract = $true; continue }
            "--threshold-ms" {
                Need ($i + 1 -lt $tokens.Count) "参数缺少值：--threshold-ms"
                $raw = [string]$tokens[++$i]
                $n = 0
                Need ([int]::TryParse($raw, [ref]$n)) ("--threshold-ms 必须是整数：{0}" -f $raw)
                Need ($n -gt 0) "--threshold-ms 必须大于 0"
                $opts.threshold_ms = $n
                continue
            }
            default { throw ("未知 doctor 参数：{0}" -f $t) }
        }
    }
    if ($opts.offline_contract) {
        Need $opts.json "--offline-contract 仅用于 doctor --json 结构契约"
        Need (-not $opts.strict) "--offline-contract 不能与 --strict 组合"
        Need (-not $opts.strict_perf) "--offline-contract 不能与 --strict-perf 组合"
        Need (-not $opts.fix -and -not $opts.dry_run_fix) "--offline-contract 不能与配置修复参数组合"
    }
    return [pscustomobject]$opts
}

function Apply-DoctorFixes($cfg, [switch]$Preview) {
    $result = [ordered]@{
        changed = $false
        applied = @()
    }
    if ($null -eq $cfg) { return [pscustomobject]$result }

    # low-risk fix #1: dedupe duplicate targets.path (keep first)
    if ($cfg.PSObject.Properties.Match("targets").Count -gt 0 -and $cfg.targets -ne $null) {
        $seenTarget = New-Object System.Collections.Generic.HashSet[string]([System.StringComparer]::OrdinalIgnoreCase)
        $newTargets = @()
        foreach ($t in @($cfg.targets)) {
            if ($null -eq $t) { continue }
            $path = if ($t.PSObject.Properties.Match("path").Count -gt 0) { [string]$t.path } else { "" }
            if ([string]::IsNullOrWhiteSpace($path)) {
                $newTargets += $t
                continue
            }
            $norm = $path.Trim()
            if ($seenTarget.Add($norm)) {
                $newTargets += $t
            }
            else {
                $result.applied += ("删除重复 targets.path：{0}" -f $norm)
                $result.changed = $true
            }
        }
        if ($result.changed -and -not $Preview) { $cfg.targets = @($newTargets) }
    }

    # low-risk fix #2: remove mappings referencing missing vendor
    if ($cfg.PSObject.Properties.Match("mappings").Count -gt 0 -and $cfg.mappings -ne $null) {
        $vendors = if ($cfg.PSObject.Properties.Match("vendors").Count -gt 0 -and $cfg.vendors -ne $null) { @($cfg.vendors) } else { @() }
        $vendorSet = New-CfgVendorNameSet $vendors

        $newMappings = @()
        foreach ($m in @($cfg.mappings)) {
            if ($null -eq $m) { continue }
            $vendor = if ($m.PSObject.Properties.Match("vendor").Count -gt 0) { [string]$m.vendor } else { "" }
            if ([string]::IsNullOrWhiteSpace($vendor) -or $vendorSet.Contains($vendor)) {
                $newMappings += $m
                continue
            }
            $from = if ($m.PSObject.Properties.Match("from").Count -gt 0) { [string]$m.from } else { "" }
            $to = if ($m.PSObject.Properties.Match("to").Count -gt 0) { [string]$m.to } else { "" }
            $result.applied += ("删除无效 mapping：vendor={0}, from={1}, to={2}" -f $vendor, $from, $to)
            $result.changed = $true
        }
        if ($result.changed -and -not $Preview) { $cfg.mappings = @($newMappings) }
    }

    $result.applied = @($result.applied)
    return [pscustomobject]$result
}

function Get-PerfThresholdMs([string]$Metric, [int]$DefaultThresholdMs = 5000) {
    if ([string]::IsNullOrWhiteSpace($Metric)) { return $DefaultThresholdMs }

    $metricKey = $Metric.Trim().ToLowerInvariant()
    switch ($metricKey) {
        "discover" { return 5000 }
        "build_agent" { return 8000 }
        "build_agent_cache_hit" { return 1000 }
        "build_agent_full" { return 20000 }
        "build_agent_cache_check" { return 10000 }
        "projection_package_hash_cache_hit" { return 3000 }
        "projection_package_hash_full" { return 20000 }
        "projection_plan_cached" { return 5000 }
        "projection_plan_full" { return 20000 }
        "apply_targets" { return 5000 }
        # Includes prebuild checks + full build/apply flow; realistic baseline in this repo is ~180s.
        "build_apply_total" { return 240000 }
        "sync_mcp" { return 10000 }
        # Update flow is network-heavy but should still surface regressions in doctor warnings.
        "update_vendor" { return 60000 }
        "update_imports" { return 180000 }
        "update_total" { return 240000 }
        # One-click workflows may include target-repo audit scans; keep this stricter than update_total but above normal audit smoke time.
        "workflow_run" { return 30000 }
        default { return $DefaultThresholdMs }
    }
}

function Add-PerfThresholdMetadata($summary, [int]$DefaultThresholdMs = 5000) {
    $annotated = @()
    if ($null -eq $summary) { return @() }

    foreach ($p in @($summary)) {
        if ($null -eq $p) { continue }
        $metricName = ""
        try { $metricName = [string]$p.metric } catch { $metricName = "" }
        $metricThreshold = Get-PerfThresholdMs $metricName $DefaultThresholdMs

        $item = [ordered]@{}
        foreach ($prop in $p.PSObject.Properties) {
            $item[$prop.Name] = $prop.Value
        }
        $item.effective_threshold_ms = $metricThreshold
        $item.anomaly_check_enabled = ($null -ne $metricThreshold)
        $annotated += [pscustomobject]$item
    }

    return @($annotated)
}

function Get-PerfAnomalyItems($summary, [int]$WarnThresholdMs = 5000, [int]$MinSamples = 3) {
    $items = @()
    if ($null -eq $summary) { return @() }
    foreach ($p in $summary) {
        if ($null -eq $p) { continue }
        $last = 0
        $avg = 0
        $samples = 0
        try { $last = [int]$p.last_ms } catch { continue }
        try { $avg = [int]$p.avg_ms } catch { continue }
        try { $samples = [int]$p.samples } catch { $samples = 0 }
        if ($samples -lt $MinSamples) { continue }
        $metricThreshold = Get-PerfThresholdMs ([string]$p.metric) $WarnThresholdMs
        if ($null -eq $metricThreshold) { continue }
        if ($last -gt $metricThreshold -or $avg -gt $metricThreshold) {
            $items += ("{0}: last={1}ms avg={2}ms threshold={3}ms" -f [string]$p.metric, $last, $avg, $metricThreshold)
        }
    }
    return ,@($items)
}

function Test-DoctorGitHubConnection {
    try {
        $tcpOk = Test-NetConnection "github.com" -Port 443 -InformationLevel Quiet
        if ($tcpOk) {
            return [pscustomobject]@{ ok = $true; method = "tcp"; detail = "" }
        }
    }
    catch {}

    if (Get-Command gh -ErrorAction SilentlyContinue) {
        try {
            $ghOutput = @(& gh api user --jq .login 2>$null)
            if ($LASTEXITCODE -eq 0 -and $ghOutput.Count -gt 0 -and -not [string]::IsNullOrWhiteSpace([string]$ghOutput[0])) {
                return [pscustomobject]@{ ok = $true; method = "gh_api"; detail = [string]$ghOutput[0] }
            }
        }
        catch {}
    }

    try {
        $probe = Invoke-GitCapture @("ls-remote", "--exit-code", "https://github.com/github/gitignore.git", "HEAD")
        if (-not [string]::IsNullOrWhiteSpace([string]$probe)) {
            return [pscustomobject]@{ ok = $true; method = "git_ls_remote"; detail = "" }
        }
    }
    catch {}

    return [pscustomobject]@{ ok = $false; method = "none"; detail = "github.com tcp, gh api, and git ls-remote probes failed" }
}

function Get-DoctorConfigRisks($cfg) {
    $risks = @()
    if ($null -eq $cfg) { return @() }

    $targetPaths = @()
    if ($cfg.PSObject.Properties.Match("targets").Count -gt 0 -and $cfg.targets -ne $null) {
        foreach ($t in $cfg.targets) {
            if ($null -eq $t) { continue }
            $path = if ($t.PSObject.Properties.Match("path").Count -gt 0) { [string]$t.path } else { "" }
            if ([string]::IsNullOrWhiteSpace($path)) { continue }
            $targetPaths += $path.Trim()
        }
    }
    $dupTargets = @($targetPaths | Group-Object | Where-Object { $_.Count -gt 1 } | ForEach-Object { $_.Name })
    if ($dupTargets.Count -gt 0) {
        $risks += ("检测到重复 targets.path：{0}" -f ($dupTargets -join ", "))
    }

    $mappingTo = @()
    if ($cfg.PSObject.Properties.Match("mappings").Count -gt 0 -and $cfg.mappings -ne $null) {
        foreach ($m in $cfg.mappings) {
            if ($null -eq $m) { continue }
            $to = if ($m.PSObject.Properties.Match("to").Count -gt 0) { [string]$m.to } else { "" }
            if ([string]::IsNullOrWhiteSpace($to)) { continue }
            $mappingTo += $to.Trim()
        }
    }
    $dupTo = @($mappingTo | Group-Object | Where-Object { $_.Count -gt 1 } | ForEach-Object { $_.Name })
    if ($dupTo.Count -gt 0) {
        $risks += ("检测到重复 mappings.to（可能互相覆盖）：{0}" -f ($dupTo -join ", "))
    }

    $vendors = if ($cfg.PSObject.Properties.Match("vendors").Count -gt 0 -and $cfg.vendors -ne $null) { @($cfg.vendors) } else { @() }
    $vendorSet = New-CfgVendorNameSet $vendors
    if ($cfg.PSObject.Properties.Match("mappings").Count -gt 0 -and $cfg.mappings -ne $null) {
        foreach ($m in $cfg.mappings) {
            if ($null -eq $m) { continue }
            $vendor = if ($m.PSObject.Properties.Match("vendor").Count -gt 0) { [string]$m.vendor } else { "" }
            if ([string]::IsNullOrWhiteSpace($vendor)) { continue }
            if (-not $vendorSet.Contains($vendor)) {
                $from = if ($m.PSObject.Properties.Match("from").Count -gt 0) { [string]$m.from } else { "" }
                $to = if ($m.PSObject.Properties.Match("to").Count -gt 0) { [string]$m.to } else { "" }
                $risks += ("mapping 引用了不存在的 vendor：{0} (from={1}, to={2})" -f $vendor, $from, $to)
            }
        }
    }

    return @($risks)
}

function Invoke-Doctor([string[]]$tokens = @()) {
    $opts = Parse-DoctorArgs $tokens
    if (-not $opts.json) {
        Write-Host "=== Skills Manager Doctor ===" -ForegroundColor Cyan
    }
    $pass = $true
    $cfgObj = $null
    $report = [ordered]@{
        pass = $true
        strict = [bool]$opts.strict
        strict_perf = [bool]$opts.strict_perf
        offline_contract = [bool]$opts.offline_contract
        checks = [ordered]@{}
        risks = @()
        performance = [ordered]@{
            threshold_ms = [int]$opts.threshold_ms
            summary = @()
            anomalies = @()
        }
        summary = [ordered]@{
            errors = @()
            warnings = @()
            error_count = 0
            warn_count = 0
        }
        fix = [ordered]@{
            requested = [bool]$opts.fix
            changed = $false
            applied = @()
        }
    }

    # 1. System Checks
    try {
        $osText = Get-DoctorOsDescription
        if ([string]::IsNullOrWhiteSpace([string]$osText)) { throw "OS detection returned empty" }
        $report.checks.os = $osText
        if (-not $opts.json) { Write-Host ("OS: {0}" -f $osText) }
    }
    catch {
        $report.checks.os = "unknown"
        if (-not $opts.json) { Write-Host "OS: unknown（读取失败）" -ForegroundColor Yellow }
    }

    # 2. Git Check
    try {
        $gitVer = Get-DoctorGitVersion -NoHostLog:$opts.json
        if ([string]::IsNullOrWhiteSpace($gitVer)) { throw "git version is empty" }
        $report.checks.git = [ordered]@{ ok = $true; value = $gitVer }
        if (-not $opts.json) { Write-Host "✅ Git: $gitVer" -ForegroundColor Green }
    }
    catch {
        $report.checks.git = [ordered]@{ ok = $false; value = "" }
        if (-not $opts.json) { Write-Host "❌ Git: Not found or error" -ForegroundColor Red }
        $pass = $false
    }

    # 3. Robocopy Check
    if (Get-Command robocopy -ErrorAction SilentlyContinue) {
        $report.checks.robocopy = [ordered]@{ ok = $true }
        if (-not $opts.json) { Write-Host "✅ Robocopy: Available" -ForegroundColor Green }
    }
    else {
        $report.checks.robocopy = [ordered]@{ ok = $false }
        if (-not $opts.json) { Write-Host "❌ Robocopy: Not found" -ForegroundColor Red }
        $pass = $false
    }

    # 4. Long Paths
    try {
        $lp = Get-ItemProperty "HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem" -Name "LongPathsEnabled" -ErrorAction SilentlyContinue
        if ($lp -and $lp.LongPathsEnabled -eq 1) {
            $report.checks.long_paths = [ordered]@{ ok = $true; value = 1 }
            if (-not $opts.json) { Write-Host "✅ LongPathsEnabled: 1 (On)" -ForegroundColor Green }
        }
        else {
            $report.checks.long_paths = [ordered]@{ ok = $false; value = 0 }
            if (-not $opts.json) { Write-Host "⚠️ LongPathsEnabled: 0 (Off) - Deep paths may fail." -ForegroundColor Yellow }
        }
    }
    catch {
        $report.checks.long_paths = [ordered]@{ ok = $false; value = "unknown" }
        if (-not $opts.json) { Write-Host "⚠️ LongPathsEnabled: Check failed" -ForegroundColor Yellow }
    }

    # 5. Config Check
    if (Test-Path $CfgPath) {
        try {
            # Keep parser behavior aligned with LoadCfg:
            # support whole-line comments in skills.json.
            $rawCfg = Get-Content $CfgPath -Raw
            $cleanCfg = $rawCfg -replace "(?m)^\s*//.*", ""
            $cfg = $cleanCfg | ConvertFrom-Json
            if ($cfg) {
                $contractErrors = @(Get-CfgContractErrors $cfg)
                if ($contractErrors.Count -gt 0) {
                    $report.checks.config = [ordered]@{
                        ok = $false
                        reason = ("contract_error: {0}" -f ($contractErrors -join " | "))
                        errors = @($contractErrors)
                    }
                    if (-not $opts.json) {
                        Write-Host "❌ skills.json: Contract Error" -ForegroundColor Red
                        foreach ($err in $contractErrors) {
                            Write-Host ("   - {0}" -f $err) -ForegroundColor Red
                        }
                    }
                    $pass = $false
                }
                else {
                    $cfgObj = $cfg
                    $report.checks.config = [ordered]@{ ok = $true; vendors = @($cfg.vendors).Count; mappings = @($cfg.mappings).Count }
                    if (-not $opts.json) {
                        Write-Host "✅ skills.json: Valid JSON + contract" -ForegroundColor Green
                        Write-Host ("   - Vendors: {0}" -f @($cfg.vendors).Count)
                        Write-Host ("   - Mappings: {0}" -f @($cfg.mappings).Count)
                    }
                }
            }
            else {
                $report.checks.config = [ordered]@{ ok = $false; reason = "invalid_or_empty" }
                if (-not $opts.json) { Write-Host "❌ skills.json: Invalid/Empty" -ForegroundColor Red }
                $pass = $false
            }
        }
        catch {
            $report.checks.config = [ordered]@{ ok = $false; reason = ("parse_error: {0}" -f $_.Exception.Message) }
            if (-not $opts.json) { Write-Host ("❌ skills.json: Parse Error - {0}" -f $_.Exception.Message) -ForegroundColor Red }
            $pass = $false
        }
    }
    else {
        $report.checks.config = [ordered]@{ ok = $false; reason = "not_found" }
        if (-not $opts.json) { Write-Host "⚠️ skills.json: Not found (Run init or add first)" -ForegroundColor Yellow }
    }

    # 6. Config Risk Scan
    try {
        if ($null -ne $cfgObj) {
            $risks = Get-DoctorConfigRisks $cfgObj
            $report.risks = @($risks)
            if ($risks.Count -gt 0) {
                if (-not $opts.json) {
                    Write-Host ("⚠️ 配置风险（{0} 项）：" -f $risks.Count) -ForegroundColor Yellow
                    foreach ($risk in $risks) {
                        Write-Host ("   - {0}" -f $risk) -ForegroundColor Yellow
                    }
                }
            }
        }
    }
    catch {
        if (-not $opts.json) { Write-Host "⚠️ 配置风险扫描失败（已忽略）" -ForegroundColor Yellow }
    }

    # 6.5 Optional auto-fix for low-risk config issues
    if (($opts.fix -or $opts.dry_run_fix) -and $null -ne $cfgObj) {
        try {
            $fixResult = Apply-DoctorFixes $cfgObj -Preview:$opts.dry_run_fix
            $report.fix.changed = [bool]$fixResult.changed
            $report.fix.applied = @($fixResult.applied)
            $report.fix.preview = [bool]$opts.dry_run_fix
            if ($fixResult.changed) {
                if (-not $DryRun -and -not $opts.dry_run_fix) {
                    $json = $cfgObj | ConvertTo-Json -Depth 50
                    Set-ContentUtf8 $CfgPath $json
                }
                if (-not $opts.json) {
                    if ($opts.dry_run_fix) {
                        Write-Host ("doctor --dry-run-fix 预览 {0} 项可修复内容。" -f @($fixResult.applied).Count) -ForegroundColor Yellow
                    }
                    else {
                        Write-Host ("✅ doctor --fix 已应用 {0} 项修复。" -f @($fixResult.applied).Count) -ForegroundColor Green
                    }
                    foreach ($line in @($fixResult.applied)) {
                        if ($opts.dry_run_fix) {
                            Write-Host ("   - {0}" -f $line) -ForegroundColor Yellow
                        }
                        else {
                            Write-Host ("   - {0}" -f $line) -ForegroundColor Green
                        }
                    }
                }
            }
            elseif (-not $opts.json) {
                if ($opts.dry_run_fix) { Write-Host "doctor --dry-run-fix：未发现可自动修复项。" }
                else { Write-Host "doctor --fix：未发现可自动修复项。" }
            }
        }
        catch {
            if (-not $opts.json) { Write-Host ("⚠️ doctor --fix 执行失败：{0}" -f $_.Exception.Message) -ForegroundColor Yellow }
        }
    }

    # 7. Network Check. JSON structure contracts are deterministic and must not
    # pay for or depend on a live GitHub probe; strict health checks always probe.
    if ($opts.offline_contract) {
        $report.checks.network = [ordered]@{ ok = $true; skipped = $true; reason = "offline_contract" }
    }
    else {
        try {
            $githubConnection = Test-DoctorGitHubConnection
            if ($githubConnection.ok) {
                $report.checks.network = [ordered]@{ ok = $true; method = [string]$githubConnection.method }
                if (-not $opts.json) { Write-Host ("✅ GitHub Connection: OK ({0})" -f [string]$githubConnection.method) -ForegroundColor Green }
            }
            else {
                $report.checks.network = [ordered]@{ ok = $false; method = [string]$githubConnection.method; reason = [string]$githubConnection.detail }
                if (-not $opts.json) { Write-Host ("❌ GitHub Connection: Failed - {0}" -f [string]$githubConnection.detail) -ForegroundColor Red }
                $pass = $false
            }
        }
        catch {
            $report.checks.network = [ordered]@{ ok = $false; reason = $_.Exception.Message }
            if (-not $opts.json) { Write-Host ("❌ GitHub Connection: Failed - {0}" -f $_.Exception.Message) -ForegroundColor Red }
            $pass = $false
        }
    }

    # 8. Performance Summary
    try {
        if (Test-Path $LogPath) {
            $lines = Get-Content $LogPath -Tail 5000 -ErrorAction SilentlyContinue
            $perf = Get-PerfSummaryFromLogLines $lines 3
            $report.performance.summary = @(Add-PerfThresholdMetadata $perf $opts.threshold_ms)
            if ($perf.Count -gt 0) {
                if (-not $opts.json) {
                    Write-Host "最近性能摘要（最近 3 次）："
                    foreach ($p in $report.performance.summary) {
                        Write-Host ("   - {0}: last={1}ms avg={2}ms samples={3}" -f $p.metric, $p.last_ms, $p.avg_ms, $p.samples)
                    }
                }
                $anomalies = Get-PerfAnomalyItems $report.performance.summary $opts.threshold_ms
                $report.performance.anomalies = @($anomalies)
                if ($anomalies.Count -gt 0) {
                    if (-not $opts.json) {
                        Write-Host ("⚠️ 性能异常（阈值 {0}ms，{1} 项）：" -f $opts.threshold_ms, $anomalies.Count) -ForegroundColor Yellow
                        foreach ($a in $anomalies) {
                            Write-Host ("   - {0}" -f $a) -ForegroundColor Yellow
                        }
                    }
                }
            }
        }
    }
    catch {
        if (-not $opts.json) { Write-Host "⚠️ 性能摘要读取失败（已忽略）" -ForegroundColor Yellow }
    }

    $report.pass = $pass
    if (-not $report.checks.git.ok) { $report.summary.errors += "git_unavailable" }
    if (-not $report.checks.robocopy.ok) { $report.summary.errors += "robocopy_unavailable" }
    if (-not $report.checks.config.ok) {
        $reason = if ($report.checks.config.reason) { [string]$report.checks.config.reason } else { "config_invalid" }
        if ($reason -like "parse_error*") { $report.summary.errors += "config_parse_error" }
        elseif ($reason -like "contract_error*") { $report.summary.errors += "config_contract_error" }
        else { $report.summary.warnings += "config_not_ready" }
    }
    if ($report.checks.network -and -not $report.checks.network.ok) { $report.summary.errors += "network_unavailable" }
    if ($report.checks.long_paths.value -eq 0) { $report.summary.warnings += "long_paths_off" }
    if (@($report.risks).Count -gt 0) { $report.summary.warnings += "config_risks_present" }
    if (@($report.performance.anomalies).Count -gt 0) { $report.summary.warnings += "perf_anomalies_present" }

    if ($opts.strict -and (@($report.risks).Count -gt 0 -or ([bool]$opts.strict_perf -and @($report.performance.anomalies).Count -gt 0))) {
        $report.pass = $false
    }
    $report.summary.error_count = @($report.summary.errors).Count
    $report.summary.warn_count = @($report.summary.warnings).Count
    if ($opts.json) {
        Write-Host ($report | ConvertTo-Json -Depth 30)
        return [pscustomobject]$report
    }
    if ($opts.strict -and -not $opts.strict_perf -and @($report.performance.anomalies).Count -gt 0) {
        Write-Host "提示：性能异常仅告警，不影响 --strict 结果。使用 --strict-perf 可将其纳入阻断。" -ForegroundColor Yellow
    }

    Write-Host ""
    if ($report.pass) {
        Write-Host "Your system is ready for skills-manager." -ForegroundColor Green
    }
    else {
        Write-Host "Some checks failed. Please review issues above." -ForegroundColor Red
    }
    return [pscustomobject]$report
}

function Upsert-Import($cfg, $import) {
    $existing = $cfg.imports | Where-Object { $_.name -eq $import.name } | Select-Object -First 1
    if ($existing) {
        $existing.repo = $import.repo
        $existing.ref = $import.ref
        $existing.skill = $import.skill
        $existing.mode = $import.mode
        $existing.sparse = $import.sparse
    }
    else {
        $cfg.imports += $import
    }
}

function Ensure-ImportVendorMapping($cfg, [string]$vendorName, [string]$skillPath, [string]$targetName) {
    $skillPath = Normalize-SkillPath $skillPath
    $from = $skillPath
    if ($from -eq ".") { $from = "." }
    $exists = $cfg.mappings | Where-Object { $_.vendor -eq $vendorName -and $_.from -eq $from } | Select-Object -First 1
    if (-not $exists) {
        $cfg.mappings += @{ vendor = $vendorName; from = $from; to = $targetName }
    }
}
function Ensure-ManualImportMapping($cfg, [string]$importName, [string]$targetName) {
    Need (-not [string]::IsNullOrWhiteSpace($importName)) "manual import name 不能为空"
    Need (-not [string]::IsNullOrWhiteSpace($targetName)) "manual target name 不能为空"
    $exists = $cfg.mappings | Where-Object { $_.vendor -eq "manual" -and $_.from -eq $importName } | Select-Object -First 1
    if (-not $exists) {
        $cfg.mappings += @{ vendor = "manual"; from = $importName; to = $targetName }
    }
}
function Test-NeedsSparseProbeFallback([string]$msg) {
    if ([string]::IsNullOrWhiteSpace($msg)) { return $false }
    return ($msg -match "unable to checkout working tree|checkout failed|git restore --source=HEAD :/|invalid path|Filename too long|文件名.*太长|路径.*过长")
}
function Get-PreferredSkillCandidates($candidates) {
    $ordered = @($candidates | Sort-Object rel)
    if ($ordered.Count -le 1) { return $ordered }
    $preferred = @($ordered | Where-Object {
            $relGit = (($_.rel -as [string]) -replace "\\", "/")
            $relGit -match "^(\\.claude/skills|skills)(/|$)"
        })
    if ($preferred.Count -gt 0) { return $preferred }
    return $ordered
}
function Get-RelevantSkillCandidates($candidates, [string]$skillPath) {
    $ranked = @(Get-SkillCandidatesByRelevance $candidates $skillPath)
    if ($ranked.Count -eq 0) { return @($candidates | Sort-Object rel) }
    return $ranked
}
function Resolve-SkillsWithSparseProbe([string]$repo, [string]$ref, [string[]]$skillPaths) {
    $repoCandidates = Get-SkillCandidatesFromGitRepo $repo $ref
    Need ($repoCandidates.Count -gt 0) "仓库内未发现任何有效的技能标记文件（SKILL.md, AGENTS.md, GEMINI.md, CLAUDE.md）"
    $resolved = @()
    foreach ($p in $skillPaths) {
        $normalized = Normalize-SkillPath $p
        $matched = $null

        $exact = @($repoCandidates | Where-Object { $_.rel -eq $normalized })
        if ($exact.Count -eq 1) {
            $matched = $exact[0].rel
        }

        if ([string]::IsNullOrWhiteSpace($matched) -and $normalized -ne "." -and $normalized -notmatch "[\\/]") {
            $prefixed = Join-Path "skills" $normalized
            $prefixedMatch = @($repoCandidates | Where-Object { $_.rel -eq $prefixed })
            if ($prefixedMatch.Count -eq 1) { $matched = $prefixedMatch[0].rel }
        }

        if ([string]::IsNullOrWhiteSpace($matched)) {
            $leaf = Split-Path $normalized -Leaf
            $leafMatches = @($repoCandidates | Where-Object { $_.leaf -eq $leaf })
            if ($leafMatches.Count -eq 1) {
                $matched = $leafMatches[0].rel
            }
            elseif ($leafMatches.Count -gt 1) {
                $preferredLeaf = @(Get-PreferredSkillCandidates $leafMatches)
                if ($preferredLeaf.Count -eq 1) {
                    $matched = $preferredLeaf[0].rel
                }
                else {
                    $rankedLeaf = @(Get-RelevantSkillCandidates $preferredLeaf $normalized)
                    $top = @($rankedLeaf | Select-Object -First 12 | ForEach-Object { "- $($_.rel)" })
                    throw ("技能路径预检失败：--skill {0}`n同名候选过多，请改为精确路径。`n{1}" -f $normalized, ($top -join "`n"))
                }
            }
        }

        if ([string]::IsNullOrWhiteSpace($matched)) {
            $leafNorm = Normalize-Name (Split-Path $normalized -Leaf)
            $leafCompact = Normalize-CompactName (Split-Path $normalized -Leaf)
            if (-not [string]::IsNullOrWhiteSpace($leafNorm)) {
                $fuzzy = @($repoCandidates | Where-Object {
                        $candNorm = Normalize-Name $_.leaf
                        if ([string]::IsNullOrWhiteSpace($candNorm)) { return $false }
                        return ($leafNorm -eq $candNorm) -or ($leafNorm.EndsWith("-$candNorm"))
                    })
                if ($fuzzy.Count -eq 1) {
                    $matched = $fuzzy[0].rel
                }
                elseif ($fuzzy.Count -gt 1) {
                    $preferredFuzzy = @(Get-PreferredSkillCandidates $fuzzy)
                    if ($preferredFuzzy.Count -eq 1) {
                        $matched = $preferredFuzzy[0].rel
                    }
                    else {
                        $rankedFuzzy = @(Get-RelevantSkillCandidates $preferredFuzzy $normalized)
                        $top = @($rankedFuzzy | Select-Object -First 12 | ForEach-Object { "- $($_.rel)" })
                        throw ("技能路径预检失败：--skill {0}`n后缀候选过多，请改为精确路径。`n{1}" -f $normalized, ($top -join "`n"))
                    }
                }
            }
            if ([string]::IsNullOrWhiteSpace($matched) -and -not [string]::IsNullOrWhiteSpace($leafCompact)) {
                $compact = @($repoCandidates | Where-Object {
                        $candCompact = Normalize-CompactName $_.leaf
                        if ([string]::IsNullOrWhiteSpace($candCompact)) { return $false }
                        return ($leafCompact -eq $candCompact) -or ($leafCompact.Contains($candCompact)) -or ($candCompact.Contains($leafCompact))
                    })
                if ($compact.Count -eq 1) {
                    $matched = $compact[0].rel
                }
                elseif ($compact.Count -gt 1) {
                    $preferredCompact = @(Get-PreferredSkillCandidates $compact)
                    $rankedCompact = @(Get-RelevantSkillCandidates $preferredCompact $normalized)
                    $top = @($rankedCompact | Select-Object -First 12 | ForEach-Object { "- $($_.rel)" })
                    throw ("技能路径预检失败：--skill {0}`n紧凑匹配候选过多，请改为精确路径。`n{1}" -f $normalized, ($top -join "`n"))
                }
            }
            if ([string]::IsNullOrWhiteSpace($matched) -and -not [string]::IsNullOrWhiteSpace($leafNorm) -and $leafNorm -match "(^|-)motion(s)?($|-)|(^|-)anim(ation|ate|ations)?($|-)") {
                $semantic = @($repoCandidates | Where-Object {
                        $candNorm = Normalize-Name $_.leaf
                        if ([string]::IsNullOrWhiteSpace($candNorm)) { return $false }
                        return ($candNorm -match "(^|-)motion(s)?($|-)|(^|-)anim(ation|ate|ations)?($|-)")
                    })
                if ($semantic.Count -eq 1) {
                    $matched = $semantic[0].rel
                }
                elseif ($semantic.Count -gt 1) {
                    $preferredSemantic = @(Get-PreferredSkillCandidates $semantic)
                    $rankedSemantic = @(Get-RelevantSkillCandidates $preferredSemantic $normalized)
                    $top = @($rankedSemantic | Select-Object -First 12 | ForEach-Object { "- $($_.rel)" })
                    throw ("技能路径预检失败：--skill {0}`n语义匹配候选过多，请改为精确路径。`n{1}" -f $normalized, ($top -join "`n"))
                }
            }
        }

        if ([string]::IsNullOrWhiteSpace($matched)) {
            $rankedAll = @(Get-RelevantSkillCandidates $repoCandidates $normalized)
            $top = @($rankedAll | Select-Object -First 12 | ForEach-Object { "- $($_.rel)" })
            throw ("技能路径预检失败：--skill {0}`n仓库在当前系统上无法完成完整 checkout，且未找到该路径。请显式指定正确路径。`n{1}" -f $normalized, ($top -join "`n"))
        }

        if ($matched -ne $normalized) { Write-Host ("未找到指定路径，已自动修正为：{0}" -f $matched) }
        $resolved += $matched
    }
    return $resolved
}
function Resolve-SkillsWithProbe([string]$repo, [string]$ref, [string[]]$skillPaths, [bool]$forceClean) {
    $probeName = ("_probe_{0}" -f ([Guid]::NewGuid().ToString("N").Substring(0, 8)))
    $probePath = Join-Path $ImportDir $probeName
    $resolved = @()
    try {
        try {
            Ensure-Repo $probePath $repo $ref $null $forceClean $false
        }
        catch {
            $probeError = $_.Exception.Message
            if (-not (Test-NeedsSparseProbeFallback $probeError)) { throw }
            Log ("完整 clone/checkout 预检失败，自动回退 sparse 预检：{0}" -f $probeError) "WARN"
            return (Resolve-SkillsWithSparseProbe $repo $ref $skillPaths)
        }
        if ($script:SkillCandidatesCache) { $script:SkillCandidatesCache.Remove($probePath) | Out-Null }
        foreach ($p in $skillPaths) {
            $normalized = Normalize-SkillPath $p
            try {
                $resolved += (Resolve-SkillPath $probePath $normalized)
            }
            catch {
                $candidates = @()
                try { $candidates = Get-SkillCandidates $probePath } catch {}
                $hint = @()
                if ($candidates.Count -gt 0) {
                    $rankedCandidates = @(Get-RelevantSkillCandidates $candidates $normalized)
                    $hint += ("可用技能路径候选（Top {0}）：" -f ([Math]::Min(12, $candidates.Count)))
                    foreach ($c in ($rankedCandidates | Select-Object -First 12)) {
                        $hint += ("- {0}" -f $c.rel)
                    }
                    if ($candidates.Count -gt 12) {
                        $hint += ("... 另有 {0} 项未显示" -f ($candidates.Count - 12))
                    }
                }
                $msg = ("技能路径预检失败：--skill {0}`n{1}" -f $normalized, $_.Exception.Message)
                if ($hint.Count -gt 0) { $msg += ("`n" + ($hint -join "`n")) }
                throw $msg
            }
        }
        return $resolved
    }
    finally {
        if (Test-Path $probePath) { Invoke-RemoveItemWithRetry $probePath -Recurse -IgnoreFailure | Out-Null }
        if ($script:SkillCandidatesCache) { $script:SkillCandidatesCache.Remove($probePath) | Out-Null }
    }
}
function Get-InstallErrorSuggestedSkillPath([string]$msg, [string[]]$skillPaths) {
    if (-not [string]::IsNullOrWhiteSpace($msg)) {
        $bulletMatches = [regex]::Matches($msg, "(?m)^-\s+(.+)$")
        foreach ($m in $bulletMatches) {
            $candidate = $m.Groups[1].Value.Trim()
            if ([string]::IsNullOrWhiteSpace($candidate)) { continue }
            if ($candidate -eq ".") { continue }
            return ($candidate -replace "\\", "/")
        }
    }

    $sample = if ($skillPaths -and $skillPaths.Count -gt 0) { $skillPaths[0] } else { "<skill>" }
    $sample = ($sample -replace "\\", "/").Trim()
    if ([string]::IsNullOrWhiteSpace($sample)) { return "skills/<skill>" }
    if ($sample -eq ".") { return "." }
    if ($sample.Contains("/")) { return $sample }

    $leaf = Split-Path $sample -Leaf
    if ([string]::IsNullOrWhiteSpace($leaf)) { $leaf = "<skill>" }
    return ("skills/{0}" -f $leaf)
}
function Get-CrossRepoInstallFallbackPlan([string]$repo, [string[]]$skillPaths, [string]$msg) {
    if ([string]::IsNullOrWhiteSpace($msg) -or $msg -notmatch "未找到技能入口文件") { return $null }
    if (-not $skillPaths -or $skillPaths.Count -eq 0) { return $null }

    $repoText = if ([string]::IsNullOrWhiteSpace($repo)) { "" } else { $repo.ToLowerInvariant() }
    $firstSkill = [string]$skillPaths[0]
    $leaf = (Split-Path (Normalize-SkillPath $firstSkill) -Leaf).ToLowerInvariant()
    $leafNorm = Normalize-Name $leaf

    # High-frequency cross-repo aliases.
    $catalog = @(
        @{
            pattern = "(^|-)motion(s)?($|-)|(^|-)anim(ation|ate|ations)?($|-)"
            repoMatch = "mblode/agent-skills"
            repo = "https://github.com/mblode/agent-skills.git"
            skill = "motion"
        },
        @{
            pattern = "(^|-)uni(-)?app($|-)|(^|-)uni-helper($|-)"
            repoMatch = "uni-helper/skills"
            repo = "https://github.com/uni-helper/skills.git"
            skill = "uniapp"
        },
        @{
            pattern = "(^|-)remotion($|-)|(^|-)remotion-best-practices($|-)"
            repoMatch = "remotion-dev/skills"
            repo = "https://github.com/remotion-dev/skills.git"
            skill = "remotion"
        }
    )

    foreach ($entry in $catalog) {
        if ($leafNorm -notmatch $entry.pattern) { continue }
        if ($repoText -match [string]$entry.repoMatch) { continue }
        return [pscustomobject]@{
            repo = [string]$entry.repo
            skill = [string]$entry.skill
            command = (".\skills.ps1 add {0} --skill {1}" -f [string]$entry.repo, [string]$entry.skill)
        }
    }
    return $null
}
function Write-InstallErrorHint([string]$msg, [string]$repo, [string[]]$skillPaths) {
    if ([string]::IsNullOrWhiteSpace($msg)) { return }
    if ($msg -match "zip 文件当前被占用|由另一进程使用|being used by another process") {
        Write-Host "提示：检测到 zip 被占用。请关闭资源管理器预览/压缩软件/同步盘后重试；工具已自动采用“临时复制 + 重试解压”策略。" -ForegroundColor Yellow
        return
    }
    if ($msg -match "仓库不可访问或不存在|Repository not found|repository '.+' not found") {
        if (Test-LocalZipRepoInput $repo) {
            Write-Host "提示：你传入的是本地 zip，已按本地压缩包处理；若仍失败，请确认 zip 可读且未被占用。" -ForegroundColor Yellow
            return
        }
        Write-Host "提示：请先在浏览器确认仓库地址可访问，私有仓库需先配置 git 凭据。" -ForegroundColor Yellow
        return
    }
    if ($msg -match "仓库内未发现任何有效的技能标记文件") {
        Write-Host "提示：该仓库可能不是本工具支持的 skills 仓库（缺少 SKILL.md/AGENTS.md/GEMINI.md/CLAUDE.md）。" -ForegroundColor Yellow
        return
    }
    if ($msg -match "未找到技能入口文件") {
        $suggestedSkillPath = Get-InstallErrorSuggestedSkillPath $msg $skillPaths
        Write-Host ("提示：请改用真实路径，例如：--skill {0}" -f $suggestedSkillPath) -ForegroundColor Yellow
        Write-Host ("提示：当前 repo = {0}" -f $repo) -ForegroundColor Yellow
        $plan = Get-CrossRepoInstallFallbackPlan $repo $skillPaths $msg
        if ($plan -and -not [string]::IsNullOrWhiteSpace([string]$plan.command)) {
            Write-Host ("提示：当前仓库可能不包含该技能，可直接执行：{0}" -f $plan.command) -ForegroundColor Yellow
        }
    }
}

function Get-DeclaredSkillNameFromDir([string]$skillDir) {
    if ([string]::IsNullOrWhiteSpace($skillDir)) { return $null }
    $skillFile = Join-Path $skillDir "SKILL.md"
    if (-not (Test-Path -LiteralPath $skillFile -PathType Leaf)) { return $null }
    foreach ($line in (Get-Content -LiteralPath $skillFile -TotalCount 80 -ErrorAction SilentlyContinue)) {
        if ($line -match "^\s*name:\s*(.+?)\s*$") {
            $declaredName = $Matches[1].Trim().Trim("'`"")
            if (-not [string]::IsNullOrWhiteSpace($declaredName)) {
                return $declaredName
            }
        }
    }
    return $null
}

function Get-AddImportPlanFromParsedArgs($parsed) {
    Need ($null -ne $parsed) "parsed add args 不能为空"

    $repo = Normalize-RepoUrl $parsed.repo
    $ref = [string]$parsed.ref
    $refIsAuto = $false
    if ([string]::IsNullOrWhiteSpace($ref)) {
        $ref = "main"
        $refIsAuto = $true
    }

    $mode = [string]$parsed.mode
    if ([string]::IsNullOrWhiteSpace($mode)) { $mode = "manual" }
    $mode = $mode.ToLowerInvariant()
    Need ($mode -eq "manual" -or $mode -eq "vendor") "mode 仅支持 manual 或 vendor"

    $registerVendorOnly = (-not [bool]$parsed.skillSpecified -and -not [bool]$parsed.modeSpecified)
    if ($registerVendorOnly) { $mode = "vendor" }

    return [pscustomobject]@{
        repo = $repo
        ref = $ref
        refIsAuto = $refIsAuto
        mode = $mode
        registerVendorOnly = $registerVendorOnly
        sparse = [bool]$parsed.sparse
    }
}

function Add-ImportFromArgs([string[]]$tokens, [switch]$NoBuild) {
    Preflight
    $cfgRaw = ""
    $cfg = LoadCfg
    if (Test-Path $CfgPath) { $cfgRaw = Get-Content $CfgPath -Raw }

    $resolvedTokens = Resolve-AddTokensFromAnyFormat $tokens
    if ($resolvedTokens) { $tokens = $resolvedTokens }
    $parsed = Parse-AddArgs $tokens
    $plan = Get-AddImportPlanFromParsedArgs $parsed
    $repo = $plan.repo
    $ref = $plan.ref
    $refIsAuto = [bool]$plan.refIsAuto
    $mode = $plan.mode
    $registerVendorOnly = [bool]$plan.registerVendorOnly
    $sparse = [bool]$plan.sparse

    if ($DryRun) {
        if ($registerVendorOnly) {
            Write-Host ("DRYRUN：将新增技能库（vendor only）：{0} ({1})" -f $repo, $ref)
        }
        else {
            Write-Host ("DRYRUN：将从 {0} ({1}) 导入 {2} 个技能，模式：{3}，Sparse：{4}" -f $repo, $ref, $parsed.skills.Count, $mode, $sparse)
        }
        if (-not $NoBuild) { Write-Host "DRYRUN：将执行【构建生效】" }
        return $true
    }

    try {
        # Strict precheck: repo must be reachable.
        Assert-RepoReachable $repo

        if ($refIsAuto) {
            $ref = Get-RepoDefaultBranch $repo
            Log ("未指定 --ref，自动使用仓库默认分支：{0}" -f $ref)
        }

        $resolvedSkillPaths = $null

        # Auto-detect mode if not specified (or default manual)
        if ($mode -eq "manual") {
            Need (-not [string]::IsNullOrWhiteSpace($repo)) "Repo URL cannot be empty"
            $matchedVendor = Match-VendorByRepo $cfg $repo
            if ($matchedVendor) {
                $mode = "vendor"
                $vendorName = $matchedVendor.name
                $parsed.name = $vendorName # Override name to vendor name
                Log ("自动检测到已存在的 Vendor：{0}。切换为 Vendor 模式安装。" -f $vendorName)
            }
            elseif ($registerVendorOnly) {
                Log "未显式指定 --skill：按“仅新增技能库”处理（不安装仓库内技能）。"
                $mode = "vendor"
            }
        }

        # Strict precheck: resolve all skill paths before writing config.
        if ($registerVendorOnly) {
            $resolvedSkillPaths = @()
        }
        elseif ($null -eq $resolvedSkillPaths) {
            $resolvedSkillPaths = @(Resolve-SkillsWithProbe $repo $ref $parsed.skills $cfg.update_force)
        }
        else {
            $resolvedSkillPaths = @($resolvedSkillPaths)
        }

        if ($mode -eq "manual") {
            $baseName = $null
            if (-not [string]::IsNullOrWhiteSpace($parsed.name)) {
                $baseName = Normalize-NameWithNotice $parsed.name "导入名称"
            }
            foreach ($skillPath in $resolvedSkillPaths) {
                $name = $baseName
                $allowDeclaredName = [string]::IsNullOrWhiteSpace($name)
                if ($allowDeclaredName -or $resolvedSkillPaths.Count -gt 1) {
                    $leaf = if ($skillPath -eq ".") { Guess-VendorName $repo } else { Split-Path $skillPath -Leaf }
                    $curName = Normalize-Name $leaf
                    $name = if (-not [string]::IsNullOrWhiteSpace($name)) { "$name-$curName" } else { $curName }
                }
                $name = Normalize-NameWithNotice $name "导入名称"

                $cache = Join-Path $ImportDir $name
                $gitSkillPath = To-GitPath $skillPath
                $curSparse = $sparse
                if ($gitSkillPath -eq "." -and $curSparse) { $curSparse = $false }
                $sparsePath = if ($curSparse) { $gitSkillPath } else { $null }
                $usedArchiveFallback = $false

                try {
                    Ensure-Repo $cache $repo $ref $sparsePath $cfg.update_force $true
                }
                catch {
                    $importError = $_.Exception.Message
                    if (($skillPath -eq ".") -or (-not (Test-NeedsSparseProbeFallback $importError))) { throw }
                    Log ("导入阶段 clone/checkout 失败，自动回退 git archive 子目录导出：{0}" -f $importError) "WARN"
                    try {
                        Ensure-RepoFromGitArchive $cache $repo $ref $skillPath $cfg.update_force
                    }
                    catch {
                        $archiveError = $_.Exception.Message
                        if (-not (Test-NeedsSparseProbeFallback $archiveError)) { throw }
                        Log ("git archive 回退失败，自动回退 GitHub 子目录快照导入：{0}" -f $archiveError) "WARN"
                        Ensure-RepoFromGitHubTreeSnapshot $cache $repo $ref $skillPath $cfg.update_force
                    }
                    $usedArchiveFallback = $true
                }
                if ($script:SkillCandidatesCache) { $script:SkillCandidatesCache.Remove($cache) | Out-Null }

                if ($curSparse -and -not $usedArchiveFallback) {
                    Ensure-Repo $cache $repo $ref (To-GitPath $skillPath) $cfg.update_force $true
                }
                $src = if ($skillPath -eq ".") { $cache } else { Join-Path $cache $skillPath }
                Need (Test-IsSkillDir $src) "未找到技能入口文件（SKILL.md/AGENTS.md/GEMINI.md/CLAUDE.md）：$src"

                if ($allowDeclaredName) {
                    $declaredName = Get-DeclaredSkillNameFromDir $src
                    if (-not [string]::IsNullOrWhiteSpace($declaredName)) {
                        $preferredName = Normalize-NameWithNotice $declaredName "导入名称"
                        if ($preferredName -ne $name) {
                            $preferredCache = Join-Path $ImportDir $preferredName
                            if ($cache -ne $preferredCache -and -not (Test-Path $preferredCache)) {
                                Invoke-MoveItem $cache $preferredCache
                                $cache = $preferredCache
                                $src = if ($skillPath -eq ".") { $cache } else { Join-Path $cache $skillPath }
                            }
                            $name = $preferredName
                        }
                    }
                }

                $import = @{ name = $name; repo = $repo; ref = $ref; skill = $skillPath; mode = "manual"; sparse = $curSparse }
                Upsert-Import $cfg $import
                Ensure-ManualImportMapping $cfg $name $name
            }
        }
        else {
            $vendorName = $parsed.name
            if ([string]::IsNullOrWhiteSpace($vendorName)) { $vendorName = Guess-VendorName $repo }
            $allowExistingVendor = ($cfg.vendors | Where-Object { $_.name -eq $vendorName -and (Is-SameRepository ([string]$_.repo) $repo) } | Select-Object -First 1) -ne $null
            $vendorName = Resolve-UniqueVendorName $cfg $vendorName $repo $allowExistingVendor
            $vendorPath = VendorPath $vendorName
      
            Ensure-Repo $vendorPath $repo $ref $null $cfg.update_force $true
            if (-not $registerVendorOnly) {
                foreach ($skillPath in $resolvedSkillPaths) {
                    if ($script:SkillCandidatesCache) { $script:SkillCandidatesCache.Remove($vendorPath) | Out-Null }
                    $src = if ($skillPath -eq ".") { $vendorPath } else { Join-Path $vendorPath $skillPath }
                    Need (Test-IsSkillDir $src) "未找到技能入口文件（SKILL.md/AGENTS.md/GEMINI.md/CLAUDE.md）：$src"

                    $targetSuffix = if ($skillPath -eq ".") { $vendorName } else { $skillPath }
                    $targetName = Make-TargetName $vendorName $targetSuffix
                    Ensure-ImportVendorMapping $cfg $vendorName $skillPath $targetName
                }

                $primarySkillPath = if ($resolvedSkillPaths -contains ".") { "." } else { [string]$resolvedSkillPaths[0] }
                $import = @{ name = $vendorName; repo = $repo; ref = $ref; skill = $primarySkillPath; mode = "vendor"; sparse = $sparse }
                Upsert-Import $cfg $import
            }
      
            $vendor = $cfg.vendors | Where-Object { $_.name -eq $vendorName } | Select-Object -First 1
            if (-not $vendor) {
                $cfg.vendors += @{ name = $vendorName; repo = $repo; ref = $ref }
            }
            else {
                $vendor.repo = $repo
                $vendor.ref = $ref
            }

            # Vendor-only registration should still reconcile already-installed manual skills from the same repo.
            if ($registerVendorOnly) {
                $migrated = Migrate-ManualToVendor $cfg $vendorName $repo
                if ($migrated -gt 0) {
                    Write-Host ("已自动迁移 {0} 个已安装技能到 vendor/{1}（仅关联，不新增其它技能）。" -f $migrated, $vendorName) -ForegroundColor Yellow
                }
            }
        }

        SaveCfgSafe $cfg $cfgRaw
        Clear-SkillsCache

        if (-not $NoBuild) {
            Write-Host "导入完成。开始【构建生效】..."
            构建生效
        }
        else {
            Write-Host "导入完成。"
        }
        return $true
    }
    catch {
        $errMsg = $_.Exception.Message
        $plan = Get-CrossRepoInstallFallbackPlan $repo $parsed.skills $errMsg
        if ($plan -and -not $script:CrossRepoAutoFallbackInProgress) {
            Log ("当前仓库未命中技能，自动回退到建议仓库重试：repo={0} --skill {1}" -f $plan.repo, $plan.skill) "WARN"
            $script:CrossRepoAutoFallbackInProgress = $true
            try {
                $fallbackTokens = @([string]$plan.repo, "--skill", [string]$plan.skill)
                if (-not [string]::IsNullOrWhiteSpace($parsed.ref)) { $fallbackTokens += @("--ref", [string]$parsed.ref) }
                if (-not [string]::IsNullOrWhiteSpace($parsed.mode) -and $parsed.mode -ne "manual") { $fallbackTokens += @("--mode", [string]$parsed.mode) }
                if ([bool]$parsed.sparse) { $fallbackTokens += "--sparse" }

                $autoOk = if ($NoBuild) { Add-ImportFromArgs $fallbackTokens -NoBuild } else { Add-ImportFromArgs $fallbackTokens }
                if ($autoOk) {
                    Write-Host ("已自动回退安装成功：{0}" -f $plan.command) -ForegroundColor Green
                    return $true
                }
            }
            finally {
                $script:CrossRepoAutoFallbackInProgress = $false
            }
        }
        if (-not $DryRun -and $cfgRaw) { Set-ContentUtf8 $CfgPath $cfgRaw }
        Write-Host ("❌ 导入失败: {0}" -f $errMsg) -ForegroundColor Red
        Write-InstallErrorHint $errMsg $repo $parsed.skills
        return $false
    }
}

function 初始化 {
    Preflight
    $cfg = LoadCfg

    foreach ($v in $cfg.vendors) {
        Need (-not [string]::IsNullOrWhiteSpace($v.name)) "vendor 缺少 name"
        Need (-not [string]::IsNullOrWhiteSpace($v.repo)) "vendor $($v.name) 缺少 repo"
        if ([string]::IsNullOrWhiteSpace($v.ref)) { $v.ref = "main" }

        $path = VendorPath $v.name
        if (Test-InstalledVendorPath $path $v.repo) {
            Write-Host "已存在：vendor/$($v.name)（来源匹配，跳过 clone）"
            continue
        }

        if (Test-Path $path) {
            $origin = $null
            try {
                Push-Location $path
                try { $origin = Invoke-GitCapture @("remote", "get-url", "origin") } finally { Pop-Location }
            }
            catch {}
            $originText = if ([string]::IsNullOrWhiteSpace($origin)) { "unknown" } else { $origin }
            throw ("vendor/{0} 已存在，但来源不匹配或不是 git 仓库：current={1}, expected={2}" -f $v.name, $originText, $v.repo)
        }

        Invoke-Git @("clone", $v.repo, $path)
        Push-Location $path
        Invoke-Git @("checkout", $v.ref)
        Pop-Location
    }

    # 初始化后建议先安装/卸载
    Write-Host "初始化完成。建议下一步：直接【安装】。"
    Clear-SkillsCache
}

function 新增技能库 {
    Preflight
    $repoInput = Read-Host "请输入技能库地址（留空=仅初始化已有 vendors）"
    if ([string]::IsNullOrWhiteSpace($repoInput)) {
        初始化
        return
    }
    $repo = Normalize-RepoUrl $repoInput
    $ref = Read-Host "可选：输入分支/Tag（留空默认 main）"
    if ([string]::IsNullOrWhiteSpace($ref)) { $ref = "main" }
    if ($ref -match "^\d+$") {
        $confirm = Read-Host "你输入的 ref 是纯数字，可能误填了菜单序号。继续使用该 ref？(y/N)"
        if (-not (Is-Yes $confirm)) { throw "已取消：请重新输入正确的分支/Tag。" }
    }
    $name = Read-Host "可选：输入自定义名称（留空自动从 URL 推断）"
    if ([string]::IsNullOrWhiteSpace($name)) { $name = Guess-VendorName $repo }
    $name = Normalize-NameWithNotice $name "vendor 名称"

    $cfg = LoadCfg
    $sameNameVendor = $cfg.vendors | Where-Object { $_.name -eq $name } | Select-Object -First 1
    if ($sameNameVendor) {
        if (Is-SameRepoIdentity ([string]$sameNameVendor.repo) $repo) {
            $installedPath = VendorPath $name
            if (Test-InstalledVendorPath $installedPath $repo) {
                Write-Host ("已存在：vendor/{0}（来源匹配，跳过新增）" -f $name)
                return
            }

            Write-Host ("已存在：vendor/{0}（来源匹配，检测到本地目录缺失或异常）" -f $name) -ForegroundColor Yellow
            Write-Host "将自动执行【初始化】补齐本地仓库..." -ForegroundColor Yellow
            初始化
            return
        }
        Need $false ("vendor 名称已存在：{0}（当前来源：{1}，期望来源：{2}）" -f $name, [string]$sameNameVendor.repo, $repo)
    }

    $sameRepoVendor = Match-VendorByRepo $cfg $repo
    if ($sameRepoVendor) {
        $installedPath = VendorPath $sameRepoVendor.name
        if (Test-InstalledVendorPath $installedPath $repo) {
            if ($sameRepoVendor.name -ne $name) {
                Write-Host ("该仓库已接入：vendor/{0}（忽略新名称：{1}，跳过新增）" -f $sameRepoVendor.name, $name)
            }
            else {
                Write-Host ("已存在：vendor/{0}（来源匹配，跳过新增）" -f $sameRepoVendor.name)
            }
            return
        }

        Write-Host ("该仓库已接入：vendor/{0}（检测到本地目录缺失或异常）" -f $sameRepoVendor.name) -ForegroundColor Yellow
        Write-Host "将自动执行【初始化】补齐本地仓库..." -ForegroundColor Yellow
        初始化
        return
    }

    $cfgRaw = ""
    if (Test-Path $CfgPath) { $cfgRaw = Get-Content $CfgPath -Raw }
    $tmp = Join-Path $VendorDir ("_tmp_" + $name)

    try {
        if (Test-Path $tmp) { Invoke-RemoveItem $tmp -Recurse }
        Invoke-Git @("clone", $repo, $tmp)
        Push-Location $tmp
        try {
            Invoke-Git @("checkout", $ref)
        }
        finally {
            Pop-Location
        }

        $cfg = LoadCfg
        if (Test-Path $CfgPath) { $cfgRaw = Get-Content $CfgPath -Raw }
        Need (-not ($cfg.vendors | Where-Object { $_.name -eq $name })) "vendor 名称已存在：$name"
        $cfg.vendors += @{ name = $name; repo = $repo; ref = $ref }
        SaveCfgSafe $cfg $cfgRaw

        $dst = VendorPath $name
        Need (-not (Test-Path $dst)) "vendor 已存在：$name"
        Invoke-MoveItem $tmp $dst

        Write-Host "新增完成。"
        
        # Auto-migrate orphan manual skills
        $migrated = Migrate-ManualToVendor $cfg $name $repo
        if ($migrated -gt 0) {
            SaveCfgSafe $cfg $cfgRaw # Save again with migrations
            Write-Host ("已自动迁移 {0} 个无需手动维护的技能到新 Vendor。" -f $migrated) -ForegroundColor Yellow
        }

        Clear-SkillsCache
    }
    catch {
        if (Test-Path $tmp) { Invoke-RemoveItem $tmp -Recurse }
        if (-not $DryRun -and $cfgRaw) { Set-ContentUtf8 $CfgPath $cfgRaw }
        Write-Host ("❌ 操作失败: {0}" -f $_.Exception.Message) -ForegroundColor Red
    }
}

function 删除技能库 {
    Preflight
    $cfg = LoadCfg
    Need ($cfg.vendors.Count -gt 0) "当前没有可删除的技能库。"

    $toRemove = Select-Items $cfg.vendors `
    { param($idx, $v) return ("{0,3}) {1} :: {2}" -f $idx, $v.name, $v.repo) } `
        "请选择要删除的技能库" `
        "未解析到有效序号（可能是分隔符或范围格式问题）。已取消删除。"
    if ($toRemove.Count -eq 0) {
        Write-Host "未选择任何技能库。"
        return
    }
    $preview = Format-VendorPreview $toRemove
    if (-not (Confirm-WithSummary "将删除以下技能库" $preview "确认删除所选技能库？" "Y")) {
        Write-Host "已取消删除。"
        return
    }
    $keepInstalledSkills = Confirm-Action "删除时是否保留该技能库下已安装技能（转换为 manual）？" "Y" -DefaultNo
    if (Skip-IfDryRun "删除技能库") { return }

    $cfgRaw = ""
    if (Test-Path $CfgPath) { $cfgRaw = Get-Content $CfgPath -Raw }
    try {
        $removeNames = New-Object System.Collections.Generic.HashSet[string]
        foreach ($v in $toRemove) { $removeNames.Add($v.name) | Out-Null }

        if ($keepInstalledSkills) {
            $totalConverted = 0
            $totalSkipped = 0
            foreach ($v in $toRemove) {
                $result = Convert-InstalledVendorSkillsToManual $cfg $v
                $totalConverted += [int]$result.converted
                $totalSkipped += [int]$result.skipped
            }
            if ($totalConverted -gt 0 -or $totalSkipped -gt 0) {
                Write-Host ("保留技能转换完成：converted={0}, skipped={1}" -f $totalConverted, $totalSkipped) -ForegroundColor Yellow
            }
        }

        $cfg.vendors = $cfg.vendors | Where-Object { -not $removeNames.Contains($_.name) }
        $cfg.mappings = $cfg.mappings | Where-Object { -not $removeNames.Contains($_.vendor) }
        $cfg.imports = $cfg.imports | Where-Object { -not ($_.mode -eq "vendor" -and $removeNames.Contains($_.name)) }
        SaveCfgSafe $cfg $cfgRaw

        foreach ($v in $toRemove) {
            $path = VendorPath $v.name
            if (Test-Path $path) { Invoke-RemoveItem $path -Recurse }
        }
        Write-Host ("已删除技能库：{0} 项。" -f $toRemove.Count)
        Clear-SkillsCache
        构建生效
    }
    catch {
        if (-not $DryRun -and $cfgRaw) { Set-ContentUtf8 $CfgPath $cfgRaw }
        Write-Host ("❌ 删除失败: {0}" -f $_.Exception.Message) -ForegroundColor Red
    }
}

function Get-SkillsUnder([string]$base, [string]$vendorName) {
    if (-not (Get-Variable -Name SkillListCache -Scope Script -ErrorAction SilentlyContinue)) { $script:SkillListCache = @{} }
    if ($null -eq $script:SkillListCache) { $script:SkillListCache = @{} }
    $baseItem = Get-Item -LiteralPath $base -Force -ErrorAction SilentlyContinue
    $resolvedBase = if ($baseItem -and $baseItem.PSIsContainer) { $baseItem.FullName } else { $null }
    $cacheBase = if ($resolvedBase) { $resolvedBase } else { $base }
    $key = "{0}|{1}" -f $vendorName, $cacheBase
    if ($script:SkillListCache.ContainsKey($key)) {
        return $script:SkillListCache[$key]
    }
    $items = @()
    if ($resolvedBase) {
        # Search for all supported markers
        $found = Get-ChildItem -LiteralPath $resolvedBase -Recurse -Force -ErrorAction SilentlyContinue |
        Where-Object { -not $_.PSIsContainer -and $_.Name -match "^(SKILL|AGENTS|GEMINI|CLAUDE)\.md$" }
      
        $seenDirs = New-Object System.Collections.Generic.HashSet[string]
        foreach ($f in $found) {
            $dir = $f.Directory.FullName
            if (-not $seenDirs.Add($dir)) { continue }
      
            $rel = $dir.Substring($resolvedBase.Length).TrimStart("\\")
            if ([string]::IsNullOrWhiteSpace($rel)) { $rel = "." }
            $items += [pscustomobject]@{ vendor = $vendorName; from = $rel; full = $dir }
        }
    }
    $items = ($items | Sort-Object vendor, from)
    $script:SkillListCache[$key] = $items
    return $items
}

function 收集Skills([string]$filter, $cfg = $null, $manualItems = $null) {
    if ($null -eq $cfg) { $cfg = LoadCfg }
    $items = @()

    foreach ($v in $cfg.vendors) {
        $base = VendorPath $v.name
        if (-not (Test-Path $base)) { continue }
        $items += Get-SkillsUnder $base $v.name
    }

    if ($null -eq $manualItems) { $manualItems = 收集ManualSkills $cfg }
    $items += $manualItems
    $items += 收集OverridesSkills

    if ($filter) {
        $items = Filter-Skills $items $filter
    }

    return ($items | Sort-Object vendor, from)
}

function Resolve-ManualImportSkillPath($cfg, [string]$importName, [switch]$AllowLegacyFallback) {
    if ($null -eq $cfg) { $cfg = LoadCfg }
    if ([string]::IsNullOrWhiteSpace($importName)) { return $null }
    $imp = $cfg.imports | Where-Object { $_.mode -eq "manual" -and $_.name -eq $importName } | Select-Object -First 1
    if ($imp) {
        $skillPath = Normalize-SkillPath $imp.skill
        $cache = Join-Path $ImportDir $imp.name
        $src = if ($skillPath -eq ".") { $cache } else { Join-Path $cache $skillPath }
        if (Test-IsSkillDir $src) { return $src }
    }
    if ($AllowLegacyFallback) {
        $legacyPath = Join-Path $ManualDir $importName
        if (Test-IsSkillDir $legacyPath) { return $legacyPath }
    }
    return $null
}

function Get-ManualDisplayVendorFromRepo([string]$repo) {
    if ([string]::IsNullOrWhiteSpace($repo)) { return "manual" }
    $r = [string]$repo
    $r = $r.Trim().Trim("'`"").TrimEnd("/")
    if ([string]::IsNullOrWhiteSpace($r)) { return "manual" }
    if ($r -match "^[A-Za-z]+://") {
        try {
            $uri = [Uri]$r
            $r = [string]$uri.AbsolutePath
        }
        catch {}
    }
    $r = $r.Trim().Trim("/")
    if ([string]::IsNullOrWhiteSpace($r)) { return "manual" }
    $r = $r -replace "\\", "/"
    $parts = @($r -split "/" | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    $leaf = if ($parts.Count -gt 0) { [string]$parts[$parts.Count - 1] } else { $r }
    if ($leaf.EndsWith(".git", [System.StringComparison]::OrdinalIgnoreCase)) {
        $leaf = $leaf.Substring(0, $leaf.Length - 4)
    }
    $leafNorm = Normalize-Name $leaf
    if ([string]::IsNullOrWhiteSpace($leafNorm)) { return "manual" }
    $first = @($leafNorm -split "-" | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -First 1)
    if ($first.Count -gt 0) { return [string]$first[0] }
    return $leafNorm
}

function 收集ManualSkills($cfg = $null, [switch]$IncludeLegacyManualDir) {
    if ($null -eq $cfg) { $cfg = LoadCfg }
    $items = @()
    $seen = New-Object System.Collections.Generic.HashSet[string]

    foreach ($i in $cfg.imports) {
        if ($i.mode -ne "manual") { continue }
        if ([string]::IsNullOrWhiteSpace($i.name)) { continue }
        $src = Resolve-ManualImportSkillPath $cfg $i.name -AllowLegacyFallback
        if (-not $src) { continue }
        $from = [string]$i.name
        if ($seen.Add($from)) {
            $items += [pscustomobject]@{
                vendor = "manual"
                display_vendor = Get-ManualDisplayVendorFromRepo ([string]$i.repo)
                from = $from
                full = $src
                source = if ((Join-Path $ManualDir $from) -eq $src) { "legacy-manual-dir" } else { "imports" }
            }
        }
    }

    if ($IncludeLegacyManualDir) {
        foreach ($legacy in (Get-SkillsUnder $ManualDir "manual")) {
            if ($seen.Add($legacy.from)) {
                $items += [pscustomobject]@{
                    vendor = "manual"
                    display_vendor = "manual"
                    from = $legacy.from
                    full = $legacy.full
                    source = "legacy-manual-dir"
                }
            }
        }
    }

    return ($items | Sort-Object vendor, from)
}

function Get-OverridesDirs {
    if (-not (Test-Path $OverridesDir)) {
        return @()
    }

    $items = New-Object System.Collections.Generic.List[object]
    $categories = @("custom", "patches", "resources")
    foreach ($category in $categories) {
        $categoryRoot = Join-Path $OverridesDir $category
        if (-not (Test-Path -LiteralPath $categoryRoot -PathType Container)) { continue }
        foreach ($directory in (Get-ChildItem -LiteralPath $categoryRoot -Directory -ErrorAction SilentlyContinue)) {
            $firstFile = Get-ChildItem -LiteralPath $directory.FullName -File -Recurse -Force -ErrorAction SilentlyContinue | Select-Object -First 1
            if ($null -eq $firstFile) { continue }
            $items.Add([pscustomobject]@{
                    Name = $directory.Name
                    FullName = $directory.FullName
                    override_category = $category
                }) | Out-Null
        }
    }

    foreach ($directory in (Get-ChildItem -LiteralPath $OverridesDir -Directory -ErrorAction SilentlyContinue)) {
        if ($directory.Name -eq ".bak" -or $categories -contains $directory.Name) { continue }
        $firstFile = Get-ChildItem -LiteralPath $directory.FullName -File -Recurse -Force -ErrorAction SilentlyContinue | Select-Object -First 1
        if ($null -eq $firstFile) { continue }
        $items.Add([pscustomobject]@{
                Name = $directory.Name
                FullName = $directory.FullName
                override_category = "legacy"
            }) | Out-Null
    }

    $resolved = @($items.ToArray() | Sort-Object Name)
    foreach ($group in @($resolved | Group-Object Name | Where-Object Count -gt 1)) {
        $locations = @($group.Group | ForEach-Object { "{0}:{1}" -f $_.override_category, $_.FullName }) -join ", "
        throw ("override output name is duplicated [{0}]: {1}" -f $group.Name, $locations)
    }
    return $resolved
}

function Resolve-OverrideDir([string]$overrideName) {
    if ([string]::IsNullOrWhiteSpace($overrideName)) { return $null }
    return @(Get-OverridesDirs | Where-Object { [string]::Equals($_.Name, $overrideName, [System.StringComparison]::OrdinalIgnoreCase) } | Select-Object -First 1)
}

function 收集OverridesSkills {
    $items = @()
    foreach ($d in (Get-OverridesDirs)) {
        $items += [pscustomobject]@{ vendor = "overrides"; from = $d.Name; full = $d.FullName }
    }
    return $items
}

function Get-InstalledSet($cfg, $manualItems = $null, $overrideItems = $null) {
    $installed = New-Object System.Collections.Generic.HashSet[string]
    foreach ($m in $cfg.mappings) {
        $installed.Add("$($m.vendor)|$($m.from)") | Out-Null
    }
    if ($null -eq $overrideItems) { $overrideItems = 收集OverridesSkills }
    foreach ($m in $overrideItems) {
        $installed.Add("overrides|$($m.from)") | Out-Null
    }
    return $installed
}

function Get-UniqueManualImportName($cfg, [string]$baseName, $reservedNames = $null) {
    $normalized = Normalize-NameWithNotice $baseName "manual 导入名称"
    if ($null -eq $reservedNames) {
        $reservedNames = New-Object System.Collections.Generic.HashSet[string]([System.StringComparer]::OrdinalIgnoreCase)
    }
    $existing = New-Object System.Collections.Generic.HashSet[string]([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($i in @($cfg.imports)) {
        if ($null -eq $i) { continue }
        $name = [string]$i.name
        if ([string]::IsNullOrWhiteSpace($name)) { continue }
        $existing.Add($name) | Out-Null
    }

    $candidate = $normalized
    $suffix = 2
    while ($existing.Contains($candidate) -or $reservedNames.Contains($candidate) -or (Test-Path (Join-Path $ImportDir $candidate))) {
        $candidate = ("{0}-{1}" -f $normalized, $suffix)
        $suffix++
    }
    $reservedNames.Add($candidate) | Out-Null
    return $candidate
}

function Convert-InstalledVendorSkillsToManual($cfg, $vendorItem) {
    Need ($null -ne $cfg) "转换失败：配置对象为空。"
    Need ($null -ne $vendorItem) "转换失败：vendor 项为空。"

    $vendorName = [string]$vendorItem.name
    $vendorRepo = [string]$vendorItem.repo
    $vendorRef = [string]$vendorItem.ref
    Need (-not [string]::IsNullOrWhiteSpace($vendorName)) "转换失败：vendor 缺少名称。"

    $vendorPath = VendorPath $vendorName
    $vendorMappings = @($cfg.mappings | Where-Object { $_.vendor -eq $vendorName -and (Normalize-SkillPath ([string]$_.from)) -ne "." })
    if ($vendorMappings.Count -eq 0) {
        return [pscustomobject]@{ converted = 0; skipped = 0 }
    }

    Need (Test-Path $vendorPath) ("转换失败：vendor 目录不存在：{0}" -f $vendorPath)
    EnsureDir $ImportDir
    $reservedNames = New-Object System.Collections.Generic.HashSet[string]([System.StringComparer]::OrdinalIgnoreCase)

    $converted = 0
    $skipped = 0
    foreach ($m in $vendorMappings) {
        $skillPath = Normalize-SkillPath ([string]$m.from)
        $src = Join-Path $vendorPath $skillPath
        if (-not (Test-IsSkillDir $src)) {
            Write-Host ("⚠️ 保留技能时跳过（源不存在或无技能标记）：vendor={0}, from={1}" -f $vendorName, $skillPath) -ForegroundColor Yellow
            $skipped++
            continue
        }

        $baseName = Split-Path $skillPath -Leaf
        if ([string]::IsNullOrWhiteSpace($baseName)) { $baseName = $vendorName }
        $manualName = Get-UniqueManualImportName $cfg $baseName $reservedNames
        $dst = Join-Path $ImportDir $manualName
        Invoke-WithRetry { Copy-Item -LiteralPath $src -Destination $dst -Recurse -Force } 3 250

        $manualImport = @{
            name = $manualName
            repo = $vendorRepo
            ref = $vendorRef
            skill = "."
            mode = "manual"
            sparse = $false
        }
        Upsert-Import $cfg $manualImport

        $cfg.mappings += @{
            vendor = "manual"
            from = $manualName
            to = [string]$m.to
        }
        $converted++
    }

    # Remove old vendor mappings now that manual mappings are created.
    $cfg.mappings = @($cfg.mappings | Where-Object { [string]$_.vendor -ne $vendorName })
    return [pscustomobject]@{ converted = $converted; skipped = $skipped }
}

function Hide-VendorRootSkills($items) {
    $arr = @($items)
    if ($arr.Count -eq 0) { return @() }

    $vendorsWithChildren = New-Object System.Collections.Generic.HashSet[string]
    foreach ($item in $arr) {
        if ($null -eq $item) { continue }
        $vendor = [string]$item.vendor
        $from = [string]$item.from
        if ([string]::IsNullOrWhiteSpace($vendor)) { continue }
        if ($from -ne ".") {
            $vendorsWithChildren.Add($vendor) | Out-Null
        }
    }

    if ($vendorsWithChildren.Count -eq 0) { return $arr }

    $filtered = @()
    foreach ($item in $arr) {
        if ($null -eq $item) { continue }
        $vendor = [string]$item.vendor
        $from = [string]$item.from
        if ($from -eq "." -and $vendorsWithChildren.Contains($vendor)) { continue }
        $filtered += $item
    }
    return $filtered
}

function Should-SyncMappingToAgent($mapping) {
    if ($null -eq $mapping) { return $false }
    $vendor = [string]$mapping.vendor
    $from = [string]$mapping.from
    # Vendor 根映射仅用于来源聚合与清单管理，不下发到各 CLI 用户级 skills 目录。
    if ($from -eq "." -and $vendor -ne "manual" -and $vendor -ne "overrides") { return $false }
    return $true
}

function Get-InvalidMappings($cfg = $null) {
    if ($null -eq $cfg) { $cfg = LoadCfg }
    $invalid = New-Object System.Collections.Generic.List[object]
    $mappings = @($cfg.mappings)
    $resolveContext = New-AgentMappingResolveContext
    for ($idx = 0; $idx -lt $mappings.Count; $idx++) {
        $m = $mappings[$idx]
        if ($null -eq $m) { continue }
        $vendor = [string]$m.vendor
        $from = [string]$m.from
        $to = [string]$m.to
        $src = $null
        $reason = $null
        try {
            $resolved = Resolve-AgentMappingForAgent $cfg $m $resolveContext
            if ($null -eq $resolved -or -not [bool]$resolved.sync) { continue }
            $vendor = [string]$resolved.vendor
            $from = [string]$resolved.from
            $to = [string]$resolved.to
            if (-not [bool]$resolved.source_valid) {
                $reason = [string]$resolved.reason
            }
            else {
                $src = [string]$resolved.src_full
                if (-not (Test-ResolvedAgentMappingSkillDir $resolved $resolveContext)) {
                    $reason = Get-ResolvedAgentMappingInvalidReason $resolved
                }
            }
        }
        catch {
            $reason = $_.Exception.Message
        }

        if ($reason -match "^非法 mapping\.from") { $reason = "非法 mapping.from" }
        elseif ($reason -match "^非法 mapping\.to") { $reason = "非法 mapping.to" }
        elseif ($reason -match "^manual 导入不存在或无效") { $reason = "manual 导入不存在或无效" }
        elseif ($reason -match "^mapping\.from 越界") { $reason = "mapping.from 越界" }

        if (-not [string]::IsNullOrWhiteSpace($reason)) {
            $invalid.Add([pscustomobject]@{
                    index = $idx
                    vendor = $vendor
                    from = $from
                    to = $to
                    src = [string]$src
                    reason = $reason
                }) | Out-Null
        }
    }
    return $invalid.ToArray()
}

function Parse-CleanupInvalidMappingsArgs([string[]]$tokens) {
    $result = [ordered]@{
        yes = $false
        no_build = $false
    }
    foreach ($t in @($tokens)) {
        if ([string]::IsNullOrWhiteSpace([string]$t)) { continue }
        switch (([string]$t).Trim().ToLowerInvariant()) {
            "--yes" { $result.yes = $true; continue }
            "--no-build" { $result.no_build = $true; continue }
            default { throw ("未知参数：{0}（支持 --yes, --no-build）" -f [string]$t) }
        }
    }
    return [pscustomobject]$result
}

function 清理无效映射([string[]]$tokens = @()) {
    $opts = Parse-CleanupInvalidMappingsArgs $tokens
    $cfg = LoadCfg
    $invalid = @(Get-InvalidMappings $cfg)
    if ($invalid.Count -eq 0) {
        Write-Host "未发现失效 mappings。"
        return
    }

    $preview = @()
    foreach ($item in $invalid) {
        $preview += ("[{0}] {1} -> {2} ({3})" -f [string]$item.vendor, [string]$item.from, [string]$item.to, [string]$item.reason)
    }
    if (-not $opts.yes) {
        if (-not (Confirm-WithSummary "将删除以下失效 mappings" $preview "确认删除并写回 skills.json？" "Y")) {
            Write-Host "已取消清理。"
            return
        }
    }

    if (Skip-IfDryRun "清理无效映射") {
        Write-Host ("DRYRUN：预计删除失效 mappings {0} 项。" -f $invalid.Count)
        return
    }

    $dropIndexes = New-Object System.Collections.Generic.HashSet[int]
    foreach ($item in $invalid) { $dropIndexes.Add([int]$item.index) | Out-Null }
    $nextMappings = @()
    $all = @($cfg.mappings)
    for ($i = 0; $i -lt $all.Count; $i++) {
        if ($dropIndexes.Contains($i)) { continue }
        $nextMappings += $all[$i]
    }
    $cfg.mappings = @($nextMappings)
    SaveCfg $cfg
    Clear-SkillsCache

    Write-Host ("已清理失效 mappings：{0} 项。" -f $invalid.Count) -ForegroundColor Green
    if (-not $opts.no_build) {
        Write-Host "开始【构建生效】..." -ForegroundColor Cyan
        构建生效
    }
}

function Remove-VendorRootMappingOutputsFromAgent($cfg) {
    if ($null -eq $cfg) { return 0 }
    $removed = 0
    foreach ($m in @($cfg.mappings)) {
        if ($null -eq $m) { continue }
        if (Should-SyncMappingToAgent $m) { continue }
        $to = [string]$m.to
        if ([string]::IsNullOrWhiteSpace($to)) { continue }
        $dst = Join-Path $AgentDir $to
        if (-not (Is-PathInsideOrEqual $dst $AgentDir)) { continue }
        if (Test-Path -LiteralPath $dst) {
            Invoke-RemoveItemWithRetry $dst -Recurse -IgnoreFailure | Out-Null
            $removed++
            Log ("已剔除 vendor 根映射产物：{0}" -f $to)
        }
    }
    return $removed
}

function Parse-IndexSelection([string]$selText, [int]$max) {
    if ($null -eq $selText) { return @() }
    $selText = $selText.Trim()
    if ([string]::IsNullOrWhiteSpace($selText)) { return @() }
    $low = $selText.ToLowerInvariant()
    if ($low -eq "all") { return 1..$max }
    if ($low -eq "0") { return @() }
    if ($low -eq "none") { return @() }

    # Normalize common non-ASCII separators/dashes from IME input.
    $selText = $selText -replace "[，、；;/;\\s]+", ","
    $selText = $selText -replace "[－–—−]", "-"

    $set = New-Object System.Collections.Generic.HashSet[int]
    foreach ($part in $selText.Split(",") | ForEach-Object { $_.Trim() }) {
        if ($part -match "^\d+$") {
            $n = [int]$part
            if ($n -ge 1 -and $n -le $max) { $set.Add($n) | Out-Null }
        }
        elseif ($part -match "^(\d+)-(\d+)$") {
            $a = [int]$Matches[1]; $b = [int]$Matches[2]
            if ($a -gt $b) { $tmp = $a; $a = $b; $b = $tmp }
            for ($i = $a; $i -le $b; $i++) {
                if ($i -ge 1 -and $i -le $max) { $set.Add($i) | Out-Null }
            }
        }
    }
    return $set | Sort-Object
}

function Write-SelectionHint {
    Write-Host ""
    Write-Host "输入多选：如 1,3,5-10；输入 all 全选；输入 0 取消。"
}

function Read-SelectionIndices([string]$prompt, [int]$count, [string]$invalidMsg) {
    $sel = Read-HostSafe $prompt
    $idx = Parse-IndexSelection $sel $count
    if ($idx.Count -eq 0 -and -not [string]::IsNullOrWhiteSpace($sel) -and $sel.ToLowerInvariant() -ne "0") {
        Write-Host $invalidMsg
        return [pscustomobject]@{ indices = @(); canceled = $false }
    }
    $canceled = -not [string]::IsNullOrWhiteSpace($sel) -and $sel.Trim().ToLowerInvariant() -eq "0"
    return [pscustomobject]@{ indices = $idx; canceled = $canceled }
}
function Select-Items($items, [scriptblock]$formatter, [string]$prompt, [string]$invalidMsg) {
    if ($items.Count -eq 0) { return [pscustomobject]@{ items = @(); canceled = $false } }
    Write-ItemsInColumns $items $formatter
    Write-SelectionHint
    $selection = Read-SelectionIndices $prompt $items.Count $invalidMsg
    if ($selection.canceled) { return [pscustomobject]@{ items = @(); canceled = $true } }
    $idx = $selection.indices
    if ($idx.Count -eq 0) { return [pscustomobject]@{ items = @(); canceled = $false } }
    $selected = @()
    foreach ($n in $idx) { $selected += $items[$n - 1] }
    return [pscustomobject]@{ items = $selected; canceled = $false }
}

function Get-SkillSelectionMatchKeys($item) {
    $keys = New-Object System.Collections.Generic.List[string]
    if ($null -eq $item) { return @() }

    foreach ($value in @(
            [string]$item.from,
            (Split-Path ([string]$item.from) -Leaf),
            ("{0}|{1}" -f [string]$item.vendor, [string]$item.from),
            (Make-TargetName ([string]$item.vendor) ([string]$item.from))
        )) {
        if (-not [string]::IsNullOrWhiteSpace($value)) {
            $keys.Add($value.Trim().ToLowerInvariant()) | Out-Null
        }
    }

    if ($item.PSObject.Properties.Match("to").Count -gt 0 -and -not [string]::IsNullOrWhiteSpace([string]$item.to)) {
        $keys.Add(([string]$item.to).Trim().ToLowerInvariant()) | Out-Null
    }
    if ($item.PSObject.Properties.Match("display_vendor").Count -gt 0 -and -not [string]::IsNullOrWhiteSpace([string]$item.display_vendor)) {
        $keys.Add(("{0}|{1}" -f [string]$item.display_vendor, [string]$item.from).Trim().ToLowerInvariant()) | Out-Null
    }

    return @($keys | Select-Object -Unique)
}

function Resolve-SkillSelectionFromTokens($items, [string[]]$selectionTokens, [string]$invalidMsg) {
    $items = @($items)
    $selectionTokens = @($selectionTokens | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
    if ($selectionTokens.Count -eq 0) {
        return [pscustomobject]@{ items = @(); canceled = $false }
    }

    $selected = @()
    $selectedKeys = New-Object System.Collections.Generic.HashSet[string]([System.StringComparer]::OrdinalIgnoreCase)
    $unmatched = New-Object System.Collections.Generic.List[string]
    $ambiguous = New-Object System.Collections.Generic.List[string]

    foreach ($token in $selectionTokens) {
        $text = ([string]$token).Trim()
        if ([string]::IsNullOrWhiteSpace($text)) { continue }
        if ($text.ToLowerInvariant() -eq "0") {
            return [pscustomobject]@{ items = @(); canceled = $true }
        }

        $indexSelection = Parse-IndexSelection $text $items.Count
        if ($indexSelection.Count -gt 0 -or $text.ToLowerInvariant() -eq "all") {
            foreach ($n in @($indexSelection)) {
                $item = $items[$n - 1]
                $key = "{0}|{1}" -f [string]$item.vendor, [string]$item.from
                if ($selectedKeys.Add($key)) { $selected += $item }
            }
            continue
        }

        $needle = $text.ToLowerInvariant()
        $matches = @($items | Where-Object {
                $keys = @(Get-SkillSelectionMatchKeys $_)
                $keys -contains $needle
            })

        if ($matches.Count -eq 0) {
            $unmatched.Add($text) | Out-Null
            continue
        }
        if ($matches.Count -gt 1) {
            $ambiguous.Add($text) | Out-Null
            continue
        }

        $match = $matches[0]
        $matchKey = "{0}|{1}" -f [string]$match.vendor, [string]$match.from
        if ($selectedKeys.Add($matchKey)) { $selected += $match }
    }

    if ($unmatched.Count -gt 0 -or $ambiguous.Count -gt 0) {
        if (-not [string]::IsNullOrWhiteSpace($invalidMsg)) { Write-Host $invalidMsg }
        if ($unmatched.Count -gt 0) {
            Write-Host ("未找到技能：{0}" -f (@($unmatched) -join ", "))
        }
        if ($ambiguous.Count -gt 0) {
            Write-Host ("技能选择不唯一，请使用 vendor|path 或序号：{0}" -f (@($ambiguous) -join ", "))
        }
        return [pscustomobject]@{ items = @(); canceled = $false }
    }

    return [pscustomobject]@{ items = @($selected); canceled = $false }
}

function Filter-Skills($items, [string]$filter) {
    if ([string]::IsNullOrWhiteSpace($filter)) { return $items }
    $f = $filter.Trim()
    if ($f.StartsWith("/") -and $f.EndsWith("/") -and $f.Length -gt 2) {
        $pattern = $f.Trim("/")
        try {
            return $items | Where-Object { $_.vendor -match $pattern -or $_.from -match $pattern }
        }
        catch {
            Write-Warning "无效的正则表达式：$pattern"
            return @()
        }
    }
    $terms = $f.Split(" ", [System.StringSplitOptions]::RemoveEmptyEntries)
    foreach ($t in $terms) {
        $safeT = [WildcardPattern]::Escape($t)
        $items = $items | Where-Object { $_.vendor -like "*$safeT*" -or $_.from -like "*$safeT*" }
    }
    return $items
}

function Write-ItemsInColumns($items, [scriptblock]$formatter) {
    $items = @($items)
    $count = $items.Count
    if ($count -eq 0) { return }
    $width = 120
    try { $width = [int]$Host.UI.RawUI.WindowSize.Width } catch {}
    $sample = @()
    for ($i = 0; $i -lt $count; $i++) {
        $sample += (& $formatter ($i + 1) $items[$i])
    }
    $maxLen = ($sample | Measure-Object -Maximum -Property Length).Maximum
    if (-not $maxLen) { $maxLen = 40 }
    $colWidth = $maxLen + 2
    $cols = [Math]::Max(1, [Math]::Floor($width / $colWidth))
    $rows = [Math]::Ceiling($count / $cols)
    for ($r = 0; $r -lt $rows; $r++) {
        for ($c = 0; $c -lt $cols; $c++) {
            $i = $r + ($c * $rows)
            if ($i -ge $count) { continue }
            $text = (& $formatter ($i + 1) $items[$i])
            $pad = " " * ($colWidth - $text.Length)
            Write-Host -NoNewline ($text + $pad)
        }
        Write-Host ""
    }
}

function Make-TargetName([string]$vendor, [string]$from) {
    $suffix = ($from -replace "[\\\\/]", "-")
    return ("{0}-{1}" -f $vendor, $suffix)
}

function 安装 {
    Preflight
    $cfg = LoadCfg
    $manualItems = 收集ManualSkills $cfg
    $filter = Read-Host "可选：关键词过滤（空格=AND，或 /regex/）"
    $all = 收集Skills "" $cfg $manualItems
    Need ($all.Count -gt 0) "未发现任何 skills。请先【新增技能库】。"
    $list = Hide-VendorRootSkills (Filter-Skills $all $filter)
    if ($list.Count -eq 0) {
        Write-Host "未发现匹配项。"
        return
    }
    $installed = Get-InstalledSet $cfg $manualItems

    $available = $list | Where-Object { -not $installed.Contains("$($_.vendor)|$($_.from)") }
    if ($available.Count -eq 0) {
        Write-Host "没有可安装的新技能。将直接执行【构建生效】。"
        构建生效
        return
    }

    $newMappings = @()
    foreach ($m in $cfg.mappings) { $newMappings += $m }
    $existing = New-Object System.Collections.Generic.HashSet[string]
    foreach ($m in $cfg.mappings) { $existing.Add("$($m.vendor)|$($m.from)") | Out-Null }
    $previewAdded = @()
    $previewMappings = @()

    $added = 0
    $selection = Select-Items $available `
    { param($idx, $item)
        $displayVendor = Get-DisplayVendor $item
        $leaf = Split-Path $item.from -Leaf
        if ($item.from -eq ".") { $leaf = $displayVendor }
        return ("{0,3}) [{1}] {2}" -f $idx, $displayVendor, $leaf)
    } `
        "请选择要安装的技能（批量安装到白名单）" `
        "未解析到有效序号（可能是分隔符或范围格式问题）。已取消写入白名单。"
    if ($selection.canceled) {
        Write-Host "已取消安装。"
        return
    }
    $selected = $selection.items
    if ($selected.Count -eq 0) {
        Write-Host "未选择新增技能。将直接执行【构建生效】。"
        构建生效
        return
    }

    foreach ($item in $selected) {
        $key = "$($item.vendor)|$($item.from)"
        if ($existing.Contains($key)) { continue }
        $to = Make-TargetName $item.vendor $item.from

        $newMappings += @{ vendor = $item.vendor; from = $item.from; to = $to }
        $existing.Add($key) | Out-Null
        $added++
        $previewItem = [ordered]@{ vendor = $item.vendor; from = $item.from; to = $to }
        if ($item.PSObject.Properties.Match("display_vendor").Count -gt 0) {
            $previewItem.display_vendor = [string]$item.display_vendor
        }
        $previewMappings += [pscustomobject]$previewItem
    }

    if ($added -eq 0) {
        Write-Host "未新增任何技能。将直接执行【构建生效】。"
        构建生效
        return
    }

    $previewAdded = Format-MappingPreview $previewMappings
    if (-not (Confirm-WithSummary "将新增以下白名单映射" $previewAdded "确认写入白名单并构建生效？" "Y")) {
        Write-Host "已取消安装。"
        return
    }
    if (Skip-IfDryRun "安装技能") { return }

    $cfg.mappings = $newMappings
    SaveCfg $cfg

    Write-Host ("已追加安装：{0} 项。开始【构建生效】..." -f $added)
    构建生效
}

function 卸载([string[]]$tokens = @()) {
    Preflight
    $cfg = LoadCfg
    $manualItems = 收集ManualSkills $cfg
    $overrideItems = 收集OverridesSkills
    $tokenList = @($tokens | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
    $assumeYes = $false
    $selectionTokens = New-Object System.Collections.Generic.List[string]
    $filter = ""
    for ($i = 0; $i -lt $tokenList.Count; $i++) {
        $t = [string]$tokenList[$i]
        $lower = $t.Trim().ToLowerInvariant()
        if ($lower -eq "--yes" -or $lower -eq "-y") {
            $assumeYes = $true
            continue
        }
        if ($lower -eq "--filter") {
            Need ($i + 1 -lt $tokenList.Count) "--filter 缺少值"
            $filter = [string]$tokenList[++$i]
            continue
        }
        if ($lower.StartsWith("--filter=")) {
            $filter = $t.Substring("--filter=".Length)
            continue
        }
        $selectionTokens.Add($t) | Out-Null
    }
    if ($selectionTokens.Count -eq 0) {
        $filter = Read-Host "可选：关键词过滤（空格=AND，或 /regex/）"
    }

    # 卸载范围：已映射技能 + overrides
    $installedSet = Get-InstalledSet $cfg $manualItems $overrideItems
    $all = 收集Skills "" $cfg $manualItems
    Need ($all.Count -gt 0) "未发现任何 skills。请先【新增技能库】。"
    $list = Filter-Skills $all $filter
    if ($list.Count -eq 0) {
        Write-Host "未发现匹配项。"
        return
    }

    # 筛选已安装的技能
    $onlyInstalled = $list | Where-Object { $installedSet.Contains("$($_.vendor)|$($_.from)") }
    $onlyInstalled = Hide-VendorRootSkills $onlyInstalled
    if ($onlyInstalled.Count -eq 0) {
        Write-Host "没有已安装的技能可卸载。"
        return
    }

    $formatter = { param($idx, $item)
        $label = Get-DisplayVendor $item
        $leaf = Split-Path $item.from -Leaf
        if ($item.from -eq ".") { $leaf = $label }
        return ("{0,3}) [{1}] {2}" -f $idx, $label, $leaf)
    }
    $selection = if ($selectionTokens.Count -gt 0) {
        Resolve-SkillSelectionFromTokens $onlyInstalled @($selectionTokens) "未解析到有效技能选择。已取消操作。"
    }
    else {
        Select-Items $onlyInstalled `
            $formatter `
            "请选择要卸载的技能（从白名单移除）" `
            "未解析到有效序号（可能是分隔符或范围格式问题）。已取消操作。"
    }
    if ($selection.canceled) {
        Write-Host "已取消卸载。"
        return
    }
    $selectedItems = $selection.items
    if ($selectedItems.Count -eq 0) {
        Write-Host "未选择任何技能。"
        return
    }

    # 区分处理：vendor 移除白名单；manual 删除 imports 条目（兼容清理 legacy manual 目录）；overrides 备份后删除
    $preview = Format-SkillPreview $selectedItems
    if (-not $assumeYes -and -not (Confirm-WithSummary "将卸载以下技能" $preview "确认卸载所选技能？" "Y")) {
        Write-Host "已取消卸载。"
        return
    }
    if (Skip-IfDryRun "卸载技能") { return }

    $removedMappings = 0
    $removedVendorImports = 0
    $deletedManualImports = 0
    $deletedLegacyManualDirs = 0
    $deletedOverrides = 0
    $backedOverrides = 0
    foreach ($item in $selectedItems) {
        if ($item.vendor -eq "manual") {
            $before = @($cfg.imports).Count
            $cfg.imports = @($cfg.imports | Where-Object { -not ($_.mode -eq "manual" -and $_.name -eq $item.from) })
            $deletedManualImports += ($before - @($cfg.imports).Count)

            $legacyPath = Join-Path $ManualDir $item.from
            if (Test-Path $legacyPath) {
                Invoke-RemoveItem $legacyPath -Recurse
                $deletedLegacyManualDirs++
            }
            $cfg.mappings = @($cfg.mappings | Where-Object { -not ("$($_.vendor)|$($_.from)" -eq "manual|$($item.from)") })
        }
        elseif ($item.vendor -eq "overrides") {
            $bak = Backup-OverrideDir $item.from
            if ($bak) { $backedOverrides++ }
            $deletedOverrides++
        }
        else {
            # mapping 技能：从 mappings 移除
            $cfg.mappings = @($cfg.mappings | Where-Object { -not ("$($_.vendor)|$($_.from)" -eq "$($item.vendor)|$($item.from)") })
            $removedMappings++

            $skillPath = Normalize-SkillPath ([string]$item.from)
            $hasSameMapping = @($cfg.mappings | Where-Object { $_.vendor -eq $item.vendor -and $_.from -eq $skillPath }).Count -gt 0
            if (-not $hasSameMapping) {
                $beforeImports = @($cfg.imports).Count
                $cfg.imports = @($cfg.imports | Where-Object {
                        $mode = if ($_.PSObject.Properties.Match("mode").Count -gt 0) { [string]$_.mode } else { "manual" }
                        if ($mode -ne "vendor") { return $true }
                        if ([string]$_.name -ne [string]$item.vendor) { return $true }
                        $importSkill = Normalize-SkillPath ([string]$_.skill)
                        return ($importSkill -ne $skillPath)
                    })
                $removedVendorImports += ($beforeImports - @($cfg.imports).Count)
            }
        }
    }

    SaveCfg $cfg
    $parts = @()
    if ($removedMappings -gt 0) { $parts += "移除白名单 $removedMappings 项" }
    if ($removedVendorImports -gt 0) { $parts += "删除 vendor 导入 $removedVendorImports 项" }
    if ($deletedManualImports -gt 0) { $parts += "删除 manual 导入 $deletedManualImports 项" }
    if ($deletedLegacyManualDirs -gt 0) { $parts += "清理 legacy manual 目录 $deletedLegacyManualDirs 项" }
    if ($deletedOverrides -gt 0) { $parts += "删除 overrides $deletedOverrides 项（已备份 $backedOverrides 项）" }
    Write-Host ("已完成：{0}。开始【构建生效】..." -f ($parts -join "，"))
    if ($backedOverrides -gt 0) {
        Write-Host "提示：overrides 备份已保存到 overrides/.bak/，如需彻底清理可手动删除该目录或其中备份。"
    }
    Clear-SkillsCache
    构建生效
}

function 选择 {
    Write-Host "提示：已改为独立【安装/卸载】菜单。"
    安装
}


function 发现 {
    Invoke-WithMetric "discover" {
        Preflight
        $cfg = LoadCfg
        $manualItems = 收集ManualSkills $cfg
        $f = $Filter
        if ([string]::IsNullOrWhiteSpace($f)) {
            $f = Read-Host "可选：关键词过滤（空格=AND，或 /regex/）"
        }
        $all = 收集Skills "" $cfg $manualItems
        Need ($all.Count -gt 0) "未发现任何 skills。请先【新增技能库】。"
        $list = Hide-VendorRootSkills (Filter-Skills $all $f)
        if ($list.Count -eq 0) {
            Write-Host "未发现匹配项。"
            return
        }
        $installed = Get-InstalledSet $cfg $manualItems
        Write-ItemsInColumns $list { param($idx, $item)
            $mark = if ($installed.Contains("$($item.vendor)|$($item.from)")) { "*" } else { " " }
            $displayVendor = Get-DisplayVendor $item
            $leaf = Split-Path $item.from -Leaf
            if ($item.from -eq ".") { $leaf = $displayVendor }
            return ("{0,3}) [{1}] [{2}] {3}" -f $idx, $mark, $displayVendor, $leaf)
        }
    } @{ command = "发现" } -NoHost
}

function 清空Agent目录 {
    if (Test-PathEntry $AgentDir) {
        Invoke-RemoveItemWithRetry $AgentDir -Recurse | Out-Null
    }
    EnsureDir $AgentDir
}

function Resolve-SourceBase([string]$vendorName, $cfg) {
    if ($vendorName -eq "manual") { return $null }
    $v = $cfg.vendors | Where-Object { $_.name -eq $vendorName } | Select-Object -First 1
    if (-not $v) { throw "白名单引用了不存在的 vendor：$vendorName" }
    return (VendorPath $v.name)
}

function Get-BuildCachePath {
    return (Join-Path $Root ".build-cache.json")
}

function ConvertTo-Hashtable($obj) {
    $table = @{}
    if ($null -eq $obj) { return $table }
    if ($obj -is [hashtable]) { return $obj }
    if ($obj -is [pscustomobject]) {
        foreach ($p in $obj.PSObject.Properties) { $table[[string]$p.Name] = $p.Value }
    }
    return $table
}

function Load-BuildCache {
    $path = Get-BuildCachePath
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { return @{} }
    try {
        $raw = Get-Content -LiteralPath $path -Raw
        if ([string]::IsNullOrWhiteSpace($raw)) { return @{} }
        $obj = $raw | ConvertFrom-Json
        return (ConvertTo-Hashtable $obj)
    }
    catch {
        Log ("构建缓存读取失败，已忽略并重建：{0}" -f $_.Exception.Message) "WARN"
        return @{}
    }
}

function Save-BuildCache($cache) {
    if ($DryRun) { return }
    try {
        $json = $cache | ConvertTo-Json -Depth 20
        Set-ContentUtf8 (Get-BuildCachePath) $json
    }
    catch {
        Log ("构建缓存保存失败（已忽略）：{0}" -f $_.Exception.Message) "WARN"
    }
}

function Get-DirectoryFingerprint([string]$dir) {
    if (-not (Test-Path -LiteralPath $dir -PathType Container)) { return "missing" }
    $input = ""
    if ($null -ne [type]::GetType("System.IO.EnumerationOptions", $false)) {
        $baseDir = [System.IO.Path]::GetFullPath($dir)
        $baseWithSeparator = $baseDir
        if (-not ($baseWithSeparator.EndsWith("\") -or $baseWithSeparator.EndsWith("/"))) {
            $baseWithSeparator += [System.IO.Path]::DirectorySeparatorChar
        }

        $options = [System.IO.EnumerationOptions]::new()
        $options.RecurseSubdirectories = $true
        $options.IgnoreInaccessible = $true
        $options.AttributesToSkip = [System.IO.FileAttributes]::Hidden -bor [System.IO.FileAttributes]::System

        $files = [System.IO.Directory]::GetFiles($baseDir, "*", $options)
        [array]::Sort($files, [System.StringComparer]::OrdinalIgnoreCase)

        $parts = [System.Text.StringBuilder]::new()
        $first = $true
        foreach ($file in $files) {
            $info = [System.IO.FileInfo]::new($file)
            $rel = if ($file.StartsWith($baseWithSeparator, [System.StringComparison]::OrdinalIgnoreCase)) {
                $file.Substring($baseWithSeparator.Length)
            }
            else {
                $info.Name
            }
            if (-not $first) { [void]$parts.Append("`n") }
            [void]$parts.AppendFormat("{0}|{1}|{2}", $rel, [string]$info.Length, [string]$info.LastWriteTimeUtc.Ticks)
            $first = $false
        }
        $input = $parts.ToString()
    }
    else {
        $files = Get-ChildItem -LiteralPath $dir -Recurse -File -ErrorAction SilentlyContinue | Sort-Object FullName
        $parts = New-Object System.Collections.Generic.List[string]
        foreach ($f in $files) {
            $rel = $f.FullName.Substring($dir.Length).TrimStart("\")
            $parts.Add(("{0}|{1}|{2}" -f $rel, [string]$f.Length, [string]$f.LastWriteTimeUtc.Ticks)) | Out-Null
        }
        $input = $parts -join "`n"
    }
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try {
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($input)
        $hash = $sha.ComputeHash($bytes)
        return ([System.BitConverter]::ToString($hash) -replace "-", "").ToLowerInvariant()
    }
    finally {
        $sha.Dispose()
    }
}

function Mirror-SkillWithCache(
    [string]$src,
    [string]$dst,
    [string]$cacheKey,
    [hashtable]$oldCache,
    [hashtable]$newCache,
    $stats,
    [hashtable]$fingerprintCache = $null,
    [switch]$ForceMirror
) {
    if ($null -eq $fingerprintCache) { $fingerprintCache = @{} }
    if ($null -ne $stats -and $stats.PSObject.Properties.Match("fp_cache_hit").Count -eq 0) {
        $stats | Add-Member -NotePropertyName fp_cache_hit -NotePropertyValue 0
    }
    if ($null -ne $stats -and $stats.PSObject.Properties.Match("fp_cache_miss").Count -eq 0) {
        $stats | Add-Member -NotePropertyName fp_cache_miss -NotePropertyValue 0
    }
    $dstExists = (Test-Path -LiteralPath $dst -PathType Container)
    if (-not $dstExists) {
        # The destination is guaranteed to be rebuilt in this pass, so fingerprint
        # calculation cannot lead to a cache skip. Mirror directly to reduce build cost.
        RoboMirror $src $dst
        $expanded = Expand-RelativeSkillPlaceholders $dst
        if ($expanded -gt 0) {
            Log ("已展开相对路径 SKILL 占位文件：{0} 项 [{1}]" -f $expanded, $cacheKey)
        }
        $stats.mirrored++
        return
    }
    $srcKey = [System.IO.Path]::GetFullPath($src).ToLowerInvariant()
    if ($fingerprintCache.ContainsKey($srcKey)) {
        $fp = [string]$fingerprintCache[$srcKey]
        if ($null -ne $stats) { $stats.fp_cache_hit++ }
    }
    else {
        $fp = Get-DirectoryFingerprint $src
        $fingerprintCache[$srcKey] = $fp
        if ($null -ne $stats) { $stats.fp_cache_miss++ }
    }
    $newCache[$cacheKey] = $fp
    $old = if ($oldCache.ContainsKey($cacheKey)) { [string]$oldCache[$cacheKey] } else { "" }
    if ($dstExists -and -not $ForceMirror -and $old -eq $fp) {
        $expanded = Expand-RelativeSkillPlaceholders $dst
        if ($expanded -gt 0) {
            Log ("命中构建缓存后补展开相对路径 SKILL 占位文件：{0} 项 [{1}]" -f $expanded, $cacheKey)
        }
        $stats.skipped++
        Log ("命中构建缓存，跳过复制：{0}" -f $cacheKey)
        return
    }
    RoboMirror $src $dst
     $expanded = Expand-RelativeSkillPlaceholders $dst
    if ($expanded -gt 0) {
        Log ("已展开相对路径 SKILL 占位文件：{0} 项 [{1}]" -f $expanded, $cacheKey)
    }
    $stats.mirrored++
}

function Get-SkillNameConflictBuckets([string]$agentRoot) {
    $nameToPaths = @{}
    foreach ($skillFile in (Get-ChildItem $agentRoot -Recurse -Filter "SKILL.md" -File -ErrorAction SilentlyContinue)) {
        $declaredName = $null
        foreach ($line in (Get-Content $skillFile.FullName -TotalCount 80 -ErrorAction SilentlyContinue)) {
            if ($line -match "^\s*name:\s*(.+?)\s*$") {
                $declaredName = $Matches[1].Trim().Trim("'`"")
                break
            }
        }
        if ([string]::IsNullOrWhiteSpace($declaredName)) { continue }
        if (-not $nameToPaths.ContainsKey($declaredName)) {
            $nameToPaths[$declaredName] = New-Object System.Collections.Generic.List[string]
        }
        $nameToPaths[$declaredName].Add($skillFile.FullName) | Out-Null
    }
    return $nameToPaths
}

function Test-SkillNameDuplicateContentAllowed([string[]]$paths) {
    if ($null -eq $paths -or $paths.Count -le 1) { return $true }
    $hashes = New-Object System.Collections.Generic.HashSet[string]
    foreach ($path in $paths) {
        $hash = Get-FileContentHash $path
        if ([string]::IsNullOrWhiteSpace($hash)) { return $false }
        $hashes.Add($hash) | Out-Null
    }
    return ($hashes.Count -le 1)
}

function Test-SkillNameSystemOverrideAllowed([string[]]$paths) {
    if ($null -eq $paths -or $paths.Count -le 1) { return $false }
    $hasSystemPath = $false
    $hasNonSystemPath = $false
    foreach ($path in $paths) {
        if ([string]::IsNullOrWhiteSpace($path)) { continue }
        if ($path -match "[\\/]\.system[\\/]") { $hasSystemPath = $true }
        else { $hasNonSystemPath = $true }
    }
    return ($hasSystemPath -and $hasNonSystemPath)
}
function Should-SkipBuildPostScan($stats) {
    if ($null -eq $stats) { return $false }
    return (($stats.mirrored -eq 0) -and (-not [bool]$stats.reused))
}
function Get-ElapsedMs($sw) {
    if ($null -eq $sw) { return 0 }
    return [int][math]::Round([double]$sw.Elapsed.TotalMilliseconds, 0)
}
function Get-AgentBuildCacheAlgorithmVersion {
    return "agent-build-v20260803.3"
}
function Get-AgentBuildMetricName([bool]$cacheHit) {
    if ($cacheHit) { return "build_agent_cache_hit" }
    return "build_agent_full"
}
function Get-StringSha256([string]$text) {
    if ($null -eq $text) { $text = "" }
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try {
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($text)
        $hash = $sha.ComputeHash($bytes)
        return ([System.BitConverter]::ToString($hash) -replace "-", "").ToLowerInvariant()
    }
    finally {
        $sha.Dispose()
    }
}
function New-AgentMappingResolveContext {
    return @{
        vendor_base = @{}
        manual_source = @{}
        skill_dir_validity = @{}
    }
}
function Resolve-AgentMappingForAgent($cfg, $mapping, [hashtable]$context) {
    if ($null -eq $mapping) { return $null }
    if ($null -eq $context) { $context = New-AgentMappingResolveContext }

    $vendor = [string]$mapping.vendor
    $from = [string]$mapping.from
    $to = [string]$mapping.to
    if (-not (Should-SyncMappingToAgent $mapping)) {
        return [pscustomobject]@{
            sync = $false
            vendor = $vendor
            from = $from
            to = $to
        }
    }

    Need (Test-SafeRelativePath $from -AllowDot) ("非法 mapping.from：{0}" -f $from)
    Need (Test-SafeRelativePath $to) ("非法 mapping.to：{0}" -f $to)

    $src = $null
    if ($vendor -eq "manual") {
        $manualSourceCache = [hashtable]$context["manual_source"]
        if ($manualSourceCache.ContainsKey($from)) {
            $src = [string]$manualSourceCache[$from]
        }
        else {
            $src = [string](Resolve-ManualImportSkillPath $cfg $from -AllowLegacyFallback)
            $manualSourceCache[$from] = $src
        }
        if ([string]::IsNullOrWhiteSpace($src)) {
            return [pscustomobject]@{
                sync = $true
                source_valid = $false
                reason = ("manual 导入不存在或无效：{0}" -f $from)
                vendor = $vendor
                from = $from
                to = $to
            }
        }
    }
    else {
        $vendorBaseCache = [hashtable]$context["vendor_base"]
        if ($vendorBaseCache.ContainsKey($vendor)) {
            $base = [string]$vendorBaseCache[$vendor]
        }
        else {
            $base = [string](Resolve-SourceBase $vendor $cfg)
            $vendorBaseCache[$vendor] = $base
        }
        $src = Join-Path $base $from
        Need (Is-PathInsideOrEqual $src $base) ("mapping.from 越界：{0}" -f $from)
    }

    $dst = Join-Path $AgentDir $to
    Need (Is-PathInsideOrEqual $dst $AgentDir) ("mapping.to 越界：{0}" -f $to)

    $srcFull = [System.IO.Path]::GetFullPath($src)
    $outRel = Normalize-SkillPath $to
    return [pscustomobject]@{
        sync = $true
        source_valid = $true
        vendor = $vendor
        from = $from
        to = $to
        out_rel = $outRel
        src = [string]$src
        src_full = $srcFull
        src_key = $srcFull.ToLowerInvariant()
        dst = $dst
        cache_key = ("mapping|{0}|{1}|{2}" -f $vendor, $from, $to)
    }
}
function Test-ResolvedAgentMappingSkillDir($resolved, [hashtable]$context) {
    if ($null -eq $resolved -or -not [bool]$resolved.sync -or -not [bool]$resolved.source_valid) { return $false }
    if ($null -eq $context) { $context = New-AgentMappingResolveContext }

    $skillDirValidityCache = [hashtable]$context["skill_dir_validity"]
    $srcKey = [string]$resolved.src_key
    if ($skillDirValidityCache.ContainsKey($srcKey)) {
        return [bool]$skillDirValidityCache[$srcKey]
    }

    $isSkillDir = Test-IsSkillDir ([string]$resolved.src_full)
    $skillDirValidityCache[$srcKey] = $isSkillDir
    return $isSkillDir
}
function Get-ResolvedAgentMappingInvalidReason($resolved) {
    $src = if ($null -ne $resolved -and $resolved.PSObject.Properties.Match("src_full").Count -gt 0) { [string]$resolved.src_full } else { "" }
    if (-not (Test-Path -LiteralPath $src -PathType Container)) { return "源目录不存在" }
    return "缺少标记文件"
}
function Get-AgentBuildState($cfg) {
    $records = New-Object System.Collections.Generic.List[object]
    $outputs = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $resolveContext = New-AgentMappingResolveContext
    $fingerprintCache = @{}
    $index = 0

    foreach ($m in @($cfg.mappings)) {
        $resolved = Resolve-AgentMappingForAgent $cfg $m $resolveContext
        if ($null -eq $resolved) { continue }
        if (-not [bool]$resolved.sync) {
            $records.Add([ordered]@{
                    index = $index
                    kind = "mapping"
                    sync = $false
                    vendor = [string]$resolved.vendor
                    from = [string]$resolved.from
                    to = [string]$resolved.to
                }) | Out-Null
            $index++
            continue
        }

        if (-not [bool]$resolved.source_valid) {
            return [pscustomobject]@{ can_skip = $false; reason = [string]$resolved.reason; signature = $null; outputs = @() }
        }
        if (-not (Test-ResolvedAgentMappingSkillDir $resolved $resolveContext)) {
            $reason = Get-ResolvedAgentMappingInvalidReason $resolved
            return [pscustomobject]@{ can_skip = $false; reason = ("{0}: {1}" -f $reason, [string]$resolved.src_full); signature = $null; outputs = @() }
        }
        $srcKey = [string]$resolved.src_key
        if ($fingerprintCache.ContainsKey($srcKey)) {
            $fp = [string]$fingerprintCache[$srcKey]
        }
        else {
            $fp = Get-DirectoryFingerprint ([string]$resolved.src_full)
            $fingerprintCache[$srcKey] = $fp
        }
        $outRel = [string]$resolved.out_rel
        $outputs.Add($outRel) | Out-Null
        $records.Add([ordered]@{
                index = $index
                kind = "mapping"
                sync = $true
                vendor = [string]$resolved.vendor
                from = [string]$resolved.from
                to = $outRel
                source = $srcKey
                fingerprint = $fp
            }) | Out-Null
        $index++
    }

    foreach ($d in (Get-OverridesDirs | Sort-Object Name)) {
        $srcFull = [System.IO.Path]::GetFullPath($d.FullName)
        $srcKey = $srcFull.ToLowerInvariant()
        if ($fingerprintCache.ContainsKey($srcKey)) {
            $fp = [string]$fingerprintCache[$srcKey]
        }
        else {
            $fp = Get-DirectoryFingerprint $srcFull
            $fingerprintCache[$srcKey] = $fp
        }
        $outputs.Add([string]$d.Name) | Out-Null
        $records.Add([ordered]@{
                index = $index
                kind = "override"
                name = [string]$d.Name
                to = [string]$d.Name
                source = $srcKey
                fingerprint = $fp
            }) | Out-Null
        $index++
    }

    $recordList = $records.ToArray()
    $outputList = @($outputs | Sort-Object)
    $payload = [ordered]@{
        schema = 1
        algorithm = (Get-AgentBuildCacheAlgorithmVersion)
        records = $recordList
        outputs = $outputList
    }
    $json = $payload | ConvertTo-Json -Depth 30 -Compress
    return [pscustomobject]@{
        can_skip = $true
        reason = "ok"
        signature = (Get-StringSha256 $json)
        outputs = $outputList
    }
}
function Set-AgentBuildStateCache($cache, $cfg) {
    try {
        $state = Get-AgentBuildState $cfg
        if (-not $state.can_skip) { return $state }
        $cache["__agent_build_algorithm"] = (Get-AgentBuildCacheAlgorithmVersion)
        $cache["__agent_build_signature"] = [string]$state.signature
        $cache["__agent_build_output_count"] = @($state.outputs).Count
        $cache["__agent_build_output_fingerprint"] = Get-DirectoryFingerprint $AgentDir
        $cache["__agent_build_saved_at"] = (Get-Date -Format "yyyy-MM-dd HH:mm:ss")
        return $state
    }
    catch {
        Log ("构建快路径状态写入失败，已忽略：{0}" -f $_.Exception.Message) "WARN"
        return [pscustomobject]@{ can_skip = $false; reason = $_.Exception.Message; signature = $null; outputs = @() }
    }
}
function Test-AgentBuildCacheHit($cfg) {
    if ($DryRun) { return [pscustomobject]@{ hit = $false; reason = "dry-run"; state = $null } }
    if (-not (Test-Path -LiteralPath $AgentDir -PathType Container)) {
        return [pscustomobject]@{ hit = $false; reason = "agent-missing"; state = $null }
    }
    $cache = Load-BuildCache
    $algorithm = [string]$cache["__agent_build_algorithm"]
    $signature = [string]$cache["__agent_build_signature"]
    $outputFingerprint = [string]$cache["__agent_build_output_fingerprint"]
    if ($algorithm -ne (Get-AgentBuildCacheAlgorithmVersion)) {
        return [pscustomobject]@{ hit = $false; reason = "algorithm-mismatch"; state = $null }
    }
    if ([string]::IsNullOrWhiteSpace($signature)) {
        return [pscustomobject]@{ hit = $false; reason = "signature-missing"; state = $null }
    }
    try {
        $state = Get-AgentBuildState $cfg
        if (-not $state.can_skip) {
            return [pscustomobject]@{ hit = $false; reason = $state.reason; state = $state }
        }
        if ([string]$state.signature -ne $signature) {
            return [pscustomobject]@{ hit = $false; reason = "signature-mismatch"; state = $state }
        }
        foreach ($rel in @($state.outputs)) {
            $outPath = Join-Path $AgentDir $rel
            if (-not (Test-Path -LiteralPath $outPath -PathType Container)) {
                return [pscustomobject]@{ hit = $false; reason = ("output-missing:{0}" -f $rel); state = $state }
            }
        }
        $expectedTopLevels = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($rel in @($state.outputs)) {
            $normalized = Normalize-SkillPath ([string]$rel)
            $topLevel = @($normalized -split "\\", 2)[0]
            if (-not [string]::IsNullOrWhiteSpace($topLevel) -and $topLevel -ne ".") {
                $expectedTopLevels.Add($topLevel) | Out-Null
            }
        }
        foreach ($dir in @(Get-ChildItem -LiteralPath $AgentDir -Directory -Force | Sort-Object Name)) {
            if (-not $expectedTopLevels.Contains([string]$dir.Name)) {
                return [pscustomobject]@{ hit = $false; reason = ("unexpected-output:{0}" -f $dir.Name); state = $state }
            }
        }
        if ([string]::IsNullOrWhiteSpace($outputFingerprint)) {
            return [pscustomobject]@{ hit = $false; reason = "output-fingerprint-missing"; state = $state }
        }
        if ((Get-DirectoryFingerprint $AgentDir) -ne $outputFingerprint) {
            return [pscustomobject]@{ hit = $false; reason = "output-fingerprint-mismatch"; state = $state }
        }
        return [pscustomobject]@{ hit = $true; reason = "cache-hit"; state = $state }
    }
    catch {
        return [pscustomobject]@{ hit = $false; reason = $_.Exception.Message; state = $null }
    }
}
function Invoke-AgentBuildCacheHit($cacheHit) {
    return (Invoke-WithMetric (Get-AgentBuildMetricName $true) {
        $state = $cacheHit.state
        $signature = [string]$state.signature
        $shortSignature = if ($signature.Length -gt 12) { $signature.Substring(0, 12) } else { $signature }
        Log ("构建 Agent 输入未变化，跳过重建：outputs={0}, signature={1}" -f @($state.outputs).Count, $shortSignature)
        return @()
    } @{ command = "构建Agent"; cache_hit = $true } -NoHost)
}
function Get-DuplicateMappingSourceGroups($cfg) {
    $groups = @{}
    if ($null -eq $cfg -or $null -eq $cfg.mappings) { return @() }
    foreach ($m in @($cfg.mappings)) {
        if ($null -eq $m) { continue }
        if (-not (Should-SyncMappingToAgent $m)) { continue }
        $key = ("{0}|{1}" -f [string]$m.vendor, [string]$m.from).ToLowerInvariant()
        if (-not $groups.ContainsKey($key)) {
            $groups[$key] = New-Object System.Collections.Generic.List[object]
        }
        $groups[$key].Add($m) | Out-Null
    }
    return @($groups.GetEnumerator() | Where-Object { $_.Value.Count -gt 1 })
}

function Start-BuildTransaction {
    $txnRoot = Join-Path $Root ".txn"
    $txnId = [Guid]::NewGuid().ToString("N").Substring(0, 10)
    $path = Join-Path $txnRoot ("build-{0}" -f $txnId)
    $backupAgent = Join-Path $path "agent.backup"
    $buildCachePath = Get-BuildCachePath
    $backupBuildCache = Join-Path $path "build-cache.backup.json"
    $state = [ordered]@{
        path = $path
        backup_agent = $backupAgent
        has_backup_agent = $false
        build_cache_path = $buildCachePath
        backup_build_cache = $backupBuildCache
        had_build_cache = $false
        has_backup_build_cache = $false
        build_cache_backup_error = $null
        backup_error = $null
    }
    if ($DryRun) { return [pscustomobject]$state }
    EnsureDir $txnRoot
    EnsureDir $path
    if (Test-Path -LiteralPath $buildCachePath -PathType Leaf) {
        $state.had_build_cache = $true
        try {
            Copy-Item -LiteralPath $buildCachePath -Destination $backupBuildCache -Force
            $state.has_backup_build_cache = $true
        }
        catch {
            $state.build_cache_backup_error = $_.Exception.Message
            Log ("构建缓存无法备份；若事务回滚，将删除缓存并强制下次重建：{0}" -f $_.Exception.Message) "WARN"
        }
    }
    if (Test-Path $AgentDir) {
        try {
            Invoke-MoveItem $AgentDir $backupAgent
            $state.has_backup_agent = $true
        }
        catch {
            if (Test-Path $backupAgent) { Invoke-RemoveItemWithRetry $backupAgent -Recurse -IgnoreFailure -SilentIgnore | Out-Null }
            $state.backup_error = $_.Exception.Message
            Log ("旧 agent/ 无法挪入事务备份，后续将直接在原目录上构建：{0}" -f $_.Exception.Message)
        }
    }
    return [pscustomobject]$state
}

function Rollback-BuildTransaction($txn) {
    if ($DryRun -or $null -eq $txn) { return }
    try {
        if (Test-Path $AgentDir) { Invoke-RemoveItemWithRetry $AgentDir -Recurse -IgnoreFailure -SilentIgnore | Out-Null }
        if ($txn.has_backup_agent -and (Test-Path $txn.backup_agent)) {
            Invoke-MoveItem $txn.backup_agent $AgentDir
            Write-Host "已回滚 agent/ 到构建前状态。" -ForegroundColor Yellow
        }
        if ($txn.had_build_cache -and $txn.has_backup_build_cache -and (Test-Path -LiteralPath $txn.backup_build_cache -PathType Leaf)) {
            Copy-Item -LiteralPath $txn.backup_build_cache -Destination $txn.build_cache_path -Force
            Write-Host "已回滚构建缓存到构建前状态。" -ForegroundColor Yellow
        }
        elseif (Test-Path -LiteralPath $txn.build_cache_path -PathType Leaf) {
            Invoke-RemoveItemWithRetry $txn.build_cache_path -IgnoreFailure -SilentIgnore | Out-Null
            Write-Host "已清除本次构建缓存，下一次将强制重建。" -ForegroundColor Yellow
        }
    }
    finally {
        if (Test-Path $txn.path) { Invoke-RemoveItemWithRetry $txn.path -Recurse -IgnoreFailure -SilentIgnore | Out-Null }
    }
}

function Complete-BuildTransaction($txn) {
    if ($DryRun -or $null -eq $txn) { return }
    if (Test-Path $txn.path) { Invoke-RemoveItemWithRetry $txn.path -Recurse -IgnoreFailure -SilentIgnore | Out-Null }
}

function 构建Agent($cfg = $null, [switch]$SkipPreflight, $Txn = $null) {
    return (Invoke-WithMetric (Get-AgentBuildMetricName $false) {
        if (-not $SkipPreflight) { Preflight }
        if ($null -eq $cfg) { $cfg = LoadCfg }
        Log "开始构建 Agent..."
        $reusedExistingAgent = $false
        $cleanAgentError = $null
        try {
            清空Agent目录
        }
        catch {
            $reusedExistingAgent = $true
            $cleanAgentError = $_.Exception.Message
            EnsureDir $AgentDir
            Log ("清空 agent/ 失败，将在现有目录上继续覆盖构建：{0}" -f $_.Exception.Message)
        }
        $failures = New-Object System.Collections.Generic.List[string]
        $invalidMappings = New-Object System.Collections.Generic.List[object]
        if ($null -ne $Txn -and $Txn.PSObject.Properties.Match("backup_error").Count -gt 0 -and -not [string]::IsNullOrWhiteSpace($Txn.backup_error)) {
            $failures.Add(("build-txn:agent-backup => {0}" -f $Txn.backup_error)) | Out-Null
        }
        $stats = [pscustomobject]@{ mirrored = 0; skipped = 0; reused = $reusedExistingAgent }
        $oldCache = if ($DryRun) { @{} } else { Load-BuildCache }
        $newCache = @{}
        $fingerprintCache = @{}
        $resolveContext = New-AgentMappingResolveContext

        $swMapping = [System.Diagnostics.Stopwatch]::StartNew()
        foreach ($m in $cfg.mappings) {
            try {
                $resolved = Resolve-AgentMappingForAgent $cfg $m $resolveContext
                if ($null -eq $resolved) { continue }
                if (-not [bool]$resolved.sync) {
                    Log ("跳过 vendor 根映射（不参与同步）：{0}/{1}" -f [string]$resolved.vendor, [string]$resolved.from)
                    continue
                }

                if (-not [bool]$resolved.source_valid) {
                    $invalidMappings.Add([pscustomobject]@{
                            vendor = [string]$resolved.vendor
                            from = [string]$resolved.from
                            to = [string]$resolved.to
                            src = ""
                            reason = [string]$resolved.reason
                        }) | Out-Null
                    continue
                }
                if (-not (Test-ResolvedAgentMappingSkillDir $resolved $resolveContext)) {
                    $invalidReason = Get-ResolvedAgentMappingInvalidReason $resolved
                    Write-Host ("⚠️ 跳过无效技能（{0}）：{1}" -f $invalidReason, [string]$resolved.src_full) -ForegroundColor Yellow
                    $invalidMappings.Add([pscustomobject]@{
                            vendor = [string]$resolved.vendor
                            from = [string]$resolved.from
                            to = [string]$resolved.to
                            src = [string]$resolved.src_full
                            reason = $invalidReason
                        }) | Out-Null
                    continue
                }
                Mirror-SkillWithCache ([string]$resolved.src_full) ([string]$resolved.dst) ([string]$resolved.cache_key) $oldCache $newCache $stats $fingerprintCache
            }
            catch {
                Write-Host ("❌ 处理技能失败 [{0}/{1}]: {2}" -f $m.vendor, $m.from, $_.Exception.Message) -ForegroundColor Red
                $failures.Add(("mapping:{0}/{1} => {2}" -f $m.vendor, $m.from, $_.Exception.Message)) | Out-Null
            }
        }

        $manualItems = 收集ManualSkills $cfg
        if ($manualItems.Count -gt 0) {
            $manualMapped = New-Object System.Collections.Generic.HashSet[string]
            foreach ($m in @($cfg.mappings)) {
                if ($m.vendor -eq "manual") { $manualMapped.Add([string]$m.from) | Out-Null }
            }
            $unmappedManual = @($manualItems | Where-Object { -not $manualMapped.Contains([string]$_.from) })
            if ($unmappedManual.Count -gt 0) {
                Log ("检测到 {0} 个 manual imports 未映射；按白名单策略不会进入 agent（可通过【安装】写入 mapping 后生效）。" -f $unmappedManual.Count) "WARN"
            }
        }
        $swMapping.Stop()
        $stats | Add-Member -NotePropertyName phase_ms_mapping -NotePropertyValue (Get-ElapsedMs $swMapping) -Force

        # overrides 覆盖层（可选）：同名目录将覆盖 agent 中对应技能
        $swOverrides = [System.Diagnostics.Stopwatch]::StartNew()
        foreach ($d in (Get-OverridesDirs)) {
            try {
                $dst = Join-Path $AgentDir $d.Name
                $cacheKey = ("override|{0}" -f $d.Name)
                # A clean agent build recreates mapping destinations before this
                # phase. Never let a stale override cache entry skip the
                # replacement that must win over that freshly mirrored output.
                Mirror-SkillWithCache $d.FullName $dst $cacheKey $oldCache $newCache $stats $fingerprintCache -ForceMirror
                Log ("应用覆盖层: {0}" -f $d.Name)
            }
            catch {
                Write-Host ("❌ 应用覆盖层失败 [{0}]: {1}" -f $d.Name, $_.Exception.Message) -ForegroundColor Red
                $failures.Add(("override:{0} => {1}" -f $d.Name, $_.Exception.Message)) | Out-Null
            }
        }
        $swOverrides.Stop()
        $stats | Add-Member -NotePropertyName phase_ms_overrides -NotePropertyValue (Get-ElapsedMs $swOverrides) -Force

        $swPostScan = [System.Diagnostics.Stopwatch]::StartNew()
        $removedVendorRoots = Remove-VendorRootMappingOutputsFromAgent $cfg
        if ($removedVendorRoots -gt 0) {
            Log ("已剔除 {0} 个 vendor 根映射目录（不参与同步）。" -f $removedVendorRoots)
        }

        if (Should-SkipBuildPostScan $stats) {
            Log "增量构建无新复制内容，跳过 SKILL.md 归一化/清理与冲突扫描。"
        }
        else {
            $normalizedSkillMd = Normalize-SkillMarkdownFiles $AgentDir
            if ($normalizedSkillMd.normalized -gt 0) {
                Log ("已归一化 SKILL.md 编码（移除 UTF-8 BOM）：{0} 项" -f $normalizedSkillMd.normalized)
            }
            if ($normalizedSkillMd.failed -gt 0) {
                foreach ($path in $normalizedSkillMd.failed_paths) {
                    $failures.Add(("build-skill-md-normalize:{0}" -f $path)) | Out-Null
                }
            }

            $invalidSkillCleanup = Remove-InvalidSkillMarkdownFiles $AgentDir
            if ($invalidSkillCleanup.removed -gt 0) {
                Log ("已清理无效 SKILL.md（缺少 YAML frontmatter）：{0} 项" -f $invalidSkillCleanup.removed) "WARN"
            }
            if ($invalidSkillCleanup.failed -gt 0) {
                foreach ($path in $invalidSkillCleanup.failed_paths) {
                    $failures.Add(("build-invalid-skill-md-cleanup:{0}" -f $path)) | Out-Null
                }
            }

            $nameToPaths = Get-SkillNameConflictBuckets $AgentDir
            foreach ($name in $nameToPaths.Keys | Sort-Object) {
                $paths = @($nameToPaths[$name])
                if ($paths.Count -le 1) { continue }
                if (Test-SkillNameDuplicateContentAllowed $paths) {
                    Log ("检测到同名同内容技能别名，已跳过冲突：{0}" -f $name)
                    continue
                }
                if (Test-SkillNameSystemOverrideAllowed $paths) {
                    Log ("检测到系统技能与普通技能同名，已保留系统技能优先：{0}" -f $name)
                    continue
                }
                Write-Host ("❌ 技能名冲突：{0}" -f $name) -ForegroundColor Red
                foreach ($p in $paths) {
                    Write-Host ("   - {0}" -f $p) -ForegroundColor Red
                }
                $failures.Add(("skill-name-conflict:{0} => {1}" -f $name, ($paths -join " | "))) | Out-Null
            }
        }
        $swPostScan.Stop()
        $stats | Add-Member -NotePropertyName phase_ms_postscan -NotePropertyValue (Get-ElapsedMs $swPostScan) -Force

        if (-not $DryRun) {
            if ($failures.Count -eq 0 -and -not $stats.reused) {
                Set-AgentBuildStateCache $newCache $cfg | Out-Null
            }
            Save-BuildCache $newCache
        }
        if ($stats.skipped -gt 0) {
            Log ("增量构建：复用缓存 {0} 项，实际复制 {1} 项。" -f $stats.skipped, $stats.mirrored)
        }
        if (($stats.fp_cache_hit -gt 0) -or ($stats.fp_cache_miss -gt 0)) {
            $fpTotal = [double]($stats.fp_cache_hit + $stats.fp_cache_miss)
            $hitRate = if ($fpTotal -le 0) { 0.0 } else { [math]::Round((100.0 * [double]$stats.fp_cache_hit / $fpTotal), 1) }
            Log ("目录指纹缓存：hit={0}, miss={1}, hit_rate={2}%" -f $stats.fp_cache_hit, $stats.fp_cache_miss, $hitRate)
        }
        $dupGroups = @(Get-DuplicateMappingSourceGroups $cfg)
        if ($dupGroups.Count -gt 0) {
            Log ("检测到重复源目录映射组：{0}（建议合并配置以提升构建命中率）" -f $dupGroups.Count) "WARN"
        }
        Log ("构建阶段耗时：mapping={0}ms, overrides={1}ms, postscan={2}ms" -f $stats.phase_ms_mapping, $stats.phase_ms_overrides, $stats.phase_ms_postscan)
        if ($stats.reused) {
            Log "本次构建未能清空旧 agent/，已按目录增量覆盖；若仍有陈旧技能残留，可在释放相关文件占用后重试。"
            Write-Host "❌ 检测到在旧 agent/ 上增量覆盖构建，已升级为失败。" -ForegroundColor Red
            Write-Host "   建议：先执行【解除关联】并关闭占用进程，再重试【构建生效】。" -ForegroundColor Red
            if ([string]::IsNullOrWhiteSpace($cleanAgentError)) { $cleanAgentError = "unknown error" }
            $failures.Add(("build-agent-reused-existing-dir => {0}" -f $cleanAgentError)) | Out-Null
        }
        if ($invalidMappings.Count -gt 0) {
            Log ("检测到 {0} 条失效 mappings（源目录不存在或缺少标记文件），建议清理 skills.json。" -f $invalidMappings.Count) "WARN"
            Write-Host ("⚠️ 检测到 {0} 条失效 mappings（未参与同步）。" -f $invalidMappings.Count) -ForegroundColor Yellow
            $preview = @($invalidMappings | Select-Object -First 10)
            foreach ($item in $preview) {
                Write-Host ("   - [{0}] {1} -> {2} ({3})" -f [string]$item.vendor, [string]$item.from, [string]$item.to, [string]$item.reason) -ForegroundColor Yellow
            }
            if ($invalidMappings.Count -gt $preview.Count) {
                Write-Host ("   ... 另有 {0} 条未显示" -f ($invalidMappings.Count - $preview.Count)) -ForegroundColor Yellow
            }
            Write-Host "   建议：删除上述 mappings 后再执行【构建生效】。" -ForegroundColor Yellow
        }
        $count = @((Get-ChildItem -LiteralPath $AgentDir -Directory -ErrorAction SilentlyContinue)).Count
        Log ("构建完成：agent/ (共 {0} 项技能)" -f $count)
        return $failures.ToArray()
    } @{ command = "构建Agent" } -NoHost)
}

function Resolve-TargetDir([string]$path) {
    if ([string]::IsNullOrWhiteSpace($path)) { return $null }
    if ($path.StartsWith("~")) {
        $homeDir = [Environment]::GetFolderPath("UserProfile")
        $path = $path -replace "^~", $homeDir
    }
    # Normalize slashes for Windows CMD compatibility
    $path = $path.Replace("/", "\")
  
    if ([System.IO.Path]::IsPathRooted($path)) {
        return $path
    }
    return (Join-Path $Root $path)
}

function 应用到ClaudeCodex($cfg = $null, [switch]$SkipPreflight, [string]$VerifiedAgentBuildSignature = "", $PromotionContext = $null) {
    return (Invoke-WithMetric "apply_targets" {
        if (-not $SkipPreflight) { Preflight }
        if ($null -eq $cfg) { $cfg = LoadCfg }
        $mode = $cfg.sync_mode
        if ([string]::IsNullOrWhiteSpace($mode)) { $mode = "link" }
        $failures = New-Object System.Collections.Generic.List[string]

        Invoke-WithMetric "apply_target_links" {
            foreach ($t in $cfg.targets) {
                try {
                    $target = Resolve-TargetDir $t.path
                    if (-not $target) { continue }
                    Assert-SafeTargetDir $target

                    if ($mode -eq "sync") {
                        EnsureDir $target
                        RoboMirror $AgentDir $target
                        Log ("已同步（拷贝）：{0}" -f $t.path)
                    }
                    else {
                        New-Junction $target $AgentDir
                        Log ("已关联（链接）：{0} -> agent/" -f $t.path)
                    }
                }
                catch {
                    Write-Host ("❌ 同步目标失败 [{0}]: {1}" -f $t.path, $_.Exception.Message) -ForegroundColor Red
                    $failures.Add(("target:{0} => {1}" -f $t.path, $_.Exception.Message)) | Out-Null
                }
            }
        } @{ command = "应用到ClaudeCodex"; target_count = @($cfg.targets).Count } -NoHost | Out-Null
        try {
            $projectionResult = Sync-ConfiguredSkillProjection $cfg $VerifiedAgentBuildSignature $PromotionContext
            if ($projectionResult -and -not [bool]$projectionResult.skipped) {
                $plan = $projectionResult.plan
                Log ("技能投影已生成：entries={0}, unique={1}, disabled={2}, conflicts={3}, persisted={4}" -f @($plan.skills).Count, @($plan.unique_names).Count, @($plan.disabled).Count, @($plan.conflicts).Count, [bool]$projectionResult.persisted)
                if ([bool]$projectionResult.reconciliation.signal_updated) {
                    Log ("技能清单已变化，宿主 AI 应在任务边界执行 profile reconciliation：{0}" -f [string]$projectionResult.reconciliation.signal_path) "WARN"
                }
            }
        }
        catch {
            Write-Host ("❌ 同步技能投影失败：{0}" -f $_.Exception.Message) -ForegroundColor Red
            $failures.Add(("skill-projection => {0}" -f $_.Exception.Message)) | Out-Null
        }
        return $failures.ToArray()
    } @{ command = "应用到ClaudeCodex" } -NoHost)
}
function Write-FailureSummary([string]$title, [string[]]$failures, [string]$detailHint = "") {
    if ($null -eq $failures -or $failures.Count -eq 0) { return }
    $msg = ("{0}（{1} 项）" -f $title, $failures.Count)
    if (-not [string]::IsNullOrWhiteSpace($detailHint)) {
        $msg = ("{0}，{1}" -f $msg, $detailHint)
    }
    Write-Host $msg -ForegroundColor Yellow
    foreach ($f in ($failures | Select-Object -First 10)) {
        Write-Host ("- {0}" -f $f) -ForegroundColor Yellow
    }
    if ($failures.Count -gt 10) {
        Write-Host ("... 另有 {0} 项未显示" -f ($failures.Count - 10)) -ForegroundColor Yellow
    }
}

function 构建生效([switch]$AllowUnverifiedProjection = $AllowUnverifiedHostProjection) {
    Invoke-WithMetric "build_apply_total" {
        Preflight
        Invoke-PrebuildCheck
        $cfg = LoadCfg
        if ($Locked) {
            Ensure-LockedState $cfg | Out-Null
        }
        $txn = $null
        $needRollback = $false
        $promotionBlocked = $false

        # Optimization/Migration check
        $cfgRawBeforeOptimize = if (Test-Path $CfgPath) { Get-Content $CfgPath -Raw } else { "" }
        Optimize-Imports $cfg
        $optChanges = Get-CfgChangeSummaryLines $cfgRawBeforeOptimize $cfg
        if (@($optChanges).Count -gt 0) {
            SaveCfg $cfg
            Log ("已写回自动迁移配置：{0}" -f ($optChanges -join "; ")) "WARN"
        }

        Write-BuildSummary $cfg
        Log "=== 启动构建生效流程 ==="
        $agentBuildCacheHit = Invoke-WithMetric "build_agent_cache_check" {
            Test-AgentBuildCacheHit $cfg
        } @{ command = "构建Agent" } -NoHost
        if (-not $agentBuildCacheHit.hit) {
            $txn = Start-BuildTransaction
        }
        Start-DryRunMirrorCollect
        try {
            $failures = @()
            if ($agentBuildCacheHit.hit) {
                $buildFailures = Invoke-AgentBuildCacheHit $agentBuildCacheHit
            }
            else {
                $buildFailures = 构建Agent $cfg -SkipPreflight -Txn $txn
            }
            if ($buildFailures) { $failures += $buildFailures }
            if ($buildFailures -and @($buildFailures).Count -gt 0) {
                Log "检测到构建失败，已跳过同步阶段。" "WARN"
                Write-Host "⚠️ 构建失败，未执行同步。请先修复上方错误后重试【构建生效】。" -ForegroundColor Yellow
            }
            else {
                $verifiedAgentBuildSignature = if ($agentBuildCacheHit.hit) {
                    [string]$agentBuildCacheHit.state.signature
                }
                else {
                    [string](Load-BuildCache)["__agent_build_signature"]
                }
                $promotionContext = $null
                try {
                    $promotionContext = Get-HostProjectionPromotionContext $cfg -AllowUnverified:$AllowUnverifiedProjection
                }
                catch {
                    $promotionBlocked = $true
                    $failures += ("host-projection-promotion => {0}" -f $_.Exception.Message)
                    Log ("宿主投影晋级已阻断：{0}" -f $_.Exception.Message) "ERROR"
                    Write-Host "⚠️ agent/ staging 已保留，但未写入任何仓库外宿主目标。提交并验证当前 revision 后可重新执行构建生效。" -ForegroundColor Yellow
                }
                if (@($failures).Count -eq 0) {
                    $syncFailures = 应用到ClaudeCodex $cfg -SkipPreflight -VerifiedAgentBuildSignature $verifiedAgentBuildSignature -PromotionContext $promotionContext
                    if ($syncFailures) { $failures += $syncFailures }
                }
            }
            Write-FailureSummary "构建生效部分失败" $failures
            if ($failures.Count -gt 0 -and -not $promotionBlocked) { $needRollback = $true }
            Write-DryRunMirrorSummary "DRYRUN Robocopy 预览（构建生效）"
        }
        finally {
            Stop-DryRunMirrorCollect
        }
        if ($needRollback) {
            if ($null -ne $txn) { Rollback-BuildTransaction $txn }
            Write-Host "⚠️ 已回滚本次构建产物（agent/）。同步目标可能仍需手动重建。" -ForegroundColor Yellow
        }
        else {
            if ($null -ne $txn) { Complete-BuildTransaction $txn }
        }
        Log "=== 构建生效流程完成 ==="
        if (@($failures).Count -gt 0) {
            throw ("构建生效失败（{0} 项）：{1}" -f @($failures).Count, [string]@($failures)[0])
        }
    } @{ command = "构建生效" } -NoHost
}

function 命令导入安装 {
    Write-Host "可一次性粘贴一条或多条命令，空行结束。示例："
    Write-Host "  add <repo> [--skill <name>] [--ref <branch/tag>] [--mode manual|vendor] [--sparse]"
    Write-Host "  npx skills add <repo> [--skill <name>] [--ref <branch/tag>] [--mode manual|vendor] [--sparse]"
    Write-Host "说明："
    Write-Host "  - 支持连续粘贴多条 add / npx skills add / npx add-skill 命令"
    Write-Host "  - 未指定 --skill 时：仅新增技能库（vendor），不自动安装仓库内技能"
    Write-Host "  - 行尾用 \\ 可续行，脚本会自动拼接为一条命令"
    $lines = New-Object System.Collections.Generic.List[string]
    while ($true) {
        $line = Read-Host "输入命令"
        if ([string]::IsNullOrWhiteSpace($line)) { break }
        $trim = $line.Trim()
        if ($trim.StartsWith("#") -or $trim.StartsWith("//")) { continue }
        $lines.Add($line) | Out-Null
    }
    if ($lines.Count -eq 0) {
        Write-Host "未输入参数，已取消。"
        return
    }

    $commands = New-Object System.Collections.Generic.List[string]
    $pending = ""
    foreach ($raw in $lines) {
        $part = [string]$raw
        $trimmed = $part.TrimEnd()
        $continued = $trimmed.EndsWith("\")
        if ($continued) {
            $trimmed = $trimmed.Substring(0, $trimmed.Length - 1).TrimEnd()
        }
        if ([string]::IsNullOrWhiteSpace($pending)) { $pending = $trimmed }
        else { $pending = ("{0} {1}" -f $pending, $trimmed).Trim() }
        if (-not $continued) {
            if (-not [string]::IsNullOrWhiteSpace($pending)) { $commands.Add($pending) | Out-Null }
            $pending = ""
        }
    }
    if (-not [string]::IsNullOrWhiteSpace($pending)) {
        Write-Host "警告：检测到末行续行符 '\\'，已按当前内容尝试执行。" -ForegroundColor Yellow
        $commands.Add($pending) | Out-Null
    }

    $successCount = 0
    foreach ($line in $commands) {
        if ([string]::IsNullOrWhiteSpace($line)) { continue }
        $lineTrim = $line.Trim()
        if ($lineTrim.StartsWith("#") -or $lineTrim.StartsWith("//")) { continue }
        $tokens = Split-Args $line
        if ($tokens.Count -eq 0) { continue }
        try {
            $tokens = Get-AddTokensFromCommandLineTokens $tokens
            if ($tokens.Count -eq 0) { continue }
            if (Add-ImportFromArgs $tokens -NoBuild) { $successCount++ }
        }
        catch {
            Write-Host ("❌ 解析失败（已跳过）：{0}" -f $_.Exception.Message) -ForegroundColor Red
            if ($line -match "^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+@.+$") {
                Write-Host "提示：你可能使用了 repo@skill 语法。可改为：npx ""skills add <repo> --skill <path>""" -ForegroundColor Yellow
            }
        }
    }
    if ($successCount -gt 0) {
        Write-Host ("多行导入完成：{0} 项。开始【构建生效】..." -f $successCount)
        Clear-SkillsCache
        构建生效
    }
}

function Should-ForceCleanTarget($cfg, $SkipForceClean, [string]$kind, [string]$name) {
    if ($null -eq $cfg -or -not $cfg.update_force) { return $false }
    if ($null -eq $SkipForceClean) { return $true }
    $key = "{0}|{1}" -f $kind, $name
    return (-not $SkipForceClean.ContainsKey($key))
}

function Get-UpdateRepoCount($cfg) {
    if ($null -eq $cfg) { return 0 }
    $keys = New-Object System.Collections.Generic.HashSet[string]
    foreach ($v in @($cfg.vendors)) {
        if ($null -eq $v) { continue }
        $repoKey = Get-RepoIdentityKey ([string]$v.repo)
        if ([string]::IsNullOrWhiteSpace($repoKey)) { continue }
        $keys.Add($repoKey) | Out-Null
    }
    foreach ($i in @($cfg.imports)) {
        if ($null -eq $i -or $i.mode -ne "manual") { continue }
        $repoKey = Get-RepoIdentityKey ([string]$i.repo)
        if ([string]::IsNullOrWhiteSpace($repoKey)) { continue }
        $keys.Add($repoKey) | Out-Null
    }
    return $keys.Count
}

function Get-UpdateParallelism($cfg) {
    $n = $null
    $hasConfigured = ($null -ne $cfg -and $cfg.PSObject.Properties.Match("update_parallelism").Count -gt 0)
    if ($hasConfigured) {
        try { $n = [int]$cfg.update_parallelism } catch { $n = 1 }
    }
    else {
        $repoCount = Get-UpdateRepoCount $cfg
        if ($repoCount -le 1) { return 1 }
        $cpu = 2
        try { $cpu = [Environment]::ProcessorCount } catch {}
        if ($cpu -lt 2) { $cpu = 2 }
        $n = [Math]::Min(8, $cpu)
        if ($n -gt $repoCount) { $n = $repoCount }
    }
    if ($n -lt 1) { $n = 1 }
    return $n
}

function Test-WindowsInvalidPathIssue([string]$message) {
    if ([string]::IsNullOrWhiteSpace($message)) { return $false }
    if ($message -notmatch "invalid path") { return $false }
    return ($message -match "git\s+(pull|checkout|reset)")
}

function Get-UpdatePrefetchTimeoutSeconds {
    $defaultSeconds = 120
    $raw = [Environment]::GetEnvironmentVariable("SKILLS_UPDATE_PREFETCH_TIMEOUT_SECONDS")
    if ([string]::IsNullOrWhiteSpace($raw)) { return $defaultSeconds }
    try {
        $n = [int]$raw
    }
    catch {
        return $defaultSeconds
    }
    if ($n -lt 1) { return 1 }
    if ($n -gt 1800) { return 1800 }
    return $n
}

function Invoke-ImportArchiveFallback(
    [string]$cache,
    [string]$repo,
    [string]$ref,
    [string]$skillPath,
    [bool]$forceClean,
    [string]$archiveSuccessMessage,
    [string]$snapshotSuccessMessage,
    [string]$failurePrefix,
    [string]$failureDetailPrefix = ""
) {
    try {
        Ensure-RepoFromGitArchive $cache $repo $ref $skillPath $forceClean | Out-Null
        Log $archiveSuccessMessage "WARN"
        return
    }
    catch {
        $archiveError = $_.Exception.Message
        try {
            Ensure-RepoFromGitHubTreeSnapshot $cache $repo $ref $skillPath $forceClean | Out-Null
            Log $snapshotSuccessMessage "WARN"
            return
        }
        catch {
            $snapshotError = $_.Exception.Message
            throw ("{0}{1}archive={2} | snapshot={3}" -f $failurePrefix, $failureDetailPrefix, $archiveError, $snapshotError)
        }
    }
}

function Invoke-ParallelGitPrefetch($cfg, [int]$Parallelism = 1) {
    if ($DryRun) { return $false }
    if ($Parallelism -le 1) { return $false }
    if (-not (Get-Command Start-Job -ErrorAction SilentlyContinue)) { return $false }
    if ($null -eq $cfg) { return $false }

    $paths = New-Object System.Collections.Generic.List[string]
    foreach ($v in @($cfg.vendors)) {
        $p = VendorPath $v.name
        if (Test-Path $p) { $paths.Add($p) | Out-Null }
    }
    foreach ($i in @($cfg.imports)) {
        if ($i.mode -ne "manual") { continue }
        $p = Join-Path $ImportDir $i.name
        if (Test-Path $p) { $paths.Add($p) | Out-Null }
    }
    $paths = @($paths | Select-Object -Unique | Where-Object { Test-IsGitRepoRoot ([string]$_) })
    if ($paths.Count -eq 0) { return $false }

    $running = @()
    $errors = New-Object System.Collections.Generic.List[string]
    $timeoutSeconds = Get-UpdatePrefetchTimeoutSeconds
    foreach ($p in $paths) {
        while (@($running).Count -ge $Parallelism) {
            $runningIds = @($running | ForEach-Object { [int]$_.Id })
            $done = Wait-Job -Id $runningIds -Any -Timeout $timeoutSeconds
            if ($null -eq $done) {
                foreach ($stuck in @($running)) {
                    Stop-Job -Id ([int]$stuck.Id) -ErrorAction SilentlyContinue
                    Remove-Job -Id ([int]$stuck.Id) -Force -ErrorAction SilentlyContinue
                }
                $errors.Add(("prefetch timeout after {0}s" -f $timeoutSeconds)) | Out-Null
                return $false
            }
            $output = Receive-Job -Id ([int]$done.Id) -ErrorAction SilentlyContinue
            Remove-Job -Id ([int]$done.Id) -Force -ErrorAction SilentlyContinue
            $running = @($running | Where-Object { $_.Id -ne $done.Id })
            if ($output -and $output.ok -eq $false) { $errors.Add([string]$output.msg) | Out-Null }
        }
        $job = Start-Job -ScriptBlock {
            param($repoPath)
            try {
                $prevErrorActionPreference = $ErrorActionPreference
                try {
                    $ErrorActionPreference = "Continue"
                    & git -C $repoPath fetch --all --tags 2>$null | Out-Null
                }
                finally {
                    $ErrorActionPreference = $prevErrorActionPreference
                }
                if ($LASTEXITCODE -ne 0) {
                    return [pscustomobject]@{ ok = $false; msg = ("prefetch failed: {0}" -f $repoPath) }
                }
                return [pscustomobject]@{ ok = $true; msg = "" }
            }
            catch {
                return [pscustomobject]@{ ok = $false; msg = ("prefetch exception: {0} -> {1}" -f $repoPath, $_.Exception.Message) }
            }
        } -ArgumentList $p
        $running += $job
    }
    foreach ($j in @($running)) {
        $done = Wait-Job -Id ([int]$j.Id) -Timeout $timeoutSeconds
        if ($null -eq $done) {
            Stop-Job -Id ([int]$j.Id) -ErrorAction SilentlyContinue
            Remove-Job -Id ([int]$j.Id) -Force -ErrorAction SilentlyContinue
            $errors.Add(("prefetch timeout after {0}s: {1}" -f $timeoutSeconds, [string]$j.Name)) | Out-Null
            continue
        }
        $output = Receive-Job -Id ([int]$j.Id) -ErrorAction SilentlyContinue
        Remove-Job -Id ([int]$j.Id) -Force -ErrorAction SilentlyContinue
        if ($output -and $output.ok -eq $false) { $errors.Add([string]$output.msg) | Out-Null }
    }
    if ($errors.Count -gt 0) {
        Log ("并行预取完成（部分失败 {0} 项，后续将按原流程继续）。" -f $errors.Count) "WARN"
        return $false
    }
    else {
        Log ("并行预取完成：{0} 个仓库路径（并发={1}）。" -f $paths.Count, $Parallelism)
        return $true
    }
}

function Get-CurrentRepoCommit([string]$path) {
    if ([string]::IsNullOrWhiteSpace($path)) { return $null }
    if (-not (Test-Path $path)) { return $null }
    if (-not (Test-IsGitRepoRoot $path)) {
        return (Get-ImportSourceMetadataCommit $path)
    }
    Push-Location $path
    try {
        return (Invoke-GitCapture @("rev-parse", "HEAD"))
    }
    finally { Pop-Location }
}

function Get-ImportSourceMetadataPath([string]$path) {
    if ([string]::IsNullOrWhiteSpace($path)) { return $null }
    return (Join-Path $path ".skills-manager-source.json")
}

function Get-ImportSourceMetadataCommit([string]$path) {
    $metadataPath = Get-ImportSourceMetadataPath $path
    if ([string]::IsNullOrWhiteSpace($metadataPath)) { return $null }
    if (-not (Test-Path -LiteralPath $metadataPath -PathType Leaf)) { return $null }
    try {
        $data = Get-Content -LiteralPath $metadataPath -Raw | ConvertFrom-Json
        $commit = [string]$data.commit
        if ([string]::IsNullOrWhiteSpace($commit)) { return $null }
        return $commit
    }
    catch {
        return $null
    }
}

function Write-ImportSourceMetadata([string]$path, [string]$repo, [string]$ref, [string]$commit, [string]$sourceKind) {
    if ([string]::IsNullOrWhiteSpace($path)) { return }
    if (-not (Test-Path -LiteralPath $path -PathType Container)) { return }
    if ([string]::IsNullOrWhiteSpace($commit)) { return }
    $metadataPath = Get-ImportSourceMetadataPath $path
    $payload = [ordered]@{
        schema_version = 1
        source_kind = if ([string]::IsNullOrWhiteSpace($sourceKind)) { "archive" } else { $sourceKind }
        repo = $repo
        ref = $ref
        commit = $commit
        updated_at = (Get-Date).ToString("o")
    }
    Set-ContentUtf8 $metadataPath ($payload | ConvertTo-Json -Depth 6)
}

function Remove-ImportSourceMetadata([string]$path) {
    $metadataPath = Get-ImportSourceMetadataPath $path
    if ([string]::IsNullOrWhiteSpace($metadataPath)) { return }
    if (Test-Path -LiteralPath $metadataPath -PathType Leaf) {
        Remove-Item -LiteralPath $metadataPath -Force
    }
}

function Resolve-RemoteCommit([string]$repo, [string]$ref) {
    if ([string]::IsNullOrWhiteSpace($repo)) { return $null }
    if (Test-LocalZipRepoInput $repo) {
        return ("zip:{0}" -f (Get-FileContentHash $repo))
    }
    $targetRef = if ([string]::IsNullOrWhiteSpace($ref)) { "main" } else { $ref }
    if ($targetRef -match "^[0-9a-fA-F]{40}$") { return $targetRef }
    if ($targetRef -eq "HEAD" -or $targetRef -match "^refs/") {
        $candidates = @($targetRef)
    }
    else {
        $candidates = @(
            ("refs/heads/{0}" -f $targetRef),
            ("refs/tags/{0}^{{}}" -f $targetRef),
            ("refs/tags/{0}" -f $targetRef),
            $targetRef
        )
    }
    foreach ($candidate in $candidates) {
        $line = Invoke-GitCapture @("ls-remote", $repo, $candidate)
        if ([string]::IsNullOrWhiteSpace($line)) { continue }
        if ($line -match "^[0-9a-fA-F]{40}") {
            return (($line -split "\s+")[0]).Trim()
        }
    }
    return $null
}

function Resolve-RemoteCommitCached([string]$repo, [string]$ref, [hashtable]$cache = $null) {
    if ($null -eq $cache) {
        return (Resolve-RemoteCommit $repo $ref)
    }
    $targetRef = if ([string]::IsNullOrWhiteSpace($ref)) { "main" } else { [string]$ref }
    $cacheKey = ("{0}|{1}" -f (Get-RepoIdentityKey $repo), $targetRef).ToLowerInvariant()
    if ($cache.ContainsKey($cacheKey)) {
        return $cache[$cacheKey]
    }
    $resolved = Resolve-RemoteCommit $repo $targetRef
    $cache[$cacheKey] = $resolved
    return $resolved
}

function Resolve-LocalRemoteCommit([string]$path, [string]$ref) {
    if ([string]::IsNullOrWhiteSpace($path) -or -not (Test-IsGitRepoRoot $path)) { return $null }
    $targetRef = if ([string]::IsNullOrWhiteSpace($ref)) { "main" } else { [string]$ref }
    $candidates = @()
    if ($targetRef -match "^[0-9a-fA-F]{40}$") { return $targetRef }
    if ($targetRef -match "^refs/heads/(.+)$") {
        $branch = $Matches[1]
        $candidates += @("refs/remotes/origin/$branch", "origin/$branch")
    }
    elseif ($targetRef -match "^refs/tags/(.+)$") {
        $tag = $Matches[1]
        $candidates += @("refs/tags/$tag^{}", "refs/tags/$tag")
    }
    elseif ($targetRef -match "^refs/") {
        $candidates += $targetRef
    }
    else {
        $candidates += @("refs/remotes/origin/$targetRef", "origin/$targetRef", "refs/tags/$targetRef^{}", "refs/tags/$targetRef", $targetRef)
    }

    Push-Location $path
    try {
        foreach ($candidate in $candidates) {
            try {
                $value = Invoke-GitCapture @("rev-parse", "--verify", $candidate)
                if ($value -match "^[0-9a-fA-F]{40}$") { return $value.Trim() }
            }
            catch {}
        }
    }
    finally { Pop-Location }
    return $null
}

function Resolve-UpdatePlanTargetCommit([string]$path, [string]$repo, [string]$ref, [hashtable]$remoteCommitCache, [bool]$PreferLocalRefs) {
    if ($PreferLocalRefs) {
        $localRemote = Resolve-LocalRemoteCommit $path $ref
        if (-not [string]::IsNullOrWhiteSpace($localRemote)) { return $localRemote }
    }
    return (Resolve-RemoteCommitCached $repo $ref $remoteCommitCache)
}

function Get-UpdatePlanItems($cfg, [switch]$PreferLocalRefs) {
    $items = @()
    $remoteCommitCache = @{}
    foreach ($v in @($cfg.vendors)) {
        $ref = if ([string]::IsNullOrWhiteSpace([string]$v.ref)) { "main" } else { [string]$v.ref }
        $path = VendorPath $v.name
        $current = Get-CurrentRepoCommit $path
        $remote = Resolve-UpdatePlanTargetCommit $path ([string]$v.repo) $ref $remoteCommitCache ([bool]$PreferLocalRefs)
        $items += [pscustomobject]@{
            type = "vendor"
            name = [string]$v.name
            ref = $ref
            current = if ([string]::IsNullOrWhiteSpace($current)) { "missing" } else { $current }
            target = if ([string]::IsNullOrWhiteSpace($remote)) { "unknown" } else { $remote }
            changed = (-not [string]::IsNullOrWhiteSpace($remote)) -and ($remote -ne $current)
        }
    }

    foreach ($i in @($cfg.imports)) {
        if ($i.mode -eq "vendor") { continue }
        $name = [string]$i.name
        $ref = if ([string]::IsNullOrWhiteSpace([string]$i.ref)) { "main" } else { [string]$i.ref }
        $path = Join-Path $ImportDir $name
        $current = Get-CurrentRepoCommit $path
        $remote = Resolve-UpdatePlanTargetCommit $path ([string]$i.repo) $ref $remoteCommitCache ([bool]$PreferLocalRefs)
        $items += [pscustomobject]@{
            type = "import"
            name = $name
            ref = $ref
            current = if ([string]::IsNullOrWhiteSpace($current)) { "missing" } else { $current }
            target = if ([string]::IsNullOrWhiteSpace($remote)) { "unknown" } else { $remote }
            changed = (-not [string]::IsNullOrWhiteSpace($remote)) -and ($remote -ne $current)
        }
    }
    return @($items)
}

function Test-UpdateCacheCleanForPlanItem($item, $cfg) {
    if ($null -eq $item) { return $false }
    if ([string]$item.current -eq "missing" -or [string]$item.target -eq "unknown") { return $false }
    if ([bool]$item.changed) { return $false }

    $path = $null
    if ([string]$item.type -eq "vendor") {
        $path = VendorPath ([string]$item.name)
    }
    elseif ([string]$item.type -eq "import") {
        $path = Join-Path $ImportDir ([string]$item.name)
    }
    else {
        return $false
    }
    if ([string]::IsNullOrWhiteSpace($path) -or -not (Test-Path -LiteralPath $path -PathType Container)) { return $false }

    if (Test-IsGitRepoRoot $path) {
        Push-Location $path
        try {
            $status = Invoke-GitCapture @("status", "--porcelain", "--ignored")
            return [string]::IsNullOrWhiteSpace($status)
        }
        finally { Pop-Location }
    }

    if ([string]$item.type -ne "import") { return $false }
    $import = @($cfg.imports | Where-Object { [string]$_.name -eq [string]$item.name } | Select-Object -First 1)
    if ($null -eq $import -or $import.Count -eq 0) { return $false }
    $skillPath = Normalize-SkillPath ([string]$import[0].skill)
    $src = if ($skillPath -eq ".") { $path } else { Join-Path $path $skillPath }
    return (Test-IsSkillDir $src)
}

function Test-UpdateCanFastNoop($cfg, $items) {
    $itemsArray = @($items)
    if ($itemsArray.Count -eq 0) { return $false }
    foreach ($item in $itemsArray) {
        if (-not (Test-UpdateCacheCleanForPlanItem $item $cfg)) {
            return $false
        }
    }
    return $true
}

function Show-UpdatePlan($cfg) {
    Write-Host "=== 更新预览（--plan）==="
    $items = Get-UpdatePlanItems $cfg
    if ($items.Count -eq 0) {
        Write-Host "未发现可规划项（vendors/imports 为空）。"
        return @()
    }
    $changed = @($items | Where-Object { $_.changed })
    foreach ($it in $items) {
        $mark = if ($it.changed) { "UPGRADE" } else { "UNCHANGED" }
        Write-Host ("[{0}] {1}/{2} ref={3}" -f $mark, $it.type, $it.name, $it.ref)
        Write-Host ("  current: {0}" -f $it.current)
        Write-Host ("  target : {0}" -f $it.target)
    }
    Write-Host ("计划摘要：total={0}, upgrade={1}, unchanged={2}" -f $items.Count, $changed.Count, ($items.Count - $changed.Count))
    return $items
}

function 更新Vendor($cfg = $null, [switch]$SkipPreflight, $SkipForceClean = $null, [switch]$SkipFetch) {
    return (Invoke-WithMetric "update_vendor" {
        if (-not $SkipPreflight) { Preflight }
        if ($null -eq $cfg) { $cfg = LoadCfg }
        $failures = New-Object System.Collections.Generic.List[string]

        foreach ($v in $cfg.vendors) {
            try {
                $path = VendorPath $v.name
                if (-not (Test-Path $path)) {
                    Write-Host ("❌ 未找到 vendor/{0} (跳过)" -f $v.name) -ForegroundColor Red
                    continue 
                }
                if ([string]::IsNullOrWhiteSpace($v.ref)) { $v.ref = "main" }

                Push-Location $path
                try {
                    $forceClean = Should-ForceCleanTarget $cfg $SkipForceClean "vendor" $v.name
                    Git-HardResetClean $forceClean
                    if (-not $SkipFetch) {
                        Invoke-Git @("fetch", "--all", "--tags")
                    }
                    $sparsePaths = @()
                    foreach ($i in $cfg.imports) {
                        if ($i.mode -ne "vendor") { continue }
                        if ($i.name -ne $v.name) { continue }
                        if (-not $i.sparse) { continue }
                        $p = To-GitPath (Normalize-SkillPath $i.skill)
                        if ($p -and $p -ne ".") { $sparsePaths += $p }
                    }
                    foreach ($m in $cfg.mappings) {
                        if ($m.vendor -ne $v.name) { continue }
                        $p = To-GitPath (Normalize-SkillPath $m.from)
                        if ($p -and $p -ne ".") { $sparsePaths += $p }
                    }
                    $sparsePaths = $sparsePaths | Select-Object -Unique
                    Set-GitSparseCheckout $sparsePaths
                    Invoke-Git @("checkout", $v.ref)
                    # fetch already happened above (unless SkipFetch), so prefer local fast-forward.
                    Update-CurrentBranchFromUpstream $false
                }
                finally {
                    Pop-Location
                }
            }
            catch {
                Write-Host ("❌ 更新失败 [{0}]: {1}" -f $v.name, $_.Exception.Message) -ForegroundColor Red
                $failures.Add(("vendor:{0} => {1}" -f $v.name, $_.Exception.Message)) | Out-Null
            }
        }
        if ($failures.Count -eq 0) {
            Write-Host "上游仓库更新完成。"
        }
        else {
            Write-Host ("上游仓库更新完成（部分失败：{0} 项）。" -f $failures.Count) -ForegroundColor Yellow
        }
        Clear-SkillsCache
        return $failures.ToArray()
    } @{ command = "更新Vendor" } -NoHost)
}

function 更新Imports($cfg = $null, [switch]$SkipPreflight, $SkipForceClean = $null, [switch]$SkipFetch) {
    return (Invoke-WithMetric "update_imports" {
        if (-not $SkipPreflight) { Preflight }
        if ($null -eq $cfg) { $cfg = LoadCfg }
        $cfgRaw = if (Test-Path $CfgPath) { Get-Content $CfgPath -Raw } else { "" }
        $cfgChanged = $false

        # Optimization/Migration before update
        Optimize-Imports $cfg

        if ($cfg.imports.Count -eq 0) { return @() }
        $failures = New-Object System.Collections.Generic.List[string]
        foreach ($i in $cfg.imports) {
            if ($i.mode -ne "manual") { continue }
            try {
                $name = $i.name
                $repo = Normalize-RepoUrl $i.repo
                $ref = $i.ref
                if ([string]::IsNullOrWhiteSpace($ref)) { $ref = "main" }
                $skillPath = Normalize-SkillPath $i.skill
                $gitSkillPath = To-GitPath $skillPath
                $sparse = [bool]$i.sparse
                if ($gitSkillPath -eq "." -and $sparse) { $sparse = $false }
                $sparsePath = $null
                if ($sparse) { $sparsePath = $gitSkillPath }
                $cache = Join-Path $ImportDir $name

                $forceClean = Should-ForceCleanTarget $cfg $SkipForceClean "import" $i.name
                try {
                    $null = Ensure-Repo $cache $repo $ref $sparsePath $forceClean $false (-not $SkipFetch)
                }
                catch {
                    if ((Test-WindowsInvalidPathIssue $_.Exception.Message) -and $gitSkillPath -ne ".") {
                        $invalidPathForceClean = $forceClean
                        if (-not $invalidPathForceClean -and (Test-Path -LiteralPath $cache)) {
                            $expectedSrc = if ($skillPath -eq ".") { $cache } else { Join-Path $cache $skillPath }
                            if (-not (Test-IsSkillDir $expectedSrc)) {
                                $invalidPathForceClean = $true
                                Log ("导入缓存已不可用，非法路径回退临时启用强制清理：{0} [{1}]" -f $name, $repo) "WARN"
                            }
                        }
                        $fallbackDone = $false
                        $sparseFallbackError = $null
                        if (-not $sparse) {
                            try {
                                $fallbackSparsePath = $gitSkillPath
                                Log ("导入更新检测到 Windows 非法路径，先回退为 sparse checkout：{0} [{1}] -> {2}" -f $name, $repo, $fallbackSparsePath) "WARN"
                                $null = Ensure-Repo $cache $repo $ref $fallbackSparsePath $invalidPathForceClean $false (-not $SkipFetch)
                                $sparse = $true
                                $sparsePath = $fallbackSparsePath
                                if (-not [bool]$i.sparse) {
                                    $i.sparse = $true
                                    $cfgChanged = $true
                                }
                                $fallbackDone = $true
                            }
                            catch {
                                $sparseFallbackError = $_.Exception.Message
                                Log ("sparse checkout 回退失败，改用归档回退：{0} [{1}]；原因：{2}" -f $name, $repo, $sparseFallbackError) "WARN"
                            }
                        }
                        if (-not $fallbackDone) {
                            $prefix = if ([string]::IsNullOrWhiteSpace($sparseFallbackError)) { "" } else { ("sparse={0} | " -f $sparseFallbackError) }
                            Invoke-ImportArchiveFallback $cache $repo $ref $skillPath $invalidPathForceClean `
                                ("导入更新已回退为 git archive：{0} [{1}] -> {2}" -f $name, $repo, $skillPath) `
                                ("导入更新已回退为 GitHub tree 快照：{0} [{1}] -> {2}" -f $name, $repo, $skillPath) `
                                "Windows 非法路径回退失败：" `
                                $prefix
                            $fallbackDone = $true
                        }
                        if (-not $fallbackDone) { throw }
                    }
                    else {
                        $lockPath = Join-Path $cache ".git\index.lock"
                        $fallbackSkillPath = Resolve-SkillPath $cache $skillPath
                        $fallbackSrc = if ($fallbackSkillPath -eq ".") { $cache } else { Join-Path $cache $fallbackSkillPath }
                        if ((Test-Path -LiteralPath $lockPath -PathType Leaf) -and (Test-IsSkillDir $fallbackSrc)) {
                            Log ("导入更新遇到 Git 索引锁异常，已保留现有缓存：{0} [{1}]；原因：{2}" -f $name, $repo, $_.Exception.Message) "WARN"
                            if ($fallbackSkillPath -ne $skillPath) {
                                $i.skill = $fallbackSkillPath
                                $cfgChanged = $true
                                $skillPath = $fallbackSkillPath
                            }
                        }
                        else {
                            throw
                        }
                    }
                }
                $src = if ($skillPath -eq ".") { $cache } else { Join-Path $cache $skillPath }
                if (-not (Test-IsSkillDir $src)) {
                    $resolvedSkillPath = Resolve-SkillPath $cache $skillPath
                    if ($resolvedSkillPath -ne $skillPath) {
                        $i.skill = $resolvedSkillPath
                        $cfgChanged = $true
                        $skillPath = $resolvedSkillPath
                        $src = if ($skillPath -eq ".") { $cache } else { Join-Path $cache $skillPath }
                        Log ("导入技能路径已自动修正：{0} -> {1} [{2}]" -f [string]$i.name, $skillPath, $repo) "WARN"
                    }
                }
                if (-not (Test-IsSkillDir $src) -and $gitSkillPath -ne ".") {
                    $missingSkillForceClean = $forceClean
                    if (-not $missingSkillForceClean -and (Test-Path -LiteralPath $cache)) {
                        $missingSkillForceClean = $true
                        Log ("导入缓存缺少目标技能，回退归档时临时启用强制清理：{0} [{1}]" -f $name, $repo) "WARN"
                    }
                    Invoke-ImportArchiveFallback $cache $repo $ref $skillPath $missingSkillForceClean `
                        ("导入缓存缺少目标技能，已回退为 git archive：{0} [{1}] -> {2}" -f $name, $repo, $skillPath) `
                        ("导入缓存缺少目标技能，已回退为 GitHub tree 快照：{0} [{1}] -> {2}" -f $name, $repo, $skillPath) `
                        "导入缓存缺少目标技能，归档回退失败："
                    $src = if ($skillPath -eq ".") { $cache } else { Join-Path $cache $skillPath }
                }
                Need (Test-IsSkillDir $src) "未找到技能入口文件（SKILL.md/AGENTS.md/GEMINI.md/CLAUDE.md）：$src"
                if (Test-IsGitRepoRoot $cache) {
                    Remove-ImportSourceMetadata $cache
                }
                else {
                    $sourceCommit = Resolve-RemoteCommit $repo $ref
                    Write-ImportSourceMetadata $cache $repo $ref $sourceCommit "archive"
                }
                Write-Host ("已更新导入技能缓存：{0}" -f $name)
            }
            catch {
                Write-Host ("❌ 导入更新失败 [{0}]: {1}" -f $i.name, $_.Exception.Message) -ForegroundColor Red
                $failures.Add(("import:{0} => {1}" -f $i.name, $_.Exception.Message)) | Out-Null
            }
        }
        if ($cfgChanged) {
            SaveCfgSafe $cfg $cfgRaw
        }
        Clear-SkillsCache
        return $failures.ToArray()
    } @{ command = "更新Imports" } -NoHost)
}

function 更新 {
    Invoke-WithMetric "update_total" {
        $cfg = LoadCfg
        if ($Locked -and ($Plan -or $Upgrade)) {
            throw "-Locked 不能与 -Plan 或 -Upgrade 同时使用。"
        }
        Invoke-PrebuildCheck
        if ($Plan) {
            Preflight
            Show-UpdatePlan $cfg | Out-Null
            return
        }
        if ($Locked) {
            $lock = Load-LockData
            Assert-LockMatchesCfg $cfg $lock
            Apply-LockToWorkspace $cfg $lock
            构建生效
            Write-Host "已按锁文件固定版本完成更新与构建。"
            return
        }
        $skipForceClean = @{}
        if (-not (Confirm-UpdateForce $cfg ([ref]$skipForceClean))) { return }
        if (Skip-IfDryRun "更新") { return }
        Preflight
        $parallelism = Get-UpdateParallelism $cfg
        $prefetchOk = $false
        if ($parallelism -gt 1) {
            $prefetchOk = [bool](Invoke-ParallelGitPrefetch $cfg $parallelism)
        }
        $planItems = @(Get-UpdatePlanItems $cfg -PreferLocalRefs:$prefetchOk)
        if (Test-UpdateCanFastNoop $cfg $planItems) {
            Log ("更新快路径：{0} 个缓存源均已是目标版本，跳过 fetch/reset，仅验证构建生效。" -f $planItems.Count)
            构建生效
            Write-Host "更新完成：所有技能源已是最新版本。"
            return
        }
        $failures = @()
        $importFailures = 更新Imports $cfg -SkipPreflight -SkipForceClean $skipForceClean -SkipFetch:$prefetchOk
        if ($importFailures) { $failures += $importFailures }
        $vendorFailures = 更新Vendor $cfg -SkipPreflight -SkipForceClean $skipForceClean -SkipFetch:$prefetchOk
        if ($vendorFailures) { $failures += $vendorFailures }
        构建生效
        if ($Upgrade -and $failures.Count -eq 0) {
            Save-LockData $cfg | Out-Null
            Write-Host ("已刷新锁文件：{0}" -f (Get-LockPath))
        }
        if ($failures.Count -gt 0) {
            Write-FailureSummary "更新部分失败" $failures "请查看上方错误并重试。"
        }
        else {
            Write-Host "更新完成。若某 CLI 未立即识别新技能，重启该 CLI 会话即可。"
        }
    } @{ command = "更新" } -NoHost
}

function Parse-KeyValueToken([string]$token, [string]$flagName) {
    Need (-not [string]::IsNullOrWhiteSpace($token)) ("{0} 参数不能为空" -f $flagName)
    $pair = $token.Split("=", 2)
    Need ($pair.Count -eq 2) ("{0} 参数格式必须是 KEY=VALUE：{1}" -f $flagName, $token)
    $key = $pair[0].Trim()
    Need (-not [string]::IsNullOrWhiteSpace($key)) ("{0} 参数的 KEY 不能为空：{1}" -f $flagName, $token)
    Need ($key -notmatch '[\r\n]') ("{0} 参数的 KEY 不能包含换行：{1}" -f $flagName, $token)
    Need ($pair[1] -notmatch '[\r\n]') ("{0} 参数的 VALUE 不能包含换行：{1}" -f $flagName, $token)
    return [pscustomobject]@{
        key = $key
        value = $pair[1]
    }
}

function Resolve-McpProfileServers($cfg) {
    $baseServers = @($cfg.mcp_servers)
    if ($cfg.PSObject.Properties.Match("mcp_profiles").Count -eq 0 -or $null -eq $cfg.mcp_profiles) {
        return $baseServers
    }

    $profileCfg = $cfg.mcp_profiles
    $active = ([string]$profileCfg.active).Trim()
    Need (-not [string]::IsNullOrWhiteSpace($active)) "mcp_profiles.active 不能为空"
    Need ($profileCfg.PSObject.Properties.Match("profiles").Count -gt 0 -and $null -ne $profileCfg.profiles) "mcp_profiles 缺少 profiles"
    $profileProperty = @($profileCfg.profiles.PSObject.Properties | Where-Object { [string]::Equals($_.Name, $active, [System.StringComparison]::OrdinalIgnoreCase) } | Select-Object -First 1)
    Need ($profileProperty.Count -eq 1) ("mcp_profiles.active 不存在：{0}" -f $active)
    $profile = $profileProperty[0].Value
    Need ($null -ne $profile -and $profile.PSObject.Properties.Match("enabled").Count -gt 0) ("MCP profile 缺少 enabled：{0}" -f $active)

    $knownNames = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($server in $baseServers) { $knownNames.Add([string]$server.name) | Out-Null }
    $enabledNames = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($rawName in @($profile.enabled)) {
        $name = ([string]$rawName).Trim()
        Need (-not [string]::IsNullOrWhiteSpace($name)) ("MCP profile enabled 不得包含空值：{0}" -f $active)
        Need ($knownNames.Contains($name)) ("MCP profile 引用了不存在的服务：{0}/{1}" -f $active, $name)
        $enabledNames.Add($name) | Out-Null
    }

    $toolOverrides = $null
    if ($profile.PSObject.Properties.Match("enabled_tools").Count -gt 0 -and $null -ne $profile.enabled_tools) {
        $toolOverrides = $profile.enabled_tools
        foreach ($property in @($toolOverrides.PSObject.Properties)) {
            Need ($knownNames.Contains([string]$property.Name)) ("MCP profile enabled_tools 引用了不存在的服务：{0}/{1}" -f $active, [string]$property.Name)
        }
    }

    $projected = New-Object System.Collections.Generic.List[object]
    foreach ($server in $baseServers) {
        $copy = [ordered]@{}
        foreach ($property in $server.PSObject.Properties) {
            $copy[[string]$property.Name] = $property.Value
        }
        $name = [string]$server.name
        $copy["enabled"] = $enabledNames.Contains($name)
        if ($null -ne $toolOverrides) {
            $toolProperty = @($toolOverrides.PSObject.Properties | Where-Object { [string]::Equals($_.Name, $name, [System.StringComparison]::OrdinalIgnoreCase) } | Select-Object -First 1)
            if ($toolProperty.Count -eq 1) {
                $tools = New-Object System.Collections.Generic.List[string]
                foreach ($rawTool in @($toolProperty[0].Value)) {
                    $tool = ([string]$rawTool).Trim()
                    Need (-not [string]::IsNullOrWhiteSpace($tool)) ("MCP profile enabled_tools 不得包含空值：{0}/{1}" -f $active, $name)
                    if (-not $tools.Contains($tool)) { $tools.Add($tool) | Out-Null }
                }
                $copy["enabled_tools"] = @($tools.ToArray())
            }
        }
        $projected.Add([pscustomobject]$copy) | Out-Null
    }
    return @($projected.ToArray())
}

function Remove-McpProfileServerReferences($cfg, [string[]]$serverNames) {
    if ($null -eq $cfg -or $cfg.PSObject.Properties.Match("mcp_profiles").Count -eq 0 -or $null -eq $cfg.mcp_profiles) {
        return $false
    }
    if ($cfg.mcp_profiles.PSObject.Properties.Match("profiles").Count -eq 0 -or $null -eq $cfg.mcp_profiles.profiles) {
        return $false
    }

    $names = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($rawName in @($serverNames)) {
        $name = ([string]$rawName).Trim()
        if (-not [string]::IsNullOrWhiteSpace($name)) { $names.Add($name) | Out-Null }
    }
    if ($names.Count -eq 0) { return $false }

    $changed = $false
    foreach ($profileProperty in @($cfg.mcp_profiles.profiles.PSObject.Properties)) {
        $profile = $profileProperty.Value
        if ($null -eq $profile) { continue }

        if ($profile.PSObject.Properties.Match("enabled").Count -gt 0) {
            $remaining = New-Object System.Collections.Generic.List[object]
            foreach ($rawName in @($profile.enabled)) {
                if ($names.Contains(([string]$rawName).Trim())) {
                    $changed = $true
                    continue
                }
                $remaining.Add($rawName) | Out-Null
            }
            $profile.enabled = @($remaining.ToArray())
        }

        if ($profile.PSObject.Properties.Match("enabled_tools").Count -gt 0 -and $null -ne $profile.enabled_tools) {
            foreach ($toolProperty in @($profile.enabled_tools.PSObject.Properties)) {
                if (-not $names.Contains([string]$toolProperty.Name)) { continue }
                $profile.enabled_tools.PSObject.Properties.Remove([string]$toolProperty.Name)
                $changed = $true
            }
        }
    }
    return $changed
}

function Get-ActiveMcpServers($servers) {
    return @($servers | Where-Object { $_.PSObject.Properties.Match("enabled").Count -eq 0 -or [bool]$_.enabled })
}

function Invoke-McpProfileCommand([string[]]$tokens) {
    $cfg = LoadCfg
    Need ($cfg.PSObject.Properties.Match("mcp_profiles").Count -gt 0 -and $null -ne $cfg.mcp_profiles) "未配置 mcp_profiles"
    $profileCfg = $cfg.mcp_profiles
    $action = if ($null -eq $tokens -or $tokens.Count -eq 0) { "列表" } else { ([string]$tokens[0]).Trim().ToLowerInvariant() }
    if ($action -in @("列表", "list")) {
        foreach ($property in @($profileCfg.profiles.PSObject.Properties | Sort-Object Name)) {
            $marker = if ([string]::Equals($property.Name, [string]$profileCfg.active, [System.StringComparison]::OrdinalIgnoreCase)) { "*" } else { " " }
            Write-Host ("{0} {1} ({2})" -f $marker, $property.Name, (@($property.Value.enabled) -join ", "))
        }
        return
    }
    Need ($action -in @("使用", "use")) ("MCP配置仅支持 列表/list 或 使用/use：{0}" -f $action)
    Need ($tokens.Count -ge 2) "MCP配置 使用 缺少 profile 名称"
    $name = ([string]$tokens[1]).Trim()
    $profileProperty = @($profileCfg.profiles.PSObject.Properties | Where-Object { [string]::Equals($_.Name, $name, [System.StringComparison]::OrdinalIgnoreCase) } | Select-Object -First 1)
    Need ($profileProperty.Count -eq 1) ("MCP profile 不存在：{0}" -f $name)
    $profileCfg.active = [string]$profileProperty[0].Name
    $servers = @(Resolve-McpProfileServers $cfg)
    $raw = Get-ContentUtf8 $CfgPath
    SaveCfgSafe $cfg $raw
    Write-Host ("已使用 MCP profile：{0}；enabled={1}" -f $name, (@($servers | Where-Object enabled | ForEach-Object name) -join ", "))
    同步MCP
}

function Test-ValidEnvVarName([string]$name) {
    if ([string]::IsNullOrWhiteSpace($name)) { return $false }
    return ($name.Trim() -match '^[A-Za-z_][A-Za-z0-9_]*$')
}

function Assert-McpRemoteUrl([string]$url, [string]$name, [string]$transport) {
    Need (-not [string]::IsNullOrWhiteSpace($url)) ("{0} MCP 缺少 url：{1}" -f $transport, $name)
    $parsed = $null
    if (-not [System.Uri]::TryCreate($url, [System.UriKind]::Absolute, [ref]$parsed)) {
        throw ("{0} MCP URL 非法（需要绝对 http/https URL）：{1}" -f $transport, $name)
    }
    if ($parsed.Scheme -ne [System.Uri]::UriSchemeHttp -and $parsed.Scheme -ne [System.Uri]::UriSchemeHttps) {
        throw ("{0} MCP URL 非法（仅支持 http/https）：{1}" -f $transport, $name)
    }
    Need ([string]::IsNullOrWhiteSpace($parsed.UserInfo)) ("{0} MCP URL 不允许内嵌 userinfo/credential：{1}" -f $transport, $name)
    if (-not [string]::IsNullOrWhiteSpace($parsed.Query)) {
        foreach ($part in @($parsed.Query.TrimStart('?') -split '&')) {
            if ([string]::IsNullOrWhiteSpace($part)) { continue }
            $queryKey = [Uri]::UnescapeDataString(($part -split '=', 2)[0])
            Need (-not (Test-McpSensitiveKeyName $queryKey)) ("{0} MCP URL 不允许在 query 中携带敏感字段；请改用环境变量引用或 bearer_token_env_var：{1}" -f $transport, $queryKey)
        }
    }
}

function Test-McpSensitiveKeyName([string]$name) {
    if ([string]::IsNullOrWhiteSpace($name)) { return $false }
    return ($name -match '(?i)(authorization|proxy-authorization|cookie|token|secret|password|passwd|api[-_]?key|private[-_]?key|credential)')
}

function Test-McpEnvironmentTemplate([string]$value) {
    if ([string]::IsNullOrWhiteSpace($value)) { return $false }
    return ($value.Trim() -match '^(?:(?:Bearer|Basic)\s+)?\$\{[A-Za-z_][A-Za-z0-9_]*\}$')
}

function Assert-McpKeyValueMapSafe($data, [string]$label) {
    if ($null -eq $data) { return }
    $items = @()
    if ($data -is [hashtable] -or $data -is [System.Collections.IDictionary]) {
        $items = @($data.GetEnumerator())
    }
    elseif ($data -is [pscustomobject]) {
        $items = @($data.PSObject.Properties | ForEach-Object {
                [pscustomobject]@{ Key = [string]$_.Name; Value = $_.Value }
            })
    }
    foreach ($item in $items) {
        $key = [string]$item.Key
        $value = if ($null -eq $item.Value) { "" } else { [string]$item.Value }
        Need ($key -notmatch '[\r\n]') ("{0} key 不能包含换行：{1}" -f $label, $key)
        Need ($value -notmatch '[\r\n]') ("{0} value 不能包含换行：{1}" -f $label, $key)
        if (Test-McpSensitiveKeyName $key) {
            Need (Test-McpEnvironmentTemplate $value) ("{0} 敏感字段不得保存 literal value；请使用 `${{ENV_VAR}} 引用：{1}" -f $label, $key)
        }
    }
}

function Assert-McpProcessArgsSafe([object[]]$ProcessArgs,[string]$Label='args') {
    $items=@($ProcessArgs|ForEach-Object{[string]$_})
    for($i=0;$i -lt $items.Count;$i++){
        $item=$items[$i]
        Need ($item -notmatch '[\r\n]') ("{0} 不能包含换行。" -f $Label)
        Need ($item -notmatch '(?i)\b(?:https?|postgres(?:ql)?)://[^/@\s:]+:[^/@\s]+@') ("{0} 不允许内嵌 URL credential；请改用环境变量模板。" -f $Label)
        Need ($item -notmatch '(?i)\b(?:github_pat_[A-Za-z0-9_]+|gh[pousr]_[A-Za-z0-9_]+)\b') ("{0} 不允许 literal access token；请改用环境变量模板。" -f $Label)
        if($item -match '^(?i)(--?(?:access[-_]?key|api[-_]?key|authorization|password|passwd|secret|token))=(.*)$'){
            Need (Test-McpEnvironmentTemplate ([string]$Matches[2])) ("{0} 敏感参数不得保存 literal value：{1}" -f $Label,$Matches[1])
        }
        elseif($item -match '^(?i)--?(?:access[-_]?key|api[-_]?key|authorization|password|passwd|secret|token)$'){
            Need (($i+1) -lt $items.Count -and (Test-McpEnvironmentTemplate $items[$i+1])) ("{0} 敏感参数不得保存 literal value：{1}" -f $Label,$item)
            $i++
        }
    }
}

function Normalize-McpProcessArgs([string[]]$processArgs) {
    $normalized = New-Object System.Collections.Generic.List[string]
    if ($null -eq $processArgs) { return @() }
    for ($i = 0; $i -lt $processArgs.Count; $i++) {
        $t = [string]$processArgs[$i]
        if ($t -eq "--arg") {
            if ($i + 1 -lt $processArgs.Count) {
                $normalized.Add([string]$processArgs[++$i]) | Out-Null
            }
            continue
        }
        if ($t.ToLowerInvariant().StartsWith("--arg=")) {
            $normalized.Add($t.Substring(6)) | Out-Null
            continue
        }
        $normalized.Add($t) | Out-Null
    }
    return $normalized.ToArray()
}

function Get-StableHashSuffix([string]$seed, [int]$len = 10) {
    if ([string]::IsNullOrWhiteSpace($seed)) { return $null }
    $sha1 = [System.Security.Cryptography.SHA1]::Create()
    try {
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($seed)
        $hashBytes = $sha1.ComputeHash($bytes)
        $hex = ([System.BitConverter]::ToString($hashBytes)).Replace("-", "").ToLowerInvariant()
        if ($len -le 0) { return $hex }
        if ($hex.Length -le $len) { return $hex }
        return $hex.Substring(0, $len)
    }
    finally {
        $sha1.Dispose()
    }
}

function Normalize-McpServiceNameWithFallback([string]$name, [string]$fallbackSeed = $null) {
    $norm = Normalize-Name $name
    if (-not [string]::IsNullOrWhiteSpace($norm)) { return $norm }

    $seed = $null
    if (-not [string]::IsNullOrWhiteSpace($fallbackSeed)) {
        $seed = $fallbackSeed
    }
    elseif (-not [string]::IsNullOrWhiteSpace($name)) {
        $seed = $name
    }

    if (-not [string]::IsNullOrWhiteSpace($seed)) {
        $suffix = Get-StableHashSuffix $seed 10
        if (-not [string]::IsNullOrWhiteSpace($suffix)) {
            $autoName = "mcp-{0}" -f $suffix
            Write-Host ("MCP 服务名无法规范化，已自动生成：{0} -> {1}" -f $name, $autoName) -ForegroundColor Yellow
            return $autoName
        }
    }

    Need $false ("MCP 服务名 无法规范化，请更换名称：{0}" -f $name)
    return $null
}

function Parse-McpStdioCommandLine([string]$name, [string]$commandLine) {
    $tokens = Split-Args $commandLine
    $tokens = Normalize-McpProcessArgs @($tokens)
    Need ($tokens.Count -gt 0) ("MCP 服务命令不能为空：{0}" -f $name)
    return [pscustomobject]@{
        command = [string]$tokens[0]
        args = if ($tokens.Count -gt 1) { @($tokens[1..($tokens.Count - 1)]) } else { @() }
    }
}

function Parse-McpInstallArgs([string[]]$tokens) {
    Need ($tokens -and $tokens.Count -gt 0) "缺少 MCP 服务参数。示例：安装MCP context7 --cmd npx -- -y @upstash/context7-mcp"
    $result = [ordered]@{
        name = $null
        transport = "stdio"
        command = $null
        args = @()
        url = $null
        env = @{}
        headers = @{}
        bearer_token_env_var = $null
    }
    $collectProcessArgs = $false

    for ($i = 0; $i -lt $tokens.Count; $i++) {
        $t = $tokens[$i]
        if ($t -eq "--") {
            if ($i + 1 -lt $tokens.Count) {
                $result.args += $tokens[($i + 1)..($tokens.Count - 1)]
            }
            break
        }

        if ($collectProcessArgs) {
            $result.args += $t
            continue
        }

        if (-not $t.StartsWith("-")) {
            if (-not $result.name) {
                $result.name = $t
                continue
            }
            # Backward compatible: allow "name <cmd> <args...>" without --cmd or "--".
            if ($result.transport -eq "stdio" -and [string]::IsNullOrWhiteSpace($result.command) -and [string]::IsNullOrWhiteSpace($result.url)) {
                $collectProcessArgs = $true
                $result.args += $t
                continue
            }
            $result.args += $t
            continue
        }

        $key = $t.ToLowerInvariant()
        if ($key -eq "--transport" -or $key -eq "-t") {
            Need ($i + 1 -lt $tokens.Count) ("参数缺少值：{0}" -f $t)
            $nextVal = [string]$tokens[++$i]
            Need (-not $nextVal.StartsWith("-")) ("参数缺少值：{0}" -f $t)
            $result.transport = $nextVal
            continue
        }
        if ($key -eq "--cmd" -or $key -eq "--command") {
            Need ($i + 1 -lt $tokens.Count) ("参数缺少值：{0}" -f $t)
            $nextVal = [string]$tokens[++$i]
            Need (-not $nextVal.StartsWith("-")) ("参数缺少值：{0}" -f $t)
            $result.command = $nextVal
            continue
        }
        if ($key -eq "--url") {
            Need ($i + 1 -lt $tokens.Count) "参数缺少值：--url"
            $nextVal = [string]$tokens[++$i]
            Need (-not $nextVal.StartsWith("-")) "参数缺少值：--url"
            $result.url = $nextVal
            continue
        }
        if ($key -eq "--arg") {
            Need ($i + 1 -lt $tokens.Count) "参数缺少值：--arg"
            $result.args += $tokens[++$i]
            continue
        }
        if ($key -eq "--env") {
            Need ($i + 1 -lt $tokens.Count) "参数缺少值：--env"
            $pair = Parse-KeyValueToken $tokens[++$i] "--env"
            $result.env[$pair.key] = $pair.value
            continue
        }
        if ($key -eq "--header") {
            Need ($i + 1 -lt $tokens.Count) "参数缺少值：--header"
            $pair = Parse-KeyValueToken $tokens[++$i] "--header"
            $result.headers[$pair.key] = $pair.value
            continue
        }
        if ($key -eq "--bearer-token-env-var") {
            Need ($i + 1 -lt $tokens.Count) "参数缺少值：--bearer-token-env-var"
            $result.bearer_token_env_var = [string]$tokens[++$i]
            continue
        }

        # Backward compatible: in stdio mode, unknown options are treated as process
        # arguments so users can omit "--" (PowerShell may swallow the separator).
        if (-not [string]::IsNullOrWhiteSpace($result.name) -and $result.transport -eq "stdio" -and [string]::IsNullOrWhiteSpace($result.url)) {
            if (-not [string]::IsNullOrWhiteSpace($result.command)) {
                $result.args += $t
                continue
            }
            $collectProcessArgs = $true
            $result.args += $t
            continue
        }
        throw ("未知参数：{0}" -f $t)
    }

    Need (-not [string]::IsNullOrWhiteSpace($result.name)) "缺少 MCP 服务名称。示例：安装MCP context7 --cmd npx -- -y @upstash/context7-mcp"

    if (-not [string]::IsNullOrWhiteSpace($result.transport)) {
        $result.transport = $result.transport.Trim().ToLowerInvariant()
    }
    if ([string]::IsNullOrWhiteSpace($result.transport)) { $result.transport = "stdio" }
    Need (($result.transport -eq "stdio") -or ($result.transport -eq "sse") -or ($result.transport -eq "http")) "transport 仅支持 stdio/sse/http"

    if ($result.transport -eq "stdio") {
        Assert-McpKeyValueMapSafe $result.env "--env"
        $result.args = Normalize-McpProcessArgs @($result.args)
        Assert-McpProcessArgsSafe $result.args '--args'
        if ([string]::IsNullOrWhiteSpace($result.command) -and $result.args.Count -gt 0) {
            $result.command = [string]$result.args[0]
            if ($result.args.Count -gt 1) {
                $result.args = $result.args[1..($result.args.Count - 1)]
            }
            else {
                $result.args = @()
            }
        }
        Need (-not [string]::IsNullOrWhiteSpace($result.command)) "stdio MCP 需要 --cmd/--command"
        if ($result.command.Contains(" ") -and $result.args.Count -eq 0) {
            $parts = Split-Args $result.command
            Need ($parts.Count -gt 0) "无法解析 --cmd 命令"
            $result.command = $parts[0]
            if ($parts.Count -gt 1) {
                $result.args = $parts[1..($parts.Count - 1)]
            }
        }
    }
    else {
        Assert-McpRemoteUrl ([string]$result.url) ([string]$result.name) ([string]$result.transport)
        Assert-McpKeyValueMapSafe $result.headers "--header"
        if (-not [string]::IsNullOrWhiteSpace([string]$result.bearer_token_env_var)) {
            $result.bearer_token_env_var = [string]$result.bearer_token_env_var.Trim()
            Need (Test-ValidEnvVarName $result.bearer_token_env_var) ("bearer token 环境变量名非法：{0}" -f $result.bearer_token_env_var)
        }
    }

    $fallbackSeed = $null
    if (-not [string]::IsNullOrWhiteSpace([string]$result.command)) {
        $fallbackSeed = [string]$result.command
    }
    elseif (-not [string]::IsNullOrWhiteSpace([string]$result.url)) {
        $fallbackSeed = [string]$result.url
    }
    $result.name = Normalize-McpServiceNameWithFallback $result.name $fallbackSeed

    return [pscustomobject]$result
}

function Extract-McpTrailingDryRunToken([string[]]$tokens) {
    $list = @($tokens)
    if ($list.Count -eq 0) {
        return [pscustomobject]@{
            tokens = @()
            dry_run = $false
        }
    }
    $last = [string]$list[$list.Count - 1]
    $tail = $last.Trim().ToLowerInvariant()
    if ($tail -eq "-dryrun" -or $tail -eq "--dryrun" -or $tail -eq "--dry-run") {
        $trimmed = @()
        if ($list.Count -gt 1) {
            $trimmed = @($list[0..($list.Count - 2)])
        }
        return [pscustomobject]@{
            tokens = $trimmed
            dry_run = $true
        }
    }
    return [pscustomobject]@{
        tokens = $list
        dry_run = $false
    }
}

function New-McpServerObject($parsed) {
    $obj = [ordered]@{
        name = $parsed.name
        transport = $parsed.transport
    }
    if ($parsed.transport -eq "stdio") {
        $obj.command = $parsed.command
        $obj.args = @($parsed.args)
        if ($parsed.env.Count -gt 0) { $obj.env = $parsed.env }
    }
    else {
        $obj.url = $parsed.url
        if ($parsed.headers.Count -gt 0) { $obj.headers = $parsed.headers }
        if (-not [string]::IsNullOrWhiteSpace([string]$parsed.bearer_token_env_var)) {
            $obj.bearer_token_env_var = [string]$parsed.bearer_token_env_var
        }
    }
    return [pscustomobject]$obj
}

function Convert-McpServersToConfigMap($servers) {
    $map = [ordered]@{}
    if ($null -eq $servers) { return [pscustomobject]$map }

    foreach ($s in $servers) {
        if ([string]::IsNullOrWhiteSpace([string]$s.name)) { continue }
        $entry = [ordered]@{}
        $transport = if ([string]::IsNullOrWhiteSpace([string]$s.transport)) { "stdio" } else { [string]$s.transport }
        $entry.transport = $transport
        if ($transport -eq "stdio") {
            Assert-McpKeyValueMapSafe $s.env "env"
            Assert-McpProcessArgsSafe @($s.args) 'args'
            if (-not [string]::IsNullOrWhiteSpace([string]$s.command)) { $entry.command = [string]$s.command }
            if ($s.PSObject.Properties.Match("args").Count -gt 0 -and $s.args -ne $null) { $entry.args = @($s.args) }
            if ($s.PSObject.Properties.Match("env").Count -gt 0 -and $s.env -ne $null) { $entry.env = $s.env }
        }
        else {
            Assert-McpRemoteUrl ([string]$s.url) ([string]$s.name) $transport
            Assert-McpKeyValueMapSafe $s.headers "header"
            if ($s.PSObject.Properties.Match("url").Count -gt 0 -and -not [string]::IsNullOrWhiteSpace([string]$s.url)) { $entry.url = [string]$s.url }
            if ($s.PSObject.Properties.Match("headers").Count -gt 0 -and $s.headers -ne $null) { $entry.headers = $s.headers }
            if ($s.PSObject.Properties.Match("bearer_token_env_var").Count -gt 0 -and -not [string]::IsNullOrWhiteSpace([string]$s.bearer_token_env_var)) {
                Need (Test-ValidEnvVarName ([string]$s.bearer_token_env_var)) ("bearer token 环境变量名非法：{0}" -f [string]$s.bearer_token_env_var)
                $entry.bearer_token_env_var = [string]$s.bearer_token_env_var
            }
        }
        $map[[string]$s.name] = [pscustomobject]$entry
    }
    return [pscustomobject]$map
}

function Convert-McpServersToGeminiConfigMap($servers) {
    $map = [ordered]@{}
    if ($null -eq $servers) { return [pscustomobject]$map }

    foreach ($s in $servers) {
        if ([string]::IsNullOrWhiteSpace([string]$s.name)) { continue }
        $entry = [ordered]@{}
        $transport = if ([string]::IsNullOrWhiteSpace([string]$s.transport)) { "stdio" } else { ([string]$s.transport).Trim().ToLowerInvariant() }
        if ($transport -eq "stdio") {
            if (-not [string]::IsNullOrWhiteSpace([string]$s.command)) { $entry.command = [string]$s.command }
            if ($s.PSObject.Properties.Match("args").Count -gt 0 -and $s.args -ne $null) { $entry.args = @($s.args) }
            if ($s.PSObject.Properties.Match("env").Count -gt 0 -and $s.env -ne $null) { $entry.env = $s.env }
        }
        else {
            if ($s.PSObject.Properties.Match("url").Count -gt 0 -and -not [string]::IsNullOrWhiteSpace([string]$s.url)) {
                if ($transport -eq "http") { $entry.httpUrl = [string]$s.url }
                else { $entry.url = [string]$s.url }
            }
            if ($s.PSObject.Properties.Match("headers").Count -gt 0 -and $s.headers -ne $null) { $entry.headers = $s.headers }
        }
        $map[[string]$s.name] = [pscustomobject]$entry
    }
    return [pscustomobject]$map
}

function Get-CodexMcpStartupTimeoutSec($server) {
    if ($null -eq $server) { return $null }
    if ($server.PSObject.Properties.Match("startup_timeout_sec").Count -eq 0) { return $null }

    $raw = $server.startup_timeout_sec
    if ($null -eq $raw -or [string]::IsNullOrWhiteSpace([string]$raw)) { return $null }

    $parsed = 0
    if (-not [int]::TryParse([string]$raw, [ref]$parsed) -or $parsed -lt 1) {
        Log ("mcp_server.startup_timeout_sec 无效，已忽略：{0}" -f [string]$server.name) "WARN"
        return $null
    }
    return [int]$parsed
}

function Get-CodexNpxPackageName([string]$spec) {
    if ([string]::IsNullOrWhiteSpace($spec)) { return "" }
    $text = $spec.Trim()
    if ($text.StartsWith("@")) {
        $versionAt = $text.IndexOf("@", 1)
        if ($versionAt -gt 0) { return $text.Substring(0, $versionAt) }
        return $text
    }

    $plainVersionAt = $text.IndexOf("@")
    if ($plainVersionAt -gt 0) { return $text.Substring(0, $plainVersionAt) }
    return $text
}

function Get-CodexNpxWrapperBinRel([string]$packageName) {
    switch -Exact ($packageName) {
        "@upstash/context7-mcp" { return "dist/index.js" }
        "@modelcontextprotocol/server-filesystem" { return "dist/index.js" }
        "@playwright/mcp" { return "cli.js" }
        default { return "" }
    }
}

function Convert-CodexNpxServerToCachedNodeWrapper($server) {
    if ($null -eq $server) { return $null }
    if (-not [string]::Equals([string]$server.command, "npx", [System.StringComparison]::OrdinalIgnoreCase)) {
        return $null
    }
    $args = @()
    if ($server.PSObject.Properties.Match("args").Count -gt 0 -and $server.args -ne $null) {
        $args = @($server.args | ForEach-Object { [string]$_ })
    }
    $packageIndex = -1
    for ($i = 0; $i -lt $args.Count; $i++) {
        if (-not ([string]$args[$i]).StartsWith("-")) {
            $packageIndex = $i
            break
        }
    }
    if ($packageIndex -lt 0) { return $null }

    $packageSpec = ([string]$args[$packageIndex]).Trim()
    $packageName = Get-CodexNpxPackageName $packageSpec
    $binRel = Get-CodexNpxWrapperBinRel $packageName
    if ([string]::IsNullOrWhiteSpace($packageName) -or [string]::IsNullOrWhiteSpace($binRel)) {
        return $null
    }

    $extraArgs = @()
    if ($packageIndex + 1 -lt $args.Count) {
        $extraArgs = @($args[($packageIndex + 1)..($args.Count - 1)])
    }
    $wrapperPath = Join-Path (Join-Path ([Environment]::GetFolderPath("UserProfile")) ".codex\scripts") "mcp-node-cache-wrapper.mjs"
    $entry = [ordered]@{
        transport = "stdio"
        command = "node"
        args = @($wrapperPath, $packageSpec, $binRel) + @($extraArgs)
    }
    if ($server.PSObject.Properties.Match("env").Count -gt 0 -and $server.env -ne $null) { $entry.env = $server.env }
    return [pscustomobject]$entry
}

function Convert-CodexPostgresServerToCachedNodeWrapper($server) {
    if ($null -eq $server) { return $null }
    if (-not (Test-McpServerUsesPostgresConnectionString $server)) { return $null }

    $wrapperPath = Join-Path (Join-Path ([Environment]::GetFolderPath("UserProfile")) ".codex\scripts") "mcp-postgres-env-wrapper.mjs"
    $entry = [ordered]@{
        transport = "stdio"
        command = "node"
        args = @($wrapperPath)
    }
    if ($server.PSObject.Properties.Match("env").Count -gt 0 -and $server.env -ne $null) { $entry.env = $server.env }
    return [pscustomobject]$entry
}

function Test-CodexMcpKnownTaskkillStdoutLeak($server) {
    if ($null -eq $server) { return $false }
    if (-not [string]::Equals([string]$server.command, "npx", [System.StringComparison]::OrdinalIgnoreCase)) {
        return $false
    }
    $args = @()
    if ($server.PSObject.Properties.Match("args").Count -gt 0 -and $server.args -ne $null) {
        $args = @($server.args | ForEach-Object { [string]$_ })
    }
    foreach ($arg in $args) {
        if (([string]$arg).StartsWith("-")) { continue }
        $packageName = Get-CodexNpxPackageName ([string]$arg)
        return @(
            "@upstash/context7-mcp",
            "@modelcontextprotocol/server-filesystem",
            "@playwright/mcp"
        ) -contains $packageName
    }
    return $false
}

function Should-IncludeCodexMcpKnownTaskkillStdoutLeak {
    $raw = [string]$env:SKILLS_CODEX_INCLUDE_LEAKY_STDIO_MCP
    return @("1", "true", "yes", "on") -contains $raw.Trim().ToLowerInvariant()
}

function Should-SkipCodexMcpKnownTaskkillStdoutLeak($server) {
    if (-not (Test-CodexMcpKnownTaskkillStdoutLeak $server)) { return $false }
    if (Should-IncludeCodexMcpKnownTaskkillStdoutLeak) { return $false }

    # These servers are written through mcp-node-cache-wrapper.mjs below. The
    # wrapper launches the cached package entrypoint directly, so the historical
    # Windows npx/taskkill stdout leak no longer applies to the Codex projection.
    if ($null -ne (Convert-CodexNpxServerToCachedNodeWrapper $server)) { return $false }
    return $true
}

function Convert-McpServersToCodexConfigMap($servers) {
    $map = [ordered]@{}
    if ($null -eq $servers) { return [pscustomobject]$map }

    foreach ($s in $servers) {
        if ([string]::IsNullOrWhiteSpace([string]$s.name)) { continue }
        if (Should-SkipCodexMcpKnownTaskkillStdoutLeak $s) {
            continue
        }
        $entry = [ordered]@{}
        $transport = if ([string]::IsNullOrWhiteSpace([string]$s.transport)) { "stdio" } else { [string]$s.transport }
        $entry.transport = $transport
        if ($transport -eq "stdio") {
            $wrapped = Convert-CodexPostgresServerToCachedNodeWrapper $s
            if ($null -eq $wrapped) {
                $wrapped = Convert-CodexNpxServerToCachedNodeWrapper $s
            }
            if ($null -ne $wrapped) {
                foreach ($prop in $wrapped.PSObject.Properties) { $entry[[string]$prop.Name] = $prop.Value }
            }
            else {
                if (-not [string]::IsNullOrWhiteSpace([string]$s.command)) { $entry.command = [string]$s.command }
                if ($s.PSObject.Properties.Match("args").Count -gt 0 -and $s.args -ne $null) { $entry.args = @($s.args) }
                if ($s.PSObject.Properties.Match("env").Count -gt 0 -and $s.env -ne $null) { $entry.env = $s.env }
            }
        }
        else {
            if ($s.PSObject.Properties.Match("url").Count -gt 0 -and -not [string]::IsNullOrWhiteSpace([string]$s.url)) { $entry.url = [string]$s.url }
            if ($s.PSObject.Properties.Match("headers").Count -gt 0 -and $s.headers -ne $null) { $entry.headers = $s.headers }
            if ($s.PSObject.Properties.Match("bearer_token_env_var").Count -gt 0 -and -not [string]::IsNullOrWhiteSpace([string]$s.bearer_token_env_var)) {
                $entry.bearer_token_env_var = [string]$s.bearer_token_env_var
            }
        }

        if ($s.PSObject.Properties.Match("enabled").Count -gt 0) {
            Need ($s.enabled -is [bool]) ("mcp_server.enabled 必须是布尔值：{0}" -f [string]$s.name)
            $entry.enabled = [bool]$s.enabled
        }
        if ($s.PSObject.Properties.Match("enabled_tools").Count -gt 0 -and $null -ne $s.enabled_tools) {
            $tools = @()
            foreach ($rawTool in @($s.enabled_tools)) {
                $tool = ([string]$rawTool).Trim()
                Need (-not [string]::IsNullOrWhiteSpace($tool)) ("mcp_server.enabled_tools 不得包含空值：{0}" -f [string]$s.name)
                Need (-not ($tool.Contains("`r") -or $tool.Contains("`n"))) ("mcp_server.enabled_tools 不得包含换行：{0}" -f [string]$s.name)
                if ($tools -notcontains $tool) { $tools += $tool }
            }
            $entry.enabled_tools = @($tools)
        }

        $startupTimeoutSec = Get-CodexMcpStartupTimeoutSec $s
        if ($null -ne $startupTimeoutSec) {
            $entry.startup_timeout_sec = [int]$startupTimeoutSec
        }

        $map[[string]$s.name] = [pscustomobject]$entry
    }
    return [pscustomobject]$map
}

function Get-CodexMcpNodeCacheWrapperContent {
    return @'
#!/usr/bin/env node
import { existsSync, readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { pathToFileURL } from "node:url";

const [packageSpec, binRel, ...extraArgs] = process.argv.slice(2);
if (!packageSpec || !binRel) {
  console.error("usage: mcp-node-cache-wrapper.mjs <packageSpec> <binRel> [args...]");
  process.exit(64);
}

function parsePackageSpec(spec) {
  const versionAt = spec.startsWith("@") ? spec.indexOf("@", 1) : spec.indexOf("@");
  if (versionAt <= 0) return { packageName: spec, packageVersion: "" };
  return {
    packageName: spec.slice(0, versionAt),
    packageVersion: spec.slice(versionAt + 1),
  };
}

const { packageName, packageVersion } = parsePackageSpec(packageSpec.trim());
if (!packageName || (packageSpec.includes("@", 1) && !packageVersion)) {
  console.error(`Invalid npm package selector: ${packageSpec}`);
  process.exit(64);
}

const npmCache = process.env.npm_config_cache || join(process.env.LOCALAPPDATA || "", "npm-cache");
const npxRoot = join(npmCache, "_npx");
let entry = "";
if (existsSync(npxRoot)) {
  for (const item of readdirSync(npxRoot, { withFileTypes: true })) {
    if (!item.isDirectory()) continue;
    const packageRoot = join(npxRoot, item.name, "node_modules", ...packageName.split("/"));
    const candidate = join(packageRoot, ...binRel.split("/"));
    if (!existsSync(candidate)) continue;
    if (packageVersion) {
      try {
        const manifest = JSON.parse(readFileSync(join(packageRoot, "package.json"), "utf8"));
        if (manifest.version !== packageVersion) continue;
      } catch {
        continue;
      }
    }
    entry = candidate;
    break;
  }
}

if (!entry) {
  console.error(`Cached ${packageSpec} package was not found. Run npx for this MCP once to populate the npm cache.`);
  process.exit(69);
}

process.argv = [process.argv[0], entry, ...extraArgs];
await import(pathToFileURL(entry).href);
'@
}

function Get-CodexMcpPostgresEnvWrapperContent {
    return @'
#!/usr/bin/env node
import { existsSync, readdirSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

function readWindowsEnvironmentVariable(name, scope) {
  if (process.platform !== "win32") return "";
  try {
    return execFileSync(
      "pwsh.exe",
      [
        "-NoLogo",
        "-NoProfile",
        "-NonInteractive",
        "-Command",
        `[Environment]::GetEnvironmentVariable('${name}', '${scope}')`,
      ],
      { encoding: "utf8", windowsHide: true, stdio: ["ignore", "pipe", "ignore"] },
    ).trim();
  } catch {
    return "";
  }
}

function resolveEnvironmentVariable(name) {
  const processValue = process.env[name];
  if (processValue && processValue.trim()) return processValue.trim();
  for (const scope of ["User", "Machine"]) {
    const scopedValue = readWindowsEnvironmentVariable(name, scope);
    if (scopedValue && scopedValue.trim()) return scopedValue.trim();
  }
  return "";
}

const conn = resolveEnvironmentVariable("POSTGRES_CONNECTION_STRING");
if (!conn || !conn.trim()) {
  console.error("POSTGRES_CONNECTION_STRING is required for postgres MCP.");
  process.exit(64);
}

function inferUserHomeFromWrapperPath() {
  try {
    return dirname(dirname(dirname(fileURLToPath(import.meta.url))));
  } catch {
    return "";
  }
}

const inferredUserHome = inferUserHomeFromWrapperPath();
const localAppData = resolveEnvironmentVariable("LOCALAPPDATA") || (inferredUserHome ? join(inferredUserHome, "AppData", "Local") : "");
const npmCache = process.env.npm_config_cache || join(localAppData || "", "npm-cache");
const npxRoot = join(npmCache, "_npx");
let entry = "";
if (existsSync(npxRoot)) {
  for (const item of readdirSync(npxRoot, { withFileTypes: true })) {
    if (!item.isDirectory()) continue;
    const candidate = join(
      npxRoot,
      item.name,
      "node_modules",
      "@modelcontextprotocol",
      "server-postgres",
      "dist",
      "index.js",
    );
    if (existsSync(candidate)) {
      entry = candidate;
      break;
    }
  }
}

if (!entry) {
  console.error("Cached @modelcontextprotocol/server-postgres package was not found. Run npx for this MCP once to populate the npm cache.");
  process.exit(69);
}

process.argv = [process.argv[0], entry, conn];
await import(pathToFileURL(entry).href);
'@
}

function Ensure-CodexMcpNodeCacheWrapper([string]$codexRoot) {
    if ([string]::IsNullOrWhiteSpace($codexRoot)) { return }
    $scriptsDir = Join-Path $codexRoot "scripts"
    EnsureDir $scriptsDir
    $wrapperPath = Join-Path $scriptsDir "mcp-node-cache-wrapper.mjs"
    Write-Utf8FileAtomic -Path $wrapperPath -Content (Get-CodexMcpNodeCacheWrapperContent)
    $postgresWrapperPath = Join-Path $scriptsDir "mcp-postgres-env-wrapper.mjs"
    Write-Utf8FileAtomic -Path $postgresWrapperPath -Content (Get-CodexMcpPostgresEnvWrapperContent)
}

function Convert-McpMapToOrderedMap($mapLike) {
    $map = [ordered]@{}
    if ($null -eq $mapLike) { return $map }

    if ($mapLike -is [hashtable] -or $mapLike -is [System.Collections.IDictionary]) {
        foreach ($k in $mapLike.Keys) {
            $name = [string]$k
            if ([string]::IsNullOrWhiteSpace($name)) { continue }
            $map[$name] = $mapLike[$k]
        }
        return $map
    }

    if ($mapLike -is [pscustomobject]) {
        foreach ($p in $mapLike.PSObject.Properties) {
            $name = [string]$p.Name
            if ([string]::IsNullOrWhiteSpace($name)) { continue }
            $map[$name] = $p.Value
        }
    }
    return $map
}

function Build-GenericMcpPayload([string]$existingContent, $servers) {
    $base = [ordered]@{}
    if (-not [string]::IsNullOrWhiteSpace($existingContent)) {
        try {
            $parsed = $existingContent | ConvertFrom-Json
            if ($parsed -ne $null) {
                foreach ($p in $parsed.PSObject.Properties) {
                    $base[[string]$p.Name] = $p.Value
                }
            }
        }
        catch {
            Log ("MCP JSON 解析失败，将使用最小配置重建：{0}" -f $_.Exception.Message) "WARN"
        }
    }

    $managedMap = Convert-McpServersToConfigMap $servers
    # MCP 同步以 skills.json 为唯一真源，避免卸载后残留旧项。
    $base["mcpServers"] = $managedMap
    if ($base.Contains("mcp_servers")) { $base.Remove("mcp_servers") }
    return [pscustomobject]$base
}

function Get-NativeMcpKeyValueFlags($data, [string]$flagName, [string]$separator = "=") {
    $flags = @()
    if ($null -eq $data) { return $flags }

    if ($data -is [hashtable] -or $data -is [System.Collections.IDictionary]) {
        foreach ($k in $data.Keys) {
            $key = [string]$k
            if ([string]::IsNullOrWhiteSpace($key)) { continue }
            $value = [string]$data[$k]
            $flags += @($flagName, ("{0}{1}{2}" -f $key, $separator, $value))
        }
        return $flags
    }

    if ($data -is [pscustomobject]) {
        foreach ($p in $data.PSObject.Properties) {
            $key = [string]$p.Name
            if ([string]::IsNullOrWhiteSpace($key)) { continue }
            $value = [string]$p.Value
            $flags += @($flagName, ("{0}{1}{2}" -f $key, $separator, $value))
        }
        return $flags
    }

    return $flags
}

function Get-NativeMcpAddArgs($server, [string]$scope = "user") {
    Need ($null -ne $server) "MCP 服务不能为空"
    Need (-not [string]::IsNullOrWhiteSpace([string]$server.name)) "MCP 服务缺少 name"
    Need (($scope -eq "local") -or ($scope -eq "user")) ("不支持的 scope：{0}" -f $scope)

    $name = [string]$server.name
    $transport = if ([string]::IsNullOrWhiteSpace([string]$server.transport)) { "stdio" } else { [string]$server.transport }
    $transport = $transport.Trim().ToLowerInvariant()
    $args = @("mcp", "add", "--scope", $scope)

    if ($transport -eq "stdio") {
        $envFlags = @()
        if ($server.PSObject.Properties.Match("env").Count -gt 0) {
            $envFlags = Get-NativeMcpKeyValueFlags $server.env "-e"
        }
        if ($envFlags.Count -gt 0) { $args += $envFlags }
        $args += @($name, "--")
        $cmd = [string]$server.command
        Need (-not [string]::IsNullOrWhiteSpace($cmd)) ("stdio MCP 缺少 command：{0}" -f $name)
        $args += $cmd
        if ($server.PSObject.Properties.Match("args").Count -gt 0 -and $server.args -ne $null) {
            $args += @($server.args | ForEach-Object { [string]$_ })
        }
        return $args
    }

    $headerFlags = @()
    if ($server.PSObject.Properties.Match("headers").Count -gt 0) {
        $headerFlags = Get-NativeMcpKeyValueFlags $server.headers "-H" ": "
    }
    $url = if ($server.PSObject.Properties.Match("url").Count -gt 0) { [string]$server.url } else { "" }
    Need (-not [string]::IsNullOrWhiteSpace($url)) ("{0} MCP 缺少 url：{1}" -f $transport, $name)
    $args += @("--transport", $transport, $name, $url)
    # `claude mcp add --header` is variadic and consumes trailing tokens, so headers must
    # be appended after <name> <url>.
    if ($headerFlags.Count -gt 0) { $args += $headerFlags }
    return $args
}

function Remove-McpServersFromPayload($payload, [string[]]$names) {
    if ($null -eq $payload -or $null -eq $names -or $names.Count -eq 0) { return $payload }
    if ($payload.PSObject.Properties.Match("mcpServers").Count -eq 0) { return $payload }
    $serverMap = $payload.mcpServers
    if ($null -eq $serverMap) { return $payload }

    foreach ($name in @($names)) {
        if ([string]::IsNullOrWhiteSpace([string]$name)) { continue }
        $match = @($serverMap.PSObject.Properties | Where-Object {
            [string]::Equals([string]$_.Name, [string]$name, [System.StringComparison]::OrdinalIgnoreCase)
        } | Select-Object -First 1)
        if ($match.Count -gt 0 -and $null -ne $match[0]) {
            $serverMap.PSObject.Properties.Remove($match[0].Name)
        }
    }

    return $payload
}

function Get-LegacyMcpServersToPrune() {
    return @("fetch", "filesystem")
}

function Get-McpServersToPrune($servers) {
    $names = New-Object System.Collections.Generic.List[string]
    foreach ($name in @(Get-LegacyMcpServersToPrune)) {
        if ([string]::IsNullOrWhiteSpace([string]$name)) { continue }
        if (Has-McpServerByName $servers ([string]$name)) { continue }
        $names.Add([string]$name) | Out-Null
    }
    return @($names.ToArray())
}

function Has-McpServerByName($servers, [string]$name) {
    if ([string]::IsNullOrWhiteSpace($name)) { return $false }
    foreach ($s in @($servers)) {
        if ($null -eq $s) { continue }
        if ([string]::Equals([string]$s.name, $name, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $true
        }
    }
    return $false
}

function Invoke-Gh([string[]]$GhArgs) {
    Need ($GhArgs -and $GhArgs.Count -gt 0) "gh 参数不能为空"
    $output = & gh @GhArgs 2>$null
    if ($LASTEXITCODE -ne 0) { return $null }
    return @($output | ForEach-Object { [string]$_ })
}

function Get-McpUserEnvironmentVariable([string]$name) {
    Need (-not [string]::IsNullOrWhiteSpace($name)) "环境变量名不能为空"
    return [System.Environment]::GetEnvironmentVariable($name, "User")
}

function Set-McpUserEnvironmentVariable([string]$name, [AllowNull()][string]$value) {
    Need (-not [string]::IsNullOrWhiteSpace($name)) "环境变量名不能为空"
    [System.Environment]::SetEnvironmentVariable($name, $value, "User")
}

function Get-EnvironmentVariableWithScope([string]$name, [string[]]$scopes = @("Process", "User", "Machine")) {
    Need (-not [string]::IsNullOrWhiteSpace($name)) "环境变量名不能为空"
    foreach ($scope in @($scopes)) {
        $value = if ([string]$scope -eq "User") { Get-McpUserEnvironmentVariable $name } else { [System.Environment]::GetEnvironmentVariable($name, $scope) }
        if (-not [string]::IsNullOrWhiteSpace($value)) {
            return [pscustomobject]@{
                name = $name
                scope = [string]$scope
                value = [string]$value
            }
        }
    }
    return $null
}

function Convert-PostgresKeyValueConnectionStringToUrl([string]$connectionString) {
    if ([string]::IsNullOrWhiteSpace($connectionString)) { return $null }
    if ($connectionString -match '^\s*postgres(ql)?://') { return $connectionString.Trim() }
    if ($connectionString -notmatch '(?i)(^|;)Host\s*=') { return $null }

    $map = @{}
    foreach ($part in ($connectionString -split ';')) {
        if ([string]::IsNullOrWhiteSpace($part)) { continue }
        $pair = $part -split '=', 2
        if ($pair.Count -ne 2) { continue }
        $key = $pair[0].Trim().ToLowerInvariant()
        if ([string]::IsNullOrWhiteSpace($key)) { continue }
        $map[$key] = $pair[1].Trim()
    }

    $hostValue = $map["host"]
    $portValue = $map["port"]
    $databaseValue = $map["database"]
    $userValue = $map["username"]
    if ([string]::IsNullOrWhiteSpace($userValue)) { $userValue = $map["user id"] }
    if ([string]::IsNullOrWhiteSpace($userValue)) { $userValue = $map["userid"] }
    $passwordValue = $map["password"]

    if ([string]::IsNullOrWhiteSpace($hostValue) -or
        [string]::IsNullOrWhiteSpace($portValue) -or
        [string]::IsNullOrWhiteSpace($databaseValue) -or
        [string]::IsNullOrWhiteSpace($userValue) -or
        [string]::IsNullOrWhiteSpace($passwordValue)) {
        return $null
    }

    return ("postgresql://{0}:{1}@{2}:{3}/{4}" -f
        [System.Uri]::EscapeDataString($userValue),
        [System.Uri]::EscapeDataString($passwordValue),
        $hostValue,
        $portValue,
        [System.Uri]::EscapeDataString($databaseValue))
}

function Test-McpServerUsesPostgresConnectionString($server) {
    if ($null -eq $server) { return $false }
    if ([string]::Equals([string]$server.name, "postgres", [System.StringComparison]::OrdinalIgnoreCase)) { return $true }
    $text = ""
    if ($server.PSObject.Properties.Match("command").Count -gt 0) { $text += " " + [string]$server.command }
    if ($server.PSObject.Properties.Match("args").Count -gt 0 -and $null -ne $server.args) { $text += " " + (@($server.args) -join " ") }
    return ($text -match 'POSTGRES_CONNECTION_STRING' -or $text -match '@modelcontextprotocol/server-postgres')
}

function Ensure-PostgresMcpEnvironment($servers) {
    $needsPostgres = $false
    foreach ($server in @($servers)) {
        if (-not (Test-McpServerUsesPostgresConnectionString $server)) { continue }

        $hasEnabled = $server.PSObject.Properties.Match("enabled").Count -gt 0
        if ($hasEnabled) {
            Need ($server.enabled -is [bool]) ("mcp_server.enabled 必须是布尔值：{0}" -f [string]$server.name)
            if (-not [bool]$server.enabled) { continue }
        }

        $needsPostgres = $true
        break
    }
    if (-not $needsPostgres) { return }

    $resolved = Get-EnvironmentVariableWithScope "POSTGRES_CONNECTION_STRING"
    Need ($null -ne $resolved) "检测到 postgres MCP，但缺少 POSTGRES_CONNECTION_STRING。请先设置用户级 postgresql:// 连接串。"

    $raw = [string]$resolved.value
    $normalized = Convert-PostgresKeyValueConnectionStringToUrl $raw
    Need (-not [string]::IsNullOrWhiteSpace($normalized)) "检测到 postgres MCP，但 POSTGRES_CONNECTION_STRING 不是可用的 postgresql:// URL，也无法从 Host=...;Port=...;Database=...;Username=...;Password=... 形态转换。"

    $env:POSTGRES_CONNECTION_STRING = $normalized
    if ($raw -ne $normalized -or [string]$resolved.scope -ne "User") {
        Set-McpUserEnvironmentVariable "POSTGRES_CONNECTION_STRING" $normalized
        Log ("Postgres MCP 连接串已归一化到 User scope：source_scope={0}, shape=postgres-url" -f [string]$resolved.scope) "INFO"
    }
}

function Ensure-GhAuthForGithubMcp($servers) {
    $requiresAuthentication = $false
    foreach ($server in @($servers)) {
        if ($null -eq $server -or -not [string]::Equals([string]$server.name, "github", [System.StringComparison]::OrdinalIgnoreCase)) {
            continue
        }

        $hasEnabled = $server.PSObject.Properties.Match("enabled").Count -gt 0
        if ($hasEnabled) {
            Need ($server.enabled -is [bool]) "mcp_server.enabled 必须是布尔值：github"
            if (-not [bool]$server.enabled) { continue }
        }

        $requiresAuthentication = $true
        break
    }
    if (-not $requiresAuthentication) { return }

    if (-not (Get-Command "gh" -ErrorAction SilentlyContinue)) {
        throw "检测到 github MCP，但未找到 gh 命令。请先安装并登录 GitHub CLI（gh auth login）。"
    }

    $tokenLines = Invoke-Gh @("auth", "token")
    $token = if ($tokenLines) { (($tokenLines -join "`n").Trim()) } else { "" }
    if ([string]::IsNullOrWhiteSpace($token)) {
        throw "检测到 github MCP，但 gh 未登录或无法读取 token。请先执行 gh auth login。"
    }

    $userLines = Invoke-Gh @("api", "user", "--jq", ".login")
    $username = if ($userLines) { (($userLines -join "`n").Trim()) } else { "" }
    if ([string]::IsNullOrWhiteSpace($username)) {
        throw "检测到 github MCP，但 gh 登录态校验失败（gh api user）。请重新执行 gh auth login。"
    }

    # gh auth 路线：同步阶段临时注入 token，供各客户端配置写入与 native 注册使用。
    $env:GITHUB_PERSONAL_ACCESS_TOKEN = $token
    $env:CODEX_GITHUB_PERSONAL_ACCESS_TOKEN = $token
    $existingGithubToken = Get-McpUserEnvironmentVariable "GITHUB_PERSONAL_ACCESS_TOKEN"
    if ([string]::IsNullOrWhiteSpace($existingGithubToken) -or $existingGithubToken -ne $token) {
        Set-McpUserEnvironmentVariable "GITHUB_PERSONAL_ACCESS_TOKEN" $token
        Log "GitHub MCP 已同步 gh token 到 User scope 的 GITHUB_PERSONAL_ACCESS_TOKEN。" "INFO"
    }
    $existingCodexToken = Get-McpUserEnvironmentVariable "CODEX_GITHUB_PERSONAL_ACCESS_TOKEN"
    if ([string]::IsNullOrWhiteSpace($existingCodexToken) -or $existingCodexToken -ne $token) {
        Set-McpUserEnvironmentVariable "CODEX_GITHUB_PERSONAL_ACCESS_TOKEN" $token
        Log "GitHub MCP 已同步 gh token 到 User scope 的 CODEX_GITHUB_PERSONAL_ACCESS_TOKEN。" "INFO"
    }
    Log ("GitHub MCP gh 认证预检通过：{0}" -f $username) "INFO"
}

function Resolve-ExternalCommandInvocation([string]$command, [string[]]$commandArgs = @()) {
    Need (-not [string]::IsNullOrWhiteSpace($command)) "外部命令名不能为空"
    $resolved = @(Get-Command $command -ErrorAction SilentlyContinue | Select-Object -First 1)
    if ($resolved.Count -gt 0 -and $null -ne $resolved[0]) {
        $resolvedPath = [string]$resolved[0].Path
        if (-not [string]::IsNullOrWhiteSpace($resolvedPath)) {
            $ext = [System.IO.Path]::GetExtension($resolvedPath).ToLowerInvariant()
            if ($ext -eq ".ps1") {
                return [pscustomobject]@{
                    file = Resolve-PowerShellExecutable
                    args = @("-NoLogo", "-NoProfile", "-ExecutionPolicy", "Bypass", "-File", $resolvedPath) + @($commandArgs)
                }
            }
            return [pscustomobject]@{
                file = $resolvedPath
                args = @($commandArgs)
            }
        }
    }

    return [pscustomobject]@{
        file = $command
        args = @($commandArgs)
    }
}

function Convert-ExternalCommandTextToCapturedOutput([string]$outText, [string]$errText) {
    $combined = New-Object System.Collections.Generic.List[string]
    foreach ($line in @((($outText + "`n" + $errText) -split "`r?`n"))) {
        if ($null -ne $line -and $line -ne "") { $combined.Add([string]$line) | Out-Null }
    }
    return [pscustomobject]@{
        output = @($combined)
        error = if ([string]::IsNullOrWhiteSpace($errText)) { "" } else { $errText.Trim() }
    }
}

function Invoke-ExternalCommandWithTimeout(
    [string]$command,
    [Alias("args")]
    [string[]]$CommandArgs = @(),
    [string]$workingDir = $null,
    [int]$timeoutSeconds = 30,
    [hashtable]$EnvironmentOverrides = $null
) {
    Need (-not [string]::IsNullOrWhiteSpace($command)) "外部命令名不能为空"
    if ($timeoutSeconds -lt 1) { $timeoutSeconds = 1 }

    $proc = $null
    $stdoutTask = $null
    $stderrTask = $null
    try {
        $effectiveWorkingDir = if ([string]::IsNullOrWhiteSpace($workingDir)) { $PWD.Path } else { $workingDir }
        $invocation = Resolve-ExternalCommandInvocation $command @($CommandArgs)
        $argList = @($invocation.args | ForEach-Object { [string]$_ })
        $startInfo = [System.Diagnostics.ProcessStartInfo]::new()
        $startInfo.FileName = [string]$invocation.file
        $startInfo.WorkingDirectory = $effectiveWorkingDir
        $startInfo.UseShellExecute = $false
        $startInfo.RedirectStandardOutput = $true
        $startInfo.RedirectStandardError = $true
        $startInfo.CreateNoWindow = $true
        if ($EnvironmentOverrides -ne $null) {
            foreach ($entry in $EnvironmentOverrides.GetEnumerator()) {
                $key = [string]$entry.Key
                if ([string]::IsNullOrWhiteSpace($key)) { continue }
                if ($null -eq $entry.Value) {
                    [void]$startInfo.Environment.Remove($key)
                    continue
                }
                $startInfo.Environment[$key] = [string]$entry.Value
            }
        }
        foreach ($arg in $argList) {
            [void]$startInfo.ArgumentList.Add([string]$arg)
        }

        $proc = [System.Diagnostics.Process]::new()
        $proc.StartInfo = $startInfo
        [void]$proc.Start()
        $stdoutTask = $proc.StandardOutput.ReadToEndAsync()
        $stderrTask = $proc.StandardError.ReadToEndAsync()
        $exited = $proc.WaitForExit($timeoutSeconds * 1000)
        if (-not $exited) {
            try { $proc.Kill($true) } catch { try { $proc.Kill() } catch {} }
            try { $proc.WaitForExit(2000) | Out-Null } catch {}
            $outText = if ($null -ne $stdoutTask) { [string]$stdoutTask.GetAwaiter().GetResult() } else { "" }
            $errText = if ($null -ne $stderrTask) { [string]$stderrTask.GetAwaiter().GetResult() } else { "" }
            $captured = Convert-ExternalCommandTextToCapturedOutput $outText $errText
            return [pscustomobject]@{
                timed_out = $true
                exit_code = 124
                output = @($captured.output)
                error = if ([string]::IsNullOrWhiteSpace([string]$captured.error)) { ("timeout_after_{0}s" -f $timeoutSeconds) } else { ("timeout_after_{0}s: {1}" -f $timeoutSeconds, [string]$captured.error) }
            }
        }

        try { $proc.WaitForExit() | Out-Null } catch {}
        $outText = if ($null -ne $stdoutTask) { [string]$stdoutTask.GetAwaiter().GetResult() } else { "" }
        $errText = if ($null -ne $stderrTask) { [string]$stderrTask.GetAwaiter().GetResult() } else { "" }
        $captured = Convert-ExternalCommandTextToCapturedOutput $outText $errText

        return [pscustomobject]@{
            timed_out = $false
            exit_code = [int]$proc.ExitCode
            output = @($captured.output)
            error = [string]$captured.error
        }
    }
    catch {
        return [pscustomobject]@{
            timed_out = $false
            exit_code = 1
            output = @()
            error = $_.Exception.Message
        }
    }
    finally {
        if ($null -ne $proc) { $proc.Dispose() }
    }
}

function Resolve-TimeoutSecondsFromEnv([string]$envName, [int]$defaultSeconds, [int]$minSeconds = 1, [int]$maxSeconds = 600) {
    $value = $defaultSeconds
    if ([string]::IsNullOrWhiteSpace($envName)) { return $value }

    $raw = [System.Environment]::GetEnvironmentVariable($envName)
    $parsed = 0
    if ([int]::TryParse([string]$raw, [ref]$parsed)) {
        $value = $parsed
    }

    if ($value -lt $minSeconds) { $value = $minSeconds }
    if ($value -gt $maxSeconds) { $value = $maxSeconds }
    return $value
}

function Test-EnvFlagEnabled([string]$envName) {
    if ([string]::IsNullOrWhiteSpace($envName)) { return $false }
    $raw = [System.Environment]::GetEnvironmentVariable($envName)
    if ([string]::IsNullOrWhiteSpace([string]$raw)) { return $false }
    $v = ([string]$raw).Trim().ToLowerInvariant()
    return ($v -eq "1" -or $v -eq "true" -or $v -eq "yes" -or $v -eq "on")
}

function Should-RunNativeMcpSync() {
    return (Test-EnvFlagEnabled "SKILLS_MCP_NATIVE_SYNC")
}

function Should-VerifyLiveMcpCli() {
    return (Test-EnvFlagEnabled "SKILLS_MCP_VERIFY_LIVE_CLI")
}

function Get-McpListVerifyTimeoutSeconds([string]$cli) {
    $cliName = if ([string]::IsNullOrWhiteSpace($cli)) { "" } else { [string]$cli.Trim().ToLowerInvariant() }
    $defaultSeconds = switch ($cliName) {
        "gemini" { 18 }
        "claude" { 45 }
        "codex" { 45 }
        default { 30 }
    }

    $globalTimeout = Resolve-TimeoutSecondsFromEnv "SKILLS_MCP_VERIFY_LIST_TIMEOUT_SECONDS" $defaultSeconds 1 600
    $envSuffix = if ([string]::IsNullOrWhiteSpace($cliName)) { "DEFAULT" } else { $cliName.ToUpperInvariant() }
    $perCliVar = "SKILLS_MCP_VERIFY_LIST_TIMEOUT_SECONDS_{0}" -f $envSuffix
    return (Resolve-TimeoutSecondsFromEnv $perCliVar $globalTimeout 1 600)
}

function Should-VerifyGeminiCli() {
    return (Test-EnvFlagEnabled "SKILLS_MCP_VERIFY_GEMINI_CLI")
}

function Get-NativeMcpCommandTimeoutSeconds() {
    return (Resolve-TimeoutSecondsFromEnv "SKILLS_MCP_NATIVE_TIMEOUT_SECONDS" 30 1 600)
}

function Invoke-ExternalCommandCapture(
    [string]$command,
    [Alias("args")]
    [string[]]$CommandArgs = @(),
    [int]$timeoutSeconds = 120,
    [hashtable]$EnvironmentOverrides = $null,
    [string]$workingDir = $null
) {
    $result = Invoke-ExternalCommandWithTimeout $command @($CommandArgs) $workingDir $timeoutSeconds $EnvironmentOverrides
    return [pscustomobject]@{
        command = $command
        args = @($CommandArgs)
        exit_code = [int]$result.exit_code
        timed_out = [bool]$result.timed_out
        error = [string]$result.error
        output = @($result.output)
    }
}

function Get-McpCliProcessEnvOverrides([string]$cli) {
    $cliName = if ([string]::IsNullOrWhiteSpace($cli)) { "" } else { [string]$cli.Trim().ToLowerInvariant() }
    if ([string]::IsNullOrWhiteSpace($cliName)) { return $null }

    $varsToHydrate = switch ($cliName) {
        "gemini" { @("GITHUB_PERSONAL_ACCESS_TOKEN") }
        "claude" { @("GITHUB_PERSONAL_ACCESS_TOKEN") }
        "codex" { @("CODEX_GITHUB_PERSONAL_ACCESS_TOKEN") }
        default { @() }
    }
    if ($varsToHydrate.Count -eq 0) { return $null }

    $overrides = [ordered]@{}
    foreach ($varName in $varsToHydrate) {
        if ([string]::IsNullOrWhiteSpace($varName)) { continue }
        $processValue = [System.Environment]::GetEnvironmentVariable($varName, "Process")
        if (-not [string]::IsNullOrWhiteSpace([string]$processValue)) { continue }
        $userValue = Get-McpUserEnvironmentVariable $varName
        if (-not [string]::IsNullOrWhiteSpace([string]$userValue)) {
            $overrides[$varName] = [string]$userValue
        }
    }

    if ($overrides.Count -eq 0) { return $null }
    return $overrides
}

function Get-McpCliVerificationWorkingDir([string]$cli) {
    $cliName = if ([string]::IsNullOrWhiteSpace($cli)) { "" } else { [string]$cli.Trim().ToLowerInvariant() }
    switch ($cliName) {
        "gemini" {
            $userHome = [Environment]::GetFolderPath("UserProfile")
            if (-not [string]::IsNullOrWhiteSpace([string]$userHome) -and (Test-Path -LiteralPath $userHome)) {
                return [string]$userHome
            }
            return $null
        }
        default { return $null }
    }
}

function Get-McpServerNamesFromJsonText([string]$jsonText) {
    if ([string]::IsNullOrWhiteSpace($jsonText)) { return @() }
    try {
        $obj = $jsonText | ConvertFrom-Json -Depth 100
    }
    catch {
        return @()
    }
    if ($null -eq $obj) { return @() }
    if ($obj.PSObject.Properties.Match("mcpServers").Count -eq 0 -or $null -eq $obj.mcpServers) {
        return @()
    }
    return @($obj.mcpServers.PSObject.Properties | ForEach-Object { [string]$_.Name })
}

function Get-CodexMcpServerNamesFromTomlText([string]$tomlText) {
    if ([string]::IsNullOrWhiteSpace($tomlText)) { return @() }
    $set = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($line in @(($tomlText -split "`r?`n"))) {
        $m = [regex]::Match([string]$line, '^\s*\[mcp_servers\.([^\.\]\s]+)(?:\.[^\]]+)?\]\s*$')
        if ($m.Success) {
            $set.Add([string]$m.Groups[1].Value) | Out-Null
        }
    }
    return @($set | Sort-Object)
}

function Get-McpExpectedServersByCli($roots) {
    $expected = [ordered]@{
        claude = @()
        codex = @()
        gemini = @()
    }
    foreach ($root in @($roots)) {
        if ([string]::IsNullOrWhiteSpace([string]$root)) { continue }
        $leaf = (Split-Path ([string]$root) -Leaf).ToLowerInvariant()
        if ($leaf -eq ".claude") {
            $mcpPath = Join-Path $root ".mcp.json"
            if (Test-Path $mcpPath) {
                $names = Get-McpServerNamesFromJsonText (Get-ContentUtf8 $mcpPath)
                if ($names.Count -gt 0) { $expected.claude += $names }
            }
            continue
        }
        if ($leaf -eq ".gemini") {
            $settingsPath = Join-Path $root "settings.json"
            if (Test-Path $settingsPath) {
                $names = Get-McpServerNamesFromJsonText (Get-ContentUtf8 $settingsPath)
                if ($names.Count -gt 0) { $expected.gemini += $names }
            }
            continue
        }
        if ($leaf -eq ".codex") {
            $cfgPath = Join-Path $root "config.toml"
            if (Test-Path $cfgPath) {
                $names = Get-CodexMcpServerNamesFromTomlText (Get-ContentUtf8 $cfgPath)
                if ($names.Count -gt 0) { $expected.codex += $names }
            }
            continue
        }
    }

    foreach ($k in @("claude", "codex", "gemini")) {
        $set = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($name in @($expected[$k])) {
            if ([string]::IsNullOrWhiteSpace([string]$name)) { continue }
            $set.Add([string]$name) | Out-Null
        }
        $expected[$k] = @($set | Sort-Object)
    }
    return [pscustomobject]$expected
}

function Remove-AnsiEscapeSequences([string]$text) {
    if ([string]::IsNullOrEmpty($text)) { return $text }
    return ([regex]::Replace($text, '\x1B\[[0-9;?]*[ -/]*[@-~]', ''))
}

function Mask-SensitiveMcpCommandText([string]$text) {
    if ([string]::IsNullOrWhiteSpace($text)) { return $text }
    $masked = [string]$text
    $masked = [regex]::Replace($masked, '(?i)(Authorization\s*[:=]\s*Bearer\s+)([^"\s]+)', '$1<redacted>')
    $masked = [regex]::Replace($masked, '(?i)\bgithub_pat_[A-Za-z0-9_]+\b', '<redacted>')
    $masked = [regex]::Replace($masked, '(?i)\bgh[pousr]_[A-Za-z0-9_]+\b', '<redacted>')
    $masked = [regex]::Replace($masked, '(?i)((?:--)?(?:token|secret|password|passwd|api[-_]?key|authorization)\s*(?:=|:)\s*)([^\s"'']+)', '$1<redacted>')
    $masked = [regex]::Replace($masked, '(?i)((?:--)?(?:token|secret|password|passwd|api[-_]?key|authorization)\s+)([^\s"'']+)', '$1<redacted>')
    $masked = [regex]::Replace($masked, '(?i)(https?://)([^/@\s:]+):([^/@\s]+)@', '$1<redacted>@')
    return $masked
}

function Test-IsNonInteractiveMcpError([string]$text) {
    if ([string]::IsNullOrWhiteSpace([string]$text)) { return $false }
    $normalized = ([string]$text).Trim()
    $hints = @(
        "stdout is not a terminal",
        "Input must be provided either through stdin",
        "No input provided via stdin",
        "when using --print"
    )
    foreach ($hint in $hints) {
        if ($normalized -like ("*{0}*" -f $hint)) { return $true }
    }
    return $false
}

function Test-IsNativeMcpAlreadyExistsError([string]$text, [string]$name) {
    if ([string]::IsNullOrWhiteSpace([string]$text) -or [string]::IsNullOrWhiteSpace([string]$name)) {
        return $false
    }
    $normalized = ([string]$text).Trim()
    $escapedName = [regex]::Escape([string]$name)
    return ($normalized -match ("(?i)\bMCP server\s+{0}\s+already exists\b" -f $escapedName))
}

function Test-CliMcpServerReady([string]$cli, [string[]]$expectedServers) {
    $cliName = if ([string]::IsNullOrWhiteSpace($cli)) { "" } else { [string]$cli.Trim().ToLowerInvariant() }
    $isGemini = ($cliName -eq "gemini")
    if ($null -eq $expectedServers -or $expectedServers.Count -eq 0) {
        return [pscustomobject]@{
            cli = $cli
            ok = $true
            reason = "no_expected_servers"
            missing = @()
            raw = @()
        }
    }
    if ($isGemini -and -not (Should-VerifyGeminiCli)) {
        return [pscustomobject]@{
            cli = $cli
            ok = $true
            reason = "gemini_cli_verification_skipped"
            missing = @()
            raw = @()
        }
    }
    if (-not (Get-Command $cli -ErrorAction SilentlyContinue)) {
        if ($isGemini) {
            return [pscustomobject]@{
                cli = $cli
                ok = $true
                reason = "gemini_cli_not_found_fallback"
                missing = @()
                raw = @()
            }
        }
        return [pscustomobject]@{
            cli = $cli
            ok = $false
            reason = "cli_not_found"
            missing = @($expectedServers)
            raw = @()
        }
    }

    $listTimeoutSeconds = Get-McpListVerifyTimeoutSeconds $cli
    $envOverrides = Get-McpCliProcessEnvOverrides $cliName
    $listWorkingDir = Get-McpCliVerificationWorkingDir $cliName
    $result = Invoke-ExternalCommandCapture -command $cli -args @("mcp", "list") -timeoutSeconds $listTimeoutSeconds -EnvironmentOverrides $envOverrides -workingDir $listWorkingDir
    $raw = @($result.output | ForEach-Object { Remove-AnsiEscapeSequences ([string]$_) })
    if ($result.timed_out) {
        if ($isGemini) {
            return [pscustomobject]@{
                cli = $cli
                ok = $true
                reason = ("gemini_cli_timeout_fallback_{0}s" -f $listTimeoutSeconds)
                missing = @()
                raw = $raw
            }
        }
        return [pscustomobject]@{
            cli = $cli
            ok = $false
            reason = ("timeout_after_{0}s" -f $listTimeoutSeconds)
            missing = @($expectedServers)
            raw = $raw
        }
    }

    $missing = New-Object System.Collections.Generic.List[string]
    $joined = ($raw -join "`n")
    $trimmedJoined = $joined.Trim()
    $nonInteractiveHints = @(
        "stdout is not a terminal",
        "Input must be provided either through stdin",
        "No input provided via stdin"
    )
    $isNonInteractive = $false
    foreach ($hint in $nonInteractiveHints) {
        if ($trimmedJoined -like ("*{0}*" -f $hint)) {
            $isNonInteractive = $true
            break
        }
    }
    if ($isNonInteractive) {
        return [pscustomobject]@{
            cli = $cli
            ok = $true
            reason = "non_interactive_tty_required_fallback"
            missing = @()
            raw = $raw
        }
    }
    if ($trimmedJoined.Length -eq 0 -and $cli -eq "gemini") {
        return [pscustomobject]@{
            cli = $cli
            ok = $true
            reason = if ($result.exit_code -eq 0) { "ok_empty_output" } else { ("ok_empty_output_exit_{0}" -f $result.exit_code) }
            missing = @()
            raw = $raw
        }
    }
    if ($trimmedJoined.Length -eq 0) {
        return [pscustomobject]@{
            cli = $cli
            ok = $false
            reason = ("empty_output_exit_{0}" -f $result.exit_code)
            missing = @($expectedServers)
            raw = $raw
        }
    }
    foreach ($name in @($expectedServers)) {
        if ([string]::IsNullOrWhiteSpace([string]$name)) { continue }
        $pattern = "^\s*(?:[^\w\r\n]+\s*)?{0}\b" -f [regex]::Escape([string]$name)
        $line = @($raw | Where-Object { [regex]::IsMatch([string]$_, $pattern) } | Select-Object -First 1)
        if ($line.Count -eq 0) {
            $missing.Add([string]$name) | Out-Null
            continue
        }
        $lineText = [string]$line[0]
        if ($cli -eq "claude") {
            if ($lineText -notmatch "Connected") {
                $missing.Add([string]$name) | Out-Null
            }
            continue
        }
        if ($cli -eq "codex") {
            if ($lineText -match '\bdisabled\b') {
                $missing.Add([string]$name) | Out-Null
            }
            continue
        }
        if ($cli -eq "gemini") {
            # Some Gemini CLI versions print minimal/empty table output.
            # Fallback: when list output has no rows, verify names from settings.json already written.
            if ($trimmedJoined.Length -eq 0) {
                continue
            }
        }
    }

    $reason = if ($missing.Count -eq 0) {
        if ($result.exit_code -eq 0) { "ok" } else { ("ok_with_nonzero_exit_{0}" -f $result.exit_code) }
    } else {
        if ($result.exit_code -eq 0) { "missing_or_unhealthy" } else { ("missing_or_unhealthy_exit_{0}" -f $result.exit_code) }
    }
    return [pscustomobject]@{
        cli = $cli
        ok = ($missing.Count -eq 0)
        reason = $reason
        missing = @($missing)
        raw = $raw
    }
}

function Verify-McpAcrossCliWithRetry($roots, [int]$maxAttempts = 6, [int]$intervalSeconds = 3) {
    $expected = Get-McpExpectedServersByCli $roots
    $targets = @(
        [pscustomobject]@{ cli = "claude"; names = @($expected.claude) },
        [pscustomobject]@{ cli = "codex"; names = @($expected.codex) },
        [pscustomobject]@{ cli = "gemini"; names = @($expected.gemini) }
    ) | Where-Object { @($_.names).Count -gt 0 }

    if ($targets.Count -eq 0) {
        Log "未检测到需校验的 CLI MCP 目标，跳过跨 CLI 可用性校验。" "WARN"
        return
    }

    if (-not (Should-VerifyLiveMcpCli)) {
        foreach ($target in $targets) {
            Log ("MCP 配置态校验通过：{0} -> {1}" -f $target.cli, ((@($target.names)) -join ", "))
        }
        Log "跨 CLI MCP live 校验默认跳过；如需实机 mcp list 校验，设置 SKILLS_MCP_VERIFY_LIVE_CLI=1。" "INFO"
        return
    }

    for ($attempt = 1; $attempt -le $maxAttempts; $attempt++) {
        $failed = New-Object System.Collections.Generic.List[object]
        foreach ($target in $targets) {
            $check = Test-CliMcpServerReady ([string]$target.cli) @($target.names)
            if ($check.ok) {
                Log ("MCP 校验通过：{0} -> {1}" -f $check.cli, ((@($target.names)) -join ", "))
            }
            else {
                $failed.Add($check) | Out-Null
                Log ("MCP 校验未通过：{0}，缺失/异常：{1}（reason={2}）" -f $check.cli, (($check.missing) -join ", "), $check.reason) "WARN"
                $snippet = @($check.raw | Select-Object -First 6) -join " | "
                if (-not [string]::IsNullOrWhiteSpace($snippet)) {
                    Log ("{0} mcp list 输出片段：{1}" -f $check.cli, (Mask-SensitiveMcpCommandText $snippet)) "WARN"
                }
            }
        }

        if ($failed.Count -eq 0) {
            Log ("跨 CLI MCP 校验完成：全部通过（attempt={0}/{1}）。" -f $attempt, $maxAttempts) "INFO"
            return
        }
        if ($attempt -lt $maxAttempts) {
            Log ("跨 CLI MCP 校验第 {0}/{1} 次未全部通过，{2}s 后自动重试。" -f $attempt, $maxAttempts, $intervalSeconds) "WARN"
            Start-Sleep -Seconds $intervalSeconds
        }
    }

    throw ("跨 CLI MCP 校验失败：在 {0} 次重试后仍存在不可用服务，请检查日志中的 CLI 与缺失项。" -f $maxAttempts)
}

function Invoke-NativeMcpSync($servers) {
    if (-not (Should-RunNativeMcpSync)) {
        Log "原生 Claude MCP 注册默认跳过；已写入配置文件。如需执行 claude mcp add/remove，设置 SKILLS_MCP_NATIVE_SYNC=1。" "INFO"
        return
    }
    if (-not (Get-Command "claude" -ErrorAction SilentlyContinue)) {
        Log "未检测到 claude 命令，已跳过原生 MCP 同步（仅写入 .mcp.json）。" "WARN"
        return
    }
    if ($script:SkipNativeMcpForSession) {
        Log "已检测到原生 MCP CLI 非交互不可用，本轮跳过后续原生 MCP 同步。" "WARN"
        return
    }
    if ($null -eq $servers -or $servers.Count -eq 0) {
        Log "当前 mcp_servers 为空，跳过原生 MCP 注册。" "WARN"
        return
    }

    foreach ($s in $servers) {
        $scope = "user"
        try {
            $args = Get-NativeMcpAddArgs $s $scope
            $cmdText = "claude {0}" -f (($args | ForEach-Object { [string]$_ }) -join " ")
            if ($DryRun) {
                $safeCmdText = Mask-SensitiveMcpCommandText $cmdText
                Write-Host ("DRYRUN：将执行原生 MCP 同步 -> {0}" -f $safeCmdText)
                continue
            }
            $timeoutSeconds = Get-NativeMcpCommandTimeoutSeconds
            $native = Invoke-ExternalCommandWithTimeout "claude" @($args) $script:Root $timeoutSeconds
            if ($native.timed_out) {
                Log ("原生 MCP 同步超时（已忽略）：{0}（scope={1}，timeout={2}s）" -f [string]$s.name, $scope, $timeoutSeconds) "WARN"
                continue
            }
            if ($native.exit_code -ne 0) {
                if (Test-IsNativeMcpAlreadyExistsError ([string]$native.error) ([string]$s.name)) {
                    Log ("原生 MCP 已存在，尝试替换：{0}（scope={1}）" -f [string]$s.name, $scope) "WARN"
                    $removeArgs = @("mcp", "remove", [string]$s.name, "--scope", $scope)
                    $removed = Invoke-ExternalCommandWithTimeout "claude" @($removeArgs) $script:Root $timeoutSeconds
                    if ($removed.timed_out -or $removed.exit_code -ne 0) {
                        Log ("原生 MCP 替换前清理失败（已忽略）：{0}（scope={1}，exit={2}）{3}" -f [string]$s.name, $scope, $removed.exit_code, (Mask-SensitiveMcpCommandText ([string]$removed.error))) "WARN"
                        continue
                    }

                    $native = Invoke-ExternalCommandWithTimeout "claude" @($args) $script:Root $timeoutSeconds
                    if (-not $native.timed_out -and $native.exit_code -eq 0) {
                        Log ("已替换原生 MCP：{0}（scope={1}）" -f [string]$s.name, $scope)
                        continue
                    }
                }
                Log ("原生 MCP 同步失败（已忽略）：{0}（scope={1}，exit={2}）{3}" -f [string]$s.name, $scope, $native.exit_code, (Mask-SensitiveMcpCommandText ([string]$native.error))) "WARN"
                if (Test-IsNonInteractiveMcpError ([string]$native.error)) {
                    $script:SkipNativeMcpForSession = $true
                    Log "检测到原生 MCP CLI 在非交互环境不可用，已停止本轮后续原生 MCP 同步。" "WARN"
                    break
                }
                continue
            }
            Log ("已同步原生 MCP：{0}（scope={1}）" -f [string]$s.name, $scope)
        }
        catch {
            Log ("原生 MCP 同步失败（已忽略）：{0}（scope={1}） -> {2}" -f [string]$s.name, $scope, (Mask-SensitiveMcpCommandText $_.Exception.Message)) "WARN"
            if (Test-IsNonInteractiveMcpError $_.Exception.Message) {
                $script:SkipNativeMcpForSession = $true
                Log "检测到原生 MCP CLI 在非交互环境不可用，已停止本轮后续原生 MCP 同步。" "WARN"
                break
            }
        }
    }
}

function Get-NativeMcpCleanupCommands([string]$name) {
    Need (-not [string]::IsNullOrWhiteSpace($name)) "MCP 服务名不能为空"
    return @(
        [pscustomobject]@{ command = "claude"; args = @("mcp", "remove", $name, "--scope", "user"); project = $false }
        [pscustomobject]@{ command = "claude"; args = @("mcp", "remove", $name, "--scope", "project"); project = $true }
    )
}

function Invoke-NativeMcpCleanup([string]$name) {
    if (-not (Should-RunNativeMcpSync)) {
        Log ("原生 Claude MCP 清理默认跳过：{0}。如需执行 claude mcp remove，设置 SKILLS_MCP_NATIVE_SYNC=1。" -f $name) "INFO"
        return
    }
    if ($script:SkipNativeMcpForSession) {
        Log ("已检测到原生 MCP CLI 非交互不可用，跳过清理：{0}" -f $name) "WARN"
        return
    }
    $ops = Get-NativeMcpCleanupCommands $name
    foreach ($op in $ops) {
        if (-not (Get-Command $op.command -ErrorAction SilentlyContinue)) { continue }
        $cmdText = "{0} {1}" -f $op.command, (($op.args | ForEach-Object { [string]$_ }) -join " ")
        if ($DryRun) {
            Write-Host ("DRYRUN：清理原生 MCP -> {0}" -f $cmdText)
            continue
        }
        try {
            $timeoutSeconds = Get-NativeMcpCommandTimeoutSeconds
            $workingDir = if ($op.project) { $script:Root } else { $null }
            $native = Invoke-ExternalCommandWithTimeout ([string]$op.command) @($op.args) $workingDir $timeoutSeconds
            if ($native.timed_out) {
                Log ("原生 MCP 清理超时（已忽略）：{0}（timeout={1}s）" -f $cmdText, $timeoutSeconds) "WARN"
                continue
            }
            if ($native.exit_code -ne 0) {
                Log ("原生 MCP 清理失败（已忽略）：{0}（exit={1}）{2}" -f (Mask-SensitiveMcpCommandText $cmdText), $native.exit_code, (Mask-SensitiveMcpCommandText ([string]$native.error))) "WARN"
                if (Test-IsNonInteractiveMcpError ([string]$native.error)) {
                    $script:SkipNativeMcpForSession = $true
                    Log "检测到原生 MCP CLI 在非交互环境不可用，已停止本轮后续原生 MCP 清理。" "WARN"
                    break
                }
                continue
            }
            Log ("已执行原生 MCP 清理：{0}" -f $cmdText)
        }
        catch {
            Log ("原生 MCP 清理失败（已忽略）：{0} -> {1}" -f (Mask-SensitiveMcpCommandText $cmdText), (Mask-SensitiveMcpCommandText $_.Exception.Message)) "WARN"
            if (Test-IsNonInteractiveMcpError $_.Exception.Message) {
                $script:SkipNativeMcpForSession = $true
                Log "检测到原生 MCP CLI 在非交互环境不可用，已停止本轮后续原生 MCP 清理。" "WARN"
                break
            }
        }
    }
}

function Build-GeminiSettingsPayload([string]$existingContent, $servers) {
    $base = [ordered]@{}
    if (-not [string]::IsNullOrWhiteSpace($existingContent)) {
        try {
            $parsed = $existingContent | ConvertFrom-Json
            if ($parsed -ne $null) {
                foreach ($p in $parsed.PSObject.Properties) {
                    $base[[string]$p.Name] = $p.Value
                }
            }
        }
        catch {
            Log ("Gemini settings.json 解析失败，将使用最小配置重建：{0}" -f $_.Exception.Message) "WARN"
        }
    }

    $managedMap = Convert-McpServersToGeminiConfigMap $servers
    # Gemini 同步以 skills.json 为唯一真源，避免卸载后残留旧项。
    $base["mcpServers"] = $managedMap
    if ($base.Contains("mcp_servers")) { $base.Remove("mcp_servers") }
    return [pscustomobject]$base
}

function ConvertTo-TomlBasicValue($value) {
    if ($null -eq $value) { return '""' }
    if ($value -is [bool]) { return ($(if ($value) { "true" } else { "false" })) }
    if ($value -is [int] -or $value -is [long] -or $value -is [double] -or $value -is [decimal]) { return [string]$value }
    $text = [string]$value
    $text = $text.Replace("\", "\\").Replace('"', '\"')
    return ('"{0}"' -f $text)
}

function Set-TomlTopLevelScalar([string[]]$lines, [string]$key, [string]$rawValue) {
    $safeLines = @($lines)
    $out = New-Object System.Collections.Generic.List[string]
    $found = $false
    $inserted = $false

    foreach ($line in $safeLines) {
        if (-not $inserted -and $line -match '^\s*\[[^\]]+\]\s*$') {
            if (-not $found) {
                $out.Add(("{0} = {1}" -f $key, $rawValue)) | Out-Null
            }
            $inserted = $true
        }

        if (-not $inserted -and $line -match ("^\s*" + [regex]::Escape($key) + "\s*=")) {
            $out.Add(("{0} = {1}" -f $key, $rawValue)) | Out-Null
            $found = $true
            continue
        }

        $out.Add($line) | Out-Null
    }

    if (-not $inserted -and -not $found) {
        $out.Add(("{0} = {1}" -f $key, $rawValue)) | Out-Null
    }

    return [string[]]$out.ToArray()
}

function Apply-CodexPermissionDefaults([string[]]$lines) {
    $updated = Set-TomlTopLevelScalar @($lines) "sandbox_mode" '"workspace-write"'
    $updated = Set-TomlTopLevelScalar @($updated) "approval_policy" '"never"'
    return [string[]]@($updated | ForEach-Object { [string]$_ })
}

function Build-CodexConfigToml([string]$existingToml, $servers) {
    $lines = @()
    if (-not [string]::IsNullOrWhiteSpace($existingToml)) {
        $lines = $existingToml -split "`r?`n"
    }
    $codexServers = @()
    $skippedGithubForMissingToken = $false
    $hasGithubToken = -not [string]::IsNullOrWhiteSpace($env:CODEX_GITHUB_PERSONAL_ACCESS_TOKEN) -or -not [string]::IsNullOrWhiteSpace($env:GITHUB_PERSONAL_ACCESS_TOKEN)
    if ([string]::IsNullOrWhiteSpace($env:CODEX_GITHUB_PERSONAL_ACCESS_TOKEN) -and -not [string]::IsNullOrWhiteSpace($env:GITHUB_PERSONAL_ACCESS_TOKEN)) {
        $env:CODEX_GITHUB_PERSONAL_ACCESS_TOKEN = [string]$env:GITHUB_PERSONAL_ACCESS_TOKEN
    }
    foreach ($server in @($servers)) {
        if ($null -eq $server) { continue }
        if ([string]::Equals([string]$server.name, "github", [System.StringComparison]::OrdinalIgnoreCase)) {
            $hasEnabled = $server.PSObject.Properties.Match("enabled").Count -gt 0
            if ($hasEnabled) {
                Need ($server.enabled -is [bool]) "mcp_server.enabled 必须是布尔值：github"
            }
            $isExplicitlyDisabled = $hasEnabled -and -not [bool]$server.enabled
            if (-not $hasGithubToken -and -not $isExplicitlyDisabled) {
                Log "Codex 检测到 GitHub MCP 但缺少 CODEX_GITHUB_PERSONAL_ACCESS_TOKEN（或 GITHUB_PERSONAL_ACCESS_TOKEN），已跳过同步以避免影响启动。" "WARN"
                $skippedGithubForMissingToken = $true
                continue
            }
            if ($hasGithubToken) {
                Log "Codex 检测到 GitHub MCP 且存在 Token，将写入 bearer_token_env_var=CODEX_GITHUB_PERSONAL_ACCESS_TOKEN。" "INFO"
            }
            else {
                Log "Codex 检测到 GitHub MCP 已显式停用；缺少 Token 时仍保留停用配置。" "INFO"
            }
            $normalizedGithub = [ordered]@{
                name = [string]$server.name
                transport = if ([string]::IsNullOrWhiteSpace([string]$server.transport)) { "http" } else { [string]$server.transport }
                url = [string]$server.url
                bearer_token_env_var = "CODEX_GITHUB_PERSONAL_ACCESS_TOKEN"
            }
            if ($hasEnabled) {
                $normalizedGithub.enabled = [bool]$server.enabled
            }
            if ($server.PSObject.Properties.Match("enabled_tools").Count -gt 0 -and $null -ne $server.enabled_tools) {
                $normalizedGithub.enabled_tools = @($server.enabled_tools)
            }
            $codexServers += [pscustomobject]$normalizedGithub
            continue
        }
        $codexServers += $server
    }

    $managedMap = Convert-McpServersToCodexConfigMap $codexServers
    $managedNames = @($managedMap.PSObject.Properties.Name | Sort-Object)
    $preserveExistingMcpSections = ($managedNames.Count -eq 0 -and $skippedGithubForMissingToken)

    $kept = New-Object System.Collections.Generic.List[string]
    if ($preserveExistingMcpSections) {
        foreach ($line in $lines) {
            $kept.Add($line) | Out-Null
        }
    }
    else {
        $skipMcpSection = $false
        $hostOwnedMcpNames = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
        $hostOwnedMcpNames.Add("node_repl") | Out-Null
        foreach ($line in $lines) {
            if ($line -match '^\s*\[mcp_servers\.([^\.\]]+)(?:\.[^\]]+)?\]\s*$') {
                $serverName = [string]$Matches[1]
                $skipMcpSection = -not $hostOwnedMcpNames.Contains($serverName)
                if (-not $skipMcpSection) {
                    $kept.Add($line) | Out-Null
                }
                continue
            }

            if ($skipMcpSection -and $line -match '^\s*\[[^\]]+\]\s*$') {
                $skipMcpSection = $false
                $kept.Add($line) | Out-Null
                continue
            }

            if (-not $skipMcpSection) {
                $kept.Add($line) | Out-Null
            }
        }
    }

    while ($kept.Count -gt 0 -and [string]::IsNullOrWhiteSpace($kept[$kept.Count - 1])) {
        $kept.RemoveAt($kept.Count - 1)
    }

    $output = New-Object System.Collections.Generic.List[string]
    $output.AddRange([string[]](Apply-CodexPermissionDefaults @([string[]]$kept.ToArray())))

    if ($managedNames.Count -gt 0) {
        if ($output.Count -gt 0) { $output.Add("") | Out-Null }
        foreach ($name in $managedNames) {
            $entry = $managedMap.$name
            $output.Add(("[mcp_servers.{0}]" -f $name)) | Out-Null
            foreach ($prop in $entry.PSObject.Properties) {
                $key = [string]$prop.Name
                $val = $prop.Value
                if ($null -eq $val) { continue }
                if ($val -is [Array]) {
                    $arr = @($val | ForEach-Object { ConvertTo-TomlBasicValue $_ })
                    $output.Add(("{0} = [{1}]" -f $key, ($arr -join ", "))) | Out-Null
                    continue
                }
                if ($val -is [hashtable] -or $val -is [System.Collections.IDictionary] -or $val -is [pscustomobject]) {
                    $dict = @{}
                    if ($val -is [pscustomobject]) {
                        foreach ($p in $val.PSObject.Properties) { $dict[[string]$p.Name] = $p.Value }
                    }
                    else {
                        foreach ($k in $val.Keys) { $dict[[string]$k] = $val[$k] }
                    }
                    $pairs = @($dict.Keys | Sort-Object | ForEach-Object { "{0} = {1}" -f $_, (ConvertTo-TomlBasicValue $dict[$_]) })
                    $output.Add(("{0} = {{ {1} }}" -f $key, ($pairs -join ", "))) | Out-Null
                    continue
                }
                $output.Add(("{0} = {1}" -f $key, (ConvertTo-TomlBasicValue $val))) | Out-Null
            }
            $output.Add("") | Out-Null
        }
        while ($output.Count -gt 0 -and [string]::IsNullOrWhiteSpace($output[$output.Count - 1])) {
            $output.RemoveAt($output.Count - 1)
        }
    }

    return ($output -join "`r`n")
}

function Resolve-GeminiAntigravityRootsFromCandidates($paths) {
    $roots = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    if ($null -eq $paths) { return @() }
    $token = ".gemini\antigravity"
    $tokenLower = $token.ToLowerInvariant()
    foreach ($p in $paths) {
        if ([string]::IsNullOrWhiteSpace([string]$p)) { continue }
        $norm = ([string]$p).Replace("/", "\")
        $lower = $norm.ToLowerInvariant()
        $searchStart = 0
        while ($searchStart -lt $lower.Length) {
            $idx = $lower.IndexOf($tokenLower, $searchStart)
            if ($idx -lt 0) { break }
            if ($idx -gt 0 -and $norm[$idx - 1] -ne '\') {
                $searchStart = $idx + 1
                continue
            }
            $end = $idx + $token.Length
            # Require a directory boundary to avoid false matches like antigravity-backup.
            if ($end -lt $norm.Length -and $norm[$end] -ne '\') {
                $searchStart = $idx + 1
                continue
            }
            $root = $norm.Substring(0, $idx + $token.Length)
            if (-not [string]::IsNullOrWhiteSpace($root)) { $roots.Add($root) | Out-Null }
            $searchStart = $idx + $token.Length
        }
    }
    # Keep array shape when only one root is found.
    return ,@($roots | Sort-Object)
}

function Get-TraeProjectMcpConfigPath([string]$repoRoot) {
    Need (-not [string]::IsNullOrWhiteSpace($repoRoot)) "repoRoot 不能为空"
    return (Join-Path (Join-Path $repoRoot ".trae") "mcp.json")
}

function Get-McpTargetCandidatePaths($cfg) {
    $paths = New-Object System.Collections.Generic.List[string]
    if ($null -eq $cfg) { return @() }
    if ($cfg.PSObject.Properties.Match("mcp_targets").Count -gt 0 -and $cfg.mcp_targets -ne $null) {
        foreach ($mt in $cfg.mcp_targets) {
            if ($mt -is [string]) {
                if (-not [string]::IsNullOrWhiteSpace($mt)) { $paths.Add($mt) | Out-Null }
            }
            elseif ($mt.PSObject.Properties.Match("path").Count -gt 0) {
                $v = [string]$mt.path
                if (-not [string]::IsNullOrWhiteSpace($v)) { $paths.Add($v) | Out-Null }
            }
        }
    }
    foreach ($t in $cfg.targets) {
        if ($t.PSObject.Properties.Match("path").Count -gt 0) {
            $v = [string]$t.path
            if (-not [string]::IsNullOrWhiteSpace($v)) { $paths.Add($v) | Out-Null }
        }
    }
    $resolved = New-Object System.Collections.Generic.List[string]
    foreach ($path in $paths) {
        $r = Resolve-TargetDir $path
        if (-not [string]::IsNullOrWhiteSpace($r)) { $resolved.Add($r.Replace("/", "\")) | Out-Null }
    }
    return @($resolved)
}

function Resolve-McpTargetRootsFromCfg($cfg) {
    $roots = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    if ($null -eq $cfg) { return @() }

    $candidates = Get-McpTargetCandidatePaths $cfg
    foreach ($path in $candidates) {
        if ([string]::IsNullOrWhiteSpace($path)) { continue }
        $norm = $path.Replace("/", "\")
        $lower = $norm.ToLowerInvariant()

        $dotDirs = @(".claude", ".codex", ".gemini", ".trae")
        $matched = $false
        $bestIdx = -1
        $bestNeedleLen = 0
        foreach ($dotDir in $dotDirs) {
            $needle = "\" + $dotDir.ToLowerInvariant()
            $searchStart = 0
            while ($searchStart -lt $lower.Length) {
                $idx = $lower.IndexOf($needle, $searchStart)
                if ($idx -lt 0) { break }
                $end = $idx + $needle.Length
                # Require directory boundary so ".gemini_backup" does not match ".gemini".
                if ($end -lt $norm.Length -and $norm[$end] -ne '\') {
                    $searchStart = $idx + 1
                    continue
                }
                if ($bestIdx -lt 0 -or $idx -lt $bestIdx) {
                    $bestIdx = $idx
                    $bestNeedleLen = $needle.Length
                }
                $matched = $true
                break
            }
        }
        if ($matched -and $bestIdx -ge 0) {
            $root = $norm.Substring(0, $bestIdx + $bestNeedleLen)
            $roots.Add($root) | Out-Null
        }
        if ($matched) { continue }

        $leaf = Split-Path $norm -Leaf
        if ($leaf.Equals("skills", [System.StringComparison]::OrdinalIgnoreCase)) {
            $parent = Split-Path $norm -Parent
            if (-not [string]::IsNullOrWhiteSpace($parent)) { $roots.Add($parent) | Out-Null }
            continue
        }

        $roots.Add($norm) | Out-Null
    }

    # Keep array shape when only one root is found.
    return ,@($roots | Sort-Object)
}

function ConvertTo-OrderedSignatureValue($value) {
    if ($null -eq $value) { return $null }
    if ($value -is [string]) { return [string]$value }
    if ($value -is [System.Collections.IDictionary]) {
        $ordered = [ordered]@{}
        foreach ($k in @($value.Keys | Sort-Object)) {
            $ordered[[string]$k] = ConvertTo-OrderedSignatureValue $value[$k]
        }
        return [pscustomobject]$ordered
    }
    if ($value -is [pscustomobject]) {
        $ordered = [ordered]@{}
        foreach ($p in @($value.PSObject.Properties | Sort-Object Name)) {
            $ordered[[string]$p.Name] = ConvertTo-OrderedSignatureValue $p.Value
        }
        return [pscustomobject]$ordered
    }
    if ($value -is [System.Collections.IEnumerable] -and -not ($value -is [byte[]])) {
        $items = New-Object System.Collections.Generic.List[object]
        foreach ($item in @($value)) {
            $items.Add((ConvertTo-OrderedSignatureValue $item)) | Out-Null
        }
        return @($items)
    }
    return $value
}

function Get-McpServerSignature($server) {
    if ($null -eq $server) { return $null }
    $transport = if ($server.PSObject.Properties.Match("transport").Count -gt 0 -and -not [string]::IsNullOrWhiteSpace([string]$server.transport)) {
        [string]$server.transport
    }
    else {
        "stdio"
    }
    $transport = $transport.Trim().ToLowerInvariant()
    $sig = [ordered]@{ transport = $transport }
    if ($transport -eq "stdio") {
        if ($server.PSObject.Properties.Match("command").Count -gt 0 -and -not [string]::IsNullOrWhiteSpace([string]$server.command)) {
            $sig.command = [string]$server.command
        }
        if ($server.PSObject.Properties.Match("args").Count -gt 0) {
            $sig.args = @($server.args)
        }
        if ($server.PSObject.Properties.Match("env").Count -gt 0 -and $null -ne $server.env) {
            $sig.env = ConvertTo-OrderedSignatureValue $server.env
        }
    }
    else {
        if ($server.PSObject.Properties.Match("url").Count -gt 0 -and -not [string]::IsNullOrWhiteSpace([string]$server.url)) {
            $sig.url = [string]$server.url
        }
        if ($server.PSObject.Properties.Match("headers").Count -gt 0 -and $null -ne $server.headers) {
            $sig.headers = ConvertTo-OrderedSignatureValue $server.headers
        }
        if ($server.PSObject.Properties.Match("bearer_token_env_var").Count -gt 0 -and -not [string]::IsNullOrWhiteSpace([string]$server.bearer_token_env_var)) {
            $sig.bearer_token_env_var = [string]$server.bearer_token_env_var
        }
    }
    if ($server.PSObject.Properties.Match("enabled").Count -gt 0) {
        Need ($server.enabled -is [bool]) "mcp_server.enabled 必须是布尔值"
        $sig.enabled = [bool]$server.enabled
    }
    if ($server.PSObject.Properties.Match("enabled_tools").Count -gt 0 -and $null -ne $server.enabled_tools) {
        $tools = @()
        foreach ($rawTool in @($server.enabled_tools)) {
            $tool = ([string]$rawTool).Trim()
            Need (-not [string]::IsNullOrWhiteSpace($tool)) "mcp_server.enabled_tools 不得包含空值"
            Need (-not ($tool.Contains("`r") -or $tool.Contains("`n"))) "mcp_server.enabled_tools 不得包含换行"
            if ($tools -notcontains $tool) { $tools += $tool }
        }
        $sig.enabled_tools = @($tools | Sort-Object)
    }
    return ($sig | ConvertTo-Json -Depth 30 -Compress)
}

function Test-McpServerEquivalent($a, $b) {
    $sa = Get-McpServerSignature $a
    $sb = Get-McpServerSignature $b
    if ([string]::IsNullOrWhiteSpace($sa) -or [string]::IsNullOrWhiteSpace($sb)) { return $false }
    return ($sa -eq $sb)
}

function Find-EquivalentMcpServer($servers, $candidate) {
    foreach ($server in @($servers)) {
        if (Test-McpServerEquivalent $server $candidate) { return $server }
    }
    return $null
}

function 安装MCP([string[]]$tokens = @()) {
    $cfg = LoadCfg
    $cfgRaw = Get-Content $CfgPath -Raw

    $tokenList = @($tokens | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
    $trailingDryRun = Extract-McpTrailingDryRunToken $tokenList
    $tokenList = @($trailingDryRun.tokens)
    if (-not $DryRun -and [bool]$trailingDryRun.dry_run) {
        $script:DryRun = $true
        Write-Host "检测到尾部 -DryRun 参数，已切换为预演模式。"
    }
    if ($tokenList.Count -eq 1 -and $tokenList[0] -is [string] -and $tokenList[0].Contains(" ")) {
        $tokenList = Split-Args $tokenList[0]
    }

    $parsed = $null
    if ($tokenList.Count -gt 0) {
        $parsed = Parse-McpInstallArgs $tokenList
    }
    else {
        $name = Normalize-NameWithNotice (Read-HostSafe "MCP 服务名（如 context7）") "MCP 服务名"
        $transport = Read-HostSafe "transport（stdio/sse/http，默认 stdio）"
        if ([string]::IsNullOrWhiteSpace($transport)) { $transport = "stdio" }
        $transport = $transport.Trim().ToLowerInvariant()
        if ($transport -ne "stdio" -and $transport -ne "sse" -and $transport -ne "http") {
            Write-Host "无效 transport，已使用默认值 stdio"
            $transport = "stdio"
        }

        if ($transport -eq "stdio") {
            $cmdLine = Read-HostSafe "命令（示例：npx -y @upstash/context7-mcp）"
            $parts = Split-Args $cmdLine
            Need ($parts.Count -gt 0) "命令不能为空"
            $parsed = [pscustomobject]@{
                name = $name
                transport = "stdio"
                command = $parts[0]
                args = if ($parts.Count -gt 1) { $parts[1..($parts.Count - 1)] } else { @() }
                url = $null
                env = @{}
                headers = @{}
            }
        }
        else {
            $url = Read-HostSafe "URL（示例：https://example.com/mcp）"
            Need (-not [string]::IsNullOrWhiteSpace($url)) "URL 不能为空"
            $parsed = [pscustomobject]@{
                name = $name
                transport = $transport
                command = $null
                args = @()
                url = $url
                env = @{}
                headers = @{}
            }
        }
    }

    $server = New-McpServerObject $parsed
    $existing = @($cfg.mcp_servers)
    $existingSameName = $existing | Where-Object { [string]$_.name -eq [string]$server.name } | Select-Object -First 1
    $updated = @()
    $replaced = $false
    $equivalent = Find-EquivalentMcpServer $existing $server
    if ($existingSameName -and (Test-McpServerEquivalent $existingSameName $server)) {
        Write-Host ("MCP 服务已存在且配置一致：{0}" -f $server.name)
        return
    }
    foreach ($s in $existing) {
        if ([string]$s.name -eq [string]$server.name) {
            $updated += $server
            $replaced = $true
        }
        else {
            $updated += $s
        }
    }
    if ($equivalent -and -not $replaced) {
        Write-Host ("已存在等效 MCP 服务：{0}（名称：{1}），已跳过" -f $server.name, [string]$equivalent.name)
        return
    }
    if (-not $replaced) { $updated += $server }
    $cfg.mcp_servers = $updated
    SaveCfgSafe $cfg $cfgRaw

    if ($DryRun) {
        if ($replaced) {
            Write-Host ("DRYRUN：将更新 MCP 服务：{0}" -f $server.name)
        }
        else {
            Write-Host ("DRYRUN：将安装 MCP 服务：{0}" -f $server.name)
        }
    }
    elseif ($replaced) {
        Write-Host ("已更新 MCP 服务：{0}" -f $server.name)
    }
    else {
        Write-Host ("已安装 MCP 服务：{0}" -f $server.name)
    }
    同步MCP
}

function 卸载MCP([string[]]$tokens = @()) {
    $cfg = LoadCfg
    $cfgRaw = Get-Content $CfgPath -Raw
    $servers = @($cfg.mcp_servers)
    if ($servers.Count -eq 0) {
        Write-Host "当前没有已安装的 MCP 服务。"
        return
    }

    $name = $null
    $tokenList = @($tokens | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
    $trailingDryRun = Extract-McpTrailingDryRunToken $tokenList
    $tokenList = @($trailingDryRun.tokens)
    if (-not $DryRun -and [bool]$trailingDryRun.dry_run) {
        $script:DryRun = $true
        Write-Host "检测到尾部 -DryRun 参数，已切换为预演模式。"
    }
    if ($tokenList.Count -gt 0) {
        $name = Normalize-NameWithNotice ([string]$tokenList[0]) "MCP 服务名"
    }
    if ([string]::IsNullOrWhiteSpace($name)) {
        Write-Host "已安装 MCP 服务："
        for ($i = 0; $i -lt $servers.Count; $i++) {
            Write-Host ("{0,3}) {1}" -f ($i + 1), $servers[$i].name)
        }
        $picked = Read-HostSafe "输入序号或名称"
        if ($picked -match "^\d+$") {
            $idx = [int]$picked - 1
            Need ($idx -ge 0 -and $idx -lt $servers.Count) "序号越界。"
            $name = [string]$servers[$idx].name
        }
        else {
            $name = Normalize-NameWithNotice $picked "MCP 服务名"
        }
    }

    $remaining = @()
    $removed = $false
    foreach ($s in $servers) {
        if ([string]$s.name -eq $name) {
            $removed = $true
        }
        else {
            $remaining += $s
        }
    }
    Need $removed ("未找到 MCP 服务：{0}" -f $name)

    $cfg.mcp_servers = $remaining
    Remove-McpProfileServerReferences $cfg @($name) | Out-Null
    SaveCfgSafe $cfg $cfgRaw
    if ($DryRun) {
        Write-Host ("DRYRUN：将卸载 MCP 服务：{0}" -f $name)
    }
    else {
        Write-Host ("已卸载 MCP 服务：{0}" -f $name)
        Invoke-NativeMcpCleanup $name
    }
    同步MCP
}

function Load-McpPlanConfigReadOnly {
    Need (Test-Path -LiteralPath $CfgPath -PathType Leaf) "缺少配置文件：$CfgPath"
    $raw = Get-ContentUtf8 $CfgPath
    $clean = $raw -replace '(?m)^\s*//.*', ''
    try { $cfg = $clean | ConvertFrom-Json }
    catch { throw ("skills.json 解析失败：{0}" -f $_.Exception.Message) }
    $contract = Get-CfgVersionedContractReport $cfg
    Need (@($contract.errors).Count -eq 0) "skills.json 未通过只读合同校验，plan 不会自动修复配置。"
    $cfg = Normalize-Cfg $cfg
    Assert-Cfg $cfg
    return [pscustomobject]@{ cfg = $cfg; raw = $raw }
}

function Parse-McpSyncPlanOptions([string[]]$Tokens = @()) {
    $json = $false
    $outPath = ''
    $plan = $false
    $items = @($Tokens | Where-Object { $null -ne $_ })
    for ($i = 0; $i -lt $items.Count; $i++) {
        $token = ([string]$items[$i]).Trim()
        switch -Regex ($token) {
            '^(?i)--plan$' { $plan = $true; continue }
            '^(?i)--json$' { $json = $true; continue }
            '^(?i)--out=(.+)$' { $outPath = [string]$Matches[1]; continue }
            '^(?i)--out$' {
                Need (($i + 1) -lt $items.Count) '--out 需要路径值。'
                $i++
                $outPath = [string]$items[$i]
                Need (-not [string]::IsNullOrWhiteSpace($outPath)) '--out 需要非空路径值。'
                continue
            }
            '^$' { continue }
            default { throw ('未知 MCP plan 参数：{0}' -f $token) }
        }
    }
    return [pscustomobject]@{ plan = $plan; json = $json; out_path = $outPath }
}

function Get-McpExistingStates([object[]]$Specs) {
    $states = @{}
    foreach ($spec in @($Specs)) {
        $path = [string]$spec.path
        $exists = Test-Path -LiteralPath $path -PathType Leaf
        $states[(Normalize-OperationPathKey $path)] = [pscustomobject]@{
            exists = $exists
            content = if ($exists) { Get-Content -LiteralPath $path -Raw -Encoding UTF8 } else { '' }
        }
    }
    return $states
}

function Get-McpSyncPlanningContext([switch]$ReadOnlyConfig) {
    $loaded = if ($ReadOnlyConfig) { Load-McpPlanConfigReadOnly } else { [pscustomobject]@{ cfg = (LoadCfg); raw = (Get-ContentUtf8 $CfgPath) } }
    $cfg = $loaded.cfg
    $servers = @(Resolve-McpProfileServers $cfg)
    $activeServers = @(Get-ActiveMcpServers $servers)
    $profileDisabledNames = @($servers | Where-Object { $_.PSObject.Properties.Match('enabled').Count -gt 0 -and -not [bool]$_.enabled } | ForEach-Object { [string]$_.name })
    $pruneNames = @(Get-McpServersToPrune $servers)
    $roots = @(Resolve-McpTargetRootsFromCfg $cfg)
    Need ($roots.Count -gt 0) "未找到可同步的 MCP 目标目录（请检查 targets/mcp_targets 配置）。"
    $candidatePaths = @(Get-McpTargetCandidatePaths $cfg)
    $specs = @(Get-McpSyncManagedTargetSpecs -Roots $roots -CandidatePaths $candidatePaths -RepoRoot $script:Root)
    $existingStates = Get-McpExistingStates $specs
    $desiredState = @(New-McpSyncDesiredState -Specs $specs -Servers $servers -ActiveServers $activeServers -ProfileDisabledNames $profileDisabledNames -PruneNames $pruneNames -ExistingStates $existingStates)
    return [pscustomobject]@{
        cfg = $cfg
        config_raw = [string]$loaded.raw
        config_revision = Get-OperationSha256 ([string]$loaded.raw)
        servers = $servers
        active_servers = $activeServers
        profile_disabled_names = $profileDisabledNames
        prune_names = $pruneNames
        roots = $roots
        desired_state = $desiredState
    }
}

function Invoke-McpSyncPlan([switch]$Json, [string]$OutPath = '') {
    $context = Get-McpSyncPlanningContext -ReadOnlyConfig
    $createdAt = (Get-Item -LiteralPath $CfgPath).LastWriteTimeUtc.ToString('o')
    $result = New-McpSyncOperationPlanResult -DesiredState $context.desired_state -CreatedAt $createdAt -SourceRevision $context.config_revision
    $validation = Test-OperationPlanContract $result.operation_plan
    Need ([bool]$validation.pass) ("MCP plan contract validation failed: {0}" -f (@($validation.findings.code) -join ', '))
    $serialized = $result | ConvertTo-Json -Depth 50

    if (-not [string]::IsNullOrWhiteSpace($OutPath)) {
        $resolvedOut = Resolve-TargetDir $OutPath
        $parent = Split-Path $resolvedOut -Parent
        if (-not [string]::IsNullOrWhiteSpace($parent)) { EnsureDir $parent }
        Set-ContentUtf8 $resolvedOut $serialized
    }
    if ($Json) {
        Write-Output $serialized
        return
    }
    Write-Host ("MCP plan：targets={0}, changed={1}, unchanged={2}, native=0" -f $result.summary.managed_target_count, $result.summary.changed_target_count, $result.summary.unchanged_target_count)
    foreach ($action in @($result.operation_plan.actions)) {
        $target = @($result.operation_plan.targets | Where-Object target_ref -eq $action.target_ref | Select-Object -First 1)
        Write-Host ("- {0}: {1}" -f $action.type, [string]$target[0].path)
    }
    if (-not [string]::IsNullOrWhiteSpace($OutPath)) { Write-Host ("Plan JSON：{0}" -f (Resolve-TargetDir $OutPath)) }
}

function Write-McpDesiredTarget($target) {
    $path = [string]$target.path
    $parent = Split-Path $path -Parent
    if (-not [string]::IsNullOrWhiteSpace($parent)) { EnsureDir $parent }
    if ([string]$target.kind -eq 'codex_toml') { Ensure-CodexMcpNodeCacheWrapper ([string]$target.root) }
    Write-Utf8FileAtomic -Path $path -Content ([string]$target.desired_content)
    switch ([string]$target.kind) {
        'gemini_settings' { Log ("已同步 Gemini MCP 配置：{0}" -f $path) }
        'gemini_antigravity_settings' { Log ("已同步 Gemini Antigravity MCP 配置：{0}" -f $path) }
        'codex_toml' { Log ("已同步 Codex MCP 配置：{0}" -f $path) }
        'trae_json' { Log ("已同步 Trae MCP 配置：{0}" -f $path) }
        'trae_project_json' { Log ("已同步项目级 Trae MCP 配置：{0}" -f $path) }
        default { Log ("已同步 MCP 配置：{0}" -f $path) }
    }
}

function Test-McpTargetReparsePath([string]$Path,[string]$Root) {
    $cursor=[IO.Path]::GetFullPath($Path);$boundary=[IO.Path]::GetFullPath($Root).TrimEnd('\','/')
    while($true){
        if([IO.File]::Exists($cursor) -or [IO.Directory]::Exists($cursor)){if(([IO.File]::GetAttributes($cursor) -band [IO.FileAttributes]::ReparsePoint) -ne 0){return $true}}
        if($cursor.TrimEnd('\','/').Equals($boundary,[StringComparison]::OrdinalIgnoreCase)){break}
        $parent=[IO.Directory]::GetParent($cursor);if($null -eq $parent -or -not (Test-OperationPathWithinRoot $parent.FullName $boundary)){break};$cursor=$parent.FullName
    }
    return $false
}

function Assert-McpDesiredStateFresh([object[]]$DesiredState,[string]$ExpectedConfigRevision='') {
    if(-not [string]::IsNullOrWhiteSpace($ExpectedConfigRevision)){
        $currentConfigRevision=Get-OperationSha256 (Get-ContentUtf8 $CfgPath)
        Need ($currentConfigRevision -eq $ExpectedConfigRevision) 'MCP source_revision_stale：skills.json changed after planning.'
    }
    foreach($target in @($DesiredState)){
        $path=[IO.Path]::GetFullPath([string]$target.path);$root=[IO.Path]::GetFullPath([string]$target.root)
        Need (Test-OperationPathWithinRoot $path $root) ("MCP target_out_of_root：{0}" -f $path)
        Need (-not (Test-McpTargetReparsePath $path $root)) ("MCP target_reparse_forbidden：{0}" -f $path)
        $exists=Test-Path -LiteralPath $path -PathType Leaf;$before=$target.before_hash
        if($null -eq $before){Need (-not $exists) ("MCP target_created_since_plan：{0}" -f $path)}
        else{Need $exists ("MCP target_missing_since_plan：{0}" -f $path);Need ((Get-OperationSha256 (Get-ContentUtf8 $path)) -eq [string]$before) ("MCP target_hash_stale：{0}" -f $path)}
    }
}

function Restore-McpManagedTargetSnapshot([object[]]$Snapshot) {
    $conflicts=New-Object System.Collections.Generic.List[string]
    foreach($entry in @($Snapshot)){
        $path=[string]$entry.path
        if(Test-Path -LiteralPath $path -PathType Leaf){
            $currentHash=Get-OperationSha256 (Get-ContentUtf8 $path)
            $allowed=@([string]$entry.before_hash,[string]$entry.desired_hash)|Where-Object{-not [string]::IsNullOrWhiteSpace($_)}
            if($currentHash -notin $allowed){$conflicts.Add($path)|Out-Null;continue}
        }
        if([bool]$entry.existed){Write-BytesAtomic -Path $path -Bytes ([byte[]]$entry.bytes)}
        elseif(Test-Path -LiteralPath $path -PathType Leaf){Remove-Item -LiteralPath $path -Force}
    }
    Need ($conflicts.Count -eq 0) ("MCP rollback_conflict：managed targets changed outside this transaction: {0}" -f ($conflicts -join ', '))
}

function Get-McpImplicitSidecarTargets([object[]]$DesiredState) {
    $targets=New-Object System.Collections.Generic.List[object]
    $seen=New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
    foreach($target in @($DesiredState|Where-Object{[string]$_.kind -eq 'codex_toml'})){
        $root=[IO.Path]::GetFullPath([string]$target.root)
        $nodePath=Join-Path $root 'scripts/mcp-node-cache-wrapper.mjs'
        if($seen.Add($nodePath)){$targets.Add([pscustomobject]@{path=$nodePath;root=$root;desired_content=(Get-CodexMcpNodeCacheWrapperContent)})|Out-Null}
        $postgresPath=Join-Path $root 'scripts/mcp-postgres-env-wrapper.mjs'
        if($seen.Add($postgresPath)){$targets.Add([pscustomobject]@{path=$postgresPath;root=$root;desired_content=(Get-CodexMcpPostgresEnvWrapperContent)})|Out-Null}
    }
    return @($targets.ToArray())
}

function Remove-McpCreatedRootIfEmpty([string]$Root) {
    if(-not (Test-Path -LiteralPath $Root -PathType Container)){return}
    if(Test-McpTargetReparsePath $Root $Root){return}
    $files=@([IO.Directory]::GetFiles($Root,'*',[IO.SearchOption]::AllDirectories))
    if($files.Count -gt 0){return}
    $reparse=@([IO.Directory]::GetFileSystemEntries($Root,'*',[IO.SearchOption]::AllDirectories)|Where-Object{([IO.File]::GetAttributes($_)-band [IO.FileAttributes]::ReparsePoint)-ne 0})
    if($reparse.Count -gt 0){return}
    Remove-Item -LiteralPath $Root -Recurse -Force
}

function Invoke-McpManagedTargetTransaction([object[]]$DesiredState,[string]$ExpectedConfigRevision='') {
    $lockEntries=New-Object System.Collections.Generic.List[object]
    $snapshot=New-Object System.Collections.Generic.List[object]
    $createdRoots=New-Object System.Collections.Generic.List[string]
    $transactionSucceeded=$false
    try{
        $roots=@($DesiredState|ForEach-Object{[IO.Path]::GetFullPath([string]$_.root)}|Sort-Object -Unique)
        foreach($root in $roots){
            $drive=[IO.Path]::GetPathRoot($root).TrimEnd('\','/');$trimmed=$root.TrimEnd('\','/')
            Need (-not $trimmed.Equals($drive,[StringComparison]::OrdinalIgnoreCase)) ("MCP target_root_forbidden：{0}" -f $root)
            if(Test-Path -LiteralPath $root){Need (Test-Path -LiteralPath $root -PathType Container) ("MCP target_root_not_directory：{0}" -f $root);continue}
            $parent=[IO.Directory]::GetParent($root)
            Need ($null -ne $parent -and (Test-Path -LiteralPath $parent.FullName -PathType Container)) ("MCP target_root_parent_missing：{0}" -f $root)
            Need (-not (Test-McpTargetReparsePath $parent.FullName $parent.FullName)) ("MCP target_root_parent_reparse_forbidden：{0}" -f $root)
        }
        foreach($root in $roots){
            if(-not (Test-Path -LiteralPath $root -PathType Container)){[IO.Directory]::CreateDirectory($root)|Out-Null;$createdRoots.Add($root)|Out-Null}
            Need (-not (Test-McpTargetReparsePath $root $root)) ("MCP target_reparse_forbidden：{0}" -f $root)
            $lockPath=Join-Path $root '.skills-manager-mcp-sync.lock'
            $stream=[IO.File]::Open($lockPath,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None)
            $lockEntries.Add([pscustomobject]@{path=$lockPath;stream=$stream})|Out-Null
        }
        Assert-McpDesiredStateFresh $DesiredState $ExpectedConfigRevision
        foreach($target in @($DesiredState)){
            $path=[string]$target.path;$exists=Test-Path -LiteralPath $path -PathType Leaf
            $snapshot.Add([pscustomobject]@{path=$path;existed=$exists;bytes=$(if($exists){[IO.File]::ReadAllBytes($path)}else{[byte[]]::new(0)});before_hash=$target.before_hash;desired_hash=(Get-OperationSha256 ([string]$target.desired_content))})|Out-Null
        }
        $sidecars=@(Get-McpImplicitSidecarTargets $DesiredState)
        foreach($sidecar in $sidecars){
            $path=[IO.Path]::GetFullPath([string]$sidecar.path);$root=[IO.Path]::GetFullPath([string]$sidecar.root)
            Need (Test-OperationPathWithinRoot $path $root) ("MCP sidecar_out_of_root：{0}" -f $path)
            Need (-not (Test-McpTargetReparsePath $path $root)) ("MCP sidecar_reparse_forbidden：{0}" -f $path)
            $exists=Test-Path -LiteralPath $path -PathType Leaf
            $beforeHash=$(if($exists){Get-OperationSha256 (Get-ContentUtf8 $path)}else{$null})
            $sidecar|Add-Member -NotePropertyName before_hash -NotePropertyValue $beforeHash -Force
            $snapshot.Add([pscustomobject]@{path=$path;existed=$exists;bytes=$(if($exists){[IO.File]::ReadAllBytes($path)}else{[byte[]]::new(0)});before_hash=$beforeHash;desired_hash=(Get-OperationSha256 ([string]$sidecar.desired_content))})|Out-Null
        }
        foreach($target in @($DesiredState|Where-Object changed)){
            Assert-McpDesiredStateFresh @($target) $ExpectedConfigRevision
            if([string]$target.kind -eq 'codex_toml'){
                $targetRoot=[IO.Path]::GetFullPath([string]$target.root)
                foreach($sidecar in @($sidecars|Where-Object{[IO.Path]::GetFullPath([string]$_.root) -eq $targetRoot})){
                    $exists=Test-Path -LiteralPath $sidecar.path -PathType Leaf
                    if($null -eq $sidecar.before_hash){Need (-not $exists) ("MCP sidecar_created_since_lock：{0}" -f $sidecar.path)}
                    else{Need $exists ("MCP sidecar_missing_since_lock：{0}" -f $sidecar.path);Need ((Get-OperationSha256 (Get-ContentUtf8 $sidecar.path)) -eq [string]$sidecar.before_hash) ("MCP sidecar_hash_stale：{0}" -f $sidecar.path)}
                }
            }
            Write-McpDesiredTarget $target
        }
        $transactionSucceeded=$true
        return [pscustomobject]@{pass=$true;writes=@($DesiredState|Where-Object changed).Count;snapshot=@($snapshot.ToArray());rollback_policy='managed_files_only_before_native_effects'}
    }catch{
        if($snapshot.Count -gt 0){Restore-McpManagedTargetSnapshot @($snapshot.ToArray())}
        throw
    }finally{
        foreach($lock in @($lockEntries.ToArray())){$lock.stream.Dispose();if(Test-Path -LiteralPath $lock.path -PathType Leaf){Remove-Item -LiteralPath $lock.path -Force -ErrorAction SilentlyContinue}}
        if(-not $transactionSucceeded){foreach($root in @($createdRoots.ToArray())|Sort-Object Length -Descending){Remove-McpCreatedRootIfEmpty $root}}
    }
}

function 同步MCP {
    Invoke-WithMetric "sync_mcp" {
        $script:SkipNativeMcpForSession = $false
        $context = Get-McpSyncPlanningContext
        if (-not $DryRun) {
            Ensure-PostgresMcpEnvironment $context.active_servers
            Ensure-GhAuthForGithubMcp $context.active_servers
        }

        $managedTransaction=$null
        foreach ($target in @($context.desired_state)) { if ($DryRun) { Write-Host ("DRYRUN：将写入 MCP 配置 -> {0}" -f [string]$target.path) } }
        if(-not $DryRun){$managedTransaction=Invoke-McpManagedTargetTransaction -DesiredState @($context.desired_state) -ExpectedConfigRevision ([string]$context.config_revision)}

        $nativeMutationEnabled=Should-RunNativeMcpSync
        try{
            Write-Host ("已同步 MCP 服务配置到 {0} 个目标。" -f @($context.desired_state).Count)
            foreach ($pruneName in @($context.prune_names)) { Invoke-NativeMcpCleanup $pruneName }
            Invoke-NativeMcpSync $context.active_servers
            if (-not $DryRun) {
                $attemptsParsed = 0
                $intervalParsed = 0
                $attempts = if ([int]::TryParse([string]$env:SKILLS_MCP_VERIFY_ATTEMPTS, [ref]$attemptsParsed)) { $attemptsParsed } else { 6 }
                $intervalSeconds = if ([int]::TryParse([string]$env:SKILLS_MCP_VERIFY_INTERVAL_SECONDS, [ref]$intervalParsed)) { $intervalParsed } else { 3 }
                if ($attempts -lt 1) { $attempts = 1 }
                if ($intervalSeconds -lt 1) { $intervalSeconds = 1 }
                Verify-McpAcrossCliWithRetry $context.roots $attempts $intervalSeconds
            }
        }catch{
            if($null -ne $managedTransaction -and -not $nativeMutationEnabled){Restore-McpManagedTargetSnapshot @($managedTransaction.snapshot)}
            elseif($null -ne $managedTransaction){Log 'MCP managed files were retained because opt-in native side effects may already have occurred and cannot be transactionally compensated.' 'WARN'}
            throw
        }
        if (@($context.servers).Count -eq 0) { Write-Host "提示：当前 mcp_servers 为空，已将各目标写为空配置。" }
    } @{ command = "同步MCP" } -NoHost
}

function Get-McpSyncManagedTargetSpecs {
    param(
        $Roots = @(),
        $CandidatePaths = @(),
        [Parameter(Mandatory = $true)][string]$RepoRoot
    )

    $specs = New-Object System.Collections.Generic.List[object]
    $seen = New-Object System.Collections.Generic.HashSet[string]([System.StringComparer]::OrdinalIgnoreCase)
    $flatRoots = New-Object System.Collections.Generic.List[string]
    foreach ($entry in @($Roots)) {
        foreach ($value in @($entry)) {
            if (-not [string]::IsNullOrWhiteSpace([string]$value)) { $flatRoots.Add([string]$value) | Out-Null }
        }
    }

    function Add-McpTargetSpec([string]$Path, [string]$Kind, [string]$Root) {
        if ([string]::IsNullOrWhiteSpace($Path)) { return }
        $key = Normalize-OperationPathKey $Path
        if (-not $seen.Add($key)) { return }
        $specs.Add([pscustomobject][ordered]@{
                path = $Path
                kind = $Kind
                root = $Root
            }) | Out-Null
    }

    foreach ($root in @($flatRoots.ToArray() | Sort-Object)) {
        Add-McpTargetSpec (Join-Path $root '.mcp.json') 'generic_json' $root
    }
    foreach ($root in @($flatRoots.ToArray() | Where-Object { (Split-Path ([string]$_) -Leaf).Equals('.gemini', [System.StringComparison]::OrdinalIgnoreCase) } | Sort-Object)) {
        Add-McpTargetSpec (Join-Path $root 'settings.json') 'gemini_settings' $root
    }
    foreach ($root in @(Resolve-GeminiAntigravityRootsFromCandidates $CandidatePaths | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | Sort-Object)) {
        Add-McpTargetSpec (Join-Path $root 'settings.json') 'gemini_antigravity_settings' $root
    }
    foreach ($root in @($flatRoots.ToArray() | Where-Object { (Split-Path ([string]$_) -Leaf).Equals('.codex', [System.StringComparison]::OrdinalIgnoreCase) } | Sort-Object)) {
        Add-McpTargetSpec (Join-Path $root 'config.toml') 'codex_toml' $root
    }
    $traeRoots = @($flatRoots.ToArray() | Where-Object { (Split-Path ([string]$_) -Leaf).Equals('.trae', [System.StringComparison]::OrdinalIgnoreCase) } | Sort-Object)
    foreach ($root in $traeRoots) {
        Add-McpTargetSpec (Join-Path $root 'mcp.json') 'trae_json' $root
    }
    if ($traeRoots.Count -gt 0) {
        Add-McpTargetSpec (Get-TraeProjectMcpConfigPath $RepoRoot) 'trae_project_json' $RepoRoot
    }

    return @($specs.ToArray())
}

function Get-McpExistingStateValue($ExistingStates, [string]$Path) {
    if ($null -eq $ExistingStates) {
        return [pscustomobject]@{ exists = $false; content = '' }
    }
    $key = Normalize-OperationPathKey $Path
    if ($ExistingStates -is [System.Collections.IDictionary] -and $ExistingStates.Contains($key)) {
        return $ExistingStates[$key]
    }
    if ($ExistingStates -is [pscustomobject]) {
        $property = @($ExistingStates.PSObject.Properties | Where-Object { $_.Name -eq $key } | Select-Object -First 1)
        if ($property.Count -eq 1) { return $property[0].Value }
    }
    return [pscustomobject]@{ exists = $false; content = '' }
}

function New-McpSyncDesiredState {
    param(
        [object[]]$Specs = @(),
        [object[]]$Servers = @(),
        [object[]]$ActiveServers = @(),
        [string[]]$ProfileDisabledNames = @(),
        [string[]]$PruneNames = @(),
        $ExistingStates = $null
    )

    $desired = New-Object System.Collections.Generic.List[object]
    foreach ($spec in @($Specs)) {
        $path = [string]$spec.path
        $state = Get-McpExistingStateValue $ExistingStates $path
        $existing = if ($null -eq $state -or $null -eq $state.content) { '' } else { [string]$state.content }
        $content = $null

        switch ([string]$spec.kind) {
            'generic_json' {
                $payload = Build-GenericMcpPayload $existing $ActiveServers
                $payload = Remove-McpServersFromPayload $payload @($PruneNames + $ProfileDisabledNames)
                $content = $payload | ConvertTo-Json -Depth 100
            }
            'gemini_settings' {
                $payload = Build-GeminiSettingsPayload $existing $ActiveServers
                $payload = Remove-McpServersFromPayload $payload $ProfileDisabledNames
                $content = $payload | ConvertTo-Json -Depth 100
            }
            'gemini_antigravity_settings' {
                $payload = Build-GeminiSettingsPayload $existing $ActiveServers
                $payload = Remove-McpServersFromPayload $payload $ProfileDisabledNames
                $content = $payload | ConvertTo-Json -Depth 100
            }
            'codex_toml' {
                $content = Build-CodexConfigToml $existing $Servers
            }
            'trae_json' {
                $payload = Build-GenericMcpPayload $existing $ActiveServers
                $payload = Remove-McpServersFromPayload $payload $ProfileDisabledNames
                $content = $payload | ConvertTo-Json -Depth 100
            }
            'trae_project_json' {
                $payload = Build-GenericMcpPayload $existing $ActiveServers
                $payload = Remove-McpServersFromPayload $payload $ProfileDisabledNames
                $content = $payload | ConvertTo-Json -Depth 100
            }
            default { throw ('Unsupported MCP managed target kind: {0}' -f [string]$spec.kind) }
        }

        $beforeHash = if ([bool]$state.exists) { Get-OperationSha256 $existing } else { $null }
        $desiredHash = Get-OperationSha256 ([string]$content)
        $desired.Add([pscustomobject][ordered]@{
                target_ref = 'mcp-target-{0}' -f (Get-OperationSha256 (Normalize-OperationPathKey $path)).Substring(0, 16)
                path = $path
                kind = [string]$spec.kind
                root = [string]$spec.root
                owner = 'skills-manager:mcp:{0}' -f [string]$spec.kind
                existed = [bool]$state.exists
                before_hash = $beforeHash
                desired_hash = $desiredHash
                changed = ($beforeHash -ne $desiredHash)
                desired_content = [string]$content
            }) | Out-Null
    }
    return @($desired.ToArray() | Sort-Object target_ref)
}

function New-McpSyncOperationPlanResult {
    param(
        [object[]]$DesiredState = @(),
        [Parameter(Mandatory = $true)][string]$CreatedAt,
        [string]$SourceRevision
    )

    $targets = New-Object System.Collections.Generic.List[object]
    $actions = New-Object System.Collections.Generic.List[object]
    foreach ($target in @($DesiredState)) {
        $targets.Add([pscustomobject][ordered]@{
                target_ref = [string]$target.target_ref
                path = [string]$target.path
                before_hash = $target.before_hash
                desired_hash = [string]$target.desired_hash
                owner = [string]$target.owner
            }) | Out-Null
        if ([bool]$target.changed) {
            $verb = if ([bool]$target.existed) { 'Update' } else { 'Create' }
            $actions.Add([pscustomobject][ordered]@{
                    type = if ([bool]$target.existed) { 'update' } else { 'create' }
                    target_ref = [string]$target.target_ref
                    summary = ('{0} managed MCP target ({1})' -f $verb, [string]$target.kind)
                    risk = 'medium'
                    metadata = [pscustomobject]@{ target_kind = [string]$target.kind }
                }) | Out-Null
        }
    }

    $orderedTargets = @($targets.ToArray() | Sort-Object target_ref)
    $orderedActions = @($actions.ToArray() | Sort-Object target_ref, type)
    $fingerprint = Get-OperationSha256 (($orderedTargets | ConvertTo-Json -Depth 20 -Compress) + '|' + [string]$SourceRevision)
    $plan = New-OperationPlan `
        -OperationId ('mcp-sync-{0}' -f $fingerprint.Substring(0, 16)) `
        -Domain 'mcp' `
        -Mode 'dry_run' `
        -CreatedAt $CreatedAt `
        -SourceRevision $SourceRevision `
        -Targets $orderedTargets `
        -Actions $orderedActions `
        -Preconditions @('skills.json contract valid', 'managed target roots resolved') `
        -Verification @('repo target hashes only; host loading and live acceptance are not claimed') `
        -Rollback @('plan mode performs no managed target or native mutation')

    return [pscustomobject][ordered]@{
        schema_version = 1
        kind = 'mcp_sync_plan'
        operation_plan = $plan
        summary = [pscustomobject][ordered]@{
            managed_target_count = @($DesiredState).Count
            changed_target_count = @($DesiredState | Where-Object changed).Count
            unchanged_target_count = @($DesiredState | Where-Object { -not [bool]$_.changed }).Count
            native_mutation_planned = $false
            profile_changed = $false
            host_loaded = 'not_run'
            live_accepted = 'not_run'
        }
    }
}
function New-McpPlanReceiptSkeleton {
    param(
        [Parameter(Mandatory = $true)]$Plan,
        [string]$StartedAt = [datetimeoffset]::UtcNow.ToString('o'),
        [string]$CompletedAt = [datetimeoffset]::UtcNow.ToString('o')
    )
    $validation = Test-OperationPlanContract $Plan
    return New-OperationReceipt -OperationId ([string](Get-OperationObjectProperty $Plan 'operation_id')) -Status dry_run -StartedAt $StartedAt -CompletedAt $CompletedAt -Actions @((Get-OperationObjectProperty $Plan 'actions') | ForEach-Object { [pscustomobject]@{ action_id=[string]$_.action_id; status='not_run'; target_ref=[string]$_.target_ref } }) -Verification ([pscustomobject]@{static_validated=$(if($validation.pass){'pass'}else{'fail'});repo_gates_passed='not_run';host_loaded='not_run';live_accepted='not_run'}) -Rollback @('not_run')
}

function Parse-ReadOnlyCapabilityOptions([object[]]$Tokens) {
    $result = [ordered]@{ json = $false; out_path = $null }
    for ($i = 0; $i -lt @($Tokens).Count; $i++) {
        $token = [string]$Tokens[$i]
        switch ($token.ToLowerInvariant()) {
            '--json' { $result.json = $true }
            '--out' { if ($i + 1 -ge @($Tokens).Count) { throw '--out requires a report file path.' }; $i++; $result.out_path = [string]$Tokens[$i] }
            default { throw ('Unknown capability-inventory option: {0}' -f $token) }
        }
    }
    return [pscustomobject]$result
}

function Get-ReferenceCapabilityDescriptors([string]$ManifestPath) {
    if (-not [System.IO.File]::Exists($ManifestPath)) { return @() }
    $manifest = [System.IO.File]::ReadAllText($ManifestPath) | ConvertFrom-Json
    $items = New-Object System.Collections.Generic.List[object]
    foreach ($repo in @($manifest.repos)) {
        $name = [string]$repo.name
        $kind = if ($name -match 'plugin') { 'plugin' } elseif ($name -in @('modelcontextprotocol', 'servers', 'registry')) { 'mcp' } else { 'skill' }
        $lifecycle = if ([string]$repo.status -eq 'deprecated') { 'historical' } else { 'unknown' }
        $source = [pscustomobject]@{ type = 'reference_shelf'; path_or_url = [string]$repo.upstream_url; revision = $null; checksum = $null; license = $null; trust_tier = [string]$repo.tier }
        $items.Add((New-CapabilityDescriptor -Kind $kind -Name $name -TruthOrigin reference -Source $source -Lifecycle $lifecycle -Components @([pscustomobject]@{ kind = 'reference_repo'; disposition = [string]$repo.source_disposition }) -VerificationState static_validated)) | Out-Null
    }
    return $items.ToArray()
}

function Invoke-CapabilityInventoryCommand([object[]]$Tokens = @()) {
    $options = Parse-ReadOnlyCapabilityOptions $Tokens
    $configRaw = [System.IO.File]::ReadAllText($CfgPath) -replace '(?m)^\s*//.*$', ''
    $config = $configRaw | ConvertFrom-Json
    $descriptors = @(ConvertTo-CapabilityDescriptorsFromSkillsConfig $config $CfgPath 'working-tree')
    $descriptors += @(Get-ReferenceCapabilityDescriptors (Join-Path $Root 'references\reference-shelf.manifest.json'))
    $inventory = New-CapabilityInventory $descriptors
    if (-not [string]::IsNullOrWhiteSpace([string]$options.out_path)) { $inventory.writes = 1 }
    $envelope = [pscustomobject][ordered]@{ schema_version = 1; command = 'capability-inventory'; pass = (@($inventory.findings).Count -eq 0); truth_boundary = 'repo_static_inventory'; data = $inventory }
    $json = $envelope | ConvertTo-Json -Depth 30 -Compress
    if (-not [string]::IsNullOrWhiteSpace([string]$options.out_path)) {
        $outPath = [System.IO.Path]::GetFullPath([string]$options.out_path)
        Write-Utf8FileAtomic -Path $outPath -Content $json
    }
    return [pscustomobject]@{ exit_code = $(if ($envelope.pass) { 0 } else { 1 }); output = $(if ($options.json) { $json } else { 'Capability inventory: descriptors={0}, findings={1}' -f @($inventory.descriptors).Count, @($inventory.findings).Count }); json = [bool]$options.json; envelope = $envelope }
}

function Parse-PluginCliOptions([object[]]$Tokens, [string[]]$ValueOptions) {
    $result = [ordered]@{ json = $false }
    for ($i = 0; $i -lt @($Tokens).Count; $i++) {
        $token = [string]$Tokens[$i]
        if ($token -eq '--json') { $result.json = $true; continue }
        if ($ValueOptions -contains $token) {
            if ($i + 1 -ge @($Tokens).Count) { throw ('{0} requires a value.' -f $token) }
            $i++; $result[$token.TrimStart('-').Replace('-', '_')] = [string]$Tokens[$i]; continue
        }
        throw ('Unknown plugin option: {0}' -f $token)
    }
    return [pscustomobject]$result
}
function New-PluginCommandResult([string]$Command, $Data, [bool]$Json) {
    $pass = [bool](Get-OperationObjectProperty $Data 'pass')
    $envelope = [pscustomobject][ordered]@{ schema_version = 1; command = $Command; pass = $pass; truth_boundary = 'repo_or_fixture_only'; data = $Data }
    $text = if ($Json) { $envelope | ConvertTo-Json -Depth 40 -Compress } else { '{0}: pass={1}' -f $Command, $pass }
    return [pscustomobject]@{ exit_code = $(if ($pass) { 0 } else { 2 }); output = $text; json = $Json; envelope = $envelope }
}

function Invoke-PluginInventoryCommand([object[]]$Tokens = @()) {
    $options = Parse-PluginCliOptions $Tokens @('--official', '--personal', '--workspace')
    if ([string]::IsNullOrWhiteSpace([string]$options.official)) { throw '--official snapshot is required.' }
    $official = [System.IO.File]::ReadAllText([System.IO.Path]::GetFullPath($options.official)) | ConvertFrom-Json
    $personal = if ([string]::IsNullOrWhiteSpace([string]$options.personal)) { $null } else { [System.IO.File]::ReadAllText([System.IO.Path]::GetFullPath($options.personal)) | ConvertFrom-Json }
    $workspace = if ([string]::IsNullOrWhiteSpace([string]$options.workspace)) { $null } else { [System.IO.File]::ReadAllText([System.IO.Path]::GetFullPath($options.workspace)) | ConvertFrom-Json }
    return New-PluginCommandResult 'plugin-inventory' (New-PluginInventoryFromSnapshots $official $personal $workspace) ([bool]$options.json)
}

function Invoke-PluginLintCommand([object[]]$Tokens = @()) {
    $options = Parse-PluginCliOptions $Tokens @('--path')
    $root = [System.IO.Path]::GetFullPath([string]$options.path)
    $manifestPath = Join-Path $root '.codex-plugin\plugin.json'
    if (-not (Test-Path -LiteralPath $manifestPath -PathType Leaf)) { throw 'Plugin manifest does not exist.' }
    $manifest = [System.IO.File]::ReadAllText($manifestPath) | ConvertFrom-Json
    return New-PluginCommandResult 'plugin-lint' (Test-PluginManifestContract $manifest $root $true) ([bool]$options.json)
}

function Invoke-PluginExportCommand([object[]]$Tokens = @()) {
    $options = Parse-PluginCliOptions $Tokens @('--candidate', '--fixture-root', '--out', '--token')
    $candidate = [System.IO.File]::ReadAllText([System.IO.Path]::GetFullPath([string]$options.candidate)) | ConvertFrom-Json
    $data = Export-PluginFixture $candidate ([string]$options.fixture_root) ([string]$options.out) ([string]$options.token)
    return New-PluginCommandResult 'plugin-export' $data ([bool]$options.json)
}

function Invoke-PluginEvalCommand([object[]]$Tokens = @()) {
    $options = Parse-PluginCliOptions $Tokens @('--path', '--model-snapshot')
    $model = if ([string]::IsNullOrWhiteSpace([string]$options.model_snapshot)) { $null } else { [System.IO.File]::ReadAllText([System.IO.Path]::GetFullPath($options.model_snapshot)) | ConvertFrom-Json }
    return New-PluginCommandResult 'plugin-eval' (New-PluginEvaluationReport ([System.IO.Path]::GetFullPath([string]$options.path)) $model) ([bool]$options.json)
}

function Parse-RuleAuditOptions([object[]]$Tokens) {
    $result = [ordered]@{ repo = $null; current_directory = $null; user_root = $null; host = 'codex'; json = $false; out_path = $null }
    for ($i = 0; $i -lt @($Tokens).Count; $i++) {
        $token = [string]$Tokens[$i]
        switch ($token.ToLowerInvariant()) {
            '--json' { $result.json = $true }
            { $_ -in @('--repo', '--cwd', '--user-root', '--host', '--out') } {
                if ($i + 1 -ge @($Tokens).Count) { throw ('{0} requires a value.' -f $token) }
                $i++; $value = [string]$Tokens[$i]
                switch ($token.ToLowerInvariant()) { '--repo' { $result.repo = $value }; '--cwd' { $result.current_directory = $value }; '--user-root' { $result.user_root = $value }; '--host' { $result.host = $value }; '--out' { $result.out_path = $value } }
            }
            default { throw ('Unknown rule-audit option: {0}' -f $token) }
        }
    }
    if ([string]::IsNullOrWhiteSpace([string]$result.repo)) { throw '--repo is required.' }
    if ([string]$result.host -notin @('codex', 'claude')) { throw '--host supports codex or claude.' }
    if ([string]::IsNullOrWhiteSpace([string]$result.current_directory)) { $result.current_directory = $result.repo }
    return [pscustomobject]$result
}

function Invoke-RuleAuditCommand([object[]]$Tokens = @()) {
    $options = Parse-RuleAuditOptions $Tokens
    $discovery = Get-RuleDiscovery -RepoRoot $options.repo -CurrentDirectory $options.current_directory -HostName $options.host -UserRuleRoot $options.user_root
    $profile = [pscustomobject]@{ max_bytes = 10240; max_lines = 80; global_max_bytes = 16384; global_max_lines = 130; project_max_bytes = 10240; project_max_lines = 80; blocking_codes = @('file_missing') }
    $diagnostics = Invoke-RuleDiagnostics $discovery $profile
    $constraints = @(Get-RuleAuditResponsibilityConstraints -Documents $diagnostics.documents)
    $advisor = Invoke-RuleAdvisor -Documents $diagnostics.documents -Constraints $constraints
    $repoScan = New-AuditRepoScan 'rule-audit' ([System.IO.Path]::GetFullPath($options.repo)) $options.repo
    $truth = New-RuleRepoTruthIndex -RepoRoot $options.repo -RepoScan $repoScan
    $referenceChecks = Test-RuleRepoReferences -TruthIndex $truth -References @(Get-RuleAuditReferences -Documents $diagnostics.documents)
    $blockingCount = [int]$diagnostics.blocking_count
    $reportRequested = -not [string]::IsNullOrWhiteSpace([string]$options.out_path)
    $envelope = [pscustomobject][ordered]@{
        schema_version = 1; command = 'rule-audit'; pass = ($blockingCount -eq 0); exit_code = $(if ($blockingCount -gt 0) { 2 } else { 0 })
        truth_boundary = 'repo_static_audit'; discovery = $discovery; diagnostics = $diagnostics; advisor = $advisor
        repo_truth = $truth; repo_reference_checks = $referenceChecks; provider_calls = 0; native_mutations = 0; profile_changed = $false; writes = $(if ($reportRequested) { 1 } else { 0 })
    }
    $json = $envelope | ConvertTo-Json -Depth 40 -Compress
    if (-not [string]::IsNullOrWhiteSpace([string]$options.out_path)) {
        $outPath = [System.IO.Path]::GetFullPath([string]$options.out_path)
        if (@($discovery.documents | Where-Object { [string]::Equals([System.IO.Path]::GetFullPath([string]$_.path), $outPath, [System.StringComparison]::OrdinalIgnoreCase) }).Count -gt 0) { throw '--out cannot overwrite a discovered rule file.' }
        Write-Utf8FileAtomic -Path $outPath -Content $json
    }
    return [pscustomobject]@{ exit_code = [int]$envelope.exit_code; output = $(if ($options.json) { $json } else { 'Rule audit: documents={0}, deterministic={1}, semantic={2}, blockers={3}' -f @($discovery.documents).Count, @($diagnostics.findings).Count, @($advisor.findings).Count, $blockingCount }); json = [bool]$options.json; envelope = $envelope }
}

function Parse-RuleEstateAuditOptions([object[]]$Tokens) {
    $userHome = [Environment]::GetFolderPath('UserProfile')
    $result = [ordered]@{
        workspace_root = $null; exclude_names = @('external', '文档'); registry_path = $null
        codex_user_root = (Join-Path $userHome '.codex'); claude_user_root = (Join-Path $userHome '.claude')
        max_targets = 64; out_path = $null; json = $false
    }
    for ($i = 0; $i -lt @($Tokens).Count; $i++) {
        $token = [string]$Tokens[$i]
        if ($token -eq '--json') { $result.json = $true; continue }
        if ($token -notin @('--workspace-root', '--exclude', '--registry', '--codex-user-root', '--claude-user-root', '--max-targets', '--out')) { throw ('Unknown rule-estate-audit option: {0}' -f $token) }
        if ($i + 1 -ge @($Tokens).Count) { throw ('{0} requires a value.' -f $token) }
        $i++; $value = [string]$Tokens[$i]
        switch ($token) {
            '--workspace-root' { $result.workspace_root = $value }
            '--exclude' { $result.exclude_names += $value }
            '--registry' { $result.registry_path = $value }
            '--codex-user-root' { $result.codex_user_root = $value }
            '--claude-user-root' { $result.claude_user_root = $value }
            '--max-targets' { $result.max_targets = [int]$value }
            '--out' { $result.out_path = $value }
        }
    }
    if ([string]::IsNullOrWhiteSpace([string]$result.workspace_root)) { throw '--workspace-root is required.' }
    return [pscustomobject]$result
}

function Invoke-RuleEstateAuditCommand([object[]]$Tokens = @()) {
    $options = Parse-RuleEstateAuditOptions $Tokens
    $registryTargets = @()
    if (-not [string]::IsNullOrWhiteSpace([string]$options.registry_path)) {
        $registryPath = [System.IO.Path]::GetFullPath([string]$options.registry_path)
        if (-not [System.IO.File]::Exists($registryPath)) { throw ('Registry file does not exist: {0}' -f $registryPath) }
        $registry = [System.IO.File]::ReadAllText($registryPath) | ConvertFrom-Json
        $registryTargets = @($registry.targets)
    }
    $report = Invoke-RuleEstateAudit -WorkspaceRoot $options.workspace_root -ExcludeNames $options.exclude_names -RegistryTargets $registryTargets -CodexUserRoot $options.codex_user_root -ClaudeUserRoot $options.claude_user_root -MaxTargets $options.max_targets
    $reportRequested = -not [string]::IsNullOrWhiteSpace([string]$options.out_path)
    $pass = [bool]$report.structural_pass -and [bool]$report.semantic_coverage_pass -and [bool]$report.enforcement_verified
    $exitCode = if ($pass) { 0 } else { 2 }
    $envelope = [pscustomobject][ordered]@{
        schema_version = 1; command = 'rule-estate-audit'; pass = $pass; exit_code = $exitCode; truth_boundary = $report.truth_boundary
        report = $report; writes = $(if ($reportRequested) { 1 } else { 0 }); provider_calls = 0; native_mutations = 0
    }
    $json = $envelope | ConvertTo-Json -Depth 60 -Compress
    if ($reportRequested) {
        $protected = @($report.inventory.targets | ForEach-Object { @([string]$_.agents_path, [string]$_.claude_path) })
        if (-not [string]::IsNullOrWhiteSpace([string]$options.registry_path)) { $protected += [System.IO.Path]::GetFullPath([string]$options.registry_path) }
        $outPath = Resolve-RuleEstateControlOutput ([string]$options.out_path) ([string]$options.workspace_root) $protected
        foreach ($target in @($report.inventory.targets)) {
            if ($outPath.Equals([System.IO.Path]::GetFullPath([string]$target.agents_path), [System.StringComparison]::OrdinalIgnoreCase) -or $outPath.Equals([System.IO.Path]::GetFullPath([string]$target.claude_path), [System.StringComparison]::OrdinalIgnoreCase)) { throw '--out cannot overwrite a target rule file.' }
        }
        Write-Utf8FileAtomic -Path $outPath -Content $json
    }
    $output = if ($options.json) { $json } else { 'Rule estate audit: targets={0}, findings={1}, textual_covered={2}, semantic_gaps={3}, patch_candidates={4}' -f $report.summary.target_count, $report.summary.finding_count, $report.summary.textual_mapping_covered_count, $report.summary.semantic_gap_count, $report.summary.patch_candidate_count }
    return [pscustomobject]@{ exit_code = $exitCode; output = $output; json = [bool]$options.json; envelope = $envelope }
}

function Parse-RuleEstateMutationOptions([object[]]$Tokens, [ValidateSet('plan','apply','rollback')][string]$Mode) {
    $userHome=[Environment]::GetFolderPath('UserProfile')
    $result=[ordered]@{review=$null;plan=$null;workspace_root=$null;codex_user_root=(Join-Path $userHome '.codex');claude_user_root=(Join-Path $userHome '.claude');exclude_names=@('external','文档');token=$null;out_path=$null;resume=$null;receipt=$null;action_id=$null;json=$false}
    for($i=0;$i -lt @($Tokens).Count;$i++){
        $token=[string]$Tokens[$i]
        if($token -eq '--json'){$result.json=$true;continue}
        if($token -notin @('--review','--plan','--workspace-root','--codex-user-root','--claude-user-root','--exclude','--token','--out','--resume','--receipt','--action-id')){throw ('Unknown rule-estate-{0} option: {1}' -f $Mode,$token)}
        if($i+1 -ge @($Tokens).Count){throw ('{0} requires a value.' -f $token)};$i++;$value=[string]$Tokens[$i]
        switch($token){'--review'{$result.review=$value};'--plan'{$result.plan=$value};'--workspace-root'{$result.workspace_root=$value};'--codex-user-root'{$result.codex_user_root=$value};'--claude-user-root'{$result.claude_user_root=$value};'--exclude'{$result.exclude_names+=$value};'--token'{$result.token=$value};'--out'{$result.out_path=$value};'--resume'{$result.resume=$value};'--receipt'{$result.receipt=$value};'--action-id'{$result.action_id=$value}}
    }
    if($Mode -eq 'plan' -and ([string]::IsNullOrWhiteSpace($result.review) -or [string]::IsNullOrWhiteSpace($result.workspace_root) -or [string]::IsNullOrWhiteSpace($result.out_path))){throw 'rule-estate-plan requires --review, --workspace-root, and --out.'}
    if($Mode -eq 'apply' -and ([string]::IsNullOrWhiteSpace($result.plan) -or [string]::IsNullOrWhiteSpace($result.workspace_root) -or [string]::IsNullOrWhiteSpace($result.token) -or [string]::IsNullOrWhiteSpace($result.out_path))){throw 'rule-estate-apply requires --plan, --workspace-root, --token, and --out.'}
    if($Mode -eq 'rollback' -and ([string]::IsNullOrWhiteSpace($result.receipt) -or [string]::IsNullOrWhiteSpace($result.action_id) -or [string]::IsNullOrWhiteSpace($result.token) -or [string]::IsNullOrWhiteSpace($result.workspace_root))){throw 'rule-estate-rollback requires --receipt, --action-id, --workspace-root, and --token.'}
    return [pscustomobject]$result
}

function Resolve-RuleEstateControlOutput([string]$Path,[string]$WorkspaceRoot,[string[]]$Protected=@()){
    $resolved=[IO.Path]::GetFullPath($Path);$workspace=[IO.Path]::GetFullPath($WorkspaceRoot)
    if(-not (Test-RuleDiscoveryPathWithin $resolved $workspace)){throw 'Estate control outputs must remain inside the explicit workspace root.'}
    if(Test-RuleEstateReparsePath $resolved $workspace){throw 'Estate control outputs must not cross a reparse point inside the explicit workspace root.'}
    foreach($item in @($Protected)){if(-not [string]::IsNullOrWhiteSpace($item) -and $resolved.Equals([IO.Path]::GetFullPath($item),[StringComparison]::OrdinalIgnoreCase)){throw 'Estate output cannot overwrite an input file.'}}
    return $resolved
}

function Get-RuleEstateReviewControlInputs([string]$ReviewPath) {
    $inputs=New-Object System.Collections.Generic.List[string]
    if([string]::IsNullOrWhiteSpace($ReviewPath)){return @()}
    $reviewFile=[IO.Path]::GetFullPath($ReviewPath);$inputs.Add($reviewFile)|Out-Null
    if(-not [IO.File]::Exists($reviewFile)){return @($inputs.ToArray())}
    try{$review=[IO.File]::ReadAllText($reviewFile)|ConvertFrom-Json}catch{return @($inputs.ToArray())}
    $reviewRoot=[IO.Path]::GetDirectoryName($reviewFile)
    $authorization=[string](Get-RuleEstateProperty $review 'authorization_receipt')
    if(-not [string]::IsNullOrWhiteSpace($authorization)){
        try{$inputs.Add([IO.Path]::GetFullPath((Join-Path $reviewRoot $authorization)))|Out-Null}catch{}
    }
    foreach($change in @(Get-RuleEstateProperty $review 'changes')){
        $desired=[string](Get-RuleEstateProperty $change 'desired_file')
        if([string]::IsNullOrWhiteSpace($desired)){continue}
        try{$inputs.Add([IO.Path]::GetFullPath((Join-Path $reviewRoot $desired)))|Out-Null}catch{}
    }
    return @($inputs.ToArray()|Sort-Object -Unique)
}

function Get-RuleEstatePlanControlInputs($Plan) {
    $inputs=New-Object System.Collections.Generic.List[string]
    $review=Get-RuleEstateProperty $Plan 'review';$reviewPath=[string](Get-RuleEstateProperty $review 'path')
    foreach($path in @(Get-RuleEstateReviewControlInputs $reviewPath)){if(-not [string]::IsNullOrWhiteSpace($path)){$inputs.Add($path)|Out-Null}}
    $authorizationPath=[string](Get-RuleEstateProperty (Get-RuleEstateProperty $Plan 'authorization') 'path')
    if(-not [string]::IsNullOrWhiteSpace($authorizationPath)){$inputs.Add([IO.Path]::GetFullPath($authorizationPath))|Out-Null}
    foreach($action in @(Get-RuleEstateProperty $Plan 'actions')){
        $targetPath=[string](Get-RuleEstateProperty $action 'target_path')
        if(-not [string]::IsNullOrWhiteSpace($targetPath)){$inputs.Add([IO.Path]::GetFullPath($targetPath))|Out-Null}
    }
    return @($inputs.ToArray()|Sort-Object -Unique)
}

function Invoke-RuleEstatePlanCommand([object[]]$Tokens=@()){
    $options=Parse-RuleEstateMutationOptions $Tokens plan
    $plan=New-RuleEstatePlan -ReviewPath $options.review -WorkspaceRoot $options.workspace_root -CodexUserRoot $options.codex_user_root -ClaudeUserRoot $options.claude_user_root -ExcludeNames $options.exclude_names
    $out=Resolve-RuleEstateControlOutput $options.out_path $options.workspace_root @(Get-RuleEstatePlanControlInputs $plan)
    $envelope=[pscustomobject][ordered]@{schema_version=1;command='rule-estate-plan';pass=$true;exit_code=0;truth_boundary='reviewed_multi_target_plan';plan=$plan;writes=1;target_writes=0;host_writes=0;provider_calls=0;native_mutations=0}
    $json=$envelope|ConvertTo-Json -Depth 60 -Compress;Write-Utf8FileAtomic -Path $out -Content $json
    return [pscustomobject]@{exit_code=0;json=[bool]$options.json;output=$(if($options.json){$json}else{'Rule estate plan: actions={0}, target_set={1}' -f $plan.actions.Count,$plan.target_set.count});envelope=$envelope}
}

function Invoke-RuleEstateApplyCommand([object[]]$Tokens=@()){
    $options=Parse-RuleEstateMutationOptions $Tokens apply
    $planPath=[IO.Path]::GetFullPath($options.plan);if(-not [IO.File]::Exists($planPath)){throw 'Estate plan does not exist.'}
    $document=[IO.File]::ReadAllText($planPath)|ConvertFrom-Json;$plan=if([string](Get-RuleEstateProperty $document 'command') -eq 'rule-estate-plan'){Get-RuleEstateProperty $document 'plan'}else{$document}
    $protected=@($planPath)+@(Get-RuleEstatePlanControlInputs $plan)
    $out=Resolve-RuleEstateControlOutput $options.out_path $options.workspace_root $protected
    $result=Invoke-RuleEstateApply -Plan $plan -WorkspaceRoot $options.workspace_root -CodexUserRoot $options.codex_user_root -ClaudeUserRoot $options.claude_user_root -Token $options.token -ReceiptPath $out -ResumeReceiptPath $options.resume
    $exit=if($result.pass){0}else{2};$envelope=[pscustomobject][ordered]@{schema_version=1;command='rule-estate-apply';pass=$result.pass;exit_code=$exit;truth_boundary='filesystem_applied_not_host_loaded';result=$result;provider_calls=0;native_mutations=0}
    $json=$envelope|ConvertTo-Json -Depth 60 -Compress
    return [pscustomobject]@{exit_code=$exit;json=[bool]$options.json;output=$(if($options.json){$json}else{'Rule estate apply: status={0}, writes={1}' -f $result.status,$result.writes});envelope=$envelope}
}

function Invoke-RuleEstateRollbackCommand([object[]]$Tokens=@()){
    $options=Parse-RuleEstateMutationOptions $Tokens rollback
    $result=Invoke-RuleEstateRollback -ReceiptPath $options.receipt -ActionId $options.action_id -Token $options.token -WorkspaceRoot $options.workspace_root -CodexUserRoot $options.codex_user_root -ClaudeUserRoot $options.claude_user_root
    $exit=if($result.pass){0}else{2};$envelope=[pscustomobject][ordered]@{schema_version=1;command='rule-estate-rollback';pass=$result.pass;exit_code=$exit;truth_boundary='single_target_filesystem_rollback';result=$result;provider_calls=0;native_mutations=0}
    $json=$envelope|ConvertTo-Json -Depth 30 -Compress
    return [pscustomobject]@{exit_code=$exit;json=[bool]$options.json;output=$(if($options.json){$json}else{'Rule estate rollback: status={0}' -f $result.status});envelope=$envelope}
}

function Parse-RulePatchCliOptions([object[]]$Tokens, [ValidateSet('plan', 'apply')][string]$Mode) {
    $result = [ordered]@{ target=$null; desired_file=$null; fixture_root=$null; repo_root=$null; allow_create=$false; plan_path=$null; token=$null; out_path=$null; json=$false }
    for($i=0;$i -lt @($Tokens).Count;$i++) {
        $token=[string]$Tokens[$i]
        if($token -eq '--json') { $result.json=$true; continue }
        if($token -eq '--allow-create') { $result.allow_create=$true; continue }
        if($token -notin @('--target','--desired-file','--fixture-root','--repo-root','--plan','--token','--out')) { throw ('Unknown rule-{0} option: {1}' -f $Mode,$token) }
        if($i+1 -ge @($Tokens).Count) { throw ('{0} requires a value.' -f $token) };$i++;$value=[string]$Tokens[$i]
        switch($token) { '--target'{$result.target=$value};'--desired-file'{$result.desired_file=$value};'--fixture-root'{$result.fixture_root=$value};'--repo-root'{$result.repo_root=$value};'--plan'{$result.plan_path=$value};'--token'{$result.token=$value};'--out'{$result.out_path=$value} }
    }
    $hasFixture = -not [string]::IsNullOrWhiteSpace($result.fixture_root); $hasRepo = -not [string]::IsNullOrWhiteSpace($result.repo_root)
    if($hasFixture -eq $hasRepo) { throw 'Specify exactly one of --fixture-root or --repo-root.' }
    if($Mode -eq 'plan' -and ([string]::IsNullOrWhiteSpace($result.target) -or [string]::IsNullOrWhiteSpace($result.desired_file))) { throw 'rule-plan requires --target and --desired-file.' }
    if($Mode -eq 'apply' -and ([string]::IsNullOrWhiteSpace($result.plan_path) -or [string]::IsNullOrWhiteSpace($result.token))) { throw 'rule-apply requires --plan and --token.' }
    return [pscustomobject]$result
}

function Assert-RulePatchFixtureRoot([string]$FixtureRoot) {
    $root=[IO.Path]::GetFullPath($FixtureRoot)
    if(-not [IO.Directory]::Exists($root) -or -not [IO.File]::Exists((Join-Path $root '.skills-manager-fixture'))) { throw 'Fixture root must exist and contain .skills-manager-fixture.' }
    return $root
}

function Assert-RulePatchRepoRoot([string]$RepoRoot) {
    $root=[IO.Path]::GetFullPath($RepoRoot)
    if(-not [IO.Directory]::Exists($root) -or (-not [IO.Directory]::Exists((Join-Path $root '.git')) -and -not [IO.File]::Exists((Join-Path $root '.git')))) { throw 'Repository root must exist and contain a .git marker.' }
    return $root
}

function Resolve-RulePatchOutputPath([string]$OutPath, [string]$FixtureRoot, [string[]]$ProtectedPaths = @()) {
    if ([string]::IsNullOrWhiteSpace($OutPath)) { return $null }
    $resolved = [IO.Path]::GetFullPath($OutPath)
    if (-not (Test-RuleDiscoveryPathWithin $resolved $FixtureRoot)) { throw 'Output file must remain inside fixture root.' }
    foreach ($protected in @($ProtectedPaths)) {
        if (-not [string]::IsNullOrWhiteSpace($protected) -and $resolved.Equals([IO.Path]::GetFullPath($protected), [StringComparison]::OrdinalIgnoreCase)) {
            throw 'Output file must not overwrite a rule patch input or target.'
        }
    }
    return $resolved
}

function Invoke-RulePlanCommand([object[]]$Tokens=@()) {
    $options=Parse-RulePatchCliOptions $Tokens plan
    $scope=if(-not [string]::IsNullOrWhiteSpace($options.repo_root)){'repository'}else{'fixture'}
    $boundary=if($scope -eq 'repository'){Assert-RulePatchRepoRoot $options.repo_root}else{Assert-RulePatchFixtureRoot $options.fixture_root}
    $target=[IO.Path]::GetFullPath($options.target);$desiredFile=[IO.Path]::GetFullPath($options.desired_file)
    if(-not (Test-RuleDiscoveryPathWithin $target $boundary) -or -not (Test-RuleDiscoveryPathWithin $desiredFile $boundary)) { throw 'Target and desired file must remain inside the authorized root.' }
    if(-not [IO.File]::Exists($desiredFile)){throw 'Desired file does not exist.'}
    $operation=if($options.allow_create){'create'}else{'update'}
    if($operation -eq 'create' -and [IO.File]::Exists($target)){throw '--allow-create requires an absent target.'}
    if($operation -eq 'update' -and -not [IO.File]::Exists($target)){throw 'Update target does not exist; use --allow-create for a reviewed new rule file.'}
    $outPath=Resolve-RulePatchOutputPath $options.out_path $boundary @($target,$desiredFile)
    $currentText=if($operation -eq 'create'){''}else{[IO.File]::ReadAllText($target)}
    $plan=New-RulePatchPlan -TargetPath $target -AuthorizedRoot $boundary -CurrentText $currentText -DesiredText ([IO.File]::ReadAllText($desiredFile)) -DesiredSource reviewed_file -AuthorizationScope $scope -TargetOperation $operation
    $validation=Test-RulePatchPlanContract $plan;$exit=if($validation.pass){0}else{2}
    $envelope=[pscustomobject][ordered]@{schema_version=1;command='rule-plan';pass=$validation.pass;exit_code=$exit;truth_boundary=$(if($scope -eq 'fixture'){'fixture_only'}else{'single_repository'});plan=$plan;findings=@($validation.findings);target_writes=0;host_writes=0;provider_calls=0;native_mutations=0}
    $json=$envelope|ConvertTo-Json -Depth 40 -Compress
    if($null -ne $outPath){Write-Utf8FileAtomic -Path $outPath -Content $json}
    return [pscustomobject]@{exit_code=$exit;json=[bool]$options.json;output=$(if($options.json){$json}else{'Rule plan: pass={0}, changes={1}' -f $envelope.pass,$plan.diff.has_changes});envelope=$envelope}
}

function Invoke-RuleApplyCommand([object[]]$Tokens=@()) {
    $options=Parse-RulePatchCliOptions $Tokens apply
    $scope=if(-not [string]::IsNullOrWhiteSpace($options.repo_root)){'repository'}else{'fixture'}
    $boundary=if($scope -eq 'repository'){Assert-RulePatchRepoRoot $options.repo_root}else{Assert-RulePatchFixtureRoot $options.fixture_root}
    $planPath=[IO.Path]::GetFullPath($options.plan_path);if(-not (Test-RuleDiscoveryPathWithin $planPath $boundary)){throw 'Plan file must remain inside the authorized root.'}
    $planDocument=[IO.File]::ReadAllText($planPath)|ConvertFrom-Json
    $plan=if([string](Get-OperationObjectProperty $planDocument 'command') -eq 'rule-plan'){Get-OperationObjectProperty $planDocument 'plan'}else{$planDocument}
    $targetPath=[string](Get-OperationObjectProperty (Get-OperationObjectProperty $plan 'target') 'path')
    $planScope=[string](Get-OperationObjectProperty (Get-OperationObjectProperty $plan 'apply') 'boundary_scope');if($planScope -ne $scope){throw 'CLI authorization root type does not match the plan.'}
    $outPath=Resolve-RulePatchOutputPath $options.out_path $boundary @($planPath,$targetPath)
    $result=Invoke-RulePatchApply $plan $boundary $options.token;$exit=if($result.pass){0}else{2}
    $envelope=[pscustomobject][ordered]@{schema_version=1;command='rule-apply';pass=$result.pass;exit_code=$exit;truth_boundary=$(if($scope -eq 'fixture'){'fixture_only'}else{'single_repository'});result=$result;host_writes=0;provider_calls=0;native_mutations=0}
    $json=$envelope|ConvertTo-Json -Depth 40 -Compress
    if($null -ne $outPath){Write-Utf8FileAtomic -Path $outPath -Content $json}
    return [pscustomobject]@{exit_code=$exit;json=[bool]$options.json;output=$(if($options.json){$json}else{'Rule apply: status={0}' -f $result.status});envelope=$envelope}
}

function Parse-AgentWorkflowCommandOptions([object[]]$Tokens) {
    $result = [ordered]@{ input_path = $null; json = $false }
    for ($i = 0; $i -lt @($Tokens).Count; $i++) {
        $token = ([string]$Tokens[$i]).ToLowerInvariant()
        switch ($token) {
            '--input' { if ($i + 1 -ge @($Tokens).Count) { throw '--input requires a JSON file path.' }; $i++; $result.input_path = [string]$Tokens[$i] }
            '--json' { $result.json = $true }
            default { throw ('Unknown agent workflow option: {0}' -f [string]$Tokens[$i]) }
        }
    }
    if ([string]::IsNullOrWhiteSpace([string]$result.input_path)) { throw '--input is required.' }
    return [pscustomobject]$result
}

function Read-AgentWorkflowRequest([string]$InputPath) {
    $fullPath = [IO.Path]::GetFullPath($InputPath)
    if (-not (Test-OperationPathWithinRoot $fullPath $Root)) { throw 'Agent workflow input must remain inside the repository root.' }
    if (-not [IO.File]::Exists($fullPath)) { throw ('Agent workflow input does not exist: {0}' -f $fullPath) }
    $rootPath = [IO.Path]::GetFullPath($Root)
    $cursor = $fullPath
    while (Test-OperationPathWithinRoot $cursor $rootPath) {
        if ([IO.File]::Exists($cursor) -or [IO.Directory]::Exists($cursor)) {
            if (([IO.File]::GetAttributes($cursor) -band [IO.FileAttributes]::ReparsePoint) -ne 0) {
                throw 'Agent workflow input cannot traverse a reparse point.'
            }
        }
        if ($cursor.Equals($rootPath, [StringComparison]::OrdinalIgnoreCase)) { break }
        $parent = [IO.Directory]::GetParent($cursor)
        if ($null -eq $parent) { break }
        $cursor = $parent.FullName
    }
    return [IO.File]::ReadAllText($fullPath) | ConvertFrom-Json
}

function New-AgentWorkflowCommandResult([string]$Command, [bool]$Json, $Data, [bool]$Pass) {
    $envelope = [pscustomobject][ordered]@{
        schema_version = 1; command = $Command; pass = $Pass; truth_boundary = 'repo_advisory_only'; decision_owner = 'host_ai'; executor = 'host_native_runtime'
        provider_calls = 0; native_mutations = 0; writes = 0; data = $Data
    }
    $output = if ($Json) { $envelope | ConvertTo-Json -Depth 50 -Compress } else { '{0}: pass={1}; findings={2}; writes=0; provider_calls=0' -f $Command, $Pass, @((Get-OperationObjectProperty $Data 'findings')).Count }
    return [pscustomobject]@{ exit_code = $(if ($Pass) { 0 } else { 2 }); output = $output; json = $Json; envelope = $envelope }
}

function Invoke-AgentValidateCommand([object[]]$Tokens = @()) {
    $options = Parse-AgentWorkflowCommandOptions $Tokens
    $request = Read-AgentWorkflowRequest $options.input_path
    $validation = Test-AgentWorkflowRequest $request
    return New-AgentWorkflowCommandResult 'agent-validate' ([bool]$options.json) $validation ([bool]$validation.pass)
}

function Invoke-AgentPlanCommand([object[]]$Tokens = @()) {
    $options = Parse-AgentWorkflowCommandOptions $Tokens
    $request = Read-AgentWorkflowRequest $options.input_path
    $plan = New-AgentWorkflowAdvisoryPlan $request
    return New-AgentWorkflowCommandResult 'agent-plan' ([bool]$options.json) $plan ([bool]$plan.pass)
}

